/**
 * Назначение: оркестратор bootstrap — StartAppRoot (легкий) / lazy SurveyAppRoot.
 */

import { Suspense, lazy, useCallback, useEffect, useState } from 'react';

import { AppBootstrapSkeleton } from './components/AppBootstrapSkeleton/AppBootstrapSkeleton';
import type { AppSurveyContentProps } from './AppSurveyContent';
import { useSurveyBootstrap } from './hooks/useSurveyBootstrap';
import { StartAppRoot } from './StartAppRoot';
import { useSurveySession } from './surveySession/useSurveySession';
import type { AppBootstrapMode } from './surveySession/types';
import type { SurveyDraft } from './types/surveyDraft';
import {
  consumePendingProjectNavigation,
  type PendingProjectNavigation,
} from './utils/pendingProjectNavigation';
import type { SurveyAppRootDraftMeta } from './SurveyAppRoot';

const SurveyAppRoot = lazy(() =>
  import('./SurveyAppRoot').then((m) => ({ default: m.SurveyAppRoot })),
);

type AppRootProps = Omit<AppSurveyContentProps, 'projectChrome'> & {
  onBootstrapModeChange: (mode: AppBootstrapMode) => void;
};

/**
 * @param props — справочники для SurveyAppRoot / AppSurveyContent
 */
export function AppRoot(props: AppRootProps) {
  const { onBootstrapModeChange, ...surveyContentProps } = props;
  const { dispatch } = useSurveySession();

  const [draftMeta, setDraftMeta] = useState<SurveyAppRootDraftMeta>({
    clientName: '',
    projectId: null,
  });
  const [pendingNavigation, setPendingNavigation] =
    useState<PendingProjectNavigation | null>(null);

  const onDraftMetaLoaded = useCallback((loaded: SurveyDraft) => {
    setDraftMeta({
      clientName: loaded.clientName,
      projectId: loaded.projectId ?? null,
    });
  }, []);

  const {
    bootstrapMode,
    beginSurvey,
    resetToStart,
    enterSurveyMode,
    retryBootstrap,
  } = useSurveyBootstrap({
    dispatch,
    onDraftMetaLoaded,
  });

  useEffect(() => {
    onBootstrapModeChange(bootstrapMode);
  }, [bootstrapMode, onBootstrapModeChange]);

  useEffect(() => {
    if (bootstrapMode === 'resolving' || bootstrapMode === 'error') return;

    const pending = consumePendingProjectNavigation();
    if (!pending) return;

    if (pending.kind === 'newProject') {
      beginSurvey();
      return;
    }

    queueMicrotask(() => {
      setPendingNavigation(pending);
      enterSurveyMode();
    });
  }, [bootstrapMode, beginSurvey, enterSurveyMode]);

  const clearPendingNavigation = useCallback(() => {
    setPendingNavigation(null);
  }, []);

  if (bootstrapMode === 'start' || bootstrapMode === 'resolving' || bootstrapMode === 'error') {
    return (
      <StartAppRoot
        bootstrapMode={bootstrapMode}
        onStartNew={beginSurvey}
        onRetryBootstrap={retryBootstrap}
      />
    );
  }

  return (
    <Suspense fallback={<AppBootstrapSkeleton statusLabel="Завантаження анкети…" />}>
      <SurveyAppRoot
        {...surveyContentProps}
        draftMeta={draftMeta}
        bootstrap={{ resetToStart, enterSurveyMode, beginSurvey }}
        pendingNavigation={pendingNavigation}
        onPendingNavigationHandled={clearPendingNavigation}
      />
    </Suspense>
  );
}

/**
 * Назначение: Тело анкеты (шаги, формы, отчёт).
 * Описание: Все мутации через SurveySession.dispatch и единый pipeline.
 */

import { useCallback, useEffect, useMemo, useRef } from 'react';

import { Header } from './components/Header/Header';
import type { HeaderProps } from './components/Header/Header';
import { Footer } from './components/Footer/Footer';
import styles from './App.module.css';
import { ObjectMetaForm } from './components/ObjectMetaForm/ObjectMetaForm';
import type { ObjectMetaValue, EnvelopePreset } from './types/envelope';
import { RoomsForm } from './components/RoomsForm/RoomsForm';
import type { RoomFormValue } from './types/rooms';
import { HotWaterForm } from './components/HotWaterForm/HotWaterForm';
import type { HotWaterFormValue } from './types/hotWater';
import { WaterHeaterForm } from './components/WaterHeaterForm/WaterHeaterForm';
import type { WaterHeaterFormValue } from './types/waterHeater';
import {
  getWaterHeaterSchemeOptions,
  isApartmentLargeForIndirectScheme,
} from './utils/waterHeaterSchemeOptions';
import { useSurveyStepNavigation } from './hooks/useSurveyStepNavigation';
import { HydraulicsSection } from './components/HydraulicsSection/HydraulicsSection';
import type { HydraulicsFormValue } from './types/hydraulics';
import type { WiringSystemType } from './surveySession/wiringLayoutV3';
import {
  SURVEY_STEP_NAV_ITEMS,
  surveyStepGlobalMetaTitle,
  surveyStepHasGlobalMetaContent,
  surveyStepHasWorkAreaContent,
} from './constants/surveySteps';
import { RESULTS_SECTION_IDS } from './constants/surveyResultsSections';
import type { SurveyCurrentStep } from './types/surveyStep';
import { useCalcReport } from './hooks/useCalcReport';
import { useSurveySession } from './surveySession/useSurveySession';
import { RecommendationsBlock } from './components/RecommendationsBlock/RecommendationsBlock';
import { CatalogEquipmentReference } from './components/CatalogEquipmentReference/CatalogEquipmentReference';
import { FinancialSummaryTable } from './components/FinancialSummary/FinancialSummaryTable';
import {
  HOT_WATER_BOILER_MATCHING_SCHEME_ENUM,
  SCHEME_BOILER_MAX_COMBI,
  SCHEME_BOILER_SINGLE_INDIRECT_SUM,
  type HotWaterBoilerPowerMatchingScheme,
} from './types/heatingMatching';
import {
  recommendedThermalRegimePresetForScheme,
  thermalRegimeRecommendationHint,
} from './types/heatingThermalRegime';
import { BoilerSurveyForm } from './components/BoilerSurveyForm/BoilerSurveyForm';
import { RadiatorsSurveyForm } from './components/RadiatorsSurveyForm/RadiatorsSurveyForm';
import { WarmFloorSection } from './components/WarmFloorSection/WarmFloorSection';
import { useRoomsOrchestration } from './hooks/useRoomsOrchestration';
import { useSurveyEstimates } from './hooks/useSurveyEstimates';
import type { UfhModePresetId, UfhModePresetCard } from './types/ufhModePreset';
import type { UnderfloorHeatingBasePreset, FlooringFinishMaterial } from './types/underfloorHeating';
import { useCatalogEquipmentQuery } from './query/queries/useCatalogEquipmentQuery';

const CALC_SCHEME_VALUES: readonly HotWaterBoilerPowerMatchingScheme[] = [
  ...HOT_WATER_BOILER_MATCHING_SCHEME_ENUM,
];

export type AppSurveyContentProps = {
  projectChrome: HeaderProps;
  wallPresets: EnvelopePreset[];
  windowPresetsList: EnvelopePreset[];
  floorPresets: EnvelopePreset[];
  ceilingPresets: EnvelopePreset[];
  roofPresets: EnvelopePreset[];
  sftkInsulationPresets: EnvelopePreset[];
  ventilatedInsulationPresets: EnvelopePreset[];
  insulationPresets: EnvelopePreset[];
  presetsLoading: boolean;
  presetsError: string | null;
  underfloorHeatingBases: UnderfloorHeatingBasePreset[];
  flooringFinishes: FlooringFinishMaterial[];
  underfloorPresetsLoading: boolean;
  ufhModePresets: UfhModePresetCard[];
  ufhModePresetsLoading: boolean;
  ufhModePresetsError: string | null;
};

function isCalcMatchingScheme(
  v: string,
): v is HotWaterBoilerPowerMatchingScheme {
  return (CALC_SCHEME_VALUES as readonly string[]).includes(v);
}

export function AppSurveyContent({
  projectChrome,
  wallPresets,
  windowPresetsList,
  floorPresets,
  ceilingPresets,
  roofPresets,
  sftkInsulationPresets,
  ventilatedInsulationPresets,
  insulationPresets,
  presetsLoading,
  presetsError,
  underfloorHeatingBases,
  flooringFinishes,
  underfloorPresetsLoading,
  ufhModePresets,
  ufhModePresetsLoading,
  ufhModePresetsError,
}: AppSurveyContentProps) {
  const {
    dispatch,
    draft,
    report: calcReport,
    uiPhase,
    calcLoading,
    calcError,
    state: sessionState,
  } = useSurveySession();

  const {
    currentStep,
    objectMeta,
    rooms,
    temps,
    hotWaterForm,
    waterHeaterForm,
    waterUnderfloorHeating,
    underfloorDistributionPreset,
    thermalRegimePreset,
    radiatorConnection,
    radiatorEmitterPreference,
    ufhPresetId,
    hydraulicsForm,
    wiringLayoutV3,
  } = draft;

  const draftRef = useRef(draft);

  useEffect(() => {
    draftRef.current = draft;
  }, [draft]);

  const { catalogSnap, catalogSnapLoading, catalogSnapError, reloadCatalog } =
    useCatalogEquipmentQuery();

  const setCurrentStep = useCallback(
    (step: SurveyCurrentStep) => { dispatch({ type: 'SET_CURRENT_STEP', step }); },
    [dispatch],
  );

  const { mainColumnRef, navigateToSurveyStep, navigateToResultsSection } =
    useSurveyStepNavigation({
      setCurrentStep,
    });

  const setObjectMeta = useCallback(
    (next: ObjectMetaValue | ((prev: ObjectMetaValue) => ObjectMetaValue)) => {
      const objectMetaValue =
        typeof next === 'function'
          ? next(draftRef.current.objectMeta)
          : next;
      if (objectMetaValue === draftRef.current.objectMeta) return;
      dispatch({ type: 'SET_OBJECT_META', objectMeta: objectMetaValue });
    },
    [dispatch],
  );

  const setRooms = useCallback(
    (next: RoomFormValue[] | ((prev: RoomFormValue[]) => RoomFormValue[])) => {
      const roomsNext =
        typeof next === 'function' ? next(draftRef.current.rooms) : next;
      if (roomsNext === draftRef.current.rooms) return;
      dispatch({ type: 'SET_ROOMS', rooms: roomsNext });
    },
    [dispatch],
  );

  const setTemps = useCallback(
    (
      next:
        | { insideC: number; outsideC: number; bathroomAirTempC?: number }
        | ((
            prev: { insideC: number; outsideC: number; bathroomAirTempC?: number },
          ) => { insideC: number; outsideC: number; bathroomAirTempC?: number }),
    ) => {
      const tempsNext =
        typeof next === 'function' ? next(draftRef.current.temps) : next;
      if (tempsNext === draftRef.current.temps) return;
      dispatch({ type: 'SET_TEMPS', temps: tempsNext });
    },
    [dispatch],
  );

  const setHotWaterForm = useCallback(
    (next: HotWaterFormValue | ((prev: HotWaterFormValue) => HotWaterFormValue)) => {
      const formNext =
        typeof next === 'function' ? next(draftRef.current.hotWaterForm) : next;
      if (formNext === draftRef.current.hotWaterForm) return;
      dispatch({ type: 'SET_HOT_WATER_FORM', hotWaterForm: formNext });
    },
    [dispatch],
  );

  const setHydraulicsForm = useCallback(
    (hydraulicsFormValue: HydraulicsFormValue) => {
      if (hydraulicsFormValue === draftRef.current.hydraulicsForm) return;
      dispatch({ type: 'SET_HYDRAULICS_FORM', hydraulicsForm: hydraulicsFormValue });
    },
    [dispatch],
  );

  const setWiringSystemType = useCallback(
    (systemType: WiringSystemType) => {
      if (systemType === draftRef.current.wiringLayoutV3.systemType) return;
      dispatch({ type: 'WIRING_SCHEME_SET', systemType });
    },
    [dispatch],
  );

  const setBranchLength = useCallback(
    (roomId: string, pipeLengthToEquipmentM: number) => {
      const prev = draftRef.current.wiringLayoutV3.branches.find(
        (b) => b.roomId === roomId,
      );
      if (prev?.pipeLengthToEquipmentM === pipeLengthToEquipmentM) return;
      dispatch({
        type: 'WIRING_BRANCH_LENGTH_SET',
        roomId,
        pipeLengthToEquipmentM,
      });
    },
    [dispatch],
  );

  const reorderBranch = useCallback(
    (roomId: string, direction: 'up' | 'down') => {
      dispatch({ type: 'WIRING_BRANCH_REORDER', roomId, direction });
    },
    [dispatch],
  );

  const apartmentLargeForScheme = useMemo(
    () =>
      isApartmentLargeForIndirectScheme(
        objectMeta.objectType,
        rooms,
        hotWaterForm.fixtures,
      ),
    [objectMeta.objectType, rooms, hotWaterForm.fixtures],
  );

  const recommendedThermalRegimePreset = useMemo(
    () =>
      recommendedThermalRegimePresetForScheme(
        waterHeaterForm.hotWaterBoilerPowerMatchingScheme,
        objectMeta.objectType,
      ),
    [waterHeaterForm.hotWaterBoilerPowerMatchingScheme, objectMeta.objectType],
  );

  const thermalRegimeTouchedRef = useRef(sessionState.thermalRegimeTouched);

  const thermalRegimeRecommendationHintText = useMemo(
    () =>
      thermalRegimeRecommendationHint(
        waterHeaterForm.hotWaterBoilerPowerMatchingScheme,
        objectMeta.objectType,
        thermalRegimePreset,
      ),
    [
      waterHeaterForm.hotWaterBoilerPowerMatchingScheme,
      objectMeta.objectType,
      thermalRegimePreset,
    ],
  );

  useEffect(() => {
    if (thermalRegimeTouchedRef.current) return;
    queueMicrotask(() => {
      dispatch({
        type: 'SET_THERMAL_REGIME_PRESET',
        preset: recommendedThermalRegimePreset,
      });
    });
  }, [dispatch, recommendedThermalRegimePreset]);

  useRoomsOrchestration({
    objectMeta,
    setObjectMeta,
    setRooms,
    wallPresets,
    floorPresets,
    ceilingPresets,
    roofPresets,
    windowPresets: windowPresetsList,
  });

  const { quickEstimate } = useSurveyEstimates(rooms);

  const reportIsStale = uiPhase === 'recalculating';

  const {
    apiHeatLoss,
    apiHotWaterFromReport,
    apiBoilerFromReport,
    apiBoilerKw,
    apiRadiatorsFromReport,
    apiIndirectWhFromReport,
    apiElectricWhFromReport,
    apiUnderfloorHeatingFromReport,
    apiUniboxesFromReport,
    apiHydraulicsFromReport,
    apiCommercialBomFromReport,
    displayedRadiatorSectionsTotal,
    apiCatalogSource,
    apiAutomationHints,
  } = useCalcReport(
    calcReport,
    isCalcMatchingScheme,
    quickEstimate.radiatorsSections,
    ufhPresetId,
  );

  /** Смена схемы из подсказок отчёта или формы водонагревателя. */
  const handleWaterHeaterSchemeChange = useCallback(
    (scheme: HotWaterBoilerPowerMatchingScheme) => {
      dispatch({
        type: 'SET_WATER_HEATER_FORM',
        waterHeaterForm: {
          ...waterHeaterForm,
          hotWaterBoilerPowerMatchingScheme: scheme,
          indirectDhwSpaceAvailable:
            objectMeta.objectType === 'apartment' &&
            scheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM
              ? waterHeaterForm.indirectDhwSpaceAvailable
              : false,
        },
      });
    },
    [dispatch, objectMeta.objectType, waterHeaterForm],
  );

  const handleWaterHeaterFormChange = useCallback(
    (next: WaterHeaterFormValue) => {
      dispatch({ type: 'SET_WATER_HEATER_FORM', waterHeaterForm: next });
    },
    [dispatch],
  );

  const handleUfhPresetChange = useCallback(
    (next: UfhModePresetId | null) => {
      dispatch({ type: 'HEATING_EMITTERS_MODE_SET', presetId: next });
    },
    [dispatch],
  );

  const { hotWaterBoilerPowerMatchingScheme } = waterHeaterForm;

  // Если схема стала недоступна (малая квартира) — сброс на max-комби.
  useEffect(() => {
    const allowed = getWaterHeaterSchemeOptions(
      objectMeta.objectType,
      apartmentLargeForScheme,
    ).map((o) => o.value);
    if (allowed.includes(hotWaterBoilerPowerMatchingScheme)) {
      return;
    }
    queueMicrotask(() => {
      dispatch({
        type: 'SET_WATER_HEATER_FORM',
        waterHeaterForm: {
          ...waterHeaterForm,
          hotWaterBoilerPowerMatchingScheme: SCHEME_BOILER_MAX_COMBI,
          indirectDhwSpaceAvailable: false,
        },
      });
    });
  }, [
    apartmentLargeForScheme,
    dispatch,
    hotWaterBoilerPowerMatchingScheme,
    objectMeta.objectType,
    waterHeaterForm,
  ]);

  const hasGlobalMetaContent = surveyStepHasGlobalMetaContent(currentStep);
  const hasWorkAreaContent = surveyStepHasWorkAreaContent(currentStep);

  const calcStatusNode =
    calcLoading || calcError ? (
      <div className={styles.calcStatus}>
        {calcLoading ? <div className={styles.hint}>Розрахунок…</div> : null}
        {calcError ? (
          <div className={styles.calcError} role="alert" data-testid="calc-error">
            {calcError}
          </div>
        ) : null}
      </div>
    ) : null;

  return (
    <div className={styles.appContainer}>
      <Header {...projectChrome} variant="survey" />

      <div className={styles.layoutBody}>
        <aside className={styles.navigationSteps}>
          <nav aria-label="Етапи анкети">
            {/* Навигация по шагам (пока без роутинга) */}
            <ul className={styles.stepList}>
              {SURVEY_STEP_NAV_ITEMS.map(({ step, label }) => (
                <li key={step}>
                  <button
                    type="button"
                    onClick={() => { setCurrentStep(step); }}
                    aria-current={currentStep === step ? 'step' : undefined}
                    data-testid={`step-nav-${step}`}
                    className={styles.stepButton}
                  >
                    {label}
                  </button>
                </li>
              ))}
            </ul>
          </nav>
        </aside>

        <main ref={mainColumnRef} className={styles.mainColumn}>
          {hasGlobalMetaContent ? (
            <section
              className={styles.globalMeta}
              aria-labelledby="global-meta-title"
            >
              <h2 id="global-meta-title">
                {surveyStepGlobalMetaTitle(currentStep)}
              </h2>
              {currentStep === 'object' && (
                <ObjectMetaForm
                  value={objectMeta}
                  wallPresets={wallPresets}
                  sftkInsulationPresets={sftkInsulationPresets}
                  ventilatedInsulationPresets={ventilatedInsulationPresets}
                  roofPresets={roofPresets}
                  loadingPresets={presetsLoading}
                  presetsError={presetsError}
                  onChange={setObjectMeta}
                />
              )}

              {currentStep === 'hotWater' && (
                <p className={`${styles.hint} ${styles.hintMt8}`}>
                  Тип об&apos;єкта:{' '}
                  <strong>
                    {objectMeta.objectType === 'apartment' ? 'Квартира' : 'Будинок'}
                  </strong>
                  , поверховість {objectMeta.floors}, кімнат за планом:{' '}
                  {objectMeta.roomsCount}. Норми витрати води на особу та
                  коефіцієнт одночасності беруться з довідника бекенду (за
                  типом об&apos;єкта).
                </p>
              )}

              {currentStep === 'boiler' && (
                <p className={`${styles.hint} ${styles.hintMt8}`}>
                  Задайте графік подачі/звороту радіаторного контуру (пресет під
                  тип котла). Підводка та тип приладів — на кроці «Радіатори».
                  Сценарій ГВП і підбір БКН/електробойлера — на кроці
                  «Водонагрівач».
                </p>
              )}

              {currentStep === 'radiators' && (
                <p className={`${styles.hint} ${styles.hintMt8}`}>
                  Підводка (бокова / нижня) фільтрує панельний пул; тип
                  приладів задається один на весь об&apos;єкт. Графік 75/65 або 55/45 —
                  на кроці «Котел».
                </p>
              )}

              {currentStep === 'waterHeater' && (
                <p className={`${styles.hint} ${styles.hintMt8}`}>
                  Оберіть стратегію ГВП: від цього залежать підбір бойлера
                  непрямого нагріву або електронакопичувача та формула потужності
                  котла. Зміни перераховуються автоматично.
                </p>
              )}

              {currentStep === 'object' && (
                <div className={styles.tempRow}>
                  <label className={styles.tempField}>
                    Всередині, °C
                    <input
                      type="number"
                      data-testid="field-inside-temp"
                      value={temps.insideC}
                      onChange={(e) =>
                        { setTemps((prev) => ({
                          ...prev,
                          insideC: Number(e.target.value),
                        })); }
                      }
                    />
                  </label>
                  <label className={styles.tempField}>
                    Зовні, °C
                    <input
                      type="number"
                      data-testid="field-outside-temp"
                      value={temps.outsideC}
                      onChange={(e) =>
                        { setTemps((prev) => ({
                          ...prev,
                          outsideC: Number(e.target.value),
                        })); }
                      }
                    />
                  </label>
                  <label className={styles.tempField}>
                    Повітря в санвузлі, °C
                    <input
                      type="number"
                      data-testid="field-bathroom-temp"
                      min={24}
                      max={35}
                      placeholder="≥24"
                      value={temps.bathroomAirTempC ?? ''}
                      onChange={(e) => {
                        const raw = e.target.value.trim();
                        setTemps((prev) => {
                          if (raw === '') {
                            const { bathroomAirTempC: _omit, ...rest } = prev;
                            return rest;
                          }
                          const n = Number(raw);
                          if (!Number.isFinite(n)) return prev;
                          return {
                            ...prev,
                            bathroomAirTempC: Math.max(24, Math.min(35, n)),
                          };
                        });
                      }}
                    />
                  </label>
                </div>
              )}
              {currentStep === 'object' && (
                <p className={`${styles.hint} ${styles.hintMt8}`}>
                  «Повітря в санвузлі» — розрахункова температура повітря (не теплоносій), не
                  нижче 24 °C. Порожньо = max(всередині, 24). Можна задати вище (наприклад 26–28).
                </p>
              )}
            </section>
          ) : null}

          {hasWorkAreaContent ? (
            <section
              className={
                hasGlobalMetaContent
                  ? styles.workArea
                  : `${styles.workArea} ${styles.workAreaStandalone}`
              }
            >
            {currentStep === 'rooms' && (
              <RoomsForm
                value={rooms}
                maxFloors={objectMeta.floors}
                objectMeta={objectMeta}
                wallPresets={wallPresets}
                insulationPresets={insulationPresets}
                windowPresets={windowPresetsList}
                floorPresets={floorPresets}
                ceilingPresets={ceilingPresets}
                roofPresets={roofPresets}
                waterUnderfloorHeating={waterUnderfloorHeating}
                underfloorHeatingBases={underfloorHeatingBases}
                flooringFinishes={flooringFinishes}
                underfloorPresetsLoading={underfloorPresetsLoading}
                onChange={setRooms}
              />
            )}
            {currentStep === 'hotWater' && (
              <HotWaterForm
                value={hotWaterForm}
                onChange={setHotWaterForm}
                hotWaterReport={apiHotWaterFromReport}
                calcLoading={calcLoading}
                onBackToResults={() => {
                  navigateToResultsSection(RESULTS_SECTION_IDS.hotWater);
                }}
              />
            )}

            {currentStep === 'boiler' && (
              <BoilerSurveyForm
                thermalRegimePreset={thermalRegimePreset}
                onThermalRegimeChange={(preset) => {
                  thermalRegimeTouchedRef.current = true;
                  dispatch({
                    type: 'SET_THERMAL_REGIME_PRESET',
                    preset,
                    touched: true,
                  });
                }}
                thermalRegimeRecommendationHintText={
                  thermalRegimeRecommendationHintText
                }
                ufhOnlyMode={ufhPresetId === 'ufh_only'}
                boilerMatching={apiBoilerFromReport}
                objectType={objectMeta.objectType}
                catalogSource={apiCatalogSource}
                calcLoading={calcLoading}
                onBackToResults={() => {
                  navigateToResultsSection(RESULTS_SECTION_IDS.boiler);
                }}
              />
            )}

            {currentStep === 'radiators' && (
              <RadiatorsSurveyForm
                radiatorConnection={radiatorConnection}
                radiatorEmitterPreference={radiatorEmitterPreference}
                onConnectionChange={(connection) => {
                  dispatch({
                    type: 'SET_RADIATOR_CONNECTION',
                    connection,
                  });
                }}
                onPreferenceChange={(preference) => {
                  dispatch({
                    type: 'SET_RADIATOR_EMITTER_PREFERENCE',
                    preference,
                  });
                }}
                radiatorsDisabledReason={
                  ufhPresetId === 'ufh_only'
                    ? 'Режим «лише тепла підлога» (ufh_only): підбір радіаторів на сервері пропускається. Значення підводки та типу приладів зберігаються в чернетці й потрапляють у heatingSystem, але на matching.radiators не впливають, поки обрано цей режим.'
                    : null
                }
                radiatorsMatching={apiRadiatorsFromReport}
                calcLoading={calcLoading}
                onBackToResults={() => {
                  navigateToResultsSection(RESULTS_SECTION_IDS.radiators);
                }}
              />
            )}

            {currentStep === 'waterHeater' && (
              <WaterHeaterForm
                value={waterHeaterForm}
                onChange={handleWaterHeaterFormChange}
                objectType={objectMeta.objectType}
                apartmentLarge={apartmentLargeForScheme}
                hotWaterForm={hotWaterForm}
                calcLoading={calcLoading}
                indirectMatching={apiIndirectWhFromReport}
                electricMatching={apiElectricWhFromReport}
                onBackToResults={() => {
                  navigateToResultsSection(RESULTS_SECTION_IDS.waterHeater);
                }}
              />
            )}

            {currentStep === 'hydraulics' && (
              <HydraulicsSection
                value={hydraulicsForm}
                onChange={setHydraulicsForm}
                wiringSystemType={wiringLayoutV3.systemType}
                onWiringSystemTypeChange={setWiringSystemType}
                branches={wiringLayoutV3.branches}
                rooms={rooms}
                onBranchLengthChange={setBranchLength}
                onBranchReorder={reorderBranch}
                hydraulicsReport={apiHydraulicsFromReport}
                catalogSource={apiCatalogSource}
                calcLoading={calcLoading}
                onBackToResults={() => {
                  navigateToResultsSection(RESULTS_SECTION_IDS.hydraulics);
                }}
              />
            )}

            {currentStep === 'technicalResult' && (
              <RecommendationsBlock
                quickEstimate={quickEstimate}
                apiHeatLoss={apiHeatLoss}
                apiHotWaterFromReport={apiHotWaterFromReport}
                hotWaterFixtures={hotWaterForm.fixtures}
                waterHeaterScheme={waterHeaterForm.hotWaterBoilerPowerMatchingScheme}
                apiBoilerFromReport={apiBoilerFromReport}
                apiBoilerKw={apiBoilerKw}
                apiRadiatorsFromReport={apiRadiatorsFromReport}
                apiIndirectWhFromReport={apiIndirectWhFromReport}
                apiElectricWhFromReport={apiElectricWhFromReport}
                apiUnderfloorHeatingFromReport={apiUnderfloorHeatingFromReport}
                apiUniboxesFromReport={apiUniboxesFromReport}
                displayedRadiatorSectionsTotal={displayedRadiatorSectionsTotal}
                apiCatalogSource={apiCatalogSource}
                apiAutomationHints={apiAutomationHints}
                objectType={objectMeta.objectType}
                onApplyScheme={handleWaterHeaterSchemeChange}
                apiHydraulicsFromReport={apiHydraulicsFromReport}
                calcLoading={calcLoading}
                reportIsStale={reportIsStale}
                uiPhase={uiPhase}
                onNavigateToSurveyStep={navigateToSurveyStep}
              />
            )}

            {currentStep === 'dataReference' && (
              <CatalogEquipmentReference
                snapshot={catalogSnap}
                loading={catalogSnapLoading}
                error={catalogSnapError}
                onRetry={() => {
                  void reloadCatalog();
                }}
              />
            )}

            {currentStep === 'financialResult' && (
              <FinancialSummaryTable
                commercial={apiCommercialBomFromReport}
                calcLoading={calcLoading}
                reportIsStale={reportIsStale}
              />
            )}

            {currentStep === 'warmFloor' && (
              <WarmFloorSection
                waterUnderfloorHeating={waterUnderfloorHeating}
                underfloorDistributionPreset={underfloorDistributionPreset}
                ufhModePresets={ufhModePresets}
                ufhModePresetsLoading={ufhModePresetsLoading}
                ufhModePresetsError={ufhModePresetsError}
                ufhPresetId={ufhPresetId}
                onUfhPresetChange={handleUfhPresetChange}
                onWaterUnderfloorChange={(v) => {
                  dispatch({ type: 'WATER_UFH_FLAG_SET', enabled: v });
                }}
                onDistributionPresetChange={(preset) => {
                  dispatch({ type: 'UFH_DISTRIBUTION_PRESET_SET', preset });
                }}
                underfloorHeatingReport={apiUnderfloorHeatingFromReport}
                uniboxesReport={apiUniboxesFromReport}
                hydraulicsPumps={apiHydraulicsFromReport?.proposal?.pumps ?? null}
                onBackToResults={() => {
                  navigateToResultsSection(RESULTS_SECTION_IDS.warmFloor);
                }}
              />
            )}

              {calcStatusNode}
            </section>
          ) : (
            calcStatusNode
          )}
        </main>
      </div>

      <Footer variant="app" />
    </div>
  );
}

/**
 * Назначение: важкий UI survey — projects, persistence, AppSurveyContent (lazy chunk).
 */

import { Suspense, lazy, useCallback, useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router';

import { footerUk } from './i18n/uk/footer';
import { paths } from './routing/paths';
import { useAppChrome } from './shell/useAppChrome';
import type { PendingProjectNavigation } from './utils/pendingProjectNavigation';
import { AppBootstrapSkeleton } from './components/AppBootstrapSkeleton/AppBootstrapSkeleton';
import { AccountBar } from './components/AccountBar/AccountBar';
import { DevToolsDock } from './components/DevToolsDock/DevToolsDock';
import type { HeaderProps } from './components/Header/Header';
import Logo from './components/Logo/Logo';
import type { AppSurveyContentProps } from './AppSurveyContent';
import { useSurveyDraftPersistence } from './hooks/useSurveyDraftPersistence';
import { useSurveyProject } from './hooks/useSurveyProject';
import { useDevPanelAccess } from './hooks/useDevPanelAccess';
import { brandUk } from './i18n/uk/brand';
import { buildCalcPayloadFromDraft } from './surveySession/buildCalcInputSnapshot';
import { surveyDraftToSessionSnapshot } from './surveySession/surveyDraftBridge';
import { useSurveySession } from './surveySession/useSurveySession';
import type { UseSurveyBootstrapResult } from './hooks/useSurveyBootstrap';
import type { SurveyDraft } from './types/surveyDraft';
import styles from './App.module.css';

const AppSurveyContent = lazy(() =>
  import('./AppSurveyContent').then((m) => ({ default: m.AppSurveyContent })),
);

const ProjectsDialog = lazy(() =>
  import('./components/ProjectsDialog/ProjectsDialog').then((m) => ({
    default: m.ProjectsDialog,
  })),
);

const DevPanel = lazy(() =>
  import('./components/DevPanel/DevPanel').then((m) => ({ default: m.DevPanel })),
);

export type SurveyAppRootDraftMeta = {
  clientName: string;
  projectId: string | null;
};

export type SurveyAppRootProps = Omit<AppSurveyContentProps, 'projectChrome'> & {
  draftMeta: SurveyAppRootDraftMeta;
  bootstrap: Pick<
    UseSurveyBootstrapResult,
    'resetToStart' | 'enterSurveyMode' | 'beginSurvey'
  >;
  pendingNavigation: PendingProjectNavigation | null;
  onPendingNavigationHandled: () => void;
};

/**
 * @param props
 */
export function SurveyAppRoot({
  draftMeta,
  bootstrap,
  pendingNavigation,
  onPendingNavigationHandled,
  ...surveyContentProps
}: SurveyAppRootProps) {
  const navigate = useNavigate();
  const appChrome = useAppChrome();
  const { resetToStart, enterSurveyMode, beginSurvey } = bootstrap;

  const {
    dispatch,
    draft,
    report: calcReport,
    canAutoCalc,
    setReportFromProject,
    state: sessionState,
  } = useSurveySession();

  const draftRef = useRef(draft);

  useEffect(() => {
    draftRef.current = draft;
  }, [draft]);

  const [clientName, setClientName] = useState(draftMeta.clientName);
  const [projectId, setProjectId] = useState<string | null>(draftMeta.projectId);

  const applySurveyDraftState = useCallback(
    (loaded: SurveyDraft) => {
      dispatch({
        type: 'DRAFT_LOADED',
        draft: surveyDraftToSessionSnapshot(loaded),
        lastCalcReport: loaded.lastCalcReport ?? null,
      });
    },
    [dispatch],
  );

  const buildCalcPayload = useCallback(
    () => buildCalcPayloadFromDraft(draftRef.current, surveyContentProps.windowPresetsList),
    [surveyContentProps.windowPresetsList],
  );

  const getDraftParams = useCallback(
    () => ({
      currentStep: draftRef.current.currentStep,
      objectMeta: draftRef.current.objectMeta,
      rooms: draftRef.current.rooms,
      temps: draftRef.current.temps,
      hotWaterForm: draftRef.current.hotWaterForm,
      waterHeaterForm: draftRef.current.waterHeaterForm,
      waterUnderfloorHeating: draftRef.current.waterUnderfloorHeating,
      underfloorDistributionPreset: draftRef.current.underfloorDistributionPreset,
      thermalRegimePreset: draftRef.current.thermalRegimePreset,
      radiatorConnection: draftRef.current.radiatorConnection,
      radiatorEmitterPreference: draftRef.current.radiatorEmitterPreference,
      ufhPresetId: draftRef.current.ufhPresetId,
      hydraulicsForm: draftRef.current.hydraulicsForm,
      wiringLayoutV3: draftRef.current.wiringLayoutV3,
      lastCalcReport: calcReport,
    }),
    [calcReport],
  );

  const needsResetConfirm = useCallback(() => {
    if (calcReport != null) return true;
    return draftRef.current.rooms.some(
      (r) => typeof r.areaM2 === 'number' && r.areaM2 > 0,
    );
  }, [calcReport]);

  const runManualCalc = useCallback(() => {
    dispatch({ type: 'RUN_CALC_MANUAL' });
  }, [dispatch]);

  const surveyProject = useSurveyProject({
    bootstrapMode: 'survey',
    clientName,
    setClientName,
    projectId,
    setProjectId,
    getDraftParams,
    applyDraft: applySurveyDraftState,
    enterSurveyMode,
    resetToStart,
    needsResetConfirm,
    buildCalcPayload,
    canRunCalc: canAutoCalc,
    setCalcReport: setReportFromProject,
    runManualCalc,
  });

  const {
    fileInputRef,
    handleFileInputChange,
    statusMessage,
    statusError,
    projectsOpen,
    setProjectsOpen,
    projectsLoading,
    projectList,
    calculations,
    canPrintPdf,
    canPublishShare,
    canSaveProject,
    saveProjectBusy,
    shareBusy,
    shareToastOpen,
    dismissShareToast,
    saveProjectDraft,
    saveToFile,
    exportProjectBundleToFile,
    exportBusy,
    openImportFilePicker,
    importBusy,
    saveToServer,
    openFilePicker,
    exportTextFile,
    exportHashLink,
    copyPublicLink,
    revokeShare,
    printPdf,
    exitProject,
    loadProjectById,
    loadCalculationById,
    startNewProject,
    refreshProjectList,
    buildDraft,
  } = surveyProject;

  const { canShowDevPanel, showDevToolsDock } = useDevPanelAccess();

  useSurveyDraftPersistence({
    bootstrapMode: 'survey',
    calcInputKey: sessionState.calcInputKey,
    clientName,
    projectId,
    getDraftParams,
  });

  const handleNewCalculation = useCallback(() => {
    if (needsResetConfirm()) {
      const ok = window.confirm(footerUk.confirmNewCalculation);
      if (!ok) return;
    }
    beginSurvey();
  }, [needsResetConfirm, beginSurvey]);

  const handleOpenProjects = useCallback(() => {
    void navigate(paths.projects);
  }, [navigate]);

  useEffect(() => {
    appChrome.registerFooterActions({
      onNewCalculation: handleNewCalculation,
      onOpenProjects: handleOpenProjects,
    });
    return () => {
      appChrome.unregisterFooterActions();
    };
  }, [appChrome, handleNewCalculation, handleOpenProjects]);

  useEffect(() => {
    if (!pendingNavigation) return;
    if (pendingNavigation.kind === 'newProject') {
      handleNewCalculation();
      onPendingNavigationHandled();
      return;
    }
    if (pendingNavigation.kind === 'project') {
      void loadProjectById(pendingNavigation.projectId);
      onPendingNavigationHandled();
      return;
    }
    void loadCalculationById(pendingNavigation.calculationId);
    onPendingNavigationHandled();
  }, [
    pendingNavigation,
    handleNewCalculation,
    loadProjectById,
    loadCalculationById,
    onPendingNavigationHandled,
  ]);

  const headerProps: HeaderProps = {
    logo: <Logo />,
    title: brandUk.name,
    accountSlot: <AccountBar compact />,
    clientName,
    onClientNameChange: setClientName,
    projectId,
    statusMessage,
    statusError,
    canPrintPdf,
    canPublishShare,
    canSaveProject,
    saveProjectBusy,
    shareBusy,
    shareToastOpen,
    onDismissShareToast: dismissShareToast,
    onOpenProjects: handleOpenProjects,
    onSaveProject: saveProjectDraft,
    onExit: exitProject,
    onCopyPublicLink: () => {
      void copyPublicLink();
    },
    onPrintPdf: printPdf,
  };

  const sharedFileInput = (
    <input
      ref={fileInputRef}
      type="file"
      accept="application/json,.json"
      className={styles.hiddenInput}
      onChange={handleFileInputChange}
    />
  );

  const sharedProjectsDialog = projectsOpen ? (
    <Suspense fallback={null}>
      <ProjectsDialog
        open={projectsOpen}
        loading={projectsLoading}
        projects={projectList}
        calculations={calculations}
        activeProjectId={projectId}
        onClose={() => {
          setProjectsOpen(false);
        }}
        onRefresh={() => {
          void refreshProjectList();
        }}
        onNewProject={startNewProject}
        onSelectProject={(id) => {
          void loadProjectById(id);
        }}
        onSelectCalculation={(id) => {
          void loadCalculationById(id);
        }}
      />
    </Suspense>
  ) : null;

  const devToolsDock = showDevToolsDock ? (
    <DevToolsDock>
      {canShowDevPanel ? (
        <Suspense fallback={null}>
          <DevPanel
            projectId={projectId}
            canRunCalc={canAutoCalc}
            calcReport={calcReport}
            buildCalcPayload={buildCalcPayload}
            buildDraftJson={() => buildDraft()}
            onSaveFile={saveToFile}
            onExportProject={() => {
              void exportProjectBundleToFile();
            }}
            exportBusy={exportBusy}
            onImportProject={openImportFilePicker}
            importBusy={importBusy}
            onSaveServer={(withCalc) => {
              void saveToServer(withCalc);
            }}
            onOpenFile={openFilePicker}
            onExportText={exportTextFile}
            onExportHashLink={() => {
              void exportHashLink();
            }}
            onRunManualCalc={runManualCalc}
            onRevokeShare={() => {
              void revokeShare();
            }}
          />
        </Suspense>
      ) : null}
    </DevToolsDock>
  ) : null;

  return (
    <>
      {sharedFileInput}
      <Suspense fallback={<AppBootstrapSkeleton statusLabel="Завантаження анкети…" />}>
        <AppSurveyContent {...surveyContentProps} projectChrome={headerProps} />
      </Suspense>
      {sharedProjectsDialog}
      {devToolsDock}
    </>
  );
}

/**
 * Назначение: Clerk session → AuthContext + getToken() для projects API.
 * Описание: окремий чанк — імпортується лише коли ClerkLazyRoot активує Clerk.
 */

import { useAuth as useClerkAuth, useUser } from '@clerk/clerk-react';
import { useCallback, useEffect, useLayoutEffect, useMemo, type ReactNode } from 'react';

import { setProjectsAuthTokenGetter } from '../services/projectsAuthToken';
import {
  clearStoredAuthToken,
  decodeJwtPayload,
  getClerkJwtTemplate,
  isAuthRequiredInFrontend,
  isClerkEnabled,
  resolveClerkJwtTemplateForApi,
  writeStoredAuthToken,
} from './authConfig';
import { AuthContext, type AuthUser } from './authContext';
import { useAuthMeCacheSync } from './useAuthMeCacheSync';

export type ClerkAuthProviderInnerProps = {
  children: ReactNode;
};

/**
 * @param props
 */
export function ClerkAuthProviderInner({ children }: ClerkAuthProviderInnerProps) {
  const { getToken, isSignedIn, signOut, isLoaded } = useClerkAuth();
  const { user: clerkUser } = useUser();
  const jwtTemplate = resolveClerkJwtTemplateForApi();
  const isAuthRequired = isAuthRequiredInFrontend();
  const { refreshMeProfile, clearMeProfile } = useAuthMeCacheSync();
  const clerkSessionReady = isLoaded && isSignedIn;

  useEffect(() => {
    if (import.meta.env.DEV && isClerkEnabled() && !getClerkJwtTemplate()) {
      console.warn(
        `[auth] VITE_CLERK_JWT_TEMPLATE не задан — используется "${jwtTemplate}". ` +
          'Создайте JWT template в Clerk с claim email и aud = AUTH_AUDIENCE.',
      );
    }
  }, [jwtTemplate]);

  useLayoutEffect(() => {
    if (!clerkSessionReady) {
      setProjectsAuthTokenGetter(null);
      return;
    }

    setProjectsAuthTokenGetter(async () => {
      try {
        const token = await getToken({ template: jwtTemplate });
        if (token && import.meta.env.DEV) {
          const payload = decodeJwtPayload(token);
          if (!payload?.email) {
            console.warn(
              `[auth] JWT template "${jwtTemplate}" без claim email. ` +
                'Clerk Dashboard → JWT Templates → добавьте email: {{user.primary_email_address}}',
            );
          }
        }
        return token;
      } catch {
        return null;
      }
    });

    return () => {
      setProjectsAuthTokenGetter(null);
    };
  }, [getToken, clerkSessionReady, jwtTemplate]);

  useEffect(() => {
    if (!clerkSessionReady) return;
    refreshMeProfile();
  }, [clerkSessionReady, refreshMeProfile]);

  const user = useMemo((): AuthUser | null => {
    if (!isLoaded || !isSignedIn || !clerkUser) return null;
    const emailAddress = clerkUser.primaryEmailAddress?.emailAddress;
    const email = typeof emailAddress === 'string' ? emailAddress.trim() : undefined;
    return email ? { sub: clerkUser.id, email } : { sub: clerkUser.id };
  }, [clerkUser, isLoaded, isSignedIn]);

  const loginWithToken = useCallback(
    (token: string) => {
      const trimmed = token.trim();
      if (!trimmed) return;
      writeStoredAuthToken(trimmed);
      refreshMeProfile();
    },
    [refreshMeProfile],
  );

  const logout = useCallback(async () => {
    clearMeProfile();
    clearStoredAuthToken();
    await signOut();
  }, [clearMeProfile, signOut]);

  const isMeQueryEnabled = !isAuthRequired || clerkSessionReady;

  const value = useMemo(
    () => ({
      user,
      isAuthenticated: !isAuthRequired || clerkSessionReady,
      isMeQueryEnabled,
      isAuthRequired,
      loginWithToken,
      logout,
    }),
    [
      user,
      isAuthRequired,
      clerkSessionReady,
      isMeQueryEnabled,
      loginWithToken,
      logout,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

/**
 * Назначение: единая панель сессии — «Увійти», email, tier badge, logout.
 * Профиль tier/email — только из GET /api/v1/me (не JWT decode).
 */

import { Link, useLocation } from 'react-router';

import { useAuth } from '../../auth/useAuth';
import { adminFeedbackUk } from '../../i18n/uk/adminFeedback';
import { authUk } from '../../i18n/uk/auth';
import { useMeQuery } from '../../query/queries/useMeQuery';
import { MeApiError } from '../../services/meApi';
import { paths } from '../../routing/paths';
import { SubscriptionTierBadge } from '../SubscriptionTierBadge/SubscriptionTierBadge';
import styles from './AccountBar.module.css';

export type AccountBarProps = {
  className?: string | undefined;
  /** Компактный вид для шапки анкеты. */
  compact?: boolean;
};

/**
 * @param error
 * @returns {boolean}
 */
function isUnauthorizedMeError(error: Error | null): boolean {
  return error instanceof MeApiError && error.statusCode === 401;
}

/**
 * @param props
 */
export function AccountBar({ className, compact = false }: AccountBarProps) {
  const { isAuthenticated, isAuthRequired, logout } = useAuth();
  const { user: meUser, meLoading, meError } = useMeQuery();
  const location = useLocation();

  const loginTo = `${paths.login}?returnTo=${encodeURIComponent(
    `${location.pathname}${location.search}`,
  )}`;

  const rootClass = [
    styles.bar,
    compact ? styles.compact : '',
    className ?? '',
  ]
    .filter(Boolean)
    .join(' ');

  const showLogin =
    (isAuthRequired && !isAuthenticated) ||
    (isAuthRequired && isAuthenticated && isUnauthorizedMeError(meError));

  if (showLogin) {
    return (
      <div className={rootClass}>
        <Link to={loginTo} className={styles.loginButton}>
          {authUk.loginButton}
        </Link>
      </div>
    );
  }

  if (meLoading && !meUser) {
    return (
      <div className={rootClass} aria-busy="true" aria-live="polite">
        <div className={styles.skeleton} aria-hidden="true" />
      </div>
    );
  }

  if (!meUser) {
    if (meError && !isUnauthorizedMeError(meError)) {
      const errorText =
        meError.message.includes('JWT') || meError.message.includes('claim email')
          ? authUk.jwtTemplateError
          : meError.message.includes('Clerk JWT template')
            ? meError.message
            : authUk.profileLoadError;
      return (
        <div className={rootClass}>
          <span className={styles.error} role="alert">
            {errorText}
          </span>
          {isAuthenticated ? (
            <button
              type="button"
              className={styles.logoutButton}
              onClick={() => {
                void logout();
              }}
            >
              {authUk.logoutButton}
            </button>
          ) : null}
        </div>
      );
    }
    return null;
  }

  return (
    <div className={rootClass}>
      <span className={styles.email} aria-label={`${authUk.accountEmailAria}: ${meUser.email}`}>
        {meUser.email}
      </span>
      <SubscriptionTierBadge tier={meUser.subscription} devMode={meUser.devMode === true} />
      {meUser.role === 'admin' ? (
        <Link to={paths.adminFeedback} className={styles.adminLink}>
          {adminFeedbackUk.accountLink}
        </Link>
      ) : null}
      {isAuthRequired || meUser.authProvider != null ? (
        <button
          type="button"
          className={styles.logoutButton}
          onClick={() => {
            void logout();
          }}
        >
          {authUk.logoutButton}
        </button>
      ) : null}
    </div>
  );
}

/**
 * Назначение: Карточка предложения котла.
 * Описание: Мощность, цена, каскад, запас номинала и разбивка по контурам из отчёта.
 */

import {
  formatBrandModel,
  formatKw,
  formatLiters,
  formatPercent,
  formatPriceUah,
} from '../../utils/format';
import styles from './BoilerProposalCard.module.css';

/** Верхний предел процента запаса по отоплению при ограничении модуляцией (согласовано с matching/boiler.js). */
const HEATING_RESERVE_MODULATION_CAP_PERCENT = 150;

/** Фрагмент отчёта API: report.matching.boiler.proposal (+ proposalEconomy / proposalEfficient) */
export interface BoilerProposalPowerBreakdownView {
  heatingLoadKw: number;
  hotWaterPowerKw: number;
}

export interface EquipmentBundlePriceBreakdownView {
  boilerPrice?: number;
  waterHeaterPrice?: number;
  indirectWaterHeaterPrice?: number;
}

export interface EquipmentBundleCompanionView {
  role: 'water_heater' | 'indirect_water_heater';
  model: string;
  brand?: string;
  volumeLiters?: number;
  price?: number;
}

export interface BoilerProposalView {
  kind: 'single' | 'cascade';
  headline: string;
  model: string;
  unitsCount: number;
  unitMaxPowerKw: number;
  totalNominalKw: number;
  requiredKw: number;
  /** Строки «из них на отопление / ГВС» в блоке цифр. */
  powerRequirementBreakdown: BoilerProposalPowerBreakdownView;
  nominalReservePercent: number;
  /** Линия подбора с API (economy | efficient). */
  tier?: 'economy' | 'efficient';
  estimatedTotalPrice?: number;
  /** Сумма котла и сопутствующего ГВС-оборудования (электробойлер и/или БКН). */
  equipmentBundleTotalPrice?: number;
  equipmentBundlePriceBreakdown?: EquipmentBundlePriceBreakdownView;
  equipmentBundleCompanions?: EquipmentBundleCompanionView[];
  mountingType?: 'wall' | 'floor';
  connectionDiameters?: string[];
  advantages: string[];
  notes: string[];
}

function companionRoleLabel(role: EquipmentBundleCompanionView['role']): string {
  return role === 'water_heater' ? 'Електробойлер' : 'БКН';
}

function formatCompanionLine(c: EquipmentBundleCompanionView): string {
  const title = formatBrandModel(c.brand, c.model);
  if (c.volumeLiters != null) {
    return `${title}, ${formatLiters(c.volumeLiters)} л`;
  }
  return title;
}

function mountingLabel(m?: string): string | null {
  if (m === 'wall') return 'настінний';
  if (m === 'floor') return 'напольний';
  return null;
}

export function BoilerProposalCard({
  proposal,
  catalogSource,
  sectionTitle = 'Рекомендоване рішення',
  titleDomId = 'boiler-proposal-title',
}: {
  proposal: BoilerProposalView;
  catalogSource?: 'file' | 'mongo' | null;
  /** Заголовок карточки (например «Вариант: эконом класс»). */
  sectionTitle?: string;
  /** Уникальный id для aria-labelledby при нескольких карточках. */
  titleDomId?: string;
}) {
  const mount = mountingLabel(proposal.mountingType);
  const qtyLabel =
    proposal.kind === 'cascade'
      ? `${proposal.unitsCount} од. (каскад)`
      : `${proposal.unitsCount} од.`;

  const sourceLine =
    catalogSource === 'mongo'
      ? 'Підбір за каталогом із бази даних (MongoDB).'
      : catalogSource === 'file'
        ? 'Підбір за каталогом із файлу (локальні дані API).'
        : null;

  const { heatingLoadKw: heatPart, hotWaterPowerKw: dhwPart } =
    proposal.powerRequirementBreakdown;

  const reserveLabel =
    proposal.kind === 'single' ? 'Запас за опаленням' : 'Запас за номіналом до розрахунку';
  const reservePctFormatted =
    proposal.kind === 'single' && Number.isInteger(proposal.nominalReservePercent)
      ? String(proposal.nominalReservePercent)
      : formatPercent(proposal.nominalReservePercent);
  const reservePctSigned =
    proposal.nominalReservePercent > 0
      ? `+${reservePctFormatted}`
      : reservePctFormatted;
  const modulationCapped =
    proposal.kind === 'single' &&
    proposal.nominalReservePercent >= HEATING_RESERVE_MODULATION_CAP_PERCENT;

  return (
    <div className={styles.card} aria-labelledby={titleDomId}>
      <h4 id={titleDomId} className={styles.title}>
        {sectionTitle}
      </h4>
      {sourceLine != null && <p className={styles.catalogSource}>{sourceLine}</p>}
      <div className={styles.powerBlock}>
        <p className={styles.powerPeak}>
          Необхідна потужність:{' '}
          <strong>{formatKw(proposal.requiredKw)} кВт</strong>
        </p>
        <p className={styles.powerSub}>
          ── з них на опалення: <strong>{formatKw(heatPart)} кВт</strong>
        </p>
        <p className={styles.powerSub}>
          ── з них на гарячу воду (ГВП):{' '}
          <strong>{formatKw(dhwPart)} кВт</strong>
        </p>
      </div>
      <p className={styles.solutionLine}>
        Запропоноване рішення: {proposal.headline} —{' '}
        <strong>{formatKw(proposal.totalNominalKw, 1)} кВт</strong>
      </p>
      <p className={styles.heatingReserveLine}>
        {reserveLabel}: {reservePctSigned}%
        {modulationCapped ? (
          <span className={styles.modHint}> (обмежено модуляцією)</span>
        ) : null}
      </p>
      <dl className={styles.dl}>
        <dt>Котел</dt>
        <dd>{proposal.model}</dd>
        {proposal.equipmentBundleCompanions?.map((c, i) => (
          <div key={`${c.role}-${i}-${c.model}`} className={styles.companionPair}>
            <dt>{companionRoleLabel(c.role)}</dt>
            <dd>{formatCompanionLine(c)}</dd>
          </div>
        ))}
        <dt>Кількість</dt>
        <dd>{qtyLabel}</dd>
        {proposal.estimatedTotalPrice != null && (
          <>
            <dt>Орієнтовна вартість котла</dt>
            <dd>
              {formatPriceUah(proposal.estimatedTotalPrice)}{' '}
              грн
              {proposal.unitsCount > 1 ? ' (усі одиниці)' : ''}
            </dd>
          </>
        )}
        {proposal.equipmentBundleTotalPrice != null && (
          <>
            <dt className={styles.bundleTotalLabel}>Разом за варіантом</dt>
            <dd className={styles.bundleTotalValue}>
              {formatPriceUah(proposal.equipmentBundleTotalPrice)} грн
              {proposal.equipmentBundlePriceBreakdown != null && (
                <ul className={styles.bundleBreakdown}>
                  {proposal.equipmentBundlePriceBreakdown.boilerPrice != null && (
                    <li>
                      Котел:{' '}
                      {formatPriceUah(
                        proposal.equipmentBundlePriceBreakdown.boilerPrice,
                      )}{' '}
                      грн
                    </li>
                  )}
                  {proposal.equipmentBundlePriceBreakdown.waterHeaterPrice !=
                    null && (
                    <li>
                      Електробойлер:{' '}
                      {formatPriceUah(
                        proposal.equipmentBundlePriceBreakdown.waterHeaterPrice,
                      )}{' '}
                      грн
                    </li>
                  )}
                  {proposal.equipmentBundlePriceBreakdown
                    .indirectWaterHeaterPrice != null && (
                    <li>
                      БКН:{' '}
                      {formatPriceUah(
                        proposal.equipmentBundlePriceBreakdown
                          .indirectWaterHeaterPrice,
                      )}{' '}
                      грн
                    </li>
                  )}
                </ul>
              )}
            </dd>
          </>
        )}
        {mount != null && (
          <>
            <dt>Тип установки</dt>
            <dd>{mount}</dd>
          </>
        )}
        {proposal.connectionDiameters != null && proposal.connectionDiameters.length > 0 && (
          <>
            <dt>Приєднання</dt>
            <dd>{proposal.connectionDiameters.join(', ')}</dd>
          </>
        )}
      </dl>
      {proposal.advantages.length > 0 && (
        <div className={styles.block}>
          <div className={styles.blockTitle}>Переваги</div>
          <ul className={styles.list}>
            {proposal.advantages.map((t, i) => (
              <li key={`${i}-${t.slice(0, 40)}`}>{t}</li>
            ))}
          </ul>
        </div>
      )}
      {proposal.notes.length > 0 && (
        <div className={styles.notes}>
          {proposal.notes.map((t, i) => (
            <p key={`${i}-${t.slice(0, 40)}`} className={styles.note}>
              {t}
            </p>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Призначення: модальне вікно звіту підбору котла.
 * Опис: Патерн RadiatorsReportDialog; контент — BoilerReportView.
 */

import { useEffect } from 'react';

import type { ObjectType } from '../../types/envelope';
import type { ParsedBoilerMatching } from '../../utils/parsers/parseBoilerFromReport';
import { BoilerReportView } from './BoilerReportView';
import { hasBoilerReportContent } from './hasBoilerReportContent';
import styles from './BoilerReportDialog.module.css';

export type BoilerReportDialogProps = {
  open: boolean;
  onClose: () => void;
  boiler: ParsedBoilerMatching | null;
  objectType: ObjectType;
  catalogSource?: 'file' | 'mongo' | null;
};

/**
 * @param props
 */
export function BoilerReportDialog({
  open,
  onClose,
  boiler,
  objectType,
  catalogSource = null,
}: BoilerReportDialogProps) {
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [open, onClose]);

  if (!open) return null;

  const hasContent = hasBoilerReportContent(boiler);

  return (
    <div
      className={styles.backdrop}
      role="presentation"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className={styles.dialog}
        role="dialog"
        aria-modal="true"
        aria-labelledby="boiler-report-dialog-title"
        onClick={(e) => {
          e.stopPropagation();
        }}
      >
        <div className={styles.header}>
          <h2 id="boiler-report-dialog-title" className={styles.title}>
            Звіт із підбору котла
          </h2>
          <button
            type="button"
            className={styles.closeIconButton}
            onClick={onClose}
            aria-label="Закрити"
          >
            ✕
          </button>
        </div>

        {hasContent && boiler != null ? (
          <BoilerReportView
            boiler={boiler}
            objectType={objectType}
            catalogSource={catalogSource}
          />
        ) : (
          <p className={styles.empty}>
            Немає даних підбору котла. Заповніть приміщення та огородження, задайте
            графік опалення та сценарій ГВП, дочекайтеся авторасчунку.
          </p>
        )}

        <button type="button" className={styles.closeButton} onClick={onClose}>
          Закрити
        </button>
      </div>
    </div>
  );
}

/**
