/**
 * Назначение: модальное окно «Зворотний зв'язок».
 */

import { useCallback, useState } from 'react';

import { modalsUk } from '../../i18n/uk/modals';
import { submitFeedback } from '../../services/feedbackApi';
import { ModalDialog } from '../ModalDialog/ModalDialog';
import modalDialogStyles from '../ModalDialog/ModalDialog.module.css';

export type ContactModalProps = {
  open: boolean;
  onClose: () => void;
};

/**
 * @param props
 */
export function ContactModal({ open, onClose }: ContactModalProps) {
  const t = modalsUk.contact;
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<'idle' | 'ok' | 'err'>('idle');

  const resetAndClose = useCallback(() => {
    setName('');
    setEmail('');
    setMessage('');
    setStatus('idle');
    onClose();
  }, [onClose]);

  const onSubmit = useCallback(() => {
    const trimmed = message.trim();
    const emailTrimmed = email.trim();
    if (!trimmed || !emailTrimmed || busy) return;
    setBusy(true);
    setStatus('idle');
    void (async () => {
      try {
        await submitFeedback({
          type: 'contact',
          message: trimmed,
          email: emailTrimmed,
          ...(name.trim() ? { name: name.trim() } : {}),
          pageUrl: window.location.href,
          appVersion: __APP_VERSION__,
          buildId: __APP_BUILD_ID__,
        });
        setStatus('ok');
        setTimeout(resetAndClose, 1200);
      } catch {
        setStatus('err');
      } finally {
        setBusy(false);
      }
    })();
  }, [name, email, message, busy, resetAndClose]);

  return (
    <ModalDialog open={open} title={t.title} description={t.description} onClose={resetAndClose}>
      {status === 'ok' ? <p className={modalDialogStyles.statusOk}>{t.success}</p> : null}
      {status === 'err' ? <p className={modalDialogStyles.statusErr}>{t.error}</p> : null}
      <label className={modalDialogStyles.field}>
        <span className={modalDialogStyles.label}>{t.nameLabel}</span>
        <input
          type="text"
          className={modalDialogStyles.input}
          value={name}
          onChange={(e) => {
            setName(e.target.value);
          }}
          placeholder={t.namePlaceholder}
          maxLength={120}
          autoComplete="name"
        />
      </label>
      <label className={modalDialogStyles.field}>
        <span className={modalDialogStyles.label}>{t.emailLabel}</span>
        <input
          type="email"
          className={modalDialogStyles.input}
          value={email}
          onChange={(e) => {
            setEmail(e.target.value);
          }}
          placeholder={t.emailPlaceholder}
          required
          maxLength={200}
          autoComplete="email"
        />
      </label>
      <label className={modalDialogStyles.field}>
        <span className={modalDialogStyles.label}>{t.messageLabel}</span>
        <textarea
          className={modalDialogStyles.textarea}
          value={message}
          onChange={(e) => {
            setMessage(e.target.value);
          }}
          placeholder={t.messagePlaceholder}
          required
          maxLength={4000}
        />
      </label>
      <div className={modalDialogStyles.actions}>
        <button
          type="button"
          className={modalDialogStyles.primary}
          disabled={busy || !message.trim() || !email.trim()}
          onClick={onSubmit}
        >
          {t.submit}
        </button>
        <button type="button" className={modalDialogStyles.secondary} onClick={resetAndClose}>
          {t.cancel}
        </button>
      </div>
    </ModalDialog>
  );
}

/**
 * Назначение: панель разработчика — JSON, server save, payload (клиент не видит).
 */

import { useCallback, useState } from 'react';

import styles from './DevPanel.module.css';

export type DevPanelProps = {
  projectId: string | null;
  canRunCalc: boolean;
  calcReport: unknown;
  buildCalcPayload: () => unknown;
  buildDraftJson: () => unknown;
  onSaveFile: () => void;
  onExportProject: () => void;
  exportBusy?: boolean;
  onImportProject: () => void;
  importBusy?: boolean;
  onSaveServer: (withCalc: boolean) => void;
  onOpenFile: () => void;
  onExportText: () => void;
  onExportHashLink: () => void;
  onRunManualCalc: () => void;
  onRevokeShare?: () => void;
};

type JsonViewId = 'draft' | 'payload' | 'report' | 'modules';

/**
 * @param props
 */
export function DevPanel({
  projectId,
  canRunCalc,
  calcReport,
  buildCalcPayload,
  buildDraftJson,
  onSaveFile,
  onExportProject,
  exportBusy = false,
  onImportProject,
  importBusy = false,
  onSaveServer,
  onOpenFile,
  onExportText,
  onExportHashLink,
  onRunManualCalc,
  onRevokeShare,
}: DevPanelProps) {
  const [open, setOpen] = useState(false);
  const [view, setView] = useState<JsonViewId | null>(null);
  const [jsonText, setJsonText] = useState('');

  const showJson = useCallback(
    (id: JsonViewId) => {
      try {
        let data: unknown;
        if (id === 'draft') data = buildDraftJson();
        else if (id === 'payload') data = buildCalcPayload();
        else if (id === 'report') data = calcReport;
        else {
          const report =
            calcReport && typeof calcReport === 'object'
              ? (calcReport as Record<string, unknown>)
              : null;
          data = {
            commercial: report?.commercial ?? null,
            matching: report?.matching ?? null,
            calculations: report?.calculations ?? null,
            meta: report?.meta ?? null,
            warnings: report?.warnings ?? null,
          };
        }
        setJsonText(JSON.stringify(data, null, 2));
        setView(id);
      } catch (e) {
        setJsonText(e instanceof Error ? e.message : 'Помилка серіалізації');
        setView(id);
      }
    },
    [buildCalcPayload, buildDraftJson, calcReport],
  );

  if (!open) {
    return (
      <button
        type="button"
        className={styles.fab}
        onClick={() => {
          setOpen(true);
        }}
        title="Панель розробника"
      >
        Dev
      </button>
    );
  }

  return (
    <aside className={styles.panel} aria-label="Панель розробника">
      <div className={styles.head}>
        <strong>Developer</strong>
        <button
          type="button"
          className={styles.close}
          onClick={() => {
            setOpen(false);
            setView(null);
          }}
        >
          Закрити
        </button>
      </div>
      <p className={styles.hint}>
        Клієнт цей шар не бачить. Project id:{' '}
        <code>{projectId ?? '—'}</code>
      </p>
      <div className={styles.actions}>
        <button type="button" onClick={onOpenFile}>
          Відкрити JSON
        </button>
        <button type="button" onClick={onSaveFile}>
          Зберегти JSON
        </button>
        <button type="button" disabled={exportBusy} onClick={onExportProject}>
          {exportBusy ? 'Експорт…' : '📥 Експорт (Save JSON)'}
        </button>
        <button type="button" disabled={importBusy} onClick={onImportProject}>
          {importBusy ? 'Імпорт…' : '📤 Імпорт (Load JSON)'}
        </button>
        <button
          type="button"
          onClick={() => {
            onSaveServer(false);
          }}
        >
          На сервер
        </button>
        <button
          type="button"
          onClick={() => {
