export function Header({
  logo,
  title,
  accountSlot,
  variant = 'survey',
  clientName,
  onClientNameChange,
  projectId,
  statusMessage,
  statusError,
  canPrintPdf = false,
  canPublishShare = false,
  canSaveProject = false,
  saveProjectBusy = false,
  shareBusy = false,
  shareToastOpen = false,
  onDismissShareToast,
  onOpenProjects,
  onSaveProject,
  onExit,
  onCopyPublicLink,
  onPrintPdf,
}: HeaderProps) {
  const [pdfMenuOpen, setPdfMenuOpen] = useState(false);
  const controlsRef = useRef<HTMLDivElement>(null);
  const { user: meUser } = useMeQuery();

  const sharePublisherHint =
    meUser?.subscription === 'pro'
      ? headerUk.sharePublisherHintPro
      : meUser?.subscription === 'marketplace'
        ? headerUk.sharePublisherHintMarketplace
        : null;

  const closeMenus = useCallback(() => {
    setPdfMenuOpen(false);
  }, []);

  useEffect(() => {
    if (!pdfMenuOpen) return;

    const onPointerDown = (e: PointerEvent) => {
      const target = e.target;
      if (target instanceof Node && controlsRef.current?.contains(target)) return;
      setPdfMenuOpen(false);
    };

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setPdfMenuOpen(false);
    };

    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('pointerdown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [pdfMenuOpen]);

  return (
    <header className={styles.header}>
      <div className={styles.brand}>
        <div className={styles.logoSlot} aria-hidden={logo ? undefined : 'true'}>
          {logo ?? <div className={styles.logoMark} aria-hidden="true" />}
