            placeholder={headerUk.clientNamePlaceholder}
            maxLength={200}
            autoComplete="off"
            aria-label={headerUk.clientNameAria}
          />
        ) : null}

        {accountSlot ? <div className={styles.accountSlot}>{accountSlot}</div> : null}

        <button
          type="button"
          className={`${styles.secondaryButton} ${styles.projectsButton}`}
          data-testid="header-projects"
          onClick={() => {
            closeMenus();
            onOpenProjects();
          }}
        >
          {headerUk.projects}
        </button>

        {variant === 'survey' ? (
          <>
            <button
              type="button"
              className={styles.secondaryButton}
              data-testid="header-save"
              disabled={!canSaveProject || saveProjectBusy}
              aria-busy={saveProjectBusy}
              title={
                saveProjectBusy
                  ? headerUk.saveProjectBusy
                  : canSaveProject
                    ? headerUk.saveProjectTitle
                    : headerUk.saveProjectDisabled
              }
              onClick={() => {
                closeMenus();
                onSaveProject();
              }}
            >
              {saveProjectBusy ? headerUk.saveProjectBusy : headerUk.saveProject}
            </button>

            <div className={styles.shareLinkWrap}>
              <button
                type="button"
                className={styles.secondaryButton}
                data-testid="header-share"
                disabled={!canPublishShare || shareBusy}
                aria-busy={shareBusy}
                title={
                  shareBusy
                    ? headerUk.linkPublishing
                    : canPublishShare
                      ? headerUk.linkShareTitle
                      : headerUk.linkShareDisabled
                }
                onClick={() => {
                  closeMenus();
                  onCopyPublicLink();
                }}
              >
                {shareBusy ? headerUk.linkPublishing : headerUk.link}
              </button>
              {onDismissShareToast ? (
                <ShareLinkToast open={shareToastOpen} onDismiss={onDismissShareToast} />
              ) : null}
              {sharePublisherHint ? (
                <p className={styles.sharePublisherHint}>{sharePublisherHint}</p>
              ) : null}
            </div>

            <div className={styles.menu}>
              <button
                type="button"
                className={
                  pdfMenuOpen
                    ? `${styles.primaryButton} ${styles.menuTriggerActivePrimary}`
                    : styles.primaryButton
                }
                data-testid="header-pdf"
                disabled={!canPrintPdf}
                aria-expanded={pdfMenuOpen}
                aria-haspopup="menu"
                onClick={() => {
                  setPdfMenuOpen((v) => !v);
                }}
              >
                {headerUk.pdfDownload}
              </button>
              {pdfMenuOpen ? (
                <div className={styles.menuPanel} role="menu">
                  <button
                    type="button"
                    role="menuitem"
                    data-testid="pdf-financial"
                    onClick={() => {
                      onPrintPdf(false);
                      closeMenus();
