/**
 * Назначение: Модальное окно полного отчёта ГВС.
 * Описание: Точки из анкеты всегда; расчёт API — когда есть; без блокировки точек calc-ом.
 */

import { useEffect } from 'react';

import type { HotWaterFormValue } from '../../types/hotWater';
import type { ParsedHotWaterReport } from '../../types/hotWaterReport';
import { hasHotWaterFixturesContent } from '../../utils/countThermalFixtures';
import { normalizeHotWaterForm } from '../../utils/normalizeHotWaterForm';
import { HotWaterReportView } from './HotWaterReportView';
import { hasHotWaterReportContent } from './hasHotWaterReportContent';
import styles from './HotWaterReportDialog.module.css';

export type HotWaterReportDialogProps = {
  open: boolean;
  onClose: () => void;
  hotWater: ParsedHotWaterReport | null;
  /** Анкета ГВ — обязательна для таблицы точек. */
  formValue: HotWaterFormValue;
};

/**
 * @param props
 */
export function HotWaterReportDialog({
  open,
  onClose,
  hotWater,
  formValue,
}: HotWaterReportDialogProps) {
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [open, onClose]);

  if (!open) return null;

  const form = normalizeHotWaterForm(formValue);
  const hasFixtures = hasHotWaterFixturesContent(form.fixtures);
  const hasCalc = hasHotWaterReportContent(hotWater);
  const hasAnything = hasFixtures || hasCalc;

  return (
    <div
      className={styles.backdrop}
      role="presentation"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className={styles.dialog}
        role="dialog"
        aria-modal="true"
        aria-labelledby="hot-water-report-dialog-title"
        onClick={(e) => {
          e.stopPropagation();
        }}
      >
        <div className={styles.header}>
          <h2 id="hot-water-report-dialog-title" className={styles.title}>
            Звіт із розрахунку ГВ
          </h2>
          <button
            type="button"
            className={styles.closeIconButton}
            onClick={onClose}
            aria-label="Закрити"
          >
            ✕
          </button>
        </div>

        {hasAnything ? (
          <HotWaterReportView
            hotWater={hasCalc ? hotWater : null}
            formValue={form}
          />
        ) : (
          <p className={styles.empty}>
            Вкажіть точки водорозбору на кроці «Гаряча вода». Розрахункові
            показники з&apos;являться після авторасчунку.
          </p>
        )}

        <button type="button" className={styles.closeButton} onClick={onClose}>
          Закрити
        </button>
      </div>
    </div>
  );
}

/**
 * Назначение: Полный отчёт расчёта ГВС.
 * Описание: Точки — всегда из анкеты; расход/мощность — из API (если есть).
 */

import type { HotWaterFormValue } from '../../types/hotWater';
import type { ParsedHotWaterReport } from '../../types/hotWaterReport';
import {
  formatCoefficient,
  formatFlowLps,
  formatKw,
  formatLiters,
  formatTempC,
} from '../../utils/format';
import { hasHotWaterFixturesContent } from '../../utils/countThermalFixtures';
import { normalizeHotWaterForm } from '../../utils/normalizeHotWaterForm';
import { HotWaterFixturesTable } from './HotWaterFixturesTable';
import styles from './HotWaterReportView.module.css';

export type HotWaterReportViewProps = {
  /** Расчёт API; null — только точки анкеты + подсказка ожидания. */
  hotWater: ParsedHotWaterReport | null;
  /** Анкета ГВ (SSOT точек водоразбора). */
  formValue: HotWaterFormValue;
};

/**
 * @param props
 */
export function HotWaterReportView({
  hotWater,
  formValue,
}: HotWaterReportViewProps) {
  const form = normalizeHotWaterForm(formValue);
  const showFixtures = hasHotWaterFixturesContent(form.fixtures);

  if (hotWater == null) {
    return (
      <div>
        {showFixtures && (
          <>
            <h4 className={styles.sectionTitle}>Точки водорозбору (з анкети)</h4>
            <HotWaterFixturesTable fixtures={form.fixtures} />
          </>
        )}
        <p className={styles.hint} role="status">
          Розрахункові показники (пік витрати, потужність, бак) з&apos;являться після
          авторасчунку. Заповніть приміщення та огородження, якщо розрахунок ще не
          запускався.
        </p>
      </div>
    );
  }

  const scenarioHint =
    hotWater.dhwSupplyScenario === 'storage'
      ? 'Сценарій API: дім — накопичувальний (об\'єм бака і потужність для котла від нагрівання бака; пік витрати нижче — довідково).'
      : hotWater.dhwSupplyScenario === 'flowThrough'
        ? 'Сценарій API: квартира — проточний пік (потужність на нагрів від витрати та ΔT).'
        : 'Сценарій ГВП з розрахунку API.';

  const recommendedTankLabel =
    hotWater.recommendedTankLiters === 0
      ? 'Не застосовується (проточний сценарій)'
      : hotWater.recommendedTankLiters != null
        ? `${formatLiters(hotWater.recommendedTankLiters)} л`
        : '—';

  const coldSeasonLabel =
    hotWater.coldWaterDesignSeason === 'summer'
      ? 'Літо (+15 °C)'
      : hotWater.coldWaterDesignSeason === 'winter'
        ? 'Зима (+5 °C)'
        : '—';

  return (
    <div>
      <p className={styles.hint}>
        {scenarioHint}
        {hotWater.normsSchemaVersion != null && (
          <span className={styles.muted}>
            {' '}
            · water_norms v{hotWater.normsSchemaVersion}
          </span>
        )}
      </p>

      {showFixtures && (
        <>
          <h4 className={styles.sectionTitle}>Точки водорозбору (з анкети)</h4>
          <HotWaterFixturesTable fixtures={form.fixtures} />
        </>
      )}

      <h4 className={styles.sectionTitle}>Вихідні параметри</h4>
      <dl className={styles.dl}>
        {hotWater.objectType != null && (
          <>
            <dt>Тип об&apos;єкта</dt>
            <dd>{hotWater.objectType === 'apartment' ? 'Квартира' : 'Будинок'}</dd>
          </>
        )}
        {hotWater.residents != null && (
          <>
            <dt>Кількість людей</dt>
            <dd>{hotWater.residents}</dd>
          </>
        )}
        {hotWater.tropicalShower != null && (
          <>
            <dt>Тропічний душ</dt>
            <dd>{hotWater.tropicalShower ? 'так (+30 % до об\'єму бака)' : 'ні'}</dd>
          </>
        )}
        <dt>Розрахункова ХВ</dt>
        <dd>
          {coldSeasonLabel}
          {hotWater.designColdWaterC != null && (
            <span className={styles.muted}>
              {' '}
              · {formatTempC(hotWater.designColdWaterC)} °C
            </span>
          )}
        </dd>
        {hotWater.hotWaterC != null && (
          <>
            <dt>Температура ГВ</dt>
            <dd>{formatTempC(hotWater.hotWaterC)} °C</dd>
          </>
        )}
        {hotWater.deltaTK != null && (
          <>
            <dt>ΔT (ГВ − ХВ)</dt>
            <dd>{formatTempC(hotWater.deltaTK)} K</dd>
          </>
        )}
      </dl>

      <h4 className={styles.sectionTitle}>Витрата і потужність</h4>
      <dl className={styles.dl}>
        {hotWater.sumFlowLpsRaw != null && (
          <>
            <dt>Сума витрат (без зниження)</dt>
            <dd>
              {formatFlowLps(hotWater.sumFlowLpsRaw)} <span>л/с</span>
            </dd>
          </>
        )}
        {hotWater.simultaneityFactor != null && (
          <>
            <dt>Коефіцієнт одночасності β</dt>
            <dd>
              {formatCoefficient(hotWater.simultaneityFactor)}
              {hotWater.simultaneityBaseNorm != null && (
                <span className={styles.muted}>
                  {' '}
                  (база норми {formatCoefficient(hotWater.simultaneityBaseNorm)})
                </span>
              )}
            </dd>
          </>
        )}
        <dt className={styles.totalLabel}>Пікова витрата гарячої води</dt>
        <dd className={styles.totalLabel}>
          {formatFlowLps(hotWater.peakFlowLps)} <span>л/с</span>
        </dd>
        <dt className={styles.totalLabel}>Потужність на ГВ для підбору котла</dt>
        <dd className={styles.totalLabel}>
          {formatKw(hotWater.hotWaterPowerKw)} <span>кВт</span>
        </dd>
        {hotWater.dhwSupplyScenario === 'storage'
          && hotWater.peakThermalPowerKw != null && (
            <>
              <dt>Потужність при піковому витраті (довідково)</dt>
              <dd>
                {formatKw(hotWater.peakThermalPowerKw)} <span>кВт</span>
                <span className={styles.muted}> — не для формули котла</span>
              </dd>
            </>
          )}
        <dt>Рекомендований накопичувач</dt>
        <dd>{recommendedTankLabel}</dd>
      </dl>

      {hotWater.dhwSupplyScenario === 'storage' && (
        <>
          <h4 className={styles.sectionTitle}>Накопичувальний сценарій (дім)</h4>
          <dl className={styles.dl}>
            {hotWater.storageTankLitersPerPersonBasis != null && (
              <>
                <dt>Норма на людину</dt>
                <dd>
                  {formatLiters(hotWater.storageTankLitersPerPersonBasis)} л
                </dd>
              </>
            )}
            {hotWater.sessionDemandLitersMixed != null && (
              <>
                <dt>Сеансовий попит (змішана вода)</dt>
                <dd>{formatLiters(hotWater.sessionDemandLitersMixed)} л</dd>
              </>
            )}
            {hotWater.dhwEquivalentTankLitersFromSession != null && (
              <>
                <dt>Еквівалент бака за сеансом</dt>
                <dd>
                  {formatLiters(hotWater.dhwEquivalentTankLitersFromSession)} л
                </dd>
              </>
            )}
            {hotWater.dhwTankLitersCombinedRaw != null && (
              <>
                <dt>Об&apos;єм до округлення за типорозмірами</dt>
                <dd>{formatLiters(hotWater.dhwTankLitersCombinedRaw)} л</dd>
              </>
            )}
            {hotWater.storageHeatTimeMinutes != null && (
              <>
                <dt>Час нагрівання бака (норма)</dt>
                <dd>{hotWater.storageHeatTimeMinutes} хв</dd>
              </>
            )}
            {hotWater.storageIndirectHeatPowerKw != null && (
              <>
                <dt>Потужність нагрівання бака</dt>
                <dd>
                  {formatKw(hotWater.storageIndirectHeatPowerKw)} <span>кВт</span>
                </dd>
              </>
            )}
          </dl>
        </>
      )}
    </div>
  );
}

/**
 * Назначение: Агрегат подбора ЭБ/БКН для сайдбара «Итог».
 * Описание: Две строки; детали потребления — модалка ГВ; карточки — модалка водонагревателя.
 */

import type { HotWaterBoilerPowerMatchingScheme } from '../../types/heatingMatching';
import type { ParsedHotWaterReport } from '../../types/hotWaterReport';
import type { ParsedIndirectWaterHeaterMatching } from '../../utils/parsers/parseIndirectWaterHeaterMatchingFromReport';
import type { ParsedWaterHeaterMatching } from '../../utils/parsers/parseWaterHeaterMatchingFromReport';
import {
  hasHotWaterEquipmentWarnings,
  isHotWaterEquipmentSchemeParticipant,
  resolveHotWaterEquipmentRowLabel,
} from '../../utils/hotWaterEquipmentParticipation';
import { hasHotWaterSummaryContent } from './hasHotWaterSummaryContent';
import { RESULTS_SECTION_IDS } from '../../constants/surveyResultsSections';
import { SurveyStepLink } from '../SurveyNavigation/SurveyStepLink';
import styles from './HotWaterSummaryTable.module.css';

export type HotWaterSummaryTableProps = {
  scheme: HotWaterBoilerPowerMatchingScheme;
  hotWater: ParsedHotWaterReport | null;
  electric: ParsedWaterHeaterMatching | null;
  indirect: ParsedIndirectWaterHeaterMatching | null;
  calcLoading?: boolean;
};

/**
 * @param props
 */
export function HotWaterSummaryTable({
  scheme,
  hotWater,
  electric,
  indirect,
  calcLoading = false,
}: HotWaterSummaryTableProps) {
  if (!hasHotWaterSummaryContent(hotWater, electric, indirect)) {
    return null;
  }

  const hasReport = hotWater != null;
  const electricLabel = resolveHotWaterEquipmentRowLabel({
    kind: 'electric',
    scheme,
    matching: electric,
    hasReport,
  });
  const indirectLabel = resolveHotWaterEquipmentRowLabel({
    kind: 'indirect',
    scheme,
    matching: indirect,
    hasReport,
  });
  const hasWarnings = hasHotWaterEquipmentWarnings(electric, indirect);

  const electricNotParticipating =
    !isHotWaterEquipmentSchemeParticipant(scheme, 'electric')
    && electricLabel.startsWith('Не бере участі');
  const indirectNotParticipating =
    !isHotWaterEquipmentSchemeParticipant(scheme, 'indirect')
    && indirectLabel.startsWith('Не бере участі');

  return (
    <div
      id={RESULTS_SECTION_IDS.waterHeater}
      className={styles.wrap}
      aria-labelledby="hot-water-summary-title"
    >
      <h3 id="hot-water-summary-title" className={styles.title}>
        Водонагрівач (підсумок)
      </h3>
      <div className={styles.tableWrap}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th>Обладнання</th>
              <th>Результат підбору</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>Електробойлер (ЕБ)</td>
              <td className={electricNotParticipating ? styles.notParticipating : undefined}>
                {electricLabel}
              </td>
            </tr>
            <tr>
              <td>Бойлер непрямого нагріву (БКН)</td>
              <td className={indirectNotParticipating ? styles.notParticipating : undefined}>
                {indirectLabel}
              </td>
            </tr>
          </tbody>
        </table>
      </div>
      {calcLoading && (
        <p className={styles.hint} role="status">
          Оновлення підбору…
        </p>
      )}
      <p className={styles.hint}>
        Деталі розрахунку споживання — на кроці{' '}
        <SurveyStepLink step="hotWater">«Гаряча вода»</SurveyStepLink>
        . Схема котел/ГВП і картки номенклатури — у звіті на кроці{' '}
        <SurveyStepLink step="waterHeater">«Водонагрівач»</SurveyStepLink>
        .
      </p>
      {hasWarnings && (
        <p className={styles.attention}>
          Зверніть увагу на попередження підбору у звіті на кроці{' '}
          <SurveyStepLink step="waterHeater">«Водонагрівач»</SurveyStepLink>
          .
        </p>
      )}
    </div>
  );
}

/**
 * Призначення: компактна таблиця підбору труб у блоці «Рекомендация».
 * Опис: Позиції каталогу без цін і без деталізації по контурах/ділянках.
 */

import type { ParsedHydraulicsPipeLine, ParsedHydraulicsView } from '../../types/hydraulics';
import { formatBrandModel } from '../../utils/format';
import { hasHydraulicsReportContent } from './hasHydraulicsReportContent';
import styles from './HydraulicsProposalTable.module.css';

export type HydraulicsProposalTableProps = {
  hydraulics: ParsedHydraulicsView | null;
};

/**
 * Плоский список позицій труб (без групування по контурах).
 *
 * @param proposal
 */
function resolveFlatPipeLines(
  proposal: NonNullable<ParsedHydraulicsView['proposal']>,
): ParsedHydraulicsPipeLine[] {
  if (proposal.pipeLines.length > 0) {
    return proposal.pipeLines;
  }
  return proposal.pipeLineGroups.flatMap((g) => g.pipeLines);
}

/**
 * @param props
 */
export function HydraulicsProposalTable({
  hydraulics,
}: HydraulicsProposalTableProps) {
  if (!hasHydraulicsReportContent(hydraulics) || hydraulics == null) {
    return null;
  }

  const proposal = hydraulics.proposal;
  if (proposal == null) {
    return null;
  }

  if (!proposal.hasPipeSelection) {
    return (
      <div
        className={styles.wrap}
        aria-labelledby="hydraulics-proposal-table-title"
      >
        <h4 id="hydraulics-proposal-table-title" className={styles.title}>
          Гідравліка · труби
        </h4>
        <p className={styles.empty} role="status">
          {proposal.unavailableReason
            ?? 'Немає відповідних позицій труб у каталозі. Повний розрахунок — на кроці «Гідравліка».'}
        </p>
      </div>
    );
  }

  const pipeLines = resolveFlatPipeLines(proposal);
  if (pipeLines.length === 0) {
    return null;
  }

  return (
    <div
      className={styles.wrap}
      aria-labelledby="hydraulics-proposal-table-title"
    >
      <h4 id="hydraulics-proposal-table-title" className={styles.title}>
        Гідравліка · труби
      </h4>
      <div className={styles.tableWrap}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th>Модель</th>
              <th>Матеріал</th>
              <th>Ø внутр.</th>
              <th>Довжина</th>
            </tr>
          </thead>
          <tbody>
            {pipeLines.map((line) => (
              <tr key={line.catalogPipeId}>
                <td>{formatBrandModel(line.brand, line.model)}</td>
                <td>{line.material.length > 0 ? line.material : '—'}</td>
                <td>{line.internalDiameterMm.toFixed(1)} мм</td>
                <td>{line.totalLengthM.toFixed(1)} м</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/**
 * Призначення: модальне вікно звіту гідравліки.
 * Опис: Патерн RadiatorsReportDialog; контент — HydraulicsReportView.
 */

import { useEffect } from 'react';

import type { ParsedHydraulicsView } from '../../types/hydraulics';
import { HydraulicsReportView } from './HydraulicsReportView';
import { hasHydraulicsReportContent } from './hasHydraulicsReportContent';
import styles from './HydraulicsReportDialog.module.css';

export type HydraulicsReportDialogProps = {
  open: boolean;
  onClose: () => void;
  hydraulics: ParsedHydraulicsView | null;
  catalogSource?: 'file' | 'mongo' | null;
};

/**
 * @param props
 */
export function HydraulicsReportDialog({
  open,
  onClose,
  hydraulics,
  catalogSource = null,
}: HydraulicsReportDialogProps) {
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [open, onClose]);

  if (!open) return null;

  const hasContent = hasHydraulicsReportContent(hydraulics);

  return (
    <div
      className={styles.backdrop}
      role="presentation"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className={styles.dialog}
        role="dialog"
        aria-modal="true"
        aria-labelledby="hydraulics-report-dialog-title"
        onClick={(e) => {
          e.stopPropagation();
        }}
      >
        <div className={styles.header}>
          <h2 id="hydraulics-report-dialog-title" className={styles.title}>
            Звіт з гідравліки
          </h2>
          <button
            type="button"
            className={styles.closeIconButton}
            onClick={onClose}
            aria-label="Закрити"
          >
            ✕
          </button>
        </div>

        {hasContent && hydraulics != null ? (
          <HydraulicsReportView
            hydraulics={hydraulics}
            catalogSource={catalogSource}
          />
        ) : (
          <p className={styles.empty}>
            Немає даних гідравліки. Заповніть приміщення та огорожі, задайте
            параметри розводки на кроці «Гідравліка», дочекайтеся авторозрахунку.
          </p>
        )}

        <button type="button" className={styles.closeButton} onClick={onClose}>
          Закрити
        </button>
      </div>
    </div>
  );
}

/**
 * Призначення: повний звіт гідравліки (труби + насос).
 * Опис: Тіло модалки кроку «Гидравлика»; деталізація не дублюється в «Рекомендації».
 */

import type {
  ParsedHydraulicsCalculations,
  ParsedHydraulicsFlowContext,
  ParsedHydraulicsPipeLine,
  ParsedHydraulicsPipeLineGroup,
  ParsedHydraulicsProposal,
  ParsedHydraulicsView,
} from '../../types/hydraulics';
import {
  formatBrandModel,
  formatPriceUah,
} from '../../utils/format';
import { excludeUfhZonePumps } from '../../utils/ufhHydraulicsPumps';
import { HydraulicsPumpCard } from '../Hydraulics/HydraulicsPumpCard';
import styles from './HydraulicsReportView.module.css';

export type HydraulicsReportViewProps = {
  hydraulics: ParsedHydraulicsView;
  catalogSource?: 'file' | 'mongo' | null;
};

/**
 * @param role
 * @param isMainLine
 */
function segmentRoleLabel(
  role: string,
  isMainLine?: boolean,
): string {
  if (isMainLine) return 'Транзит котла';
  switch (role) {
    case 'main':
      return 'Магістраль';
    case 'branch':
      return 'Гілка';
    case 'ufh_loop':
      return 'Петля ТП';
    case 'dhw':
      return 'ГВП';
    default:
      return role;
  }
}

/**
 * @param topology
 */
function topologyLabel(topology: ParsedHydraulicsProposal['topology']): string | null {
  switch (topology) {
    case 'direct':
      return 'Пряме підключення (сума витрат контурів).';
    case 'mixing_valve':
      return 'Змішувальний вузол ТП — насос контуру підлоги у звіті кроку «Тепла підлога».';
    case 'hydraulic_separator':
      return 'Гідрострелка — первинний контур тут; насос ТП у звіті кроку «Тепла підлога».';
    default:
      return null;
  }
}

/**
 * @param props
 */
function FlowContextBlock({ flowContext }: { flowContext: ParsedHydraulicsFlowContext }) {
  const hasGraph =
    flowContext.supplyC != null && flowContext.returnC != null;
  const hasFlowDt = flowContext.flowDeltaTK != null;
  if (!hasGraph && !hasFlowDt) return null;

  return (
    <dl className={styles.summaryDl}>
      {hasGraph && (
        <>
          <dt>Температурний графік радіаторів</dt>
          <dd>
            {flowContext.supplyC}/{flowContext.returnC}{' '}
            <span className={styles.unit}>°C</span>
            {flowContext.thermalRegimeDeltaTK != null && (
              <span className={styles.hintInline}>
                {' '}
                (Δt графіка {flowContext.thermalRegimeDeltaTK} K)
              </span>
            )}
          </dd>
        </>
      )}
      {hasFlowDt && (
        <>
          <dt>Δt для розрахунку витрати (анкета)</dt>
          <dd>
            {flowContext.flowDeltaTK} <span className={styles.unit}>K</span>
            {flowContext.thermalRegimeDeltaTK != null
              && flowContext.flowDeltaTK !== flowContext.thermalRegimeDeltaTK && (
                <span className={styles.hintInline}>
                  {' '}
                  — відрізняється від Δt графіка; витрата Q = P/(c·Δt) рахується за цим значенням
                </span>
            )}
          </dd>
        </>
      )}
    </dl>
  );
}

/**
 * @param props
 */
function CalculationsSummary({
  calculations,
  proposal,
}: {
  calculations: ParsedHydraulicsCalculations;
  proposal: ParsedHydraulicsProposal | null;
}) {
  const flow =
    proposal != null && proposal.designFlowM3PerHour > 0
      ? proposal.designFlowM3PerHour
      : calculations.flowRateM3PerHour;
  const head =
    proposal != null && proposal.headRequiredM > 0
      ? proposal.headRequiredM
      : calculations.headRequiredM;

  if (flow <= 0 && head <= 0) return null;

  return (
    <dl className={styles.summaryDl}>
      <dt>Розрахунковий витрат системи</dt>
      <dd>
        {flow.toFixed(3)} <span className={styles.unit}>м³/ч</span>
      </dd>
      <dt>Необхідний напір</dt>
      <dd>
        {head.toFixed(2)} <span className={styles.unit}>м</span>
      </dd>
      {calculations.deltaTSystemK != null && (
        <>
          <dt>Δt витрати (з розрахунку)</dt>
          <dd>
            {calculations.deltaTSystemK} <span className={styles.unit}>K</span>
          </dd>
        </>
      )}
      {calculations.mainLineLengthM != null && calculations.mainLineLengthM > 0 && (
        <>
          <dt>Довжина магістралі (анкета)</dt>
          <dd>
            {calculations.mainLineLengthM.toFixed(1)} <span className={styles.unit}>м</span>
          </dd>
        </>
      )}
      {calculations.recommendedPipeDiameter != null
        && calculations.recommendedPipeDiameter.length > 0 && (
        <>
          <dt>Орієнтовний DN (за витратою)</dt>
          <dd>{calculations.recommendedPipeDiameter}</dd>
        </>
      )}
    </dl>
  );
}

/**
 * @param props
 */
function PipeLinesTable({
  title,
  pipeLines,
  footerPrice,
}: {
  title: string;
  pipeLines: ParsedHydraulicsPipeLine[];
  footerPrice?: number;
}) {
  if (pipeLines.length === 0) return null;

  return (
    <div className={styles.tableWrap}>
      <h4 className={styles.subTitle}>{title}</h4>
      <table className={styles.table}>
        <thead>
          <tr>
            <th>Модель</th>
            <th>Матеріал</th>
            <th>Ø внутр.</th>
            <th>Довжина</th>
            <th>Ціна/м</th>
            <th>Сума</th>
          </tr>
        </thead>
        <tbody>
          {pipeLines.map((line) => (
            <tr key={line.catalogPipeId}>
              <td>{formatBrandModel(line.brand, line.model)}</td>
              <td>{line.material || '—'}</td>
              <td>
                {line.internalDiameterMm.toFixed(1)} <span className={styles.unit}>мм</span>
              </td>
              <td>
                {line.totalLengthM.toFixed(1)} <span className={styles.unit}>м</span>
                {line.edgeCount > 1 ? (
                  <span className={styles.hintInline}> ({line.edgeCount} ділян.)</span>
                ) : null}
              </td>
              <td>
                {line.pricePerMeter > 0
                  ? `${formatPriceUah(line.pricePerMeter)} грн`
                  : '—'}
              </td>
              <td>
                {line.linePrice > 0
                  ? `${formatPriceUah(line.linePrice)} грн`
                  : '—'}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {footerPrice != null && footerPrice > 0 && (
        <p className={styles.tableFooter}>
          Разом за контуром: <strong>{formatPriceUah(footerPrice)} грн</strong>
        </p>
      )}
    </div>
  );
}

/**
 * @param props
 */
function ProposalContent({
  proposal,
  catalogSource,
}: {
  proposal: ParsedHydraulicsProposal;
  catalogSource: 'file' | 'mongo' | null;
}) {
  const sourceLine =
    catalogSource === 'mongo'
      ? 'Підбір за каталогом із бази даних (MongoDB).'
      : catalogSource === 'file'
        ? 'Підбір за каталогом із файлу (локальні дані API).'
        : null;

  /** Зони ТП — лише в звіті кроку «Тёплый пол». */
  const pumpsForHydraulics = excludeUfhZonePumps(proposal.pumps);
  const topologyText = topologyLabel(proposal.topology);

  return (
    <>
      {sourceLine != null && <p className={styles.hint}>{sourceLine}</p>}

      {topologyText != null && (
        <p className={styles.hint}>{topologyText}</p>
      )}

      {(proposal.designFlowM3PerHour > 0 || proposal.headRequiredM > 0) && (
        <dl className={styles.summaryDl}>
          <dt>Розрахунковий витрат контуру (підбір)</dt>
          <dd>
            {proposal.designFlowM3PerHour.toFixed(3)} <span className={styles.unit}>м³/ч</span>
          </dd>
          <dt>Необхідний напір (підбір)</dt>
          <dd>
            {proposal.headRequiredM.toFixed(2)} <span className={styles.unit}>м</span>
          </dd>
          {proposal.estimatedTotalPrice > 0 && (
            <>
              <dt>Орієнтовна вартість (труби + насос)</dt>
              <dd className={styles.valueStrong}>
                {formatPriceUah(proposal.estimatedTotalPrice)}{' '}
                <span className={styles.unit}>грн</span>
              </dd>
            </>
          )}
        </dl>
      )}

      {!proposal.hasPipeSelection && proposal.unavailableReason != null && (
        <p className={styles.emptyHint}>{proposal.unavailableReason}</p>
      )}

      {proposal.pumpUnavailableReason != null && pumpsForHydraulics.length === 0 && (
        <p className={styles.hint}>{proposal.pumpUnavailableReason}</p>
      )}

      {pumpsForHydraulics.length > 0 && (
        <div className={styles.pumpsList}>
          {pumpsForHydraulics.map((p) => (
            <HydraulicsPumpCard key={p.zoneId} pump={p} />
          ))}
        </div>
      )}

      {proposal.pipeLineGroups.length > 0
        ? proposal.pipeLineGroups.map((group: ParsedHydraulicsPipeLineGroup) => (
            <PipeLinesTable
              key={group.circuitId}
              title={`Труби — ${group.label}`}
              pipeLines={group.pipeLines}
              footerPrice={group.estimatedPrice}
            />
          ))
        : (
          <PipeLinesTable
            title="Труби (зведення за позиціями каталогу)"
            pipeLines={proposal.pipeLines}
            {...(proposal.estimatedPipesPrice > 0
              ? { footerPrice: proposal.estimatedPipesPrice }
              : {})}
          />
        )}

      {proposal.hasPipeSelection
        && proposal.estimatedPipesPrice > 0
        && proposal.pipeLineGroups.length > 1 && (
        <p className={styles.tableFooter}>
          Разом за трубами: <strong>{formatPriceUah(proposal.estimatedPipesPrice)} грн</strong>
        </p>
      )}

      {proposal.pipeSegments.length > 0 && (
        <details className={styles.details}>
          <summary>Деталізація за ділянками ({proposal.pipeSegments.length})</summary>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>Ділянка</th>
                <th>Тип</th>
                <th>Довжина</th>
                <th>Труба</th>
                <th>v</th>
                <th>Δp</th>
              </tr>
            </thead>
            <tbody>
              {proposal.pipeSegments.map((seg) => (
                <tr
                  key={seg.edgeId}
                  className={
                    seg.velocityLimitExceeded
                    || seg.catalogPoolExhausted
                    || (seg.velocityBelowMin === true && seg.mainTransitGuardApplied !== true)
                      ? styles.segmentRowWarning
                      : undefined
                  }
                >
                  <td>
                    {seg.segmentLabel}
                    {seg.groupedRoomIds != null && seg.groupedRoomIds.length > 0 ? (
                      <span className={styles.hintInline}>
                        {' '}
                        (колектор: {seg.groupedRoomIds.join(', ')})
                      </span>
                    ) : null}
                  </td>
                  <td>{segmentRoleLabel(seg.segmentRole, seg.isMainLine)}</td>
                  <td>
                    {seg.lengthM.toFixed(1)} <span className={styles.unit}>м</span>
                  </td>
                  <td>{formatBrandModel(seg.brand, seg.model)}</td>
                  <td>
                    {seg.velocityMps.toFixed(2)} <span className={styles.unit}>м/с</span>
                    {seg.velocityLimitExceeded === true ? (
                      <span className={styles.hintInline}> (вище норми)</span>
                    ) : null}
                    {seg.velocityBelowMin === true ? (
                      <span className={styles.hintInline}>
                        {seg.mainTransitGuardApplied === true
                          ? ' (нижче норми v, guard Dвн)'
                          : ' (нижче норми)'}
                      </span>
                    ) : null}
                    {seg.catalogPoolExhausted === true ? (
                      <span className={styles.hintInline}> (немає Ø у каталозі)</span>
                    ) : null}
                  </td>
                  <td>
                    {seg.pressureDropKPa.toFixed(1)} <span className={styles.unit}>кПа</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </details>
      )}

      {proposal.warnings.length > 0 && (
        <ul className={styles.warningsList}>
          {proposal.warnings.map((w, i) => (
            <li key={`hyd-w-${i}-${w.slice(0, 64)}`}>{w}</li>
          ))}
        </ul>
      )}
    </>
  );
}

/**
 * @param props
 */
export function HydraulicsReportView({
  hydraulics,
  catalogSource = null,
}: HydraulicsReportViewProps) {
  const proposal = hydraulics.proposal;
  const calculations = hydraulics.calculations;
  const flowContext = hydraulics.flowContext;
  const matchingWarnings = hydraulics.matchingWarnings;

  const allWarnings = [
    ...matchingWarnings,
    ...(calculations?.notes ?? []),
  ];

  return (
    <div>
      <p className={styles.hint}>
        Джерело: розрахунок API (Pure Pipeline) · підбір труб і насоса з каталогу.
        У блоці «Рекомендація» — компактна таблиця труб без цін; тут — повний розрахунок
        з цінами та деталізацією за ділянками.
      </p>

      {flowContext != null && <FlowContextBlock flowContext={flowContext} />}

      {calculations != null && (
        <CalculationsSummary calculations={calculations} proposal={proposal} />
      )}

      {proposal != null ? (
        <ProposalContent
          proposal={proposal}
          catalogSource={catalogSource}
        />
      ) : (
        calculations != null && (
          <p className={styles.hint}>
            Підбір позицій каталогу не сформовано — див. попередження нижче або перевірте каталог
            труб/насосів.
          </p>
        )
      )}

      {allWarnings.length > 0 && (
        <>
          <h4 className={styles.sectionTitle}>Попередження</h4>
          <ul className={styles.warningsList}>
            {allWarnings.map((w, i) => (
              <li key={`hyd-mw-${i}-${w.slice(0, 64)}`}>{w}</li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}

/**
 * Призначення: компактний підсумок гідравліки для сайдбара «Итог».
 * Опис: KPI; довжини — за призначенням ділянок (магістраль / колектор), не число SKU.
 */

import { RESULTS_SECTION_IDS } from '../../constants/surveyResultsSections';
import type { ParsedHydraulicsView } from '../../types/hydraulics';
import { formatBrandModel } from '../../utils/format';
import { sumHydraulicsPipeLengthsByRole } from '../../utils/sumHydraulicsPipeLengthsByRole';
import { excludeUfhZonePumps } from '../../utils/ufhHydraulicsPumps';
import { SurveyStepLink } from '../SurveyNavigation/SurveyStepLink';
import { hasHydraulicsReportContent } from './hasHydraulicsReportContent';
import styles from './HydraulicsSummaryTable.module.css';

export type HydraulicsSummaryTableProps = {
  hydraulics: ParsedHydraulicsView | null;
};

/**
 * @param props
 */
export function HydraulicsSummaryTable({
  hydraulics,
}: HydraulicsSummaryTableProps) {
  if (!hasHydraulicsReportContent(hydraulics) || hydraulics == null) {
    return null;
  }

  const proposal = hydraulics.proposal;
  const calculations = hydraulics.calculations;
  const flow =
    proposal != null && proposal.designFlowM3PerHour > 0
      ? proposal.designFlowM3PerHour
      : calculations?.flowRateM3PerHour ?? 0;
  const head =
    proposal != null && proposal.headRequiredM > 0
      ? proposal.headRequiredM
      : calculations?.headRequiredM ?? 0;

  const pumps = excludeUfhZonePumps(proposal?.pumps ?? []);
  const primaryPump = pumps[0] ?? proposal?.pump ?? null;
  const pumpLabel = (() => {
    if (primaryPump == null) return null;
    const base = formatBrandModel(primaryPump.brand, primaryPump.model);
    if (primaryPump.pumpSource === 'catalog') {
      return `${base} — дод. на котлову гілку (вбудований слабкий)`;
    }
    return base;
  })();

  const hasWarnings =
    hydraulics.matchingWarnings.length > 0
    || (proposal?.warnings.length ?? 0) > 0
    || (calculations?.notes.length ?? 0) > 0;

  const deltaT =
    calculations?.deltaTSystemK
    ?? hydraulics.flowContext?.flowDeltaTK
    ?? null;

  const lengthsFromSegments =
    proposal != null && proposal.pipeSegments.length > 0
      ? sumHydraulicsPipeLengthsByRole(proposal.pipeSegments)
      : null;

  const mainLineM =
    lengthsFromSegments != null && lengthsFromSegments.mainLineM > 0
      ? lengthsFromSegments.mainLineM
      : calculations?.mainLineLengthM != null && calculations.mainLineLengthM > 0
        ? Math.round(calculations.mainLineLengthM * 10) / 10
        : 0;

  const collectorBranchesM =
    lengthsFromSegments != null && lengthsFromSegments.collectorBranchesM > 0
      ? lengthsFromSegments.collectorBranchesM
      : 0;

  return (
    <div
      id={RESULTS_SECTION_IDS.hydraulics}
      className={styles.wrap}
      aria-labelledby="hydraulics-summary-title"
    >
      <h3 id="hydraulics-summary-title" className={styles.title}>
        Гідравліка (підсумок)
      </h3>
      <div className={styles.tableWrap}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th>Показник</th>
              <th>Значення</th>
            </tr>
          </thead>
          <tbody>
            {flow > 0 && (
              <tr>
                <td>Розрахункова витрата</td>
                <td>{flow.toFixed(3)} м³/ч</td>
              </tr>
            )}
            {head > 0 && (
              <tr>
                <td>Потрібний напір</td>
                <td>{head.toFixed(2)} м</td>
              </tr>
            )}
            {deltaT != null && (
              <tr>
                <td>Δt витрати</td>
                <td>{deltaT} K</td>
              </tr>
            )}
            {mainLineM > 0 && (
              <tr>
                <td>Магистраль</td>
                <td>{mainLineM.toFixed(1)} м</td>
              </tr>
            )}
            {collectorBranchesM > 0 && (
              <tr>
                <td>Коллектор</td>
                <td>{collectorBranchesM.toFixed(1)} м</td>
              </tr>
            )}
            {pumpLabel != null && (
              <tr>
                <td>Насос</td>
                <td>{pumpLabel}</td>
              </tr>
            )}
            {proposal != null && !proposal.hasPipeSelection && (
              <tr>
                <td>Труби</td>
                <td>
                  {proposal.unavailableReason
                    ?? 'Немає відповідних позицій у каталозі'}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      <p className={styles.hint}>
        Повний розрахунок, ціни та ділянки — на кроці{' '}
        <SurveyStepLink step="hydraulics">«Гідравліка»</SurveyStepLink>
        . Підбір труб без цін — у блоці «Рекомендація».
      </p>
      {hasWarnings && (
        <p className={styles.attention}>
          Є попередження щодо гідравліки — відкрийте звіт на кроці{' '}
          <SurveyStepLink step="hydraulics">«Гідравліка»</SurveyStepLink>
          .
        </p>
      )}
    </div>
  );
}

/**
 * Назначение: форма шага «Гидравлика» в анкете.
 * Описание: разводка, длины; полный расчёт — в модалке (паттерн радиаторов / ГВ).
 */

import { useState } from 'react';

import type { RoomFormValue } from '../../types/rooms';
import type {
  HydraulicsFormValue,
  ParsedHydraulicsView,
} from '../../types/hydraulics';
import type { WiringBranchV3, WiringSystemType } from '../../surveySession/wiringLayoutV3';
import { WIRING_SYSTEM_TYPE_OPTIONS } from '../../utils/wiringSystemTypeLabels';
import { HydraulicsReportDialog } from '../HydraulicsReport/HydraulicsReportDialog';
import { hasHydraulicsReportContent } from '../HydraulicsReport/hasHydraulicsReportContent';
import reportActionsStyles from '../SurveyNavigation/SurveyReportActions.module.css';
import styles from './HydraulicsSection.module.css';

type HydraulicsSectionProps = {
  value: HydraulicsFormValue;
  onChange: (next: HydraulicsFormValue) => void;
  wiringSystemType: WiringSystemType;
  onWiringSystemTypeChange: (systemType: WiringSystemType) => void;
  branches: WiringBranchV3[];
  rooms: RoomFormValue[];
  onBranchLengthChange: (roomId: string, pipeLengthToEquipmentM: number) => void;
  onBranchReorder: (roomId: string, direction: 'up' | 'down') => void;
  hydraulicsReport?: ParsedHydraulicsView | null;
  catalogSource?: 'file' | 'mongo' | null;
  calcLoading?: boolean;
  /** Прокрутка до підсумку гідравліки в сайдбарі «Результати». */
  onBackToResults?: () => void;
};

/**
 * @param rooms — комнаты анкеты
 * @param roomId — id комнаты
 * @returns {string} Отображаемое имя
 */
function resolveRoomLabel(rooms: RoomFormValue[], roomId: string): string {
  const room = rooms.find((r) => r.id === roomId);
  if (!room) return roomId;
  const name = room.name.trim();
  return name || roomId;
}

/**
 * @param systemType — тип разводки
 * @returns {boolean} Нужен ли порядок радиаторов на магистрали
 */
function isSequentialWiring(systemType: WiringSystemType): boolean {
  return systemType === 'two-pipe-dead-end' || systemType === 'two-pipe-pass';
}

export function HydraulicsSection({
  value,
  onChange,
  wiringSystemType,
  onWiringSystemTypeChange,
  branches,
  rooms,
  onBranchLengthChange,
  onBranchReorder,
  hydraulicsReport = null,
  catalogSource = null,
  calcLoading = false,
  onBackToResults,
}: HydraulicsSectionProps) {
  const [reportOpen, setReportOpen] = useState(false);
  const canOpenReport = hasHydraulicsReportContent(hydraulicsReport);

  return (
    <div className={styles.root}>
      <p className={styles.hint}>
        Вкажіть тип розводки, довжину магістралі котел → колектор і підводи колектор →
        радіатор. Δt — для розрахунку витрати радіаторного контуру (може відрізнятися від
        номінального графіка 75/65 або 55/45). Діаметри труб і насос підбираються
        автоматично — повний розрахунок з цінами та ділянками відкривається кнопкою
        «Звіт з гідравліки»; короткий підсумок — у правій колонці.
      </p>

      <fieldset className={styles.wiringFieldset}>
        <legend className={styles.wiringLegend}>Тип розводки системи опалення</legend>
        <div className={styles.wiringOptions} role="presentation">
          {WIRING_SYSTEM_TYPE_OPTIONS.map((opt) => {
            const inputId = `wiring-system-${opt.value}`;
            const isSelected = wiringSystemType === opt.value;
            return (
              <label
                key={opt.value}
                htmlFor={inputId}
                className={`${styles.wiringOption} ${isSelected ? styles.wiringOptionSelected : ''}`}
              >
                <input
                  id={inputId}
                  className={styles.wiringRadio}
                  type="radio"
                  name="wiringSystemType"
                  value={opt.value}
                  checked={isSelected}
                  onChange={() => { onWiringSystemTypeChange(opt.value); }}
                />
                <span className={styles.wiringOptionBody}>
                  <span className={styles.wiringOptionTitleRow}>
                    <span className={styles.wiringOptionTitle}>{opt.label}</span>
                    {opt.recommended ? (
                      <span className={styles.wiringRecommendedBadge}>Рекомендовано</span>
                    ) : null}
                  </span>
                  <span className={styles.wiringOptionDesc}>{opt.description}</span>
                </span>
              </label>
            );
          })}
        </div>
      </fieldset>

      <label className={styles.field}>
        Довжина магістралі котел → колектор, м
        <input
          type="number"
          min={0}
          step={0.5}
          value={value.mainLineLengthM}
          onChange={(e) =>
            { onChange({
              ...value,
              mainLineLengthM: Number(e.target.value) || 0,
            }); }
          }
        />
      </label>

      <label className={styles.field}>
        Δt системи опалення (радіатори), K
        <input
          type="number"
          min={1}
          max={30}
          step={1}
          value={value.deltaTSystemK}
          onChange={(e) =>
            { onChange({
              ...value,
              deltaTSystemK: Number(e.target.value) || 20,
            }); }
          }
        />
      </label>

      <label className={styles.field}>
        Перевага матеріалу труб (опційно)
        <select
          value={value.pipeMaterialPreference}
          onChange={(e) =>
            { onChange({
              ...value,
              pipeMaterialPreference: e.target.value as HydraulicsFormValue['pipeMaterialPreference'],
            }); }
          }
        >
          <option value="">Авто (з каталогу)</option>
          <option value="pex">PEX</option>
          <option value="metal_plastic">Металопластик</option>
          <option value="steel">Сталь</option>
        </select>
      </label>

      {branches.length > 0 ? (
        <div className={styles.branchesBlock}>
          <h4 className={styles.branchesTitle}>
            Підводи колектор → радіатор, м
          </h4>
          {isSequentialWiring(wiringSystemType) ? (
            <p className={styles.branchesHint}>
              Порядок рядків задає послідовність радіаторів на магістралі (від котла
              до дальнього приладу).
            </p>
          ) : null}
          <table className={styles.branchesTable}>
            <thead>
              <tr>
                {isSequentialWiring(wiringSystemType) ? (
                  <th className={styles.colOrder}>Порядок</th>
                ) : null}
                <th>Приміщення</th>
                <th className={styles.colLength}>Довжина, м</th>
              </tr>
            </thead>
            <tbody>
              {branches.map((branch, index) => (
                <tr key={branch.roomId}>
                  {isSequentialWiring(wiringSystemType) ? (
                    <td className={styles.colOrder}>
                      <div className={styles.orderControls}>
                        <button
                          type="button"
                          className={styles.orderBtn}
                          disabled={index === 0}
                          onClick={() => { onBranchReorder(branch.roomId, 'up'); }}
                          aria-label={`Вище: ${resolveRoomLabel(rooms, branch.roomId)}`}
                        >
                          ↑
                        </button>
                        <button
                          type="button"
                          className={styles.orderBtn}
                          disabled={index === branches.length - 1}
                          onClick={() => { onBranchReorder(branch.roomId, 'down'); }}
                          aria-label={`Нижче: ${resolveRoomLabel(rooms, branch.roomId)}`}
                        >
                          ↓
                        </button>
                      </div>
                    </td>
                  ) : null}
                  <td>{resolveRoomLabel(rooms, branch.roomId)}</td>
                  <td className={styles.colLength}>
                    <input
                      type="number"
                      min={0}
                      step={0.5}
                      className={styles.branchInput}
                      value={branch.pipeLengthToEquipmentM}
                      onChange={(e) =>
                        { onBranchLengthChange(
                          branch.roomId,
                          Number(e.target.value) || 0,
                        ); }
                      }
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <p className={styles.branchesEmpty}>
          Додайте приміщення на кроці «Приміщення», щоб задати довжини підводів до
          радіаторів.
        </p>
      )}

      <div className={reportActionsStyles.reportActions}>
        <div className={reportActionsStyles.reportActionsRow}>
          <button
            type="button"
            className={reportActionsStyles.reportButton}
            disabled={!canOpenReport}
            onClick={() => {
              setReportOpen(true);
            }}
          >
            Звіт з гідравліки
          </button>
          {onBackToResults != null && (
            <button
              type="button"
              className={reportActionsStyles.backButton}
              onClick={onBackToResults}
            >
              Назад до результатів
            </button>
          )}
        </div>
        {calcLoading && (
          <p className={`${styles.hint} ${styles.hintMt8}`} role="status">
            Оновлення розрахунку…
          </p>
        )}
        {!canOpenReport && !calcLoading && (
          <p className={`${styles.hint} ${styles.hintMt8}`}>
            Звіт з&apos;явиться після авторозрахунку. Заповніть приміщення та огородження,
            задайте довжини розводки.
          </p>
        )}
      </div>

      <HydraulicsReportDialog
        open={reportOpen}
        onClose={() => {
          setReportOpen(false);
        }}
        hydraulics={hydraulicsReport}
        catalogSource={catalogSource}
      />
    </div>
  );
}

/**
 * Назначение: Форма шага «Объект» анкеты.
 * Описание: Тип здания, этажность, наружные стены, фасад, вентиляция, размещение котла и котельная.
 */

import styles from './ObjectMetaForm.module.css';

import {
  DEFAULT_SFTK_INSULATION_PRESET_ID,
} from '../../data/fallbackEnvelopePresets';
import { ROOMS_COUNT_MAX, ROOMS_COUNT_MIN } from '../../types/envelope';
import type {
  BoilerPlacementZone,
  EnvelopePreset,
  FacadeSystem,
  ObjectMetaValue,
  ApartmentStackPosition,
  ObjectType,
  VentilationReserveMode,
} from '../../types/envelope';
import { envelopePresetLabel } from '../../utils/presetLabel';

type Props = {
  value: ObjectMetaValue;
  wallPresets: EnvelopePreset[];
  sftkInsulationPresets: EnvelopePreset[];
  ventilatedInsulationPresets: EnvelopePreset[];
  roofPresets: EnvelopePreset[];
  loadingPresets: boolean;
  presetsError: string | null;
  onChange: (next: ObjectMetaValue) => void;
};

function toIntOrUndefined(x: string): number | undefined {
  const n = Number(x);
  if (!Number.isFinite(n)) return undefined;
  return Math.trunc(n);
}

function clampRoomsCount(n: number): number {
  const t = Number.isFinite(n) ? Math.trunc(n) : ROOMS_COUNT_MIN;
  return Math.max(ROOMS_COUNT_MIN, Math.min(ROOMS_COUNT_MAX, t));
}

export function ObjectMetaForm({
  value,
  wallPresets,
  sftkInsulationPresets,
  ventilatedInsulationPresets,
  roofPresets,
  loadingPresets,
  presetsError,
  onChange,
}: Props) {
  const selectedWallPreset =
    wallPresets.find((p) => p.id === value.externalWalls.presetId) ?? null;
  const thicknessOptions = selectedWallPreset?.thicknessOptionsMm ?? null;
  const facadeSystem: FacadeSystem = value.externalWalls.facadeSystem ?? 'none';

  const activeInsulationPresets =
    facadeSystem === 'sftk'
      ? sftkInsulationPresets
      : facadeSystem === 'ventilated'
        ? ventilatedInsulationPresets
        : [];

  const selectedInsulationPreset =
    activeInsulationPresets.find((p) => p.id === value.externalWalls.insulationPresetId) ??
    null;
  const insulationThicknessOptions = selectedInsulationPreset?.thicknessOptionsMm ?? null;

  const patchExternalWalls = (patch: Partial<ObjectMetaValue['externalWalls']>) => {
    onChange({
      ...value,
      externalWalls: { ...value.externalWalls, ...patch },
    });
  };

  const onFacadeSystemChange = (next: FacadeSystem) => {
    if (next === 'none') {
      const {
        insulationPresetId: _insulationPresetId,
        insulationThicknessMm: _insulationThicknessMm,
        ...wallsWithoutInsulation
      } = value.externalWalls;
      void _insulationPresetId;
      void _insulationThicknessMm;
      onChange({
        ...value,
        externalWalls: { ...wallsWithoutInsulation, facadeSystem: 'none' },
      });
      return;
    }
    if (next === 'sftk') {
      patchExternalWalls({
        facadeSystem: 'sftk',
        insulationPresetId:
          sftkInsulationPresets[0]?.id ?? DEFAULT_SFTK_INSULATION_PRESET_ID,
        insulationThicknessMm: value.externalWalls.insulationThicknessMm ?? 100,
      });
      return;
    }
    const defaultVentilatedInsulationId = ventilatedInsulationPresets[0]?.id;
    const ventilatedInsulationPresetId =
      value.externalWalls.insulationPresetId
      && ventilatedInsulationPresets.some(
        (p) => p.id === value.externalWalls.insulationPresetId,
      )
        ? value.externalWalls.insulationPresetId
        : defaultVentilatedInsulationId;
    patchExternalWalls({
      facadeSystem: 'ventilated',
      insulationThicknessMm: value.externalWalls.insulationThicknessMm ?? 100,
      ...(ventilatedInsulationPresetId !== undefined
        ? { insulationPresetId: ventilatedInsulationPresetId }
        : {}),
    });
  };

  return (
    <div className={styles.formGrid}>
      <div className={styles.field}>
        <label className={styles.label} htmlFor="objectType">
          Тип об&apos;єкта
        </label>
        <select
          id="objectType"
          className={styles.control}
          value={value.objectType}
          onChange={(e) => {
            const objectType = e.target.value as ObjectType;
            if (objectType === 'apartment') {
              onChange({
                objectType,
                apartmentStackPosition: value.apartmentStackPosition ?? 'middle_floor',
                floors: value.floors,
                roomsCount: value.roomsCount,
                externalWalls: value.externalWalls,
                ...(value.ventilationReserveMode !== undefined
                  ? { ventilationReserveMode: value.ventilationReserveMode }
                  : {}),
                ...(value.roofPresetId !== undefined
                  ? { roofPresetId: value.roofPresetId }
                  : {}),
              });
              return;
            }
            onChange({
              ...value,
              objectType,
              boilerPlacementZone: value.boilerPlacementZone ?? 'kitchen',
            });
          }}
        >
          <option value="house">Будинок</option>
          <option value="apartment">Квартира</option>
        </select>
      </div>

      {value.objectType === 'apartment' && (
        <div className={`${styles.field} ${styles.fullWidth}`}>
          <label className={styles.label} htmlFor="apartmentStackPosition">
            Поверх квартири в будинку
          </label>
          <select
            id="apartmentStackPosition"
            className={styles.control}
            value={value.apartmentStackPosition ?? 'middle_floor'}
            onChange={(e) =>
              { onChange({
                ...value,
                apartmentStackPosition: e.target.value as ApartmentStackPosition,
              }); }
            }
          >
            <option value="first_floor">Перший (знизу підвал / холод)</option>
            <option value="middle_floor">Середній (між сусідами)</option>
            <option value="last_floor">Останній (зверху горище / покрівля)</option>
          </select>
          <p className={styles.hint}>
            Задає нижню та верхню межі приміщень: підлога та стеля в тепловтратах враховуються
            лише там, де за межею холодна зона.
          </p>
        </div>
      )}

      <div className={styles.field}>
        <label className={styles.label} htmlFor="floors">
          Поверховість об&apos;єкта
        </label>
        <select
          id="floors"
          className={styles.control}
          value={value.floors}
          onChange={(e) =>
            { onChange({
              ...value,
              floors: (toIntOrUndefined(e.target.value) ?? 1) as 1 | 2 | 3,
            }); }
          }
        >
          <option value={1}>1</option>
          <option value={2}>2</option>
          <option value={3}>3</option>
        </select>
      </div>

      <div className={styles.field}>
        <label className={styles.label} htmlFor="roomsCount">
          Кількість приміщень ({ROOMS_COUNT_MIN}…{ROOMS_COUNT_MAX})
        </label>
        <input
          id="roomsCount"
          data-testid="field-rooms-count"
          className={styles.control}
          type="number"
          min={ROOMS_COUNT_MIN}
          max={ROOMS_COUNT_MAX}
          step={1}
          value={value.roomsCount}
          onChange={(e) =>
            { onChange({
              ...value,
              roomsCount: clampRoomsCount(Number(e.target.value)),
            }); }
          }
        />
      </div>

      <div className={`${styles.field} ${styles.fullWidth}`}>
        <label className={styles.label} htmlFor="ventilationReserveMode">
          Вентиляція та провітрювання
        </label>
        <select
          id="ventilationReserveMode"
          className={styles.control}
          value={value.ventilationReserveMode ?? 'natural'}
          onChange={(e) =>
            { onChange({
              ...value,
              ventilationReserveMode: e.target.value as VentilationReserveMode,
            }); }
          }
        >
          <option value="natural">
            Природна вентиляція / ручне провітрювання (kVent 1,3)
          </option>
          <option value="recuperation">
            Припливно-витяжна з рекуператором (kVent 1,1)
          </option>
        </select>
        <div className={styles.hint}>
          Запас до тепловтрат через огороження по кожному приміщенню; враховується при підборі котла
          та радіаторів.
        </div>
      </div>

      {value.objectType === 'house' && (
        <>
          <div className={`${styles.field} ${styles.fullWidth}`}>
            <label className={styles.label} htmlFor="boilerPlacementZone">
              Заплановане встановлення котла
            </label>
            <select
              id="boilerPlacementZone"
              className={styles.control}
              value={value.boilerPlacementZone ?? 'kitchen'}
              onChange={(e) =>
                { onChange({
                  ...value,
                  boilerPlacementZone: e.target.value as BoilerPlacementZone,
                }); }
              }
            >
              <option value="kitchen">Кухня (настінний)</option>
              <option value="living_zone">Житлова зона (настінний)</option>
              <option value="boiler_room">Окрема котельня / топочна</option>
            </select>
            <div className={styles.hint}>
              Напольні котли підбираються лише при виборі котельні та об&apos;ємі не менше 7,5 м³
              (приміщення «Котельня» в списку приміщень або площа й висота нижче).
            </div>
          </div>

          {value.boilerPlacementZone === 'boiler_room' && (
            <>
              <div className={styles.field}>
                <label className={styles.label} htmlFor="boilerRoomAreaM2">
                  Площа котельні, м²
                </label>
                <input
                  id="boilerRoomAreaM2"
                  className={styles.control}
                  type="number"
                  min={0.1}
                  step={0.1}
                  value={value.boilerRoomAreaM2 ?? ''}
                  onChange={(e) => {
                    const v = e.target.value === '' ? undefined : Number(e.target.value);
                    if (v !== undefined) {
                      onChange({ ...value, boilerRoomAreaM2: v });
                      return;
                    }
                    const { boilerRoomAreaM2: _omit, ...rest } = value;
                    void _omit;
                    onChange(rest);
                  }}
                  placeholder="наприклад, 3.5"
                />
              </div>
              <div className={styles.field}>
                <label className={styles.label} htmlFor="ceilingHeightM">
                  Висота стелі котельні, м
                </label>
                <input
                  id="ceilingHeightM"
                  className={styles.control}
                  type="number"
                  min={2.2}
                  max={6}
                  step={0.1}
                  value={value.ceilingHeightM ?? ''}
                  onChange={(e) => {
                    const v = e.target.value === '' ? undefined : Number(e.target.value);
                    if (v !== undefined) {
                      onChange({ ...value, ceilingHeightM: v });
                      return;
                    }
                    const { ceilingHeightM: _omit, ...rest } = value;
                    void _omit;
                    onChange(rest);
                  }}
                  placeholder="не менше 2,2"
                />
              </div>
            </>
          )}
        </>
      )}

      <div className={`${styles.field} ${styles.fullWidth}`}>
        <label className={styles.label} htmlFor="wallPresetId">
          Несуча стіна (без утеплювача)
        </label>
        <select
          id="wallPresetId"
          className={styles.control}
          value={wallPresets.length === 0 ? '' : value.externalWalls.presetId}
          onChange={(e) => { patchExternalWalls({ presetId: e.target.value }); }}
          disabled={loadingPresets || wallPresets.length === 0}
        >
          {loadingPresets ? (
            <option value="">Завантаження…</option>
          ) : wallPresets.length === 0 ? (
            <option value="">Немає пресетів для стін</option>
          ) : (
            wallPresets.map((p) => (
              <option key={p.id} value={p.id}>
                {envelopePresetLabel(p)}
              </option>
            ))
          )}
        </select>
        {presetsError ? (
          <div className={styles.hint}>{presetsError}</div>
        ) : (
          <div className={styles.hint}>
            Пресети несучого шару — з довідника API (`/api/v1/presets/envelope`, kind=wall).
          </div>
        )}
      </div>

      <div className={`${styles.field} ${styles.fullWidth}`}>
        <label className={styles.label} htmlFor="wallThicknessMm">
          Товщина несучої стіни, мм
        </label>
        <input
          id="wallThicknessMm"
          data-testid="field-wall-thickness"
          className={styles.control}
          type="number"
          inputMode="numeric"
          min={50}
          max={2000}
          step={10}
          value={value.externalWalls.thicknessMm ?? ''}
          onChange={(e) => {
            const next = e.target.value === '' ? undefined : Number(e.target.value);
            if (next !== undefined) {
              patchExternalWalls({ thicknessMm: next });
              return;
            }
            const { thicknessMm: _omit, ...wallsWithout } = value.externalWalls;
            void _omit;
            onChange({ ...value, externalWalls: wallsWithout });
          }}
          placeholder={
            thicknessOptions && thicknessOptions.length > 0
              ? `наприклад, ${thicknessOptions[0]}`
              : 'наприклад, 300'
          }
        />
        {thicknessOptions && thicknessOptions.length > 0 && (
          <div className={styles.hint}>
            Типові товщини: {thicknessOptions.join(', ')} мм.
          </div>
        )}
      </div>

      <div className={`${styles.field} ${styles.fullWidth}`}>
        <label className={styles.label} htmlFor="facadeSystem">
          Утеплення фасаду
        </label>
        <select
          id="facadeSystem"
          className={styles.control}
          value={facadeSystem}
          onChange={(e) => { onFacadeSystemChange(e.target.value as FacadeSystem); }}
        >
          <option value="none">Без утеплювача</option>
          <option value="sftk">СФТК (мокрий фасад) — ППС 16Ф</option>
          <option value="ventilated">Відкритий / вентильований фасад — мінвата</option>
        </select>
        <div className={styles.hint}>
          Пінополістирол допустимий лише в СФТК (шар захищений штукатуркою). У відкритому вигляді — лише
          мінеральна вата (СП 50.13330).
        </div>
      </div>

      {facadeSystem !== 'none' && (
        <>
          <div className={`${styles.field} ${styles.fullWidth}`}>
            <label className={styles.label} htmlFor="insulationPresetId">
              {facadeSystem === 'sftk' ? 'Утеплювач СФТК' : 'Мінеральна вата'}
            </label>
            <select
              id="insulationPresetId"
              className={styles.control}
              value={
                activeInsulationPresets.length === 0
                  ? ''
                  : (value.externalWalls.insulationPresetId ?? '')
              }
              onChange={(e) => { patchExternalWalls({ insulationPresetId: e.target.value }); }}
              disabled={loadingPresets || activeInsulationPresets.length === 0}
            >
              {activeInsulationPresets.length === 0 ? (
                <option value="">Немає пресетів утеплювача</option>
              ) : (
                activeInsulationPresets.map((p) => (
                  <option key={p.id} value={p.id}>
                    {envelopePresetLabel(p)}
                  </option>
                ))
              )}
            </select>
          </div>

          <div className={`${styles.field} ${styles.fullWidth}`}>
            <label className={styles.label} htmlFor="insulationThicknessMm">
              Товщина утеплювача, мм
            </label>
            <input
              id="insulationThicknessMm"
              className={styles.control}
              type="number"
              inputMode="numeric"
              min={30}
              max={300}
              step={10}
              value={value.externalWalls.insulationThicknessMm ?? ''}
              onChange={(e) => {
                const next = e.target.value === '' ? undefined : Number(e.target.value);
                if (next !== undefined) {
                  patchExternalWalls({ insulationThicknessMm: next });
                  return;
                }
                const { insulationThicknessMm: _omit, ...wallsWithout } = value.externalWalls;
                void _omit;
                onChange({ ...value, externalWalls: wallsWithout });
              }}
              placeholder={
                insulationThicknessOptions && insulationThicknessOptions.length > 0
                  ? `наприклад, ${insulationThicknessOptions[0]}`
                  : 'наприклад, 100'
              }
            />
            {insulationThicknessOptions && insulationThicknessOptions.length > 0 && (
              <div className={styles.hint}>
                Типові товщини: {insulationThicknessOptions.join(', ')} мм.
              </div>
            )}
          </div>
        </>
      )}

      <div className={`${styles.field} ${styles.fullWidth}`}>
        <label className={styles.label} htmlFor="roofPresetId">
          Покрівля за замовчуванням (пресет)
        </label>
        <select
          id="roofPresetId"
          className={styles.control}
          value={roofPresets.length === 0 ? '' : (value.roofPresetId ?? '')}
          onChange={(e) => { onChange({ ...value, roofPresetId: e.target.value }); }}
          disabled={loadingPresets || roofPresets.length === 0}
        >
          {loadingPresets ? (
            <option value="">Завантаження…</option>
          ) : roofPresets.length === 0 ? (
            <option value="">Немає пресетів для покрівлі</option>
          ) : (
            <>
              <option value="">Не враховувати покрівлю</option>
              {roofPresets.map((p) => (
                <option key={p.id} value={p.id}>
                  {envelopePresetLabel(p)}
                </option>
              ))}
            </>
          )}
        </select>
        <div className={styles.hint}>
          Використовується як значення за замовчуванням для кімнат з верхньою межею «Покрівля (мансарда)»,
          якщо в кімнаті не обрано свій пресет.
        </div>
      </div>

      <div className={`${styles.field} ${styles.fullWidth}`}>
        <div className={styles.hint}>
          U зовнішньої стіни: несучий шар + утеплювач (якщо обрано) по шарах; β за орієнтацією — у
          розрахунку приміщень.
        </div>
      </div>
    </div>
  );
}

/**
