/**
 * Назначение: Таблица подбора радиаторов по комнатам.
 * Описание: Секции / панели для линии Economy или Efficient с явным типом прибора.
 */

import styles from './RadiatorProposalLineTable.module.css';
import {
  formatRadiatorRoomQuantityLabel,
  formatRadiatorsEmittersSummaryLabel,
  type RadiatorsProposalLineView,
} from '../../utils/parsers/parseRadiatorsMatchingFromReport';

type RadiatorProposalLineTableProps = {
  line: RadiatorsProposalLineView | null;
  caption: string;
  tableId: string;
};

/** Таблиця секцій / панелей радіаторів по приміщеннях. */
export function RadiatorProposalLineTable({
  line,
  caption,
  tableId,
}: RadiatorProposalLineTableProps) {
  if (line == null) {
    return null;
  }

  if (line.unavailableReason) {
    return (
      <p className={styles.unavailable} role="status">
        {line.unavailableReason}
      </p>
    );
  }

  const graphLabel =
    line.supplyC != null && line.returnC != null
      ? `${line.supplyC}/${line.returnC} °C`
      : null;
  const emittersLabel = formatRadiatorsEmittersSummaryLabel(line.emittersSummary);

  return (
    <div className={styles.wrap}>
      <p className={styles.caption} id={`${tableId}-caption`}>
        {caption}
        {graphLabel != null ? ` · графік ${graphLabel}` : ''}
        {emittersLabel != null ? ` · ${emittersLabel}` : ''}
      </p>
      {line.byRoom.length > 0 ? (
        <table
          className={styles.table}
          aria-labelledby={`${tableId}-caption`}
        >
          <thead>
            <tr>
              <th scope="col">Приміщення</th>
              <th scope="col">Прилад</th>
              <th scope="col">Кількість</th>
              <th scope="col">Віддача, Вт</th>
            </tr>
          </thead>
          <tbody>
            {line.byRoom.map((row) => {
              const qty = formatRadiatorRoomQuantityLabel(row);
              const model =
                row.radiatorModel && row.radiatorModel !== '—'
                  ? row.radiatorModel
                  : '—';
              const deliverable =
                row.deliverableWatts != null && row.deliverableWatts > 0
                  ? String(Math.round(row.deliverableWatts))
                  : '—';
              return (
                <tr
                  key={row.roomId || row.roomName}
                  className={
                    row.equipmentKindChangedVsEconomy
                      ? styles.kindChanged
                      : undefined
                  }
                  title={
                    row.equipmentKindChangedVsEconomy
                      ? 'Тип приладу відрізняється від варіанта «Економ»'
                      : undefined
                  }
                >
                  <td>
                    {row.roomName}
                    {row.equipmentKindChangedVsEconomy ? (
                      <span className={styles.kindChangedMark} aria-label="Тип приладу відрізняється від варіанта Економ">
                        {' '}
                        ≠економ
                      </span>
                    ) : null}
                  </td>
                  <td>{model}</td>
                  <td>{qty}</td>
                  <td>{deliverable}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      ) : (
        <p className={styles.unavailable}>Немає даних за приміщеннями.</p>
      )}
    </div>
  );
}

/**
 * Призначення: модальне вікно звіту підбору радіаторів.
 * Опис: Патерн WaterHeaterReportDialog; контент — RadiatorsReportView.
 */

import { useEffect } from 'react';

import type { ParsedRadiatorsMatching } from '../../utils/parsers/parseRadiatorsMatchingFromReport';
import { RadiatorsReportView } from './RadiatorsReportView';
import { hasRadiatorsReportContent } from './hasRadiatorsReportContent';
import styles from './RadiatorsReportDialog.module.css';

export type RadiatorsReportDialogProps = {
  open: boolean;
  onClose: () => void;
  radiators: ParsedRadiatorsMatching | null;
};

/**
 * @param props
 */
export function RadiatorsReportDialog({
  open,
  onClose,
  radiators,
}: RadiatorsReportDialogProps) {
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [open, onClose]);

  if (!open) return null;

  const hasContent = hasRadiatorsReportContent(radiators);

  return (
    <div
      className={styles.backdrop}
      role="presentation"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className={styles.dialog}
        role="dialog"
        aria-modal="true"
        aria-labelledby="radiators-report-dialog-title"
        onClick={(e) => {
          e.stopPropagation();
        }}
      >
        <div className={styles.header}>
          <h2 id="radiators-report-dialog-title" className={styles.title}>
            Звіт із розрахунку радіаторів
          </h2>
          <button
            type="button"
            className={styles.closeIconButton}
            onClick={onClose}
            aria-label="Закрити"
          >
            ✕
          </button>
        </div>

        {hasContent && radiators != null ? (
          <RadiatorsReportView radiators={radiators} />
        ) : (
          <p className={styles.empty}>
            Немає даних підбору радіаторів. Заповніть приміщення та огородження,
            задайте підводку та тип приладів, дочекайтеся авторасчунку. У режимі
            «лише тепла підлога» (ufh_only) підбір радіаторів пропускається.
          </p>
        )}

        <button type="button" className={styles.closeButton} onClick={onClose}>
          Закрити
        </button>
      </div>
    </div>
  );
}

/**
 * Призначення: повний звіт підбору радіаторів.
 * Опис: Тіло модалки кроку «Радіатори»; деталізація не дублюється в «Рекомендації».
 */

import {
  formatRadiatorsEmittersSummaryLabel,
  type ParsedRadiatorsMatching,
} from '../../utils/parsers/parseRadiatorsMatchingFromReport';
import { RadiatorProposalLineTable } from '../RadiatorProposalLineTable/RadiatorProposalLineTable';
import styles from './RadiatorsReportView.module.css';

export type RadiatorsReportViewProps = {
  radiators: ParsedRadiatorsMatching;
};

/**
 * @param props
 */
export function RadiatorsReportView({ radiators }: RadiatorsReportViewProps) {
  const emittersLabel = formatRadiatorsEmittersSummaryLabel(radiators.emittersSummary);
  const inputs = radiators.inputs;
  const showInputs =
    inputs != null
    && (inputs.supplyC != null
      || inputs.flowDeltaTK != null
      || inputs.radiatorConnection != null
      || inputs.radiatorEmitterPreference != null
      || inputs.targetDeltaT != null);

  const hasProposalLines =
    radiators.lineEconomy != null || radiators.lineEfficient != null;

  return (
    <div>
      <p className={styles.hint}>
        Підбір за matching.radiators. Таблиці поруч із котлом у блоці «Рекомендація»
        залишаються для порівняння варіантів; тут — повний розрахунок.
      </p>

      {showInputs ? (
        <>
          <h4 className={styles.sectionTitle}>Вихідні параметри</h4>
          <dl className={styles.dl}>
            {inputs.supplyC != null && inputs.returnC != null && (
              <>
                <dt>Графік подача / зворотка</dt>
                <dd>
                  {inputs.supplyC}/{inputs.returnC} °C
                </dd>
              </>
            )}
            {inputs.targetDeltaT != null && (
              <>
                <dt>ΔT_mean (EN442)</dt>
                <dd>{inputs.targetDeltaT} K</dd>
              </>
            )}
            {inputs.flowDeltaTK != null && (
              <>
                <dt>Δt витрати</dt>
                <dd>{inputs.flowDeltaTK} K</dd>
              </>
            )}
            {inputs.radiatorConnection != null && (
              <>
                <dt>Підводка</dt>
                <dd>
                  {inputs.radiatorConnection === 'bottom' ? 'нижня' : 'бокова'}
                  <span className={styles.muted}>
                    {' '}
                    ({inputs.radiatorConnection})
                  </span>
                </dd>
              </>
            )}
            {inputs.radiatorEmitterPreference != null && (
              <>
                <dt>Тип приладів (анкета)</dt>
                <dd>
                  {inputs.radiatorEmitterPreference === 'auto'
                    ? 'авто (Two-Pass)'
                    : inputs.radiatorEmitterPreference === 'panel'
                      ? 'панельні'
                      : 'секційні'}
                  <span className={styles.muted}>
                    {' '}
                    ({inputs.radiatorEmitterPreference})
                  </span>
                </dd>
              </>
            )}
            {radiators.resolvedEmitterKind != null && (
              <>
                <dt>Тип приладів (результат)</dt>
                <dd>
                  {radiators.resolvedEmitterKind === 'panel'
                    ? 'панельні'
                    : 'секційні'}
                </dd>
              </>
            )}
          </dl>
        </>
      ) : null}

      {(radiators.chosenModel != null && radiators.chosenModel.length > 0)
        || emittersLabel != null
        || radiators.totalSections != null
        || radiators.byRoom.length > 0 ? (
        <>
          <h4 className={styles.sectionTitle}>Агрегати за об&apos;єктом</h4>
          <dl className={styles.dl}>
            {radiators.chosenModel != null && radiators.chosenModel.length > 0 && (
              <>
                <dt>Модель (підбір)</dt>
                <dd>{radiators.chosenModel}</dd>
              </>
            )}
            {emittersLabel != null && (
              <>
                <dt>Прилади</dt>
                <dd>{emittersLabel}</dd>
              </>
            )}
            {radiators.totalSections != null && (
              <>
                <dt>Секції (без панелей)</dt>
                <dd>{radiators.totalSections} шт.</dd>
              </>
            )}
            {radiators.byRoom.length > 0 && (
              <>
                <dt>Приміщень у підборі</dt>
                <dd>{radiators.byRoom.length}</dd>
              </>
            )}
          </dl>
        </>
      ) : null}

      {hasProposalLines && (
        <>
          <h4 className={styles.sectionTitle}>Лінії економ / ефективний</h4>
          <div className={styles.proposalLinesGrid}>
            <RadiatorProposalLineTable
              line={radiators.lineEconomy}
              caption="Варіант 1 · економ"
              tableId="radiators-report-line-economy"
            />
            <RadiatorProposalLineTable
              line={radiators.lineEfficient}
              caption="Варіант 2 · ефективний"
              tableId="radiators-report-line-efficient"
            />
          </div>
        </>
      )}

      {radiators.warnings.length > 0 && (
        <>
          <h4 className={styles.sectionTitle}>Попередження</h4>
          <ul className={styles.warningsList}>
            {radiators.warnings.map((w, i) => (
              <li key={`rad-report-w-${i}-${w.slice(0, 64)}`}>{w}</li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}

/**
 * Призначення: компактний підсумок радіаторів для сайдбару «Итог».
 * Опис: Ключові цифри; деталі — у модалці кроку «Радіатори».
 */

import {
  formatRadiatorsEmittersSummaryLabel,
  type ParsedRadiatorsMatching,
} from '../../utils/parsers/parseRadiatorsMatchingFromReport';
import { isRadiatorsMatchingSkipped } from '../../utils/radiatorsSkip';
import { RESULTS_SECTION_IDS } from '../../constants/surveyResultsSections';
import { SurveyStepLink } from '../SurveyNavigation/SurveyStepLink';
import { hasRadiatorsReportContent } from './hasRadiatorsReportContent';
import styles from './RadiatorsSummaryTable.module.css';

export type RadiatorsSummaryTableProps = {
  radiators: ParsedRadiatorsMatching | null;
  /** Підпис агрегату секцій / приладів (з useCalcReport або чернетка). */
  sectionsTotalLabel: string;
};

/**
 * @param props
 */
export function RadiatorsSummaryTable({
  radiators,
  sectionsTotalLabel,
}: RadiatorsSummaryTableProps) {
  if (!hasRadiatorsReportContent(radiators) || radiators == null) {
    return null;
  }

  if (isRadiatorsMatchingSkipped(radiators)) {
    return (
      <div
        id={RESULTS_SECTION_IDS.radiators}
        className={styles.wrap}
        aria-labelledby="radiators-summary-title"
      >
        <h3 id="radiators-summary-title" className={styles.title}>
          Радіатори (підсумок)
        </h3>
        <p className={styles.hint}>
          Режим «лише тепла підлога» — підбір радіаторів не виконується. Секції
          приладів не потрібні. Деталі — на кроці{' '}
          <SurveyStepLink step="radiators">«Радіатори»</SurveyStepLink>
          .
        </p>
      </div>
    );
  }

  const emittersLabel = formatRadiatorsEmittersSummaryLabel(radiators.emittersSummary);
  const instrumentsLabel = emittersLabel ?? sectionsTotalLabel;
  const hasWarnings = radiators.warnings.length > 0;

  const graphLabel =
    radiators.inputs?.supplyC != null && radiators.inputs.returnC != null
      ? `${radiators.inputs.supplyC}/${radiators.inputs.returnC} °C`
      : null;

  const connectionLabel =
    radiators.inputs?.radiatorConnection === 'bottom'
      ? 'нижня'
      : radiators.inputs?.radiatorConnection === 'side'
        ? 'бокова'
        : null;

  const kindLabel =
    radiators.resolvedEmitterKind === 'panel'
      ? 'панельні'
      : radiators.resolvedEmitterKind === 'sectional'
        ? 'секційні'
        : null;

  const onlySkipWarnings =
    radiators.byRoom.length === 0
    && radiators.emittersSummary == null
    && radiators.totalSections == null
    && radiators.chosenModel == null
    && hasWarnings;

  return (
    <div
      id={RESULTS_SECTION_IDS.radiators}
      className={styles.wrap}
      aria-labelledby="radiators-summary-title"
    >
      <h3 id="radiators-summary-title" className={styles.title}>
        Радіатори (підсумок)
      </h3>
      {onlySkipWarnings ? (
        <p className={styles.hint}>
          Підбір радіаторів пропущено або ще без приміщень у звіті. Деталі — на кроці{' '}
          <SurveyStepLink step="radiators">«Радіатори»</SurveyStepLink>
          .
        </p>
      ) : (
        <div className={styles.tableWrap}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>Показник</th>
                <th>Значення</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>Прилади / секції</td>
                <td>{instrumentsLabel}</td>
              </tr>
              {radiators.chosenModel != null && radiators.chosenModel.length > 0 && (
                <tr>
                  <td>Модель</td>
                  <td>{radiators.chosenModel}</td>
                </tr>
              )}
              {graphLabel != null && (
                <tr>
                  <td>Графік</td>
                  <td>{graphLabel}</td>
                </tr>
              )}
              {connectionLabel != null && (
                <tr>
                  <td>Підводка</td>
                  <td>{connectionLabel}</td>
                </tr>
              )}
              {kindLabel != null && (
                <tr>
                  <td>Тип приладів</td>
                  <td>{kindLabel}</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}
      <p className={styles.hint}>
        Повний розрахунок і попередження — на кроці{' '}
        <SurveyStepLink step="radiators">«Радіатори»</SurveyStepLink>
        . Таблиці за варіантами поруч із котлом — у блоці «Рекомендація».
      </p>
      {hasWarnings && (
        <p className={styles.attention}>
          Є попередження щодо радіаторів — відкрийте звіт на кроці{' '}
          <SurveyStepLink step="radiators">«Радіатори»</SurveyStepLink>
          .
        </p>
      )}
    </div>
  );
}

/**
 * Призначення: перевірка наявності даних matching.radiators для UI.
 * Опис: Кнопка звіту на кроці «Радіатори» та summary в сайдбарі.
 */

import type { ParsedRadiatorsMatching } from '../../utils/parsers/parseRadiatorsMatchingFromReport';
import { isRadiatorsMatchingSkipped } from '../../utils/radiatorsSkip';

/**
 * Чи є дані для показу звіту / summary радіаторів (включно зі skip ufh_only).
 *
 * @param radiators
 */
export function hasRadiatorsReportContent(
  radiators: ParsedRadiatorsMatching | null | undefined,
): boolean {
  if (radiators == null) return false;
  if (isRadiatorsMatchingSkipped(radiators)) return true;
  if (radiators.byRoom.length > 0) return true;
  if (radiators.emittersSummary != null) return true;
  if (radiators.totalSections != null) return true;
  if (radiators.lineEconomy != null || radiators.lineEfficient != null) return true;
  if (radiators.warnings.length > 0) return true;
  if (radiators.chosenModel != null && radiators.chosenModel.length > 0) return true;
  return false;
}

/**
 * Призначення: форма кроку анкети «Радіатори».
 * Опис: підводка, тип приладів; звіт розрахунку — у модалці (патерн ТП / ГВ / ВН).
 */

import { useState } from 'react';

import {
  isRadiatorConnection,
  RADIATOR_CONNECTION_SURVEY_UI_OPTIONS,
  type RadiatorConnection,
} from '../../types/radiatorConnection';
import {
  isRadiatorEmitterPreference,
  RADIATOR_EMITTER_PREFERENCE_SURVEY_UI_OPTIONS,
  type RadiatorEmitterPreference,
} from '../../types/radiatorEmitterPreference';
import type { ParsedRadiatorsMatching } from '../../utils/parsers/parseRadiatorsMatchingFromReport';
import { RadiatorsReportDialog } from '../RadiatorsReport/RadiatorsReportDialog';
import { hasRadiatorsReportContent } from '../RadiatorsReport/hasRadiatorsReportContent';
import reportActionsStyles from '../SurveyNavigation/SurveyReportActions.module.css';
import styles from './RadiatorsSurveyForm.module.css';

export type RadiatorsSurveyFormProps = {
  radiatorConnection: RadiatorConnection;
  radiatorEmitterPreference: RadiatorEmitterPreference;
  onConnectionChange: (connection: RadiatorConnection) => void;
  onPreferenceChange: (preference: RadiatorEmitterPreference) => void;
  /**
   * Якщо задано (режим ufh_only) — селекти disabled, значення в draft не скидаються.
   * Matching радіаторів на бекенді skip; поля все одно йдуть у heatingSystem з дефолтами.
   */
  radiatorsDisabledReason: string | null;
  radiatorsMatching: ParsedRadiatorsMatching | null;
  calcLoading?: boolean;
  /** Прокрутка до підсумку радіаторів у сайдбарі «Результати». */
  onBackToResults?: () => void;
};

/**
 * Крок «Радіатори»: підводка, тип приладів і звіт підбору.
 *
 * @param props
 */
export function RadiatorsSurveyForm({
  radiatorConnection,
  radiatorEmitterPreference,
  onConnectionChange,
  onPreferenceChange,
  radiatorsDisabledReason,
  radiatorsMatching,
  calcLoading = false,
  onBackToResults,
}: RadiatorsSurveyFormProps) {
  const [reportOpen, setReportOpen] = useState(false);
  const disabled = radiatorsDisabledReason != null;
  const canOpenReport = hasRadiatorsReportContent(radiatorsMatching);

  return (
    <div className={styles.root}>
      {radiatorsDisabledReason != null && (
        <p className={styles.status} role="status">
          {radiatorsDisabledReason}
        </p>
      )}

      <div className={styles.fieldBlock}>
        <label className={styles.fieldLabel} htmlFor="radiator-connection">
          Підводка радіаторів
        </label>
        <select
          id="radiator-connection"
          className={styles.select}
          value={radiatorConnection}
          disabled={disabled}
          aria-disabled={disabled}
          onChange={(e) => {
            if (!isRadiatorConnection(e.target.value)) return;
            onConnectionChange(e.target.value);
          }}
        >
          {RADIATOR_CONNECTION_SURVEY_UI_OPTIONS.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
        <p className={styles.hint}>
          Бокова — серії K/Klasik; нижня — VK/VKP. Фільтрує панельний пул.
          Тип приладу на весь об&apos;єкт задається окремо. В API:{' '}
          <code className={styles.inlineCode}>
            heatingSystem.radiatorConnection
          </code>
          .
        </p>
      </div>

      <div className={styles.fieldBlock}>
        <label
          className={styles.fieldLabel}
          htmlFor="radiator-emitter-preference"
        >
          Тип радіаторів на об&apos;єкт
        </label>
        <select
          id="radiator-emitter-preference"
          className={styles.select}
          value={radiatorEmitterPreference}
          disabled={disabled}
          aria-disabled={disabled}
          onChange={(e) => {
            if (!isRadiatorEmitterPreference(e.target.value)) return;
            onPreferenceChange(e.target.value);
          }}
        >
          {RADIATOR_EMITTER_PREFERENCE_SURVEY_UI_OPTIONS.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
        <p className={styles.hint}>
          Один тип приладів на всі приміщення (секції або панелі). Авто —
          Two-Pass по об&apos;єкту. В API:{' '}
          <code className={styles.inlineCode}>
            heatingSystem.radiatorEmitterPreference
          </code>
          .
        </p>
      </div>

      <div className={reportActionsStyles.reportActions}>
        <div className={reportActionsStyles.reportActionsRow}>
          <button
            type="button"
            className={reportActionsStyles.reportButton}
            disabled={!canOpenReport}
            onClick={() => {
              setReportOpen(true);
            }}
          >
            Звіт з розрахунку радіаторів
          </button>
          {onBackToResults != null && (
            <button
              type="button"
              className={reportActionsStyles.backButton}
              onClick={onBackToResults}
            >
              Назад до результатів
            </button>
          )}
        </div>
        {calcLoading && (
          <p className={`${styles.hint} ${styles.hintMt8}`} role="status">
            Оновлення розрахунку…
          </p>
        )}
        {!canOpenReport && !calcLoading && (
          <p className={`${styles.hint} ${styles.hintMt8}`}>
            Звіт з&apos;явиться після авторозрахунку. Заповніть приміщення та огородження;
            у режимі «лише тепла підлога» підбір радіаторів пропускається — у
            звіті буде пояснення після відповіді сервера.
          </p>
        )}
      </div>

      <RadiatorsReportDialog
        open={reportOpen}
        onClose={() => {
          setReportOpen(false);
        }}
        radiators={radiatorsMatching}
      />
    </div>
  );
}

