/**
 * Делегирование клика по data-survey-step в дочерних summary-блоках.
 *
 * @param e
 * @param onNavigate
 */
function handleSummaryNavigateClick(
  e: MouseEvent<HTMLElement>,
  onNavigate: RecommendationsBlockProps['onNavigateToSurveyStep'],
) {
  if (onNavigate == null) return;
  const el = (e.target as HTMLElement).closest('[data-survey-step]');
  if (el == null) return;
  const step = el.getAttribute('data-survey-step');
  if (isSurveyStep(step)) {
    e.preventDefault();
    onNavigate(step);
  }
}

export function RecommendationsBlock({
  className,
  quickEstimate,
  apiHeatLoss,
  apiHotWaterFromReport,
  hotWaterFixtures,
  waterHeaterScheme,
  apiBoilerFromReport,
  apiBoilerKw,
  apiRadiatorsFromReport,
  apiIndirectWhFromReport,
  apiElectricWhFromReport,
  apiUnderfloorHeatingFromReport,
  apiUniboxesFromReport = null,
  displayedRadiatorSectionsTotal,
  apiCatalogSource,
  apiAutomationHints,
  objectType,
  onApplyScheme,
  apiHydraulicsFromReport,
  calcLoading = false,
  reportIsStale = false,
  uiPhase = 'idle',
  onNavigateToSurveyStep,
}: RecommendationsBlockProps) {
  const showRecalculating = calcLoading || reportIsStale || uiPhase === 'recalculating';
  // Машиночитаемые маркеры для автотестов: значения берутся из уже существующего
  // состояния (apiHeatLoss — тот же признак, что формирует подпись «Джерело: …»;
  // uiPhase / showRecalculating — фаза отчёта из surveySession).
  const calcPhase = showRecalculating
    ? 'pending'
    : uiPhase === 'error'
      ? 'error'
      : uiPhase === 'stable'
        ? 'ok'
        : 'idle';
  return (
    <div
      className={[styles.root, className].filter(Boolean).join(' ')}
      data-testid="result-panel"
      data-source={apiHeatLoss != null ? 'api' : 'quick'}
      data-calc-phase={calcPhase}
    >
      <section
        aria-labelledby="calculation-results-title"
        onClick={(e) => { handleSummaryNavigateClick(e, onNavigateToSurveyStep); }}
      >
        <h2 id="calculation-results-title">Результати розрахунку</h2>

        {apiCatalogSource != null && (
          <p className={`${styles.hint} ${styles.hintMt8Mb0}`}>
            {apiCatalogSource === 'mongo'
              ? 'Підбір обладнання виконано за каталогом із бази даних (MongoDB).'
              : 'Підбір за файловим каталогом. Для використання БД: CATALOG_SOURCE=auto (або mongo), змінні MONGODB_* і колекція Product після seed.'}
          </p>
        )}

        {showRecalculating && (
          <p className={styles.hint} role="status" aria-live="polite">
            Оновлення розрахунку на сервері… Показано дані попередньої відповіді до завершення перерахунку.
          </p>
        )}

        {apiAutomationHints.length > 0 && (
          <div className={styles.boilerCalcSummary} role="status" aria-live="polite">
            <h3 className={styles.boilerCalcSummaryTitle}>
              Рекомендації щодо схеми котел / ГВП
            </h3>
            <ul className={styles.automationHintsList}>
              {apiAutomationHints.map((h, i) => (
                <li key={`${h.type}-${i}`}>
                  {h.message}
                  {h.suggestedScheme != null && (
                    <button
                      type="button"
                      className={styles.automationApplyBtn}
                      onClick={() => {
                        if (h.suggestedScheme != null) onApplyScheme(h.suggestedScheme);
                      }}
                    >
                      Застосувати схему в анкеті
                    </button>
                  )}
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Группа: Отопление */}
        <div className={styles.summaryGroup}>
          <HeatLossSummaryTable
            apiHeatLoss={apiHeatLoss}
            quickEstimate={quickEstimate}
          />
        </div>

        {hasHotWaterFixturesContent(hotWaterFixtures) && (
          <div className={styles.summaryGroup}>
            <HotWaterFixturesSummaryTable fixtures={hotWaterFixtures} />
          </div>
        )}

        {apiUnderfloorHeatingFromReport != null && (
          <div className={styles.summaryGroup}>
            <UnderfloorHeatingSummaryTable
              underfloorHeating={apiUnderfloorHeatingFromReport}
              uniboxes={apiUniboxesFromReport}
              hydraulicsPumps={apiHydraulicsFromReport?.proposal?.pumps ?? null}
            />
          </div>
        )}

        {hasBoilerReportContent(apiBoilerFromReport) && (
          <div className={styles.summaryGroup}>
            <BoilerSummaryTable
              boiler={apiBoilerFromReport}
              objectType={objectType}
              requiredKwFallback={apiBoilerKw ?? quickEstimate.boilerKw}
            />
          </div>
        )}

        {hasRadiatorsReportContent(apiRadiatorsFromReport) && (
          <div className={styles.summaryGroup}>
            <RadiatorsSummaryTable
              radiators={apiRadiatorsFromReport}
              sectionsTotalLabel={displayedRadiatorSectionsTotal}
            />
          </div>
        )}

        {hasHydraulicsReportContent(apiHydraulicsFromReport) && (
          <div className={styles.summaryGroup}>
            <HydraulicsSummaryTable
              hydraulics={apiHydraulicsFromReport ?? null}
            />
          </div>
        )}

        {hasHotWaterSummaryContent(
          apiHotWaterFromReport,
          apiElectricWhFromReport,
          apiIndirectWhFromReport,
        ) && (
          <div className={styles.summaryGroup}>
            <HotWaterSummaryTable
              scheme={waterHeaterScheme}
              hotWater={apiHotWaterFromReport}
              electric={apiElectricWhFromReport}
              indirect={apiIndirectWhFromReport}
              calcLoading={showRecalculating}
            />
          </div>
        )}

        {/* Группа: Оборудование */}
        <div className={styles.summaryGroup}>
          {apiBoilerFromReport != null
            && (apiBoilerFromReport.tierEconomy != null
              || apiBoilerFromReport.tierEfficient != null) && (
            <div className={styles.boilerChoiceRow}>
              {apiBoilerFromReport.tierEconomy != null && (
                <div className={styles.boilerChoiceColumn}>
                  <BoilerProposalCard
                    proposal={apiBoilerFromReport.tierEconomy}
                    catalogSource={apiCatalogSource}
                    sectionTitle={getBoilerUiLabels(
                      apiBoilerFromReport.summary?.hotWaterBoilerPowerMatchingScheme
                        ?? SCHEME_BOILER_MAX_COMBI,
                      objectType,
                    ).proposalEconomyTitle}
                    titleDomId="boiler-proposal-economy"
                  />
                </div>
              )}
              {apiBoilerFromReport.tierEfficient != null && (
                <div className={styles.boilerChoiceColumn}>
                  <BoilerProposalCard
                    proposal={apiBoilerFromReport.tierEfficient}
                    catalogSource={apiCatalogSource}
                    sectionTitle={getBoilerUiLabels(
                      apiBoilerFromReport.summary?.hotWaterBoilerPowerMatchingScheme
                        ?? SCHEME_BOILER_MAX_COMBI,
                      objectType,
                    ).proposalEfficientTitle}
                    titleDomId="boiler-proposal-efficient"
                  />
                </div>
              )}
            </div>
          )}

          {apiBoilerFromReport != null
            && apiBoilerFromReport.tierEconomy == null
            && apiBoilerFromReport.tierEfficient == null
            && apiBoilerFromReport.legacyProposal != null && (
            <BoilerProposalCard
              proposal={apiBoilerFromReport.legacyProposal}
              catalogSource={apiCatalogSource}
            />
          )}

          {apiRadiatorsFromReport != null
            && !isRadiatorsMatchingSkipped(apiRadiatorsFromReport)
            && (apiRadiatorsFromReport.lineEconomy != null
              || apiRadiatorsFromReport.lineEfficient != null) && (
            <div className={styles.radiatorsRecBlock}>
              <h4 className={styles.radiatorsRecTitle}>Радіатори · за варіантами</h4>
              <div className={styles.radiatorsProposalLinesGrid}>
                <RadiatorProposalLineTable
                  line={apiRadiatorsFromReport.lineEconomy}
                  caption="Варіант 1 · економ"
                  tableId="radiators-line-economy"
                />
                <RadiatorProposalLineTable
                  line={apiRadiatorsFromReport.lineEfficient}
                  caption="Варіант 2 · ефективний"
                  tableId="radiators-line-efficient"
                />
              </div>
            </div>
          )}

          {isRadiatorsMatchingSkipped(apiRadiatorsFromReport) && (
            <p className={styles.hint} role="status">
              Радіатори за варіантами не підбираються: режим «лише тепла підлога».
            </p>
          )}

          <HydraulicsProposalTable
            hydraulics={apiHydraulicsFromReport ?? null}
          />
        </div>
      </section>
    </div>
  );
}

/**
 * Назначение: модальное окно «Повідомити про помилку».
 */

import { useCallback, useState } from 'react';

import { modalsUk } from '../../i18n/uk/modals';
import { submitFeedback } from '../../services/feedbackApi';
import { ModalDialog } from '../ModalDialog/ModalDialog';
import modalDialogStyles from '../ModalDialog/ModalDialog.module.css';

export type ReportBugModalProps = {
  open: boolean;
  onClose: () => void;
};

/**
 * @param props
 */
export function ReportBugModal({ open, onClose }: ReportBugModalProps) {
  const t = modalsUk.reportBug;
  const [message, setMessage] = useState('');
  const [email, setEmail] = useState('');
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<'idle' | 'ok' | 'err'>('idle');

  const resetAndClose = useCallback(() => {
    setMessage('');
    setEmail('');
    setStatus('idle');
    onClose();
  }, [onClose]);

  const onSubmit = useCallback(() => {
    const trimmed = message.trim();
    if (!trimmed || busy) return;
    setBusy(true);
    setStatus('idle');
    void (async () => {
      try {
        await submitFeedback({
          type: 'bug',
          message: trimmed,
          ...(email.trim() ? { email: email.trim() } : {}),
          pageUrl: window.location.href,
          appVersion: __APP_VERSION__,
          buildId: __APP_BUILD_ID__,
        });
        setStatus('ok');
        setTimeout(resetAndClose, 1200);
      } catch {
        setStatus('err');
      } finally {
        setBusy(false);
      }
    })();
  }, [message, email, busy, resetAndClose]);

  return (
    <ModalDialog open={open} title={t.title} description={t.description} onClose={resetAndClose}>
      {status === 'ok' ? <p className={modalDialogStyles.statusOk}>{t.success}</p> : null}
      {status === 'err' ? <p className={modalDialogStyles.statusErr}>{t.error}</p> : null}
      <label className={modalDialogStyles.field}>
        <span className={modalDialogStyles.label}>{t.messageLabel}</span>
        <textarea
          className={modalDialogStyles.textarea}
          value={message}
          onChange={(e) => {
            setMessage(e.target.value);
          }}
          placeholder={t.messagePlaceholder}
          required
          maxLength={4000}
        />
      </label>
      <label className={modalDialogStyles.field}>
        <span className={modalDialogStyles.label}>{t.emailLabel}</span>
        <input
          type="email"
          className={modalDialogStyles.input}
          value={email}
          onChange={(e) => {
            setEmail(e.target.value);
          }}
          placeholder={t.emailPlaceholder}
          maxLength={200}
          autoComplete="email"
        />
      </label>
      <div className={modalDialogStyles.actions}>
        <button type="button" className={modalDialogStyles.primary} disabled={busy || !message.trim()} onClick={onSubmit}>
          {t.submit}
        </button>
        <button type="button" className={modalDialogStyles.secondary} onClick={resetAndClose}>
          {t.cancel}
        </button>
      </div>
    </ModalDialog>
  );
}

/**
 * Назначение: Карточка-аккордеон одного помещения.
 * Описание: Площадь, высота, этаж, окна, наружные стены, границы и ограждающие конструкции.
 */

import type { Dispatch, SetStateAction } from 'react';
import {
  ROOM_TYPE_UI_OPTIONS,
  isCanonicalRoomType,
  parseCanonicalRoomTypeFromSelect,
} from '../../constants/roomTypes';
import type { EnvelopePreset, ObjectType } from '../../types/envelope';
import type {
  ExternalWallFormValue,
  RoomExteriorLayout,
  RoomFormValue,
  BottomBoundaryType,
  TopBoundaryType,
  UfhTerminalControl,
  WindowFormValue,
  WindowOrientation,
} from '../../types/rooms';
import { UFH_TERMINAL_CONTROL_MAX_AREA_SQM } from '../../types/rooms';
import type {
  FlooringFinishMaterial,
  UnderfloorHeatingBasePreset,
  UfhPipeSpacingMm,
} from '../../types/underfloorHeating';
import {
  DEFAULT_UFH_PIPE_SPACING_MM,
  UFH_PIPE_SPACING_OPTIONS,
} from '../../types/underfloorHeating';
import { DEFAULT_FLOORING_FINISH_ID } from '../../data/fallbackFlooringFinishes';
import { DEFAULT_WINDOW_PRESET_ID } from '../../data/fallbackEnvelopePresets';
import { DEFAULT_UNDERFLOOR_HEATING_BASE_ID } from '../../data/fallbackUnderfloorHeatingPresets';
import { envelopePresetLabel } from '../../utils/presetLabel';
import { flooringFinishLabel, underfloorBasePresetLabel } from '../../utils/underfloorPresetLabel';
import { ORIENTATION_OPTIONS } from '../../utils/roomEnvelopeFields';
import {
  defaultLayoutForRoomType,
  exteriorWallsSectionHint,
  externalWallFieldConfigs,
  inferRoomExteriorLayout,
  patchRoomForLayoutChange,
} from '../../utils/roomExteriorLayout';
import { createDefaultWindowFormValue } from '../../utils/roomWindowDefaults';
import styles from './RoomAccordionItem.module.css';

type RoomAccordionItemProps = {
  room: RoomFormValue;
  index: number;
  isOpen: boolean;
  onToggle: () => void;
  maxFloors: 1 | 2 | 3;
  /** Наружные стены объекта (несущий слой + утеплитель) — задаются на шаге «Объект». */
  objectExternalWallsSummary: string;
  windowPresets: EnvelopePreset[];
  floorPresets: EnvelopePreset[];
  ceilingPresets: EnvelopePreset[];
  roofPresets: EnvelopePreset[];
  /** Глобальный флаг водяного ТП из шага «Тёплый пол». */
  waterUnderfloorHeating?: boolean;
  underfloorHeatingBases?: UnderfloorHeatingBasePreset[];
  flooringFinishes?: FlooringFinishMaterial[];
  underfloorPresetsLoading?: boolean;
  /** Квартира: границы задаются на шаге «Объект» (этаж в доме). */
  isApartment?: boolean;
  objectType: ObjectType;
  onChange: Dispatch<SetStateAction<RoomFormValue[]>>;
};

function toNumberOrEmpty(raw: string): number | '' {
  if (raw.trim() === '') return '';
  const n = Number(raw);
  if (!Number.isFinite(n)) return '';
  return n;
}

function nextWindowId(roomId: string, windows: WindowFormValue[]): string {
  const existing = new Set(windows.map((w) => w.id));
  let n = 1;
  let candidate = `win-${roomId}-${n}`;
  while (existing.has(candidate)) {
    n += 1;
    candidate = `win-${roomId}-${n}`;
  }
  return candidate;
}

export function RoomAccordionItem({
  room,
  index,
  isOpen,
  onToggle,
  maxFloors,
  objectExternalWallsSummary,
  windowPresets,
  floorPresets,
  ceilingPresets,
  roofPresets,
  waterUnderfloorHeating = false,
  underfloorHeatingBases = [],
  flooringFinishes = [],
  underfloorPresetsLoading = false,
  isApartment = false,
  objectType,
  onChange,
}: RoomAccordionItemProps) {
  const btnId = `room-acc-btn-${room.id}`;
  const panelId = `room-acc-panel-${room.id}`;
  const roomLayout = inferRoomExteriorLayout(room);
  const wallFieldConfigs = externalWallFieldConfigs(roomLayout, objectType);

  const updateRoom = (patch: Partial<RoomFormValue>) => {
    onChange((prev) =>
      prev.map((r) => (r.id === room.id ? { ...r, ...patch } : r)),
    );
  };

  const defaultBaseId =
    underfloorHeatingBases.find((p) => p.id === DEFAULT_UNDERFLOOR_HEATING_BASE_ID)?.id ??
    underfloorHeatingBases[0]?.id ??
    DEFAULT_UNDERFLOOR_HEATING_BASE_ID;

  const defaultFinishId =
    flooringFinishes.find((m) => m.id === DEFAULT_FLOORING_FINISH_ID)?.id ??
    flooringFinishes[0]?.id ??
    DEFAULT_FLOORING_FINISH_ID;

  const ufhEnabled = room.underfloorHeating?.enabled === true;
  const resolvedBaseId = underfloorHeatingBases.some(
    (p) => p.id === room.underfloorHeating?.basePresetId,
  )
    ? (room.underfloorHeating?.basePresetId ?? defaultBaseId)
    : defaultBaseId;

  const resolvedFinishId = flooringFinishes.some(
    (m) => m.id === room.underfloorHeating?.finishMaterialId,
  )
    ? (room.underfloorHeating?.finishMaterialId ?? defaultFinishId)
    : defaultFinishId;

  const resolvedPipeSpacing: UfhPipeSpacingMm =
    room.underfloorHeating?.pipeSpacingMm === 100
    || room.underfloorHeating?.pipeSpacingMm === 150
    || room.underfloorHeating?.pipeSpacingMm === 200
      ? room.underfloorHeating.pipeSpacingMm
      : DEFAULT_UFH_PIPE_SPACING_MM;

  const resolvedFurnitureArea = room.underfloorHeating?.furnitureOccupiedAreaM2 ?? '';
  const roomAreaNum = typeof room.areaM2 === 'number' ? room.areaM2 : Number(room.areaM2);
  const showUfhTerminalControl =
    Number.isFinite(roomAreaNum)
    && roomAreaNum > 0
    && roomAreaNum <= UFH_TERMINAL_CONTROL_MAX_AREA_SQM;
  const resolvedTerminalControl: UfhTerminalControl =
    showUfhTerminalControl && room.underfloorHeating?.ufhTerminalControl === 'unibox'
      ? 'unibox'
      : 'collector';

  const setUnderfloorEnabled = (enabled: boolean) => {
    if (!enabled) {
      updateRoom({
        underfloorHeating: {
          enabled: false,
          basePresetId: resolvedBaseId,
          finishMaterialId: resolvedFinishId,
          pipeSpacingMm: resolvedPipeSpacing,
          furnitureOccupiedAreaM2: resolvedFurnitureArea,
          ...(resolvedTerminalControl === 'unibox'
            ? { ufhTerminalControl: 'unibox' as const }
            : {}),
        },
      });
      return;
    }
    updateRoom({
      underfloorHeating: {
        enabled: true,
        basePresetId: resolvedBaseId || defaultBaseId,
        finishMaterialId: resolvedFinishId || defaultFinishId,
        pipeSpacingMm: resolvedPipeSpacing,
        furnitureOccupiedAreaM2: resolvedFurnitureArea,
        ...(resolvedTerminalControl === 'unibox'
          ? { ufhTerminalControl: 'unibox' as const }
          : {}),
      },
    });
  };

  const patchUnderfloor = (patch: {
    basePresetId?: string;
    finishMaterialId?: string;
    pipeSpacingMm?: UfhPipeSpacingMm;
    furnitureOccupiedAreaM2?: number | '';
    ufhTerminalControl?: UfhTerminalControl;
  }) => {
    const nextTerminal =
      patch.ufhTerminalControl !== undefined
        ? patch.ufhTerminalControl
        : resolvedTerminalControl;
    updateRoom({
      underfloorHeating: {
        enabled: true,
        basePresetId: patch.basePresetId ?? resolvedBaseId,
        finishMaterialId: patch.finishMaterialId ?? resolvedFinishId,
        pipeSpacingMm: patch.pipeSpacingMm ?? resolvedPipeSpacing,
        furnitureOccupiedAreaM2:
          patch.furnitureOccupiedAreaM2 !== undefined
            ? patch.furnitureOccupiedAreaM2
            : resolvedFurnitureArea,
        ...(nextTerminal === 'unibox' ? { ufhTerminalControl: 'unibox' as const } : {}),
      },
    });
  };

  const updateWindowAt = (index: number, patch: Partial<WindowFormValue>) => {
    onChange((prev) =>
      prev.map((r) =>
        r.id === room.id
          ? {
              ...r,
              windows: r.windows.map((w, i) =>
                i === index ? { ...w, ...patch } : w,
              ),
            }
          : r,
      ),
    );
  };

  const removeWindowAt = (index: number) => {
    onChange((prev) =>
      prev.map((r) =>
        r.id === room.id
          ? { ...r, windows: r.windows.filter((_, i) => i !== index) }
          : r,
      ),
    );
  };

  const updateExternalWall = (
    slot: 'externalWall1' | 'externalWall2',
    patch: Partial<ExternalWallFormValue>,
  ) => {
    onChange((prev) =>
      prev.map((r) =>
        r.id === room.id ? { ...r, [slot]: { ...r[slot], ...patch } } : r,
      ),
    );
  };

  const addWindow = () => {
    onChange((prev) =>
      prev.map((r) => {
        if (r.id !== room.id) return r;
        const wins = r.windows;
        const defaultPresetId =
          windowPresets.find((p) => p.id === DEFAULT_WINDOW_PRESET_ID)?.id ??
          windowPresets[0]?.id ??
          DEFAULT_WINDOW_PRESET_ID;
        const next = createDefaultWindowFormValue(r.id, wins.length + 1, defaultPresetId);
        next.id = nextWindowId(r.id, wins);
        return { ...r, windows: [...wins, next] };
      }),
    );
  };

  return (
    <article
      className={styles.card}
      aria-label={`Приміщення ${index + 1}`}
      data-testid={`room-card-${room.id}`}
    >
      <button
        id={btnId}
        type="button"
        data-testid={`room-toggle-${room.id}`}
        className={styles.accHeader}
        aria-expanded={isOpen}
        aria-controls={panelId}
        onClick={onToggle}
      >
        <div className={styles.accHeaderLeft}>
          <div className={styles.cardTitle}>
            Приміщення {index + 1}
            {room.name.trim() ? ` — ${room.name.trim()}` : ''}
          </div>
          <div className={styles.cardMeta}>
            Тип: {room.type} ·{' '}
            {typeof room.areaM2 === 'number' ? `${room.areaM2} м²` : '— м²'} ·{' '}
            {typeof room.heightM === 'number' ? `${room.heightM} м` : '— м'} ·
            ID: {room.id}
          </div>
        </div>
        <div className={styles.accHeaderRight}>
          {isOpen ? 'Згорнути' : 'Відкрити'}
        </div>
      </button>

      <div
        id={panelId}
        role="region"
        aria-labelledby={btnId}
        hidden={!isOpen}
        className={styles.accPanel}
      >
        <div className={styles.formGrid}>
          {/* Название */}
          <div className={styles.field}>
            <label className={styles.label} htmlFor={`name-${room.id}`}>
              Назва
            </label>
            <input
              id={`name-${room.id}`}
              data-testid={`room-name-${room.id}`}
              className={styles.control}
              value={room.name}
              onChange={(e) => { updateRoom({ name: e.target.value }); }}
              placeholder={`Кімната ${index + 1}`}
            />
          </div>

          {/* Тип */}
          <div className={styles.field}>
            <label className={styles.label} htmlFor={`type-${room.id}`}>
              Тип
            </label>
            <select
              id={`type-${room.id}`}
              data-testid={`room-type-${room.id}`}
              className={styles.control}
              value={isCanonicalRoomType(room.type) ? room.type : 'помещение'}
              onChange={(e) => {
                const nextType = parseCanonicalRoomTypeFromSelect(e.target.value);
                if (nextType == null) return;
                const suggestedLayout = defaultLayoutForRoomType(nextType);
                const currentLayout = inferRoomExteriorLayout(room);
                const patch: Partial<RoomFormValue> = { type: nextType };
                if (currentLayout !== suggestedLayout) {
                  Object.assign(
                    patch,
                    patchRoomForLayoutChange(suggestedLayout, room.externalWall2),
                  );
                }
                updateRoom(patch);
              }}
            >
              {ROOM_TYPE_UI_OPTIONS.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>

          {/* Этаж */}
          <div className={styles.field}>
            <label className={styles.label} htmlFor={`floor-${room.id}`}>
              Поверх
            </label>
            <select
              id={`floor-${room.id}`}
              className={styles.control}
              value={room.floor}
              onChange={(e) => { updateRoom({ floor: Number(e.target.value) as 1 | 2 | 3 }); }}
            >
              {([1, 2, 3] as const)
                .filter((f) => f <= maxFloors)
                .map((f) => (
                  <option key={f} value={f}>
                    {f}
                  </option>
                ))}
            </select>
          </div>

          {/* Границы по вертикали */}
          {isApartment ? (
            <div className={`${styles.field} ${styles.fullWidth}`}>
              <div className={styles.label}>Межі (квартира в будинку)</div>
              <p className={styles.hint}>
                Верх: {room.topBoundaryType === 'heated' ? 'теплий контур' : 'холод / горище'} · Низ:{' '}
                {room.bottomBoundaryType === 'heated' ? 'теплий контур' : 'холод / підвал'}.
                Змінюється на кроці «Об&apos;єкт» — «Поверх квартири в будинку».
              </p>
            </div>
          ) : (
            <>
              <div className={styles.field}>
                <label className={styles.label} htmlFor={`bottom-boundary-${room.id}`}>
                  Нижня межа
                </label>
                <select
                  id={`bottom-boundary-${room.id}`}
                  className={styles.control}
                  value={room.bottomBoundaryType}
                  onChange={(e) =>
                    { updateRoom({ bottomBoundaryType: e.target.value as BottomBoundaryType }); }
                  }
                >
                  <option value="heated">Знизу тепле (стать не враховувати)</option>
                  <option value="unheated">Знизу холод / підвал (стать)</option>
                </select>
              </div>
              <div className={styles.field}>
                <label className={styles.label} htmlFor={`top-boundary-${room.id}`}>
                  Верхня межа
                </label>
                <select
                  id={`top-boundary-${room.id}`}
                  className={styles.control}
                  value={room.topBoundaryType}
                  onChange={(e) =>
                    { updateRoom({ topBoundaryType: e.target.value as TopBoundaryType }); }
                  }
                >
                  <option value="heated">Зверху тепле приміщення (стелю не враховувати)</option>
                  <option value="unheated">Зверху холодна зона / горище (стеля)</option>
                  <option value="roof">Покрівля (мансарда)</option>
                </select>
              </div>
            </>
          )}

          {/* Площадь */}
          <div className={styles.field}>
            <label className={styles.label} htmlFor={`area-${room.id}`}>
              Площа, м²
            </label>
            <input
              id={`area-${room.id}`}
              data-testid={`room-area-${room.id}`}
              className={styles.control}
              type="number"
              min={0.1}
              step={0.1}
              value={room.areaM2}
              onChange={(e) =>
                { updateRoom({ areaM2: toNumberOrEmpty(e.target.value) }); }
              }
            />
          </div>

          {/* Высота */}
          <div className={styles.field}>
            <label className={styles.label} htmlFor={`height-${room.id}`}>
              Висота, м
            </label>
            <input
              id={`height-${room.id}`}
              data-testid={`room-height-${room.id}`}
              className={styles.control}
              type="number"
              min={1.8}
              step={0.05}
              value={room.heightM}
              onChange={(e) =>
                { updateRoom({ heightM: toNumberOrEmpty(e.target.value) }); }
              }
            />
          </div>

          {/* Положение относительно наружного контура */}
          <div className={styles.field}>
            <label className={styles.label} htmlFor={`room-layout-${room.id}`}>
              Розташування приміщення
            </label>
            <select
              id={`room-layout-${room.id}`}
              data-testid={`room-layout-${room.id}`}
              className={styles.control}
              value={roomLayout}
              onChange={(e) => {
                const nextLayout = e.target.value as RoomExteriorLayout;
                updateRoom(patchRoomForLayoutChange(nextLayout, room.externalWall2));
              }}
            >
              <option value="facade">На фасаді (одна зовнішня стіна)</option>
              <option value="corner">Кутове / торцеве (дві зовнішні стіни)</option>
              <option value="internal">
                {objectType === 'apartment'
                  ? 'Внутрішнє (стіна в загальний коридор під\'їзду)'
                  : 'Внутрішнє (стіна в холодний коридор / тамбур)'}
              </option>
            </select>
          </div>

          {/* Наружные стены — тип и утеплитель задаются на шаге «Объект» */}
          <div className={`${styles.field} ${styles.fullWidth}`}>
            <div className={styles.label}>Зовнішні стіни (об&apos;єкт)</div>
            <div className={styles.hint}>{objectExternalWallsSummary}</div>
            <div className={styles.hint}>
              {exteriorWallsSectionHint(roomLayout, objectType)}
            </div>
          </div>

          {waterUnderfloorHeating ? (
            <div className={`${styles.floorUfhRow} ${styles.fullWidth}`}>
              <div
                className={
                  ufhEnabled
                    ? `${styles.field} ${styles.floorFieldWithUfh}`
                    : styles.field
                }
              >
                <label className={styles.label} htmlFor={`floorPresetId-${room.id}`}>
                  Підлога (огородження)
                </label>
                <select
                  id={`floorPresetId-${room.id}`}
                  className={styles.control}
                  value={floorPresets.length === 0 ? '' : room.floorPresetId}
                  onChange={(e) => { updateRoom({ floorPresetId: e.target.value }); }}
                  disabled={floorPresets.length === 0}
                >
                  {floorPresets.length === 0 ? (
                    <option value="">Немає пресетів</option>
                  ) : (
                    floorPresets.map((p) => (
                      <option key={p.id} value={p.id}>
                        {envelopePresetLabel(p)}
                      </option>
                    ))
                  )}
                </select>
              </div>
              <div className={styles.ufhColumn}>
                <div className={styles.fieldGroupTitle}>Водяна тепла підлога</div>
                <label className={styles.checkboxRow} htmlFor={`ufh-enabled-${room.id}`}>
                  <input
                    id={`ufh-enabled-${room.id}`}
                    type="checkbox"
                    checked={ufhEnabled}
                    onChange={(e) => { setUnderfloorEnabled(e.target.checked); }}
                  />
                  <span>Тепла підлога в цьому приміщенні</span>
                </label>
                {ufhEnabled ? (
                  <div className={styles.ufhFieldsGrid}>
                  <div className={styles.field}>
                    <label className={styles.label} htmlFor={`ufh-base-${room.id}`}>
                      Основа ТП (перекриття + стяжка)
                    </label>
                    <select
                      id={`ufh-base-${room.id}`}
                      className={styles.control}
                      value={
                        underfloorPresetsLoading || underfloorHeatingBases.length === 0
                          ? ''
                          : resolvedBaseId
                      }
                      onChange={(e) => { patchUnderfloor({ basePresetId: e.target.value }); }}
                      disabled={underfloorPresetsLoading || underfloorHeatingBases.length === 0}
                    >
                      {underfloorPresetsLoading ? (
                        <option value="">Завантаження…</option>
                      ) : underfloorHeatingBases.length === 0 ? (
                        <option value="">Немає баз ТП</option>
                      ) : (
                        underfloorHeatingBases.map((p) => (
                          <option key={p.id} value={p.id}>
                            {underfloorBasePresetLabel(p)}
                          </option>
                        ))
                      )}
                    </select>
                  </div>
                  <div className={styles.field}>
                    <label className={styles.label} htmlFor={`ufh-finish-${room.id}`}>
                      Фінішне покриття
                    </label>
                    <select
                      id={`ufh-finish-${room.id}`}
                      className={styles.control}
                      value={
                        underfloorPresetsLoading || flooringFinishes.length === 0
                          ? ''
                          : resolvedFinishId
                      }
                      onChange={(e) => { patchUnderfloor({ finishMaterialId: e.target.value }); }}
                      disabled={underfloorPresetsLoading || flooringFinishes.length === 0}
                    >
                      {underfloorPresetsLoading ? (
                        <option value="">Завантаження…</option>
                      ) : flooringFinishes.length === 0 ? (
                        <option value="">Немає покриттів</option>
                      ) : (
                        flooringFinishes.map((m) => (
                          <option key={m.id} value={m.id}>
                            {flooringFinishLabel(m)} (T max {m.maxSurfaceTemperatureCelsius} °C)
                          </option>
                        ))
                      )}
                    </select>
                  </div>
                  <div className={styles.field}>
                    <label className={styles.label} htmlFor={`ufh-spacing-${room.id}`}>
                      Бажаний крок укладки, мм
                    </label>
                    <select
                      id={`ufh-spacing-${room.id}`}
                      className={styles.control}
                      value={resolvedPipeSpacing}
                      onChange={(e) =>
                        { patchUnderfloor({
                          pipeSpacingMm: Number(e.target.value) as UfhPipeSpacingMm,
                        }); }
                      }
                    >
                      {UFH_PIPE_SPACING_OPTIONS.map((mm) => (
                        <option key={mm} value={mm}>
                          {mm} мм{mm === 150 ? ' (стандарт)' : ''}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div className={styles.field}>
                    <label
                      className={styles.label}
                      htmlFor={`ufh-furniture-${room.id}`}
                      title="Вкажіть площу великих меблів, під якими не буде укладатися тепла підлога. Це захистить меблі від перегріву та дозволить точніше розрахувати крок труби."
                    >
                      Площа, зайнята меблями (без ніжок / низька посадка), S<sub>meb</sub> (м²)
                    </label>
                    <input
                      id={`ufh-furniture-${room.id}`}
                      className={styles.control}
                      type="number"
                      min={0}
                      step={0.1}
                      value={resolvedFurnitureArea}
                      onChange={(e) =>
                        { patchUnderfloor({
                          furnitureOccupiedAreaM2: toNumberOrEmpty(e.target.value),
                        }); }
                      }
                    />
                  </div>
                  {showUfhTerminalControl && (
                    <div className={`${styles.field} ${styles.fullWidth}`}>
                      <span className={styles.label} id={`ufh-terminal-${room.id}-label`}>
                        Регулювання контуру ТП (площа ≤ {UFH_TERMINAL_CONTROL_MAX_AREA_SQM} м²)
                      </span>
                      <div
                        className={styles.control}
                        role="radiogroup"
                        aria-labelledby={`ufh-terminal-${room.id}-label`}
                      >
                        <label>
                          <input
                            type="radio"
                            name={`ufh-terminal-${room.id}`}
                            checked={resolvedTerminalControl === 'collector'}
                            onChange={() =>
                              { patchUnderfloor({ ufhTerminalControl: 'collector' }); }
                            }
                          />{' '}
                          Колектор теплої підлоги
                        </label>
                        <label>
                          <input
                            type="radio"
                            name={`ufh-terminal-${room.id}`}
                            checked={resolvedTerminalControl === 'unibox'}
                            onChange={() =>
                              { patchUnderfloor({ ufhTerminalControl: 'unibox' }); }
                            }
                          />{' '}
                          Унібокс (локальний регулятор)
                        </label>
                      </div>
                      <div className={styles.hint}>
                        Унібокс — для однієї петлі малої зони; не займає вихід колектора ТП.
                      </div>
                    </div>
                  )}
                  <div className={`${styles.hint} ${styles.fullWidth}`}>
                    Вкажіть площу великих меблів, під якими не буде укладатися тепла підлога.
                    Це захистить меблі від перегріву та дозволить точніше розрахувати крок труби.
                  </div>
                  <div className={`${styles.hint} ${styles.fullWidth}`}>
                    Окремо від «Підлога (огородження)»: Rλ,B = основа над контуром + фініш (кераміка,
                    вініл, ламінат). Ліміт температури поверхні задається покриттям.
                  </div>
                  </div>
                ) : null}
              </div>
            </div>
          ) : (
            <div className={styles.field}>
              <label className={styles.label} htmlFor={`floorPresetId-${room.id}`}>
                Підлога (огородження)
              </label>
              <select
                id={`floorPresetId-${room.id}`}
                className={styles.control}
                value={floorPresets.length === 0 ? '' : room.floorPresetId}
                onChange={(e) => { updateRoom({ floorPresetId: e.target.value }); }}
                disabled={floorPresets.length === 0}
              >
                {floorPresets.length === 0 ? (
                  <option value="">Немає пресетів</option>
                ) : (
                  floorPresets.map((p) => (
                    <option key={p.id} value={p.id}>
                      {envelopePresetLabel(p)}
                    </option>
                  ))
                )}
              </select>
            </div>
          )}

          {/* Потолок (только если сверху холодно) */}
          {room.topBoundaryType === 'unheated' && (
            <div className={styles.envelopeSection}>
              <div className={styles.fieldGroupTitle}>Стеля</div>
              <div className={styles.envelopeFieldsRow}>
                <div className={styles.field}>
                  <label className={styles.label} htmlFor={`ceilingPresetId-${room.id}`}>
                    Стеля (пресет)
                  </label>
                  <select
                    id={`ceilingPresetId-${room.id}`}
                    className={styles.control}
                    value={ceilingPresets.length === 0 ? '' : room.ceilingPresetId}
                    onChange={(e) => { updateRoom({ ceilingPresetId: e.target.value }); }}
                    disabled={ceilingPresets.length === 0}
                  >
                    {ceilingPresets.length === 0 ? (
                      <option value="">Немає пресетів</option>
                    ) : (
                      ceilingPresets.map((p) => (
                        <option key={p.id} value={p.id}>
                          {envelopePresetLabel(p)}
                        </option>
                      ))
                    )}
                  </select>
                </div>
                <div className={styles.field}>
                  <label className={styles.label} htmlFor={`ceiling-area-${room.id}`}>
                    Площа стелі, м²
                  </label>
                  <input
                    id={`ceiling-area-${room.id}`}
                    className={styles.control}
                    type="number"
                    min={0}
                    step={0.1}
                    value={room.ceilingAreaM2}
                    onChange={(e) => { updateRoom({ ceilingAreaM2: toNumberOrEmpty(e.target.value) }); }}
                    placeholder="наприклад, 20"
                  />
                </div>
              </div>
              <div className={styles.hint}>
                Використовуйте площу стелі/перекриття, через яку йдуть втрати (над нею холодно).
              </div>
            </div>
          )}

          {/* Кровля (только для мансарды) */}
          {room.topBoundaryType === 'roof' && (
            <div className={styles.envelopeSection}>
              <div className={styles.fieldGroupTitle}>Покрівля</div>
              <div className={styles.envelopeFieldsRow}>
                <div className={styles.field}>
                  <label className={styles.label} htmlFor={`roofPresetId-${room.id}`}>
                    Покрівля (пресет)
                  </label>
                  <select
                    id={`roofPresetId-${room.id}`}
                    className={styles.control}
                    value={roofPresets.length === 0 ? '' : room.roofPresetId}
                    onChange={(e) => { updateRoom({ roofPresetId: e.target.value }); }}
                    disabled={roofPresets.length === 0}
                  >
                    {roofPresets.length === 0 ? (
                      <option value="">Немає пресетів</option>
                    ) : (
                      <>
                        <option value="">Не враховувати покрівлю</option>
                        {roofPresets.map((p) => (
                          <option key={p.id} value={p.id}>
                            {envelopePresetLabel(p)}
                          </option>
                        ))}
                      </>
                    )}
                  </select>
                </div>
                <div className={styles.field}>
                  <label className={styles.label} htmlFor={`roof-area-${room.id}`}>
                    Площа скатів покрівлі (за поверхнею), м²
                  </label>
                  <input
                    id={`roof-area-${room.id}`}
                    className={styles.control}
                    type="number"
                    min={0}
                    step={0.1}
                    value={room.roofAreaM2}
                    onChange={(e) => { updateRoom({ roofAreaM2: toNumberOrEmpty(e.target.value) }); }}
                    placeholder="наприклад, 18.5"
                  />
                </div>
              </div>
              <div className={styles.hint}>
                Для мансарди вкажіть площу нахилених скатів (а не площу підлоги).
              </div>
            </div>
          )}

          {/* Наружные / коридорные стены (СП 60.13330: до двух ориентированных фасадных сторон) */}
          {wallFieldConfigs.map(({ slot, label, hint, placeholder }) => (
            <div key={slot} className={`${styles.fieldGroup} ${styles.fullWidth}`}>
              <div className={styles.fieldGroupTitle}>{label}</div>
              <div className={styles.fieldRow}>
                <div className={styles.field}>
                  <label className={styles.label} htmlFor={`${slot}-area-${room.id}`}>
                    Площа, м²
                  </label>
                  <input
                    id={`${slot}-area-${room.id}`}
                    data-testid={
                      slot === 'externalWall1'
                        ? `room-wall1-area-${room.id}`
                        : `room-wall2-area-${room.id}`
                    }
                    className={styles.control}
                    type="number"
                    min={0}
                    step={0.1}
                    value={room[slot].areaM2}
                    onChange={(e) =>
                      { updateExternalWall(slot, { areaM2: toNumberOrEmpty(e.target.value) }); }
                    }
                    placeholder={placeholder}
                  />
                </div>
                <div className={styles.field}>
                  <label className={styles.label} htmlFor={`${slot}-or-${room.id}`}>
                    Орієнтація
                  </label>
                  <select
                    id={`${slot}-or-${room.id}`}
                    className={styles.control}
                    value={room[slot].orientation}
                    onChange={(e) =>
                      { updateExternalWall(slot, {
                        orientation: e.target.value as WindowOrientation,
                      }); }
                    }
                  >
                    {ORIENTATION_OPTIONS.map((o) => (
                      <option key={o.code} value={o.code}>
                        {o.label}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <div className={styles.hint}>{hint}</div>
            </div>
          ))}
        </div>

        {/* Окна */}
        <div className={`${styles.hint} ${styles.hintMt12}`}>
          Вікна задаються окремими рядками: ширина прорізу потрібна для правила «радіатор ≥ 70% ширини вікна».
          Для <strong>різних типів або розмірів</strong> натисніть «Додати вікно», а не збільшуйте поле
          «К-сть» — воно лише для однакових копій одного вікна.
        </div>
        <div className={`${styles.formGrid} ${styles.formGridMt8}`}>
          <div className={`${styles.field} ${styles.fullWidth}`}>
            <button type="button" className={styles.control} onClick={addWindow}>
              Додати вікно
            </button>
          </div>
          {room.windows.length === 0 ? (
            <div className={`${styles.hint} ${styles.fullWidth}`}>
              Вікна не додано.
            </div>
          ) : (
            room.windows.map((w, wi) => {
              const resolvedWindowPresetId = windowPresets.some((p) => p.id === w.presetId)
                ? w.presetId
                : (windowPresets[0]?.id ?? DEFAULT_WINDOW_PRESET_ID);
              const windowCount =
                typeof w.count === 'number' && w.count > 1 ? w.count : null;
              return (
              <div
                key={`${room.id}-win-row-${wi}`}
                className={`${styles.windowCard} ${styles.fullWidth}`}
              >
                <h4 className={styles.windowCardTitle}>
                  Вікно {wi + 1}
                  {w.id ? ` (${w.id})` : ''}
                </h4>
                <div className={styles.formGrid}>
                  <div className={styles.field}>
                    <label className={styles.label} htmlFor={`win-preset-${room.id}-${wi}`}>
                      Тип вікна
                    </label>
                    <select
                      id={`win-preset-${room.id}-${wi}`}
                      className={styles.control}
                      value={resolvedWindowPresetId}
                      onChange={(e) => { updateWindowAt(wi, { presetId: e.target.value }); }}
                    >
                      {windowPresets.length === 0 ? (
                        <option value={DEFAULT_WINDOW_PRESET_ID}>
                          ПВХ двокамерне (офлайн-довідник)
                        </option>
                      ) : (
                        windowPresets.map((p) => (
                          <option key={p.id} value={p.id}>
                            {envelopePresetLabel(p)}
                          </option>
                        ))
                      )}
                    </select>
                  </div>

                  <div className={styles.field}>
                    <label className={styles.label} htmlFor={`win-w-${room.id}-${wi}`}>
                      Ширина, мм
                    </label>
                    <input
                      id={`win-w-${room.id}-${wi}`}
                      className={styles.control}
                      type="number"
                      min={200}
                      step={1}
                      value={w.openingWidthMm}
                      onChange={(e) =>
                        { updateWindowAt(wi, { openingWidthMm: toNumberOrEmpty(e.target.value) }); }
                      }
                    />
                  </div>

                  <div className={styles.field}>
                    <label className={styles.label} htmlFor={`win-h-${room.id}-${wi}`}>
                      Висота, мм
                    </label>
                    <input
                      id={`win-h-${room.id}-${wi}`}
                      className={styles.control}
                      type="number"
                      min={200}
                      step={1}
                      value={w.openingHeightMm}
                      onChange={(e) =>
                        { updateWindowAt(wi, { openingHeightMm: toNumberOrEmpty(e.target.value) }); }
                      }
                    />
                  </div>

                  <div className={styles.field}>
                    <label className={styles.label} htmlFor={`win-or-${room.id}-${wi}`}>
                      Орієнтація
                    </label>
                    <select
                      id={`win-or-${room.id}-${wi}`}
                      className={styles.control}
                      value={w.orientation}
                      onChange={(e) =>
                        { updateWindowAt(wi, { orientation: e.target.value as WindowOrientation }); }
                      }
                    >
                      {ORIENTATION_OPTIONS.map((o) => (
                        <option key={o.code} value={o.code}>
                          {o.label}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div className={styles.field}>
                    <label className={styles.label} htmlFor={`win-count-${room.id}-${wi}`}>
                      К-сть однакових
                    </label>
                    <input
                      id={`win-count-${room.id}-${wi}`}
                      className={styles.control}
                      type="number"
                      min={1}
                      step={1}
                      value={w.count}
                      onChange={(e) => { updateWindowAt(wi, { count: toNumberOrEmpty(e.target.value) }); }}
                    />
                    {windowCount != null && (
                      <p className={styles.windowCountHint}>
                        {windowCount} копії з одним типом і розмірами. Інший тип — кнопка «Додати вікно».
                      </p>
                    )}
                  </div>

                  <div className={styles.field}>
                    <label className={styles.label} htmlFor={`win-remove-${room.id}-${wi}`}>
                      &nbsp;
                    </label>
                    <button
                      id={`win-remove-${room.id}-${wi}`}
                      type="button"
                      className={styles.control}
                      onClick={() => { removeWindowAt(wi); }}
                    >
                      Видалити вікно
                    </button>
                  </div>
                </div>
              </div>
              );
            })
          )}
        </div>

        {room.topBoundaryType === 'roof' && (
          <div className={styles.hint}>
            Для мансарди верхня межа враховується як покрівля (скати), а не як стеля.
          </div>
        )}
      </div>
    </article>
  );
}

/**
 * Назначение: Форма списка помещений.
 * Описание: Добавление и удаление комнат, сводка наружных стен и передача пресетов в аккордеоны.
 */

import type { Dispatch, SetStateAction } from 'react';
import { useEffect, useMemo, useState } from 'react';

import type { EnvelopePreset, ObjectMetaValue } from '../../types/envelope';
import type {
  FlooringFinishMaterial,
  UnderfloorHeatingBasePreset,
} from '../../types/underfloorHeating';
import { formatExternalWallsSummary } from '../../utils/externalWallsSummary';
import {
  type RoomFormValue,
} from '../../types/rooms';

import { RoomAccordionItem } from './RoomAccordionItem.tsx';
import styles from './RoomsForm.module.css';

type Props = {
  value: RoomFormValue[];
  maxFloors: 1 | 2 | 3;
  objectMeta: ObjectMetaValue;
  wallPresets: EnvelopePreset[];
  insulationPresets: EnvelopePreset[];
  windowPresets: EnvelopePreset[];
  floorPresets: EnvelopePreset[];
  ceilingPresets: EnvelopePreset[];
  roofPresets: EnvelopePreset[];
  waterUnderfloorHeating?: boolean;
  underfloorHeatingBases?: UnderfloorHeatingBasePreset[];
  flooringFinishes?: FlooringFinishMaterial[];
  underfloorPresetsLoading?: boolean;
  onChange: Dispatch<SetStateAction<RoomFormValue[]>>;
};

export function RoomsForm({
  value,
  maxFloors,
  objectMeta,
  wallPresets,
  insulationPresets,
  windowPresets,
  floorPresets,
  ceilingPresets,
  roofPresets,
  waterUnderfloorHeating = false,
  underfloorHeatingBases = [],
  flooringFinishes = [],
  underfloorPresetsLoading = false,
  onChange,
}: Props) {
  const objectExternalWallsSummary = formatExternalWallsSummary(
    objectMeta,
    wallPresets,
    insulationPresets,
  );
  const allIds = useMemo(() => value.map((r) => r.id), [value]);
  // Стартуем со «все свёрнуты» и разрешаем открыть только одну комнату.
  const [openId, setOpenId] = useState<string | null>(null);

  useEffect(() => {
    /* eslint-disable react-hooks/set-state-in-effect -- сброс открытой комнаты при её удалении */
    setOpenId((prev) => (prev !== null && !allIds.includes(prev) ? null : prev));
    /* eslint-enable react-hooks/set-state-in-effect */
  }, [allIds]);

  const toggleAccordion = (id: string) => {
    setOpenId((prev) => (prev === id ? null : id));
  };

  const copyFirstRoomSettings = () => {
    const r0 = value[0];
    if (!r0) return;
    onChange((prev) =>
      prev.map((r, idx) =>
        idx === 0
          ? r
          : {
              ...r,
              floor: r0.floor,
              topBoundaryType: r0.topBoundaryType,
              bottomBoundaryType: r0.bottomBoundaryType,
              floorPresetId: r0.floorPresetId,
              ceilingPresetId: r0.ceilingPresetId,
              roofPresetId: r0.roofPresetId,
              externalWall1: { ...r0.externalWall1 },
              externalWall2: { ...r0.externalWall2 },
              ...(r0.roomExteriorLayout !== undefined
                ? { roomExteriorLayout: r0.roomExteriorLayout }
                : {}),
              ceilingAreaM2: r0.ceilingAreaM2,
              roofAreaM2: r0.roofAreaM2,
              windows: r0.windows.map((w, wi) => ({
                ...w,
                id: `win-${r.id}-${wi + 1}`,
              })),
              ...(r0.underfloorHeating
                ? { underfloorHeating: { ...r0.underfloorHeating } }
                : {}),
            },
      ),
    );
  };

  return (
    <div className={styles.root}>
      <div className={styles.headerRow}>
        <h2 className={styles.title}>Приміщення</h2>
        {value.length > 1 && (
          <div className={styles.headerActions}>
            <button
              type="button"
              className={styles.smallButton}
              onClick={copyFirstRoomSettings}
            >
              Скопіювати з першої кімнати
            </button>
          </div>
        )}
      </div>
      <div className={styles.grid}>
        {value.map((room, index) => (
          <RoomAccordionItem
            key={room.id}
            room={room}
            index={index}
            isOpen={openId === room.id}
            onToggle={() => { toggleAccordion(room.id); }}
            maxFloors={maxFloors}
            objectExternalWallsSummary={objectExternalWallsSummary}
            windowPresets={windowPresets}
            floorPresets={floorPresets}
            ceilingPresets={ceilingPresets}
            roofPresets={roofPresets}
            waterUnderfloorHeating={waterUnderfloorHeating}
            underfloorHeatingBases={underfloorHeatingBases}
            flooringFinishes={flooringFinishes}
            underfloorPresetsLoading={underfloorPresetsLoading}
            isApartment={objectMeta.objectType === 'apartment'}
            objectType={objectMeta.objectType}
            onChange={onChange}
          />
        ))}
      </div>
    </div>
  );
}

/**
 * Назначение: read-only презентация сметы по публичной ссылке `/s/{token}`.
 */

import { useQuery } from '@tanstack/react-query';
import { useCallback, useMemo, useState } from 'react';

import { FinancialSummaryTable } from '../FinancialSummary/FinancialSummaryTable';
import { Footer } from '../Footer/Footer';
import Logo from '../Logo/Logo';
import { PublisherContactBlock } from '../PublisherContactBlock/PublisherContactBlock';
import { brandUk } from '../../i18n/uk/brand';
import { downloadPublicSharePdf, fetchPublicShare } from '../../services/publicShareApi';
import type { PublicSharePayload } from '../../types/projectsApi';
import { isRecord } from '../../utils/jsonGuards';
import { parseCommercialBomFromReport } from '../../utils/parsers/parseCommercialBomFromReport';
import {
  buildTechnicalPrintHtml,
  reportLikeFromPublicShare,
} from '../../utils/buildTechnicalPrintHtml';
import { formatKw } from '../../utils/format';
import styles from './SharePresentationPage.module.css';

export type SharePresentationPageProps = {
  shareToken: string;
};

/**
 * @param props
 */
export function SharePresentationPage({ shareToken }: SharePresentationPageProps) {
  const [techOpen, setTechOpen] = useState(false);
  const [pdfBusy, setPdfBusy] = useState(false);

  const query = useQuery({
    queryKey: ['publicShare', shareToken],
    queryFn: () => fetchPublicShare(shareToken),
  });

  const share: PublicSharePayload | null = query.data?.share ?? null;
  const error =
    query.error instanceof Error
      ? query.error.message
      : query.isError
        ? 'Посилання недоступна'
        : null;
  const loading = query.isPending || query.isFetching;

  const commercial = useMemo(() => {
    if (!share) return null;
    return parseCommercialBomFromReport({ commercial: share.commercial });
  }, [share]);

  const equipmentSummary = useMemo(() => buildEquipmentSummary(share), [share]);

  const technicalHtml = useMemo(() => {
    if (!share) return '';
    return buildTechnicalPrintHtml(reportLikeFromPublicShare(share));
  }, [share]);

  const onDownloadPdf = useCallback(
    (includeTechnical: boolean) => {
      if (!share || !commercial || pdfBusy) return;
      setPdfBusy(true);
      void (async () => {
        try {
          await downloadPublicSharePdf(shareToken, { includeTechnical });
        } catch (e) {
          window.alert(e instanceof Error ? e.message : 'Не вдалося завантажити PDF');
        } finally {
          setPdfBusy(false);
        }
      })();
    },
    [commercial, pdfBusy, share, shareToken],
  );

  if (loading && !share) {
    return (
      <div className={styles.page}>
        <p className={styles.status}>Завантаження кошторису…</p>
      </div>
    );
  }

  if (error || !share || !commercial) {
    return (
      <div className={styles.page}>
        <header className={styles.top}>
          <Logo />
          <h1 className={styles.brand}>{brandUk.name}</h1>
        </header>
        <p className={styles.error} role="alert">
          {error ?? 'Кошторис не знайдено'}
        </p>
        <Footer variant="share" />
      </div>
    );
  }

  return (
    <div className={styles.page}>
      <header className={styles.top}>
        <div className={styles.brandRow}>
          <Logo />
          <div>
            <h1 className={styles.brand}>{brandUk.name}</h1>
            <p className={styles.sub}>Фінансовий підсумок за розрахунком</p>
          </div>
        </div>
        <div className={styles.actions}>
          <button
            type="button"
            className={styles.btn}
            disabled={pdfBusy}
            onClick={() => {
              onDownloadPdf(false);
            }}
          >
            {pdfBusy ? 'Завантаження…' : 'Завантажити PDF'}
          </button>
          <button
            type="button"
            className={styles.btnSecondary}
            disabled={pdfBusy || !technicalHtml}
            onClick={() => {
              onDownloadPdf(true);
            }}
          >
            PDF + технічний розрахунок
          </button>
        </div>
      </header>

      <section className={styles.meta}>
        <p>
          <strong>Клієнт:</strong> {share.clientName}
        </p>
        {share.objectType ? (
          <p>
            <strong>Об&apos;єкт:</strong>{' '}
            {share.objectType === 'apartment' ? 'Квартира' : 'Будинок'}
          </p>
        ) : null}
        <p>
          <strong>Опубліковано:</strong> {share.publishedAt.slice(0, 10)}
        </p>
      </section>

      {share.publisherPresentation ? (
        <PublisherContactBlock presentation={share.publisherPresentation} />
      ) : null}

      {equipmentSummary.length > 0 ? (
        <section className={styles.equipment} aria-label="Обладнання">
          <h2 className={styles.h2}>Обладнання</h2>
          {equipmentSummary.map((block) => (
            <details key={block.title} className={styles.acc} open>
              <summary>{block.title}</summary>
              <ul>
                {block.lines.map((line) => (
                  <li key={line}>{line}</li>
                ))}
              </ul>
            </details>
          ))}
        </section>
      ) : null}

      <section className={styles.bom} aria-label="Кошторис">
        <h2 className={styles.h2}>Кошторис</h2>
        <FinancialSummaryTable commercial={commercial} />
      </section>

      {technicalHtml ? (
        <section className={styles.tech}>
          <button
            type="button"
            className={styles.techToggle}
            onClick={() => { setTechOpen((v) => !v); }}
          >
            {techOpen ? 'Приховати технічний розрахунок' : 'Показати технічний розрахунок'}
          </button>
          {techOpen ? (
            <div
              className={styles.techBody}
              dangerouslySetInnerHTML={{ __html: technicalHtml }}
            />
          ) : null}
        </section>
      ) : null}

      <p className={styles.footnote}>Документ лише для перегляду. Зміна анкети недоступна.</p>
      <Footer variant="share" />
    </div>
  );
}

type EquipmentBlock = { title: string; lines: string[] };

/**
 * @param share
 */
function buildEquipmentSummary(share: PublicSharePayload | null): EquipmentBlock[] {
  if (!share) return [];
  const matching = share.matching;
  const blocks: EquipmentBlock[] = [];

  const boiler = isRecord(matching.boiler) ? matching.boiler : null;
  if (boiler) {
    const lines: string[] = [];
    if (typeof boiler.requiredKw === 'number') {
      lines.push(`Потрібна потужність: ${formatKw(boiler.requiredKw)} кВт`);
    }
    const selected = isRecord(boiler.selected) ? boiler.selected : null;
    const proposal = isRecord(boiler.proposal) ? boiler.proposal : null;
    const model =
      (selected && typeof selected.model === 'string' ? selected.model : null) ??
      (proposal && typeof proposal.model === 'string' ? proposal.model : null);
    const brand =
      (selected && typeof selected.brand === 'string' ? selected.brand : null) ??
      (proposal && typeof proposal.brand === 'string' ? proposal.brand : null);
    if (model) lines.push(`Модель: ${[brand, model].filter(Boolean).join(' ')}`);
    if (lines.length) blocks.push({ title: 'Котел', lines });
  }

  const radiators = isRecord(matching.radiators) ? matching.radiators : null;
  if (radiators) {
    const chosen = isRecord(radiators.chosen) ? radiators.chosen : null;
    const lines: string[] = [];
    if (chosen && typeof chosen.model === 'string') {
      const brand = typeof chosen.brand === 'string' ? chosen.brand : '';
      lines.push(`Модель: ${[brand, chosen.model].filter(Boolean).join(' ')}`);
    }
    if (chosen && typeof chosen.totalSections === 'number') {
      lines.push(`Секцій: ${chosen.totalSections}`);
    }
    if (lines.length) blocks.push({ title: 'Радіатори', lines });
  }

  return blocks;
}

/**
 * Назначение: таблица гидравлики петель ТП в отчёте.
 * Описание: предупреждения «низкая скорость» не дублируются здесь —
 * выводятся один раз в отчёте с общей кнопкой устранения.
 */

import type { ParsedUfhLoopHydraulics } from '../../types/underfloorHeating';
import { isUfhLowVelocityWarning } from '../../utils/ufhWarningDisplay';
import styles from './UfhLoopHydraulicsTable.module.css';

/** Пороги MVP (appliances.hydraulics) — для подсветки в UI. */
const UFH_LOOP_V_MIN_MPS = 0.2;
const UFH_LOOP_V_MAX_MPS = 0.7;
const UFH_LOOP_DP_MAX_KPA = 20;

type UfhLoopHydraulicsTableProps = {
  loopsCount: number;
  loops: ParsedUfhLoopHydraulics[];
  pipeResizeApplied?: boolean;
};

function resizeActionLabel(action: ParsedUfhLoopHydraulics['pipeResizeAction']): string {
  switch (action) {
    case 'upsized':
      return 'Збільшено Ø';
    case 'downsized':
      return 'Зменшено Ø';
    case 'loops_adjusted':
      return 'Скориговано число петель';
    default:
      return 'Без змін';
  }
}

function velocityCellClass(velocityMps: number | null): string | undefined {
  if (velocityMps == null) return undefined;
  if (velocityMps < UFH_LOOP_V_MIN_MPS || velocityMps > UFH_LOOP_V_MAX_MPS) {
    return styles.outOfRange;
  }
  return undefined;
}

function pressureCellClass(pressureDropKPa: number | null): string | undefined {
  if (pressureDropKPa == null) return undefined;
  if (pressureDropKPa > UFH_LOOP_DP_MAX_KPA) {
    return styles.outOfRange;
  }
  return undefined;
}

export function UfhLoopHydraulicsTable({
  loopsCount,
  loops,
  pipeResizeApplied,
}: UfhLoopHydraulicsTableProps) {
  if (loops.length === 0) return null;

  const otherWarnings = loops.flatMap((l) =>
    l.warnings
      .filter((w) => !isUfhLowVelocityWarning(w))
      .map((w, i) => ({ key: `${l.loopId}-w-${i}`, text: w })),
  );

  return (
    <div className={styles.root}>
      <h5 className={styles.title}>
        Петлі ТП — гідравліка ({loopsCount} {loopsCount === 1 ? 'контур' : 'контури'})
      </h5>
      {pipeResizeApplied && (
        <p className={styles.hint}>
          Підбір Ø та/або число петель скориговано автоматично (v 0,2–0,7 м/с, Δp ≤ 20 кПа).
        </p>
      )}
      <table className={styles.table}>
        <thead>
          <tr>
            <th>Петля</th>
            <th>Довжина петлі</th>
            <th>Q</th>
            <th>Ø</th>
            <th>v</th>
            <th>Δp</th>
            <th>Оптимізація</th>
          </tr>
        </thead>
        <tbody>
          {loops.map((loop) => (
            <tr key={loop.loopId}>
              <td>{loop.loopId}</td>
              <td>
                {loop.loopLengthM.toFixed(1)} <span className={styles.unit}>м</span>
              </td>
              <td>
                {loop.flowRateM3PerHour.toFixed(3)} <span className={styles.unit}>м³/ч</span>
              </td>
              <td>
                {loop.internalDiameterMm != null
                  ? `${loop.internalDiameterMm.toFixed(1)} мм`
                  : '—'}
              </td>
              <td className={velocityCellClass(loop.velocityMps)}>
                {loop.velocityMps != null
                  ? `${loop.velocityMps.toFixed(2)} м/с`
                  : '—'}
              </td>
              <td className={pressureCellClass(loop.pressureDropKPa)}>
                {loop.pressureDropKPa != null
                  ? `${loop.pressureDropKPa.toFixed(1)} кПа`
                  : '—'}
              </td>
              <td>
                {resizeActionLabel(loop.pipeResizeAction)}
                {loop.pipeResizeReason && (
                  <span className={styles.reasonHint} title={loop.pipeResizeReason}>
                    {' '}
                    ⓘ
                  </span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {otherWarnings.length > 0 && (
        <ul className={styles.warnings}>
          {otherWarnings.map((w) => (
            <li key={w.key}>{w.text}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

/**
 * Назначение: Модалка шагов устранения предупреждения ТП.
 * Описание: Именованные решения из recommendations.resolutionSteps
 * (завоздушивание, паразитный q↓, смесительный узел, лимит Tповерх пресета,
 * недостаточное покрытие теплопотерь).
