/**
 * Назначение: Полный отчёт расчёта ТП + подбор унибоксов.
 * Описание: Тело модалки шага «Тёплый пол»; детализация не дублируется в сайдбаре.
 */

import { useMemo, useState } from 'react';
import type { ParsedUnderfloorHeating, ParsedUfhResolutionStep } from '../../types/underfloorHeating';
import type { ParsedHydraulicsPumpProposal } from '../../types/hydraulics';
import type { ParsedUniboxesMatching } from '../../utils/parsers/parseUniboxesMatchingFromReport';
import {
  formatHeatFluxWm2,
  formatKw,
  formatTempC,
  formatWatts,
} from '../../utils/format';
import { selectUfhZonePumps } from '../../utils/ufhHydraulicsPumps';
import {
  collectCoverageLowWarnings,
  collectLowVelocityLoopWarnings,
  collectParasiticDownWarnings,
  collectSurfacePresetOverrideWarnings,
  filterGlobalWarningsExcludingStructured,
  filterRoomWarningsExcludingLoops,
  UFH_COVERAGE_LOW_CODES,
  UFH_COVERAGE_LOW_RESOLUTION_STEPS_FALLBACK,
  UFH_COVERAGE_LOW_UFH_ONLY_RESOLUTION_STEPS_FALLBACK,
  UFH_SURFACE_PRESET_OVERRIDE_CODES,
  UFH_WARN_COVERAGE_LOW_UFH_ONLY_CODE,
  UFH_WARN_LOW_VELOCITY_CODE,
  UFH_WARN_MIXING_NODE_CODE,
  UFH_WARN_PARASITIC_DOWN_CODE,
} from '../../utils/ufhWarningDisplay';
import { HydraulicsPumpCard } from '../Hydraulics/HydraulicsPumpCard';
import { UfhMixingNodeSpecCard } from './UfhMixingNodeSpecCard';
import { UfhLoopHydraulicsTable } from './UfhLoopHydraulicsTable';
import { UniboxMatchingSection } from './UniboxMatchingSection';
import { UfhWarningResolutionDialog } from './UfhWarningResolutionDialog';
import styles from './UnderfloorHeatingReportView.module.css';

export type UnderfloorHeatingReportViewProps = {
  underfloorHeating: ParsedUnderfloorHeating;
  uniboxes?: ParsedUniboxesMatching | null;
  /** proposal.pumps из гидравлики — фильтруются до зон ТП. */
  hydraulicsPumps?: readonly ParsedHydraulicsPumpProposal[] | null;
};

type ResolutionDialogKind =
  | 'velocity'
  | 'parasitic'
  | 'mixing'
  | 'surfacePreset'
  | 'coverage'
  | null;

/**
 * @param props
 */
export function UnderfloorHeatingReportView({
  underfloorHeating,
  uniboxes = null,
  hydraulicsPumps = null,
}: UnderfloorHeatingReportViewProps) {
  const ufhPumps = selectUfhZonePumps(hydraulicsPumps);
  const [resolutionKind, setResolutionKind] = useState<ResolutionDialogKind>(null);

  const lowVelocityRec = useMemo(
    () =>
      underfloorHeating.resolvedRecommendations.find(
        (r) =>
          r.code === UFH_WARN_LOW_VELOCITY_CODE
          && r.resolutionSteps != null
          && r.resolutionSteps.length > 0,
      ) ?? null,
    [underfloorHeating.resolvedRecommendations],
  );

  const parasiticRec = useMemo(
    () =>
      underfloorHeating.resolvedRecommendations.find(
        (r) =>
          r.code === UFH_WARN_PARASITIC_DOWN_CODE
          && r.resolutionSteps != null
          && r.resolutionSteps.length > 0,
      ) ?? null,
    [underfloorHeating.resolvedRecommendations],
  );

  const mixingRec = useMemo(
    () =>
      underfloorHeating.resolvedRecommendations.find(
        (r) =>
          r.code === UFH_WARN_MIXING_NODE_CODE
          && r.resolutionSteps != null
          && r.resolutionSteps.length > 0,
      ) ?? null,
    [underfloorHeating.resolvedRecommendations],
  );

  const surfacePresetRec = useMemo(
    () =>
      underfloorHeating.resolvedRecommendations.find(
        (r) =>
          (UFH_SURFACE_PRESET_OVERRIDE_CODES as readonly string[]).includes(r.code)
          && r.resolutionSteps != null
          && r.resolutionSteps.length > 0,
      ) ?? null,
    [underfloorHeating.resolvedRecommendations],
  );

  const coverageRec = useMemo(
    () =>
      underfloorHeating.resolvedRecommendations.find((r) =>
        (UFH_COVERAGE_LOW_CODES as readonly string[]).includes(r.code),
      ) ?? null,
    [underfloorHeating.resolvedRecommendations],
  );

  const lowVelocityWarnings = useMemo(
    () => collectLowVelocityLoopWarnings(underfloorHeating.rooms),
    [underfloorHeating.rooms],
  );

  const parasiticWarnings = useMemo(
    () => collectParasiticDownWarnings(underfloorHeating.rooms),
    [underfloorHeating.rooms],
  );

  const surfacePresetWarnings = useMemo(
    () => collectSurfacePresetOverrideWarnings(underfloorHeating.rooms),
    [underfloorHeating.rooms],
  );

  const coverageWarnings = useMemo(
    () =>
      collectCoverageLowWarnings(
        underfloorHeating.rooms,
        underfloorHeating.resolvedRecommendations,
      ),
    [underfloorHeating.rooms, underfloorHeating.resolvedRecommendations],
  );

  const structuredOther = useMemo(
    () =>
      underfloorHeating.resolvedRecommendations.filter(
        (r) =>
          r.code !== UFH_WARN_LOW_VELOCITY_CODE
          && r.code !== UFH_WARN_PARASITIC_DOWN_CODE
          && r.code !== UFH_WARN_MIXING_NODE_CODE
          && !(UFH_SURFACE_PRESET_OVERRIDE_CODES as readonly string[]).includes(r.code)
          && !(UFH_COVERAGE_LOW_CODES as readonly string[]).includes(r.code),
      ),
    [underfloorHeating.resolvedRecommendations],
  );

  const structuredTexts = useMemo(
    () =>
      new Set(
        underfloorHeating.resolvedRecommendations.map((r) => r.text),
      ),
    [underfloorHeating.resolvedRecommendations],
  );

  const globalWarnings = useMemo(
    () =>
      filterGlobalWarningsExcludingStructured(
        underfloorHeating.warnings,
        structuredTexts,
      ),
    [underfloorHeating.warnings, structuredTexts],
  );

  const velocitySteps = lowVelocityRec?.resolutionSteps ?? [];
  const parasiticSteps = parasiticRec?.resolutionSteps ?? [];
  const mixingSteps = mixingRec?.resolutionSteps ?? [];
  const surfacePresetSteps = surfacePresetRec?.resolutionSteps ?? [];
  const coverageSteps: readonly ParsedUfhResolutionStep[] =
    coverageRec?.resolutionSteps != null && coverageRec.resolutionSteps.length > 0
      ? coverageRec.resolutionSteps
      : coverageRec?.code === UFH_WARN_COVERAGE_LOW_UFH_ONLY_CODE
        ? UFH_COVERAGE_LOW_UFH_ONLY_RESOLUTION_STEPS_FALLBACK
        : UFH_COVERAGE_LOW_RESOLUTION_STEPS_FALLBACK;
  const showVelocityResolve =
    lowVelocityWarnings.length > 0 && velocitySteps.length > 0;
  const showParasiticResolve =
    parasiticWarnings.length > 0 && parasiticSteps.length > 0;
  const showSurfacePresetResolve =
    surfacePresetWarnings.length > 0 && surfacePresetSteps.length > 0;
  /** Как у смесительного узла: при наличии WARN кнопка всегда (шаги из API или fallback). */
  const showCoverageResolve = coverageWarnings.length > 0;

  const dialogSteps: readonly ParsedUfhResolutionStep[] =
    resolutionKind === 'parasitic'
      ? parasiticSteps
      : resolutionKind === 'velocity'
        ? velocitySteps
        : resolutionKind === 'mixing'
          ? mixingSteps
          : resolutionKind === 'surfacePreset'
            ? surfacePresetSteps
            : resolutionKind === 'coverage'
              ? coverageSteps
              : [];

  return (
    <div>
      {underfloorHeating.rooms.length === 0 ? (
        <p className={styles.hint}>
          Режим ТП увімкнено в анкеті, але немає приміщень з увімкненою теплою підлогою.
          На кроці «Приміщення» відмітьте «Тепла підлога в цьому приміщенні» та задайте основу + фініш.
        </p>
      ) : (
        <p className={styles.hint}>
          Джерело: розрахунок API (warmFloorCalc) · контур{' '}
          {underfloorHeating.circuitSupplyC}/{underfloorHeating.circuitReturnC} °C
          {underfloorHeating.circuitSource === 'mixed_default'
            ? ' (типовий змішувальний вузол)'
            : underfloorHeating.circuitSource === 'finish_preset'
              ? ' (за фінішем покриття)'
              : underfloorHeating.circuitSource === 'ufh_mode_preset'
                ? ' (пресет режиму ТП)'
                : ''}
          {underfloorHeating.isMixingNodeRequired
            ? ' · потрібен змішувальний вузол'
            : underfloorHeating.circuitSource === 'ufh_mode_preset'
              ? ' · змішувальний вузол не потрібен (пряме підключення)'
              : ''}
        </p>
      )}

      {underfloorHeating.rooms.length > 0 && (
        <>
          {underfloorHeating.mixingNode != null && (
            <UfhMixingNodeSpecCard mixingNode={underfloorHeating.mixingNode} />
          )}

          {mixingRec != null && mixingSteps.length > 0 && (
            <div className={styles.velocityWarnBlock} role="status">
              <ul className={styles.warningsList}>
                <li>
                  <strong>{mixingRec.title}</strong>
                  {': '}
                  {mixingRec.text}
                </li>
              </ul>
              <button
                type="button"
                className={styles.resolveButton}
                onClick={() => {
                  setResolutionKind('mixing');
                }}
              >
                Усунення попередження
              </button>
            </div>
          )}

          <div className={styles.pumpBlock}>
            <h4 className={styles.roomTitle}>Насос контуру ТП</h4>
            {underfloorHeating.isMixingNodeRequired ? (
              ufhPumps.length > 0 ? (
                ufhPumps.map((p) => (
                  <HydraulicsPumpCard key={p.zoneId} pump={p} />
                ))
              ) : (
                <p className={styles.hint}>
                  Потрібен змішувальний вузол, але зональний насос контуру ТП не
                  підібрано — перевірте каталог насосів і попередження гідравліки.
                </p>
              )
            ) : (
              <p className={styles.hint}>
                Окремий насос контуру ТП не потрібен — циркуляцію забезпечує
                насос котла.
              </p>
            )}
          </div>

          {underfloorHeating.underfloorHydraulics != null && (
            <dl className={`${styles.dl} ${styles.dlMt10}`}>
              <dt>Гідравліка контуру ТП</dt>
              <dd>
                Δt = {underfloorHeating.underfloorHydraulics.deltaTK} K, витрата{' '}
                {underfloorHeating.underfloorHydraulics.flowRateM3PerHour} м³/ч
              </dd>
            </dl>
          )}
          <dl className={`${styles.dl} ${styles.dlMt10}`}>
            <dt>Сумарна віддача вгору</dt>
            <dd>
              {formatKw(underfloorHeating.totalHeatFluxUpWatts / 1000, 2)}{' '}
              <span>кВт</span>
              <span className={styles.muted}>
                {' '}
                ({formatWatts(underfloorHeating.totalHeatFluxUpWatts)} Вт)
              </span>
            </dd>
            <dt>Паразитний потік вниз</dt>
            <dd>
              {formatKw(underfloorHeating.totalHeatFluxDownWatts / 1000, 2)}{' '}
              <span>кВт</span>
              <span className={styles.muted}>
                {' '}
                ({formatWatts(underfloorHeating.totalHeatFluxDownWatts)} Вт)
              </span>
            </dd>
          </dl>

          {underfloorHeating.rooms.map((room) => {
            const roomWarnings = filterRoomWarningsExcludingLoops(room.warnings);
            return (
              <div key={room.roomId} className={styles.roomBlock}>
                <h4 className={styles.roomTitle}>{room.roomName}</h4>
                <dl className={styles.dl}>
                  <dt>Основа</dt>
                  <dd>{room.basePresetName}</dd>
                  <dt>Фініш</dt>
                  <dd>{room.finishMaterialName}</dd>
                  {(room.roomAreaM2 != null
                    || room.furnitureOccupiedAreaM2 != null
                    || room.heatedAreaM2 != null) && (
                    <>
                      <dt>Площі</dt>
                      <dd>
                        {room.roomAreaM2 != null && (
                          <>приміщення {room.roomAreaM2.toFixed(1)} м²</>
                        )}
                        {room.furnitureOccupiedAreaM2 != null
                          && room.furnitureOccupiedAreaM2 > 0 && (
                          <>
                            {room.roomAreaM2 != null ? ' · ' : ''}
                            меблі {room.furnitureOccupiedAreaM2.toFixed(1)} м²
                          </>
                        )}
                        {room.heatedAreaM2 != null && (
                          <>
                            {(room.roomAreaM2 != null
                              || (room.furnitureOccupiedAreaM2 != null
                                && room.furnitureOccupiedAreaM2 > 0))
                              ? ' · '
                              : ''}
                            активна {room.heatedAreaM2.toFixed(1)} м²
                          </>
                        )}
                      </dd>
                    </>
                  )}
                  <dt>Крок труби</dt>
                  <dd>
                    {room.pipeSpacingMm} мм
                    {room.requestedPipeSpacingMm != null
                      && room.resolvedPipeSpacingMm != null
                      && room.pipeSpacingResolution === 'tightened' && (
                        <span className={styles.muted}>
                          {' '}
                          (запитано {room.requestedPipeSpacingMm} мм →{' '}
                          {room.resolvedPipeSpacingMm} мм)
                        </span>
                      )}
                  </dd>
                  {room.requiredHeatFluxUpWm2 != null && (
                    <>
                      <dt>Потрібний потік вгору</dt>
                      <dd>{formatHeatFluxWm2(room.requiredHeatFluxUpWm2)}</dd>
                    </>
                  )}
                  <dt>Потік вгору / вниз</dt>
                  <dd>
                    {formatHeatFluxWm2(room.heatFluxUpWm2)}
                    {' / '}
                    {formatHeatFluxWm2(room.heatFluxDownWm2)}
                    <span className={styles.muted}>
                      {' '}
                      (ліміт {formatHeatFluxWm2(room.maxAllowableHeatFluxUpWm2)})
                    </span>
                  </dd>
                  <dt>Потужність вгору / вниз</dt>
                  <dd>
                    {formatWatts(room.heatFluxUpWatts)} / {formatWatts(room.heatFluxDownWatts)}
                  </dd>
                  <dt>Температура поверхні</dt>
                  <dd>
                    {formatTempC(room.surfaceTempC)}
                    <span className={styles.muted}>
                      {' '}
                      (макс. {formatTempC(room.maxSurfaceTemperatureCelsius)}
                      {room.comfortMaxSurfaceTemperatureCelsius != null
                        ? `, комфорт ${formatTempC(room.comfortMaxSurfaceTemperatureCelsius)}`
                        : ''}
                      )
                    </span>
                  </dd>
                  {(room.finishMaxSurfaceTemperatureCelsius != null
                    || room.presetMaxSurfaceTemperatureCelsius != null) && (
                    <>
                      <dt>Ліміти Tпов</dt>
                      <dd>
                        {room.finishMaxSurfaceTemperatureCelsius != null && (
                          <>фініш {formatTempC(room.finishMaxSurfaceTemperatureCelsius)}</>
                        )}
                        {room.presetMaxSurfaceTemperatureCelsius != null && (
                          <>
                            {room.finishMaxSurfaceTemperatureCelsius != null ? ' · ' : ''}
                            пресет режиму{' '}
                            {formatTempC(room.presetMaxSurfaceTemperatureCelsius)}
                          </>
                        )}
                      </dd>
                    </>
                  )}
                  <dt>R покриття / укладки</dt>
                  <dd>
                    {room.coveringResistanceM2KW.toFixed(3)} /{' '}
                    {room.pipeEmbedmentResistanceM2KW.toFixed(3)} м²·К/Вт
                  </dd>
                </dl>
                {room.loops != null && room.loops.length > 0 && (
                  <UfhLoopHydraulicsTable
                    loopsCount={room.loopsCount ?? room.loops.length}
                    loops={room.loops}
                    {...(room.pipeResizeApplied !== undefined
                      ? { pipeResizeApplied: room.pipeResizeApplied }
                      : {})}
                  />
                )}
                {roomWarnings.length > 0 && (
                  <ul className={styles.warningsList}>
                    {roomWarnings.map((w, i) => (
                      <li key={`ufh-room-${room.roomId}-${i}`}>{w}</li>
                    ))}
                  </ul>
                )}
              </div>
            );
          })}

          {lowVelocityWarnings.length > 0 && (
            <div className={styles.velocityWarnBlock} role="status">
              <ul className={styles.warningsList}>
                {lowVelocityWarnings.map((w, i) => (
                  <li key={`ufh-v-low-${i}`}>{w}</li>
                ))}
              </ul>
              {showVelocityResolve && (
                <button
                  type="button"
                  className={styles.resolveButton}
                  onClick={() => {
                    setResolutionKind('velocity');
                  }}
                >
                  Усунення попередження
                </button>
              )}
            </div>
          )}

          {parasiticWarnings.length > 0 && (
            <div className={styles.velocityWarnBlock} role="status">
              <ul className={styles.warningsList}>
                {parasiticWarnings.map((w, i) => (
                  <li key={`ufh-parasitic-${i}`}>{w}</li>
                ))}
              </ul>
              {showParasiticResolve && (
                <button
                  type="button"
                  className={styles.resolveButton}
                  onClick={() => {
                    setResolutionKind('parasitic');
                  }}
                >
                  Усунення попередження
                </button>
              )}
            </div>
          )}

          {surfacePresetWarnings.length > 0 && (
            <div className={styles.velocityWarnBlock} role="status">
              <ul className={styles.warningsList}>
                {surfacePresetWarnings.map((w, i) => (
                  <li key={`ufh-surface-preset-${i}`}>{w}</li>
                ))}
              </ul>
              {showSurfacePresetResolve && (
                <button
                  type="button"
                  className={styles.resolveButton}
                  onClick={() => {
                    setResolutionKind('surfacePreset');
                  }}
                >
                  Усунення попередження
                </button>
              )}
            </div>
          )}

          {coverageWarnings.length > 0 && (
            <div className={styles.velocityWarnBlock} role="status">
              <ul className={styles.warningsList}>
                {coverageWarnings.map((w, i) => (
                  <li key={`ufh-coverage-${i}`}>{w}</li>
                ))}
              </ul>
              {showCoverageResolve && (
                <button
                  type="button"
                  className={styles.resolveButton}
                  onClick={() => {
                    setResolutionKind('coverage');
                  }}
                >
                  Усунення попередження
                </button>
              )}
            </div>
          )}
        </>
      )}

      {structuredOther.length > 0 && (
        <div className={styles.structuredBlock}>
          <h4 className={styles.roomTitle}>Рекомендації та попередження</h4>
          <ul className={styles.structuredList}>
            {structuredOther.map((rec, i) => (
              <li key={`ufh-rec-${rec.code}-${i}`} className={styles.structuredItem}>
                <div className={styles.structuredText}>
                  <strong>{rec.title}</strong>
                  <span>{rec.text}</span>
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}

      {globalWarnings.length > 0 && (
        <ul className={styles.warningsList}>
          {globalWarnings.map((w, i) => (
            <li key={`ufh-global-${i}`}>{w}</li>
          ))}
        </ul>
      )}

      {uniboxes != null && (
        <UniboxMatchingSection matching={uniboxes} />
      )}

      <UfhWarningResolutionDialog
        open={resolutionKind != null}
        steps={dialogSteps}
        onClose={() => {
          setResolutionKind(null);
        }}
      />
    </div>
  );
}

/**
 * Назначение: Агрегат ТП + унибоксов + насос ТП для сайдбара «Итог».
 * Описание: Только ключевые цифры; детали — в модалке шага ТП.
 */

import type { ParsedUnderfloorHeating } from '../../types/underfloorHeating';
import type { ParsedHydraulicsPumpProposal } from '../../types/hydraulics';
import type { ParsedUniboxesMatching } from '../../utils/parsers/parseUniboxesMatchingFromReport';
import { formatKw } from '../../utils/format';
import {
  selectUfhZonePumps,
  ufhPumpSummaryLabel,
} from '../../utils/ufhHydraulicsPumps';
import { hasUnderfloorHeatingReportContent } from './hasUnderfloorHeatingReportContent';
import { RESULTS_SECTION_IDS } from '../../constants/surveyResultsSections';
import { SurveyStepLink } from '../SurveyNavigation/SurveyStepLink';
import styles from './UnderfloorHeatingSummaryTable.module.css';

export type UnderfloorHeatingSummaryTableProps = {
  underfloorHeating: ParsedUnderfloorHeating | null;
  uniboxes?: ParsedUniboxesMatching | null;
  hydraulicsPumps?: readonly ParsedHydraulicsPumpProposal[] | null;
};

/**
 * @param props
 */
export function UnderfloorHeatingSummaryTable({
  underfloorHeating,
  uniboxes = null,
  hydraulicsPumps = null,
}: UnderfloorHeatingSummaryTableProps) {
  if (!hasUnderfloorHeatingReportContent(underfloorHeating) || underfloorHeating == null) {
    return null;
  }

  const selectedUniboxes =
    uniboxes?.byLoop.filter((row) => row.selected != null).length ?? 0;
  const uniboxLoops = uniboxes?.byLoop.length ?? 0;
  const uniboxLabel =
    uniboxes == null
      ? '—'
      : uniboxLoops === 0
        ? 'немає петель'
        : `${selectedUniboxes} / ${uniboxLoops}`;

  const ufhPumps = selectUfhZonePumps(hydraulicsPumps);
  const pumpLabel = ufhPumpSummaryLabel(
    underfloorHeating.isMixingNodeRequired,
    ufhPumps,
  );

  const hasWarnings =
    underfloorHeating.warnings.length > 0
    || underfloorHeating.resolvedRecommendations.length > 0
    || (uniboxes?.warnings.length ?? 0) > 0;

  return (
    <div
      id={RESULTS_SECTION_IDS.warmFloor}
      className={styles.wrap}
      aria-labelledby="underfloor-heating-summary-title"
    >
      <h3 id="underfloor-heating-summary-title" className={styles.title}>
        Тепла підлога (підсумок)
      </h3>
      {underfloorHeating.rooms.length === 0 ? (
        <p className={styles.hint}>
          Режим ТП увімкнено, але немає приміщень з ТП. Деталі — на кроці{' '}
          <SurveyStepLink step="warmFloor">«Тепла підлога»</SurveyStepLink>
          .
        </p>
      ) : (
        <div className={styles.tableWrap}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>Показник</th>
                <th>Значення</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>Контур</td>
                <td>
                  {underfloorHeating.circuitSupplyC}/
                  {underfloorHeating.circuitReturnC} °C
                </td>
              </tr>
              <tr>
                <td>Σ q↑ (тепло вгору в приміщення)</td>
                <td>{formatKw(underfloorHeating.totalHeatFluxUpWatts / 1000, 2)} кВт</td>
              </tr>
              <tr>
                <td>Σ q↓ (тепло вниз, втрати в перекриття)</td>
                <td>
                  {formatKw(underfloorHeating.totalHeatFluxDownWatts / 1000, 2)} кВт
                </td>
              </tr>
              <tr>
                <td>Приміщень з ТП</td>
                <td>{underfloorHeating.rooms.length}</td>
              </tr>
              <tr>
                <td>Змішувальний вузол</td>
                <td>
                  {underfloorHeating.isMixingNodeRequired
                    ? 'потрібно'
                    : underfloorHeating.circuitSource === 'ufh_mode_preset'
                      ? 'не потрібно (пряме підключення, котел 40/30)'
                      : 'не потрібно'}
                </td>
              </tr>
              <tr>
                <td>Насос контуру ТП</td>
                <td>{pumpLabel}</td>
              </tr>
              <tr>
                <td>Унибокси (підібрано / петель)</td>
                <td>{uniboxLabel}</td>
              </tr>
            </tbody>
          </table>
        </div>
      )}
      {underfloorHeating.rooms.length > 0 && (
        <p className={styles.hint}>
          Деталі розрахунку за приміщеннями, унибоксами та насосом контуру — на кроці{' '}
          <SurveyStepLink step="warmFloor">«Тепла підлога»</SurveyStepLink>
          .
        </p>
      )}
      {hasWarnings && (
        <p className={styles.attention}>
          Зверніть увагу на рекомендації та попередження в картці{' '}
          <SurveyStepLink step="warmFloor">«Тепла підлога»</SurveyStepLink>
          .
        </p>
      )}
    </div>
  );
}

/**
 * Назначение: Таблица подбора унибоксов из matching.uniboxes.
 * Описание: Строки по петлям ТП — модель, лимиты, цена; warnings блока.
 */

import type { ParsedUniboxesMatching } from '../../utils/parsers/parseUniboxesMatchingFromReport';
import styles from '../CatalogEquipmentReference/CatalogEquipmentReference.module.css';

type Props = {
  matching: ParsedUniboxesMatching;
};

function formatPriceUah(price: number): string {
  return `${Math.round(price).toLocaleString('ru-RU')} ₴`;
}

/**
 * @param {Props} props
 */
export function UniboxMatchingSection({ matching }: Props) {
  const { byLoop, warnings } = matching;
  if (byLoop.length === 0 && warnings.length === 0) return null;

  return (
    <div className={styles.wrap}>
      <h3 className={styles.title}>Унибокси (підбір за петлями ТП)</h3>
      <p className={styles.meta}>
        Локальний регулятор петлі: фільтр за паспортними лімітами (площа, довжина, T, P, Kv, eurocone).
        До 3 петель з унибоксом — без попередження; від 4 — перегляд гідравліки. Каскад колекторів не блокує підбір.
      </p>

      {warnings.length > 0 && (
        <ul className={`${styles.meta} ${styles.metaDanger}`}>
          {warnings.map((w, i) => (
            <li key={`unibox-warn-${i}`}>{w}</li>
          ))}
        </ul>
      )}

      {byLoop.length === 0 ? (
        <p className={styles.meta}>Немає рядків підбору (гейт або немає петель з довжиною &gt; 0).</p>
      ) : (
        <div className={styles.tableWrap}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>Петля</th>
                <th>Площа / довжина</th>
                <th>T под/обр / повітря</th>
                <th>Модель</th>
                <th>Тип</th>
                <th>Підключення</th>
                <th>Kv</th>
                <th>Ціна</th>
              </tr>
            </thead>
            <tbody>
              {byLoop.map((row) => {
                const s = row.selected;
                return (
                  <tr key={`${row.roomId}-${row.loopId}`}>
                    <td>
                      {row.roomId} / {row.loopId}
                    </td>
                    <td>
                      {row.required.areaSqM} м² / {row.required.loopLengthM} м
                    </td>
                    <td>
                      {row.required.circuitSupplyC}/{row.required.circuitReturnC} /{' '}
                      {row.required.roomAirTempC} °C
                    </td>
                    <td>{s ? `${s.brand} ${s.model}` : '—'}</td>
                    <td>{s?.type ?? '—'}</td>
                    <td>
                      {s
                        ? `${s.connection.thread} / ${s.connection.fit}`
                        : row.required.requiredFit}
                    </td>
                    <td>{s ? s.kvM3h : `≥${row.required.minKvM3h.toFixed(3)}`}</td>
                    <td>{s ? formatPriceUah(s.price) : '—'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {byLoop.some((r) => r.warnings.length > 0) && (
        <ul className={styles.meta}>
          {byLoop.flatMap((r) =>
            r.warnings.map((w, i) => (
              <li key={`${r.loopId}-w-${i}`}>
                {r.loopId}: {w}
              </li>
            )),
          )}
        </ul>
      )}
    </div>
  );
}

/**
 * Назначение: Секция шага «Тёплый пол».
 * Описание: Карточки режимов ТП, флаг, схема подключения; полный отчёт — в модалке.
 */

import { useState } from 'react';

import { UfhPresetCards } from '../UfhPresetCards/UfhPresetCards';
import { UnderfloorHeatingReportDialog } from '../UnderfloorHeatingReport/UnderfloorHeatingReportDialog';
import { hasUnderfloorHeatingReportContent } from '../UnderfloorHeatingReport/hasUnderfloorHeatingReportContent';
import type { ParsedUnderfloorHeating } from '../../types/underfloorHeating';
import type { ParsedHydraulicsPumpProposal } from '../../types/hydraulics';
import type { UfhDistributionPreset } from '../../types/ufhDistribution';
import type { UfhModePresetCard, UfhModePresetId } from '../../types/ufhModePreset';
import type { ParsedUniboxesMatching } from '../../utils/parsers/parseUniboxesMatchingFromReport';
import reportActionsStyles from '../SurveyNavigation/SurveyReportActions.module.css';
import styles from './WarmFloorSection.module.css';
import { UfhDistributionSelect } from './UfhDistributionSelect';

type Props = {
  waterUnderfloorHeating: boolean;
  underfloorDistributionPreset: UfhDistributionPreset;
  ufhModePresets: UfhModePresetCard[];
  ufhModePresetsLoading?: boolean;
  ufhModePresetsError?: string | null;
  ufhPresetId: UfhModePresetId | null;
  onUfhPresetChange: (presetId: UfhModePresetId | null) => void;
  onWaterUnderfloorChange: (value: boolean) => void;
  onDistributionPresetChange: (value: UfhDistributionPreset) => void;
  underfloorHeatingReport?: ParsedUnderfloorHeating | null;
  uniboxesReport?: ParsedUniboxesMatching | null;
  /** proposal.pumps гидравлики — для зонального насоса ТП в модалке. */
  hydraulicsPumps?: readonly ParsedHydraulicsPumpProposal[] | null;
  /** Прокрутка к итогу ТП в сайдбаре «Результаты». */
  onBackToResults?: () => void;
};

/** Шаг анкеты: режим ТП (карточки), водяной тёплый пол и схема распределения. */
export function WarmFloorSection({
  waterUnderfloorHeating,
  underfloorDistributionPreset,
  ufhModePresets,
  ufhModePresetsLoading = false,
  ufhModePresetsError = null,
  ufhPresetId,
  onUfhPresetChange,
  onWaterUnderfloorChange,
  onDistributionPresetChange,
  underfloorHeatingReport = null,
  uniboxesReport = null,
  hydraulicsPumps = null,
  onBackToResults,
}: Props) {
  const [reportOpen, setReportOpen] = useState(false);
  const showDistribution =
    waterUnderfloorHeating
    && ufhPresetId != null
    && ufhPresetId !== 'ufh_only';
  const canOpenReport = hasUnderfloorHeatingReportContent(underfloorHeatingReport)
    || (uniboxesReport != null
      && (uniboxesReport.byLoop.length > 0 || uniboxesReport.warnings.length > 0));

  return (
    <div className={styles.root}>
      <h3 className={styles.title}>Тепла підлога</h3>
      <p className={`${styles.hint} ${styles.hintMt0}`}>
        Оберіть режим опалення. Для комбінації «тепла підлога в частині кімнат + радіатори» —
        картка <strong>«Тепла підлога + радіатори»</strong>; ТП вмикається по кімнатах на кроці
        «Приміщення». Радіаторний графік котла (75/65 або 55/45) — на кроці «Котел».
      </p>

      <UfhPresetCards
        presets={ufhModePresets}
        selectedPresetId={ufhPresetId}
        onSelect={onUfhPresetChange}
        loading={ufhModePresetsLoading}
        error={ufhModePresetsError}
      />

      <label className={`${styles.hint} ${styles.checkboxRow} ${styles.hintMt16}`}>
        <input
          type="checkbox"
          checked={waterUnderfloorHeating}
          onChange={(e) => { onWaterUnderfloorChange(e.target.checked); }}
        />
        <span>У проєкті передбачена водяна тепла підлога (кімнати на кроці «Приміщення»)</span>
      </label>
      {showDistribution && (
        <UfhDistributionSelect
          value={underfloorDistributionPreset}
          onChange={onDistributionPresetChange}
        />
      )}

      <div className={reportActionsStyles.reportActions}>
        <div className={reportActionsStyles.reportActionsRow}>
          <button
            type="button"
            className={reportActionsStyles.reportButton}
            disabled={!canOpenReport}
            onClick={() => { setReportOpen(true); }}
          >
            Звіт з розрахунку ТП
          </button>
          {onBackToResults != null && (
            <button
              type="button"
              className={reportActionsStyles.backButton}
              onClick={onBackToResults}
            >
              Назад до результатів
            </button>
          )}
        </div>
        {!canOpenReport && (
          <p className={`${styles.hint} ${styles.hintMt8}`}>
            Звіт з&apos;явиться після авторозрахунку з увімкненим ТП у приміщеннях.
          </p>
        )}
      </div>

      {import.meta.env.DEV && (
        <p className={`${styles.hint} ${styles.hintMt10}`}>
          Поля API:{' '}
          <code className={styles.inlineCode}>heatingSystem.ufhPresetId</code>,{' '}
          <code className={styles.inlineCode}>heatingSystem.waterUnderfloorHeating</code>,{' '}
          <code className={styles.inlineCode}>heatingSystem.underfloorDistributionPreset</code>.
        </p>
      )}

      <UnderfloorHeatingReportDialog
        open={reportOpen}
        onClose={() => { setReportOpen(false); }}
        underfloorHeating={underfloorHeatingReport}
        uniboxes={uniboxesReport}
        hydraulicsPumps={hydraulicsPumps}
      />
    </div>
  );
}

/**
 * Назначение: Форма шага «Водонагреватель».
 * Описание: Стратегия подбора БКН/ЭВН; полный отчёт matching — в модалке.
 */

import { useMemo, useState } from 'react';

import type { ObjectType } from '../../types/envelope';
import type { HotWaterBoilerPowerMatchingScheme } from '../../types/heatingMatching';
import type { HotWaterFormValue } from '../../types/hotWater';
import type { WaterHeaterFormValue } from '../../types/waterHeater';
import type { ParsedIndirectWaterHeaterMatching } from '../../utils/parsers/parseIndirectWaterHeaterMatchingFromReport';
import type { ParsedWaterHeaterMatching } from '../../utils/parsers/parseWaterHeaterMatchingFromReport';
import { getWaterHeaterSchemeOptions } from '../../utils/waterHeaterSchemeOptions';
import { validateWaterHeaterForm } from '../../utils/validateWaterHeaterForm';
import { shouldShowIndirectDhwSpaceCheckbox } from '../../../../shared/waterHeaterFormContract.js';
import { WaterHeaterReportDialog } from '../WaterHeaterReport/WaterHeaterReportDialog';
import { hasWaterHeaterReportContent } from '../WaterHeaterReport/hasWaterHeaterReportContent';
import reportActionsStyles from '../SurveyNavigation/SurveyReportActions.module.css';
import styles from './WaterHeaterForm.module.css';

type Props = {
  value: WaterHeaterFormValue;
  onChange: (next: WaterHeaterFormValue) => void;
  objectType: ObjectType;
  apartmentLarge: boolean;
  hotWaterForm: HotWaterFormValue;
  calcLoading: boolean;
  indirectMatching: ParsedIndirectWaterHeaterMatching | null;
  electricMatching: ParsedWaterHeaterMatching | null;
  /** Прокрутка к итогу ЭБ/БКН в сайдбаре «Результаты». */
  onBackToResults?: () => void;
};

export function WaterHeaterForm({
  value,
  onChange,
  objectType,
  apartmentLarge,
  hotWaterForm,
  calcLoading,
  indirectMatching,
  electricMatching,
  onBackToResults,
}: Props) {
  const [reportOpen, setReportOpen] = useState(false);
  const canOpenReport = hasWaterHeaterReportContent(
    indirectMatching,
    electricMatching,
  );

  const schemeOptions = useMemo(
    () => getWaterHeaterSchemeOptions(objectType, apartmentLarge),
    [objectType, apartmentLarge],
  );

  const allowedSchemes = useMemo(
    () => schemeOptions.map((o) => o.value),
    [schemeOptions],
  );

  const validation = useMemo(
    () =>
      validateWaterHeaterForm(value, {
        objectType,
        hotWaterForm,
        allowedSchemes,
      }),
    [value, objectType, hotWaterForm, allowedSchemes],
  );

  const showIndirectCheckbox = shouldShowIndirectDhwSpaceCheckbox(
    objectType,
    value.hotWaterBoilerPowerMatchingScheme,
  );

  const handleSchemeChange = (scheme: HotWaterBoilerPowerMatchingScheme) => {
    const next: WaterHeaterFormValue = {
      ...value,
      hotWaterBoilerPowerMatchingScheme: scheme,
    };
    if (!shouldShowIndirectDhwSpaceCheckbox(objectType, scheme)) {
      next.indirectDhwSpaceAvailable = false;
    }
    onChange(next);
  };

  return (
    <div className={styles.root}>
      <h2 className={styles.title}>Водонагрівач і сценарій ГВП</h2>
      <p className={styles.hint}>
        Оберіть, як забезпечується гаряча вода: через двоконтурний котел,
        бойлер непрямого нагріву (БКН) або електронакопичувач. Споживання води
        (мешканці, точки) задається на кроці «Гаряча вода»; тут — лише
        стратегія підбору обладнання.
      </p>

      <div className={styles.section}>
        <h3 className={styles.sectionTitle}>Сценарій зв&apos;язки котел / ГВП</h3>
        <label className={styles.label} htmlFor="water-heater-scheme">
          Як котел пов&apos;язаний із гарячою водою
        </label>
        <select
          id="water-heater-scheme"
          className={styles.select}
          value={value.hotWaterBoilerPowerMatchingScheme}
          onChange={(e) =>
            { handleSchemeChange(
              e.target.value as HotWaterBoilerPowerMatchingScheme,
            ); }
          }
        >
          {schemeOptions.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
        <p className={styles.hint}>
          В API:{' '}
          <code className={styles.inlineCode}>
            heatingSystem.hotWaterBoilerPowerMatchingScheme
          </code>
          . Модель і об&apos;єм підбираються автоматично за розрахунком.
        </p>

        {showIndirectCheckbox && (
          <label className={styles.checkboxLabel}>
            <input
              type="checkbox"
              checked={value.indirectDhwSpaceAvailable}
              onChange={(e) =>
                { onChange({
                  ...value,
                  indirectDhwSpaceAvailable: e.target.checked,
                }); }
              }
            />
            <span>
              Є техприміщення або ніша під бойлер непрямого нагріву (БКН).
              Без цієї позначки для квартири підбір БКН не виконується.
            </span>
          </label>
        )}
      </div>

      <p className={styles.hint}>
        Деталі розрахунку споживання (витрата, потужність, об&apos;єм бака) — на кроці
        «Гаряча вода», кнопка «Звіт з розрахунку ГВ».
      </p>

      {validation.warnings.length > 0 && (
        <div className={styles.warningsSection} role="status">
          <h3 className={styles.sectionTitle}>Підказки</h3>
          <ul className={styles.warningsList}>
            {validation.warnings.map((w) => (
              <li key={w}>{w}</li>
            ))}
          </ul>
        </div>
      )}

      <div className={reportActionsStyles.reportActions}>
        <div className={reportActionsStyles.reportActionsRow}>
          <button
            type="button"
            className={reportActionsStyles.reportButton}
            disabled={!canOpenReport}
            onClick={() => { setReportOpen(true); }}
          >
            Звіт з підбору водонагрівача
          </button>
          {onBackToResults != null && (
            <button
              type="button"
              className={reportActionsStyles.backButton}
              onClick={onBackToResults}
            >
              Назад до результатів
            </button>
          )}
        </div>
        {calcLoading && (
          <p className={`${styles.hint} ${styles.hintMt8}`} role="status">
            Оновлення підбору…
          </p>
        )}
        {!canOpenReport && !calcLoading && (
          <p className={`${styles.hint} ${styles.hintMt8}`}>
            Звіт з&apos;явиться після авторозрахунку з обраною схемою ГВП.
          </p>
        )}
      </div>

      <WaterHeaterReportDialog
        open={reportOpen}
        onClose={() => { setReportOpen(false); }}
        indirect={indirectMatching}
        electric={electricMatching}
      />
    </div>
  );
}

