/**
 * Назначение: Модальное окно отчёта подбора водонагревателя.
 * Описание: Паттерн HotWaterReportDialog; контент — WaterHeaterReportView.
 */

import { useEffect } from 'react';

import type { ParsedIndirectWaterHeaterMatching } from '../../utils/parsers/parseIndirectWaterHeaterMatchingFromReport';
import type { ParsedWaterHeaterMatching } from '../../utils/parsers/parseWaterHeaterMatchingFromReport';
import { WaterHeaterReportView } from './WaterHeaterReportView';
import { hasWaterHeaterReportContent } from './hasWaterHeaterReportContent';
import styles from './WaterHeaterReportDialog.module.css';

export type WaterHeaterReportDialogProps = {
  open: boolean;
  onClose: () => void;
  indirect: ParsedIndirectWaterHeaterMatching | null;
  electric: ParsedWaterHeaterMatching | null;
};

/**
 * @param props
 */
export function WaterHeaterReportDialog({
  open,
  onClose,
  indirect,
  electric,
}: WaterHeaterReportDialogProps) {
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [open, onClose]);

  if (!open) return null;

  const hasContent = hasWaterHeaterReportContent(indirect, electric);

  return (
    <div
      className={styles.backdrop}
      role="presentation"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className={styles.dialog}
        role="dialog"
        aria-modal="true"
        aria-labelledby="water-heater-report-dialog-title"
        onClick={(e) => {
          e.stopPropagation();
        }}
      >
        <div className={styles.header}>
          <h2 id="water-heater-report-dialog-title" className={styles.title}>
            Звіт з підбору водонагрівача
          </h2>
          <button
            type="button"
            className={styles.closeIconButton}
            onClick={onClose}
            aria-label="Закрити"
          >
            ✕
          </button>
        </div>

        {hasContent ? (
          <WaterHeaterReportView indirect={indirect} electric={electric} />
        ) : (
          <p className={styles.empty}>
            Немає даних підбору. Оберіть схему на кроці «Водонагрівач» та
            дочекайтеся авторозрахунку.
          </p>
        )}

        <button type="button" className={styles.closeButton} onClick={onClose}>
          Закрити
        </button>
      </div>
    </div>
  );
}

/**
 * Назначение: жизненный цикл SSE admin feedback, reconnect и локальное уведомление.
 */

import { useEffect, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';

import { adminFeedbackUk } from '../i18n/uk/adminFeedback';
import { AdminFeedbackApiError } from '../services/adminFeedbackApi';
import { streamAdminFeedback } from '../services/adminFeedbackStream';
import { queryKeys } from '../query/queryKeys';

export type AdminFeedbackStreamState = 'connecting' | 'connected' | 'reconnecting' | 'unavailable';

export type UseAdminFeedbackStreamResult = {
  streamState: AdminFeedbackStreamState;
  toastMessage: string | null;
  dismissToast: () => void;
};

const MAX_RECONNECT_DELAY_MS = 30_000;
const TOAST_DURATION_MS = 8_000;

/**
 * @param error
 */
function isAbortError(error: unknown): boolean {
  return error instanceof DOMException && error.name === 'AbortError';
}

/**
 * Поддерживает live-подписку, пока admin dashboard смонтирован.
 */
export function useAdminFeedbackStream(): UseAdminFeedbackStreamResult {
  const queryClient = useQueryClient();
  const [streamState, setStreamState] = useState<AdminFeedbackStreamState>('connecting');
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    let reconnectTimer: number | null = null;
    let toastTimer: number | null = null;
    let reconnectAttempt = 0;

    const connect = async (): Promise<void> => {
      if (controller.signal.aborted) return;
      setStreamState(reconnectAttempt === 0 ? 'connecting' : 'reconnecting');

      try {
        await streamAdminFeedback({
          signal: controller.signal,
          onOpen: () => {
            reconnectAttempt = 0;
            setStreamState('connected');
            void queryClient.invalidateQueries({ queryKey: queryKeys.adminFeedbackRoot });
          },
          onCreated: (item) => {
            void queryClient.invalidateQueries({ queryKey: queryKeys.adminFeedbackRoot });
            setToastMessage(
              item.type === 'bug'
                ? adminFeedbackUk.toastBugCreated
                : adminFeedbackUk.toastContactCreated,
            );
            if (toastTimer !== null) window.clearTimeout(toastTimer);
            toastTimer = window.setTimeout(() => {
              setToastMessage(null);
            }, TOAST_DURATION_MS);
          },
        });
        throw new Error('Live-потік було закрито сервером');
      } catch (error: unknown) {
        if (isAbortError(error)) return;
        if (
          error instanceof AdminFeedbackApiError &&
          (error.statusCode === 401 || error.statusCode === 403)
        ) {
          setStreamState('unavailable');
          return;
        }

        setStreamState('reconnecting');
        const delay = Math.min(1_000 * 2 ** reconnectAttempt, MAX_RECONNECT_DELAY_MS);
        reconnectAttempt += 1;
        reconnectTimer = window.setTimeout(() => {
          void connect();
        }, delay);
      }
    };

    void connect();

    return () => {
      controller.abort();
      if (reconnectTimer !== null) window.clearTimeout(reconnectTimer);
      if (toastTimer !== null) window.clearTimeout(toastTimer);
    };
  }, [queryClient]);

  return {
    streamState,
    toastMessage,
    dismissToast: () => {
      setToastMessage(null);
    },
  };
}

/**
 * Назначение: Хук разбора JSON-отчёта расчёта.
 * Описание: Парсинг узлов matching, heatLoss и рекомендаций в стабильный объект для UI.
 */

import { useMemo } from 'react';
import type { CalcReportJson } from '../types/calcApi';
import type { HotWaterBoilerPowerMatchingScheme } from '../types/heatingMatching';
import type { ApiHotWater } from '../types/recommendationsBlock';
import type { UfhModePresetId } from '../types/ufhModePreset';
import { parseHotWaterFromReport } from '../utils/parsers/parseHotWaterFromReport';
import { heatLossReserveKw, heatLossTotalKw, wattsToKilowatts } from '../utils/calculators/heatLoss';
import { isRecord, readRecordField } from '../utils/jsonGuards';
import { parseBoilerFromReport } from '../utils/parsers/parseBoilerFromReport';
import { parseIndirectWaterHeaterMatchingFromReport } from '../utils/parsers/parseIndirectWaterHeaterMatchingFromReport';
import { parseRadiatorsMatchingFromReport, formatRadiatorsEmittersSummaryLabel } from '../utils/parsers/parseRadiatorsMatchingFromReport';
import { parseWaterHeaterMatchingFromReport } from '../utils/parsers/parseWaterHeaterMatchingFromReport';
import { parseUnderfloorHeatingFromReport } from '../utils/parsers/parseUnderfloorHeatingFromReport';
import { parseHydraulicsFromReport } from '../utils/parsers/parseHydraulicsFromReport';
import { parseUniboxesMatchingFromReport } from '../utils/parsers/parseUniboxesMatchingFromReport';
import { parseCommercialBomFromReport } from '../utils/parsers/parseCommercialBomFromReport';
import {
  isRadiatorsMatchingSkipped,
  isUfhOnlySurveyMode,
} from '../utils/radiatorsSkip';

type IsCalcMatchingScheme = (v: string) => v is HotWaterBoilerPowerMatchingScheme;

/**
 * Парсить всі секції звіту POST /api/v1/calc.
 * Повертає стабільний об'єкт — усі поля null, поки звіт відсутній.
 *
 * @param calcReport
 * @param isCalcMatchingScheme
 * @param quickEstimateRadiatorsSections
 * @param ufhPresetId — щоб не показувати чернеткові секції при ufh_only до/після calc
 */
export function useCalcReport(
  calcReport: CalcReportJson | null,
  isCalcMatchingScheme: IsCalcMatchingScheme,
  quickEstimateRadiatorsSections: number,
  ufhPresetId: UfhModePresetId | null = null,
) {
  const apiHeatLoss = useMemo(() => {
    if (calcReport === null) return null;
    const calculations = readRecordField(calcReport, 'calculations');
    if (!calculations) return null;
    const heatLoss = readRecordField(calculations, 'heatLoss');
    if (!heatLoss) return null;
    const totalWatts = heatLoss.totalWatts;
    if (typeof totalWatts !== 'number' || !Number.isFinite(totalWatts)) return null;
    const heatLossKw = wattsToKilowatts(totalWatts);
    return {
      heatLossKw,
      reserveKw: heatLossReserveKw(heatLossKw),
      totalHeatKw: heatLossTotalKw(heatLossKw),
    };
  }, [calcReport]);

  const apiHotWaterFromReport = useMemo((): ApiHotWater => {
    return parseHotWaterFromReport(calcReport);
  }, [calcReport]);

  const apiBoilerFromReport = useMemo(
    () => parseBoilerFromReport(calcReport, isCalcMatchingScheme),
    [calcReport, isCalcMatchingScheme],
  );

  const apiRadiatorsFromReport = useMemo(
    () => parseRadiatorsMatchingFromReport(calcReport),
    [calcReport],
  );

  const apiIndirectWhFromReport = useMemo(
    () => parseIndirectWaterHeaterMatchingFromReport(calcReport),
    [calcReport],
  );

  const apiElectricWhFromReport = useMemo(
    () => parseWaterHeaterMatchingFromReport(calcReport),
    [calcReport],
  );

  const displayedRadiatorSectionsTotal = useMemo(() => {
    if (
      isRadiatorsMatchingSkipped(apiRadiatorsFromReport)
      || isUfhOnlySurveyMode(ufhPresetId)
    ) {
      return 'не требуется';
    }
    const ecoLabel = formatRadiatorsEmittersSummaryLabel(
      apiRadiatorsFromReport?.lineEconomy?.emittersSummary,
    );
    const effLabel = formatRadiatorsEmittersSummaryLabel(
      apiRadiatorsFromReport?.lineEfficient?.emittersSummary,
    );
    if (ecoLabel != null && effLabel != null) {
      return `эконом: ${ecoLabel} / эффективный: ${effLabel}`;
    }
    const primaryLabel = formatRadiatorsEmittersSummaryLabel(
      apiRadiatorsFromReport?.emittersSummary,
    );
    if (primaryLabel != null) return primaryLabel;
    if (
      apiRadiatorsFromReport?.totalSections != null
      && apiRadiatorsFromReport.byRoom.length > 0
    ) {
      return `${apiRadiatorsFromReport.totalSections} сек.`;
    }
    return String(quickEstimateRadiatorsSections);
  }, [apiRadiatorsFromReport, quickEstimateRadiatorsSections, ufhPresetId]);

  const apiCatalogSource = useMemo((): 'file' | 'mongo' | null => {
    if (calcReport === null) return null;
    const meta = readRecordField(calcReport, 'meta');
    if (!meta) return null;
    const s = meta.catalogSource;
    return s === 'mongo' || s === 'file' ? s : null;
  }, [calcReport]);

  const apiAutomationHints = useMemo(() => {
    if (calcReport === null) return [];
    const meta = readRecordField(calcReport, 'meta');
    if (!meta) return [];
    const raw = meta.automationHints;
    if (!Array.isArray(raw)) return [];
    const out: { type: string; message: string; suggestedScheme?: HotWaterBoilerPowerMatchingScheme }[] = [];
    for (const item of raw) {
      if (!isRecord(item)) continue;
      const message = typeof item.message === 'string' ? item.message : '';
      const type = typeof item.type === 'string' ? item.type : '';
      if (!message) continue;
      const ss = item.suggestedScheme;
      const suggestedScheme =
        typeof ss === 'string' && isCalcMatchingScheme(ss) ? ss : undefined;
      out.push({
        type,
        message,
        ...(suggestedScheme !== undefined ? { suggestedScheme } : {}),
      });
    }
    return out;
  }, [calcReport, isCalcMatchingScheme]);

  const apiBoilerKw = apiBoilerFromReport?.summary?.requiredKw ?? null;

  const apiUnderfloorHeatingFromReport = useMemo(
    () => parseUnderfloorHeatingFromReport(calcReport),
    [calcReport],
  );

  const apiUniboxesFromReport = useMemo(
    () => parseUniboxesMatchingFromReport(calcReport),
    [calcReport],
  );

  const apiHydraulicsFromReport = useMemo(
    () => parseHydraulicsFromReport(calcReport),
    [calcReport],
  );

  const apiCommercialBomFromReport = useMemo(
    () => parseCommercialBomFromReport(calcReport),
    [calcReport],
  );

  return {
    apiHeatLoss,
    apiHotWaterFromReport,
    apiBoilerFromReport,
    apiBoilerKw,
    apiRadiatorsFromReport,
    apiIndirectWhFromReport,
    apiElectricWhFromReport,
    apiUnderfloorHeatingFromReport,
    apiUniboxesFromReport,
    apiHydraulicsFromReport,
    apiCommercialBomFromReport,
    displayedRadiatorSectionsTotal,
    apiCatalogSource,
    apiAutomationHints,
  };
}

/**
 * Назначение: один file input + режим (import / openLocal) для export/import bundle.
 * Описание: кнопки задают режим; onChange делегирует receiveProjectBundle или openLocal.
 */

import {
  useCallback,
  useRef,
  useState,
  type ChangeEvent,
  type RefObject,
} from 'react';
import { useQueryClient } from '@tanstack/react-query';

import type { SurveyDraft } from '../types/surveyDraft';
import { parseSurveyDraft } from '../utils/parsers/parseSurveyDraft';
import {
  mapProjectImportErrorMessage,
  receiveProjectBundle,
  sendProjectBundle,
  type ProjectBundleExportParams,
  type ProjectBundleImportResult,
} from '../utils/projectBundleTransfer';

/** Режим очікуваного файлу для спільного input. */
export type ProjectBundleFileMode = 'import' | 'openLocal';

export type UseProjectBundleTransferParams = {
  /** Підтвердження перед імпортом (наприклад, заміна поточної анкети). */
  confirmBeforeImport?: () => boolean | Promise<boolean>;
  onImportSuccess?: (result: ProjectBundleImportResult) => void | Promise<void>;
  onOpenLocalSuccess?: (draft: SurveyDraft, fileName: string) => void;
  onStatus?: (message: string | null, error: string | null) => void;
};

export type UseProjectBundleTransferResult = {
  fileInputRef: RefObject<HTMLInputElement | null>;
  handleFileInputChange: (event: ChangeEvent<HTMLInputElement>) => void;
  requestImport: () => void;
  requestOpenLocal: () => void;
  sendProjectBundle: (params: ProjectBundleExportParams) => Promise<void>;
  importBusy: boolean;
  exportBusy: boolean;
};

/**
 * @param params
 */
export function useProjectBundleTransfer(
  params: UseProjectBundleTransferParams = {},
): UseProjectBundleTransferResult {
  const { confirmBeforeImport, onImportSuccess, onOpenLocalSuccess, onStatus } = params;
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const pendingModeRef = useRef<ProjectBundleFileMode | null>(null);
  const [importBusy, setImportBusy] = useState(false);
  const [exportBusy, setExportBusy] = useState(false);

  const notify = useCallback(
    (message: string | null, error: string | null) => {
      onStatus?.(message, error);
    },
    [onStatus],
  );

  const runImport = useCallback(
    async (file: File) => {
      if (confirmBeforeImport) {
        const ok = await confirmBeforeImport();
        if (!ok) return;
      }

      setImportBusy(true);
      notify(null, null);
      try {
        const result = await receiveProjectBundle(file, queryClient);
        await onImportSuccess?.(result);
        notify(
          `Проєкт успішно імпортовано! (${String(result.calculationsImported)} розрахунків)`,
          null,
        );
      } catch (e) {
        const raw = e instanceof Error ? e.message : 'Не вдалося імпортувати проєкт';
        notify(null, mapProjectImportErrorMessage(raw));
      } finally {
        setImportBusy(false);
      }
    },
    [confirmBeforeImport, onImportSuccess, notify, queryClient],
  );

  const runOpenLocal = useCallback(
    async (file: File) => {
      notify(null, null);
      try {
        const text = await file.text();
        const raw: unknown = JSON.parse(text);
        const draft = parseSurveyDraft(raw);
        onOpenLocalSuccess?.(draft, file.name);
        notify(`Завантажено з файлу: ${file.name}`, null);
      } catch (e) {
        notify(null, e instanceof Error ? e.message : 'Не вдалося прочитати файл');
      }
    },
    [notify, onOpenLocalSuccess],
  );

  /** Єдиний слухач file input. */
  const handleFileInputChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      event.target.value = '';
      const mode = pendingModeRef.current;
      pendingModeRef.current = null;
      if (!file || mode == null) return;

      if (mode === 'import') {
        void runImport(file);
        return;
      }
      void runOpenLocal(file);
    },
    [runImport, runOpenLocal],
  );

  const requestImport = useCallback(() => {
    pendingModeRef.current = 'import';
    fileInputRef.current?.click();
  }, []);

  const requestOpenLocal = useCallback(() => {
    pendingModeRef.current = 'openLocal';
    fileInputRef.current?.click();
  }, []);

  const runSendProjectBundle = useCallback(
    async (exportParams: ProjectBundleExportParams) => {
      setExportBusy(true);
      notify(null, null);
      try {
        const { filename, calculationsCount } = await sendProjectBundle(
          queryClient,
          exportParams,
        );
        notify(
          `Проєкт експортовано (${String(calculationsCount)} розрахунків): ${filename}`,
          null,
        );
      } catch (e) {
        const raw = e instanceof Error ? e.message : 'Не вдалося експортувати проєкт';
        if (raw !== 'Експорт скасовано') {
          notify(null, raw);
        }
      } finally {
        setExportBusy(false);
      }
    },
    [notify, queryClient],
  );

  return {
    fileInputRef,
    handleFileInputChange,
    requestImport,
    requestOpenLocal,
    sendProjectBundle: runSendProjectBundle,
    importBusy,
    exportBusy,
  };
}

/**
 * Назначение: Хук оркестрации помещений и objectMeta.
 * Описание: Синхронизация комнат с roomsCount, пресетами и границами квартиры в стояке.
 */

import { useEffect, useRef, type Dispatch, type SetStateAction } from 'react';

import { DEFAULT_WINDOW_PRESET_ID } from '../data/fallbackEnvelopePresets';
import type { EnvelopePreset, ObjectMetaValue } from '../types/envelope';
import type { RoomFormValue } from '../types/rooms';
import { migrateObjectMetaExternalWalls } from '../utils/migrateLegacyExternalWalls';
import {
  normalizeApartmentStackPosition,
  recommendedApartmentEnvelopePresets,
  resolveApartmentRoomBoundaries,
  defaultHouseBottomBoundary,
} from '../utils/apartmentStackBoundaries';
import { createDefaultExternalWall, migrateRoomEnvelopeFields } from '../utils/roomEnvelopeFields';
import { defaultLayoutForRoomType } from '../utils/roomExteriorLayout';
import { createDefaultWindowFormValue } from '../utils/roomWindowDefaults';

/**
 * Синхронизация списка комнат и objectMeta со справочником пресетов и roomsCount / этажностью.
 * Наружные стены (несущий слой + утеплитель) — только в objectMeta.externalWalls.
 */
export function useRoomsOrchestration(params: {
  objectMeta: ObjectMetaValue;
  setObjectMeta: Dispatch<SetStateAction<ObjectMetaValue>>;
  setRooms: Dispatch<SetStateAction<RoomFormValue[]>>;
  wallPresets: EnvelopePreset[];
  floorPresets: EnvelopePreset[];
  ceilingPresets: EnvelopePreset[];
  roofPresets: EnvelopePreset[];
  windowPresets: EnvelopePreset[];
}) {
  const {
    objectMeta,
    setObjectMeta,
    setRooms,
    wallPresets,
    floorPresets,
    ceilingPresets,
    roofPresets,
    windowPresets,
  } = params;

  const roomEnvelopeMigratedRef = useRef(false);

  /** Миграция legacy-полей комнат — один раз после монтирования. */
  useEffect(() => {
    if (roomEnvelopeMigratedRef.current) return;
    roomEnvelopeMigratedRef.current = true;
    setRooms((prev) => {
      const next = migrateRoomEnvelopeFields(prev);
      return next === prev ? prev : next;
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps -- не привязываем к setRooms: иначе цикл dispatch
  }, []);

  /** Миграция wall_pps_* и ошибочного insul_* в presetId стены. */
  useEffect(() => {
    setObjectMeta((prev) => {
      const nextEw = migrateObjectMetaExternalWalls(prev.externalWalls);
      if (nextEw === prev.externalWalls) return prev;
      return { ...prev, externalWalls: nextEw };
    });
  }, [setObjectMeta]);

  /** Актуальные дефолты для новых комнат (ref, чтобы эффект роста списка не зависел от массивов пресетов). */
  const newRoomTemplateRef = useRef({
    floor: '',
    ceiling: '',
    roof: '',
    windowFirst: DEFAULT_WINDOW_PRESET_ID,
  });

  useEffect(() => {
    newRoomTemplateRef.current = {
      floor: floorPresets[0]?.id ?? '',
      ceiling: ceilingPresets[0]?.id ?? '',
      roof: roofPresets[0]?.id ?? '',
      windowFirst: windowPresets[0]?.id ?? DEFAULT_WINDOW_PRESET_ID,
    };
  }, [floorPresets, ceilingPresets, roofPresets, windowPresets]);

  /** Если этажность объекта уменьшили, номер этажа комнаты не должен превышать max — иначе селект «Этаж» пустой/битый. */
  useEffect(() => {
    const maxF = objectMeta.floors;
    setRooms((prev) => {
      const next = prev.map((r) => (r.floor <= maxF ? r : { ...r, floor: maxF }));
      return next.some((r, i) => r !== prev[i]) ? next : prev;
    });
  }, [objectMeta.floors, setRooms]);

  useEffect(() => {
    // При первой загрузке пресетов выставляем дефолты для комнат (пол, потолок, кровля).
    const floorDefault = floorPresets[0]?.id ?? '';
    const ceilingDefault = ceilingPresets[0]?.id ?? '';
    const roofDefault = roofPresets[0]?.id ?? '';

    if (!floorDefault && !ceilingDefault && !roofDefault) return;
    const hasFloor = (id: string) => floorPresets.some((p) => p.id === id);
    const hasCeiling = (id: string) => ceilingPresets.some((p) => p.id === id);
    const hasRoof = (id: string) => roofPresets.some((p) => p.id === id);

    setObjectMeta((prev) => {
      if (!roofDefault) return prev;
      if (!prev.roofPresetId || !hasRoof(prev.roofPresetId)) {
        return { ...prev, roofPresetId: roofDefault };
      }
      return prev;
    });
    setRooms((prev) => {
      const next = prev.map((r) => {
        const patch: Partial<RoomFormValue> = {};
        if (floorDefault && (!r.floorPresetId || !hasFloor(r.floorPresetId)))
          patch.floorPresetId = floorDefault;
        if (ceilingDefault && (!r.ceilingPresetId || !hasCeiling(r.ceilingPresetId)))
          patch.ceilingPresetId = ceilingDefault;
        if (roofDefault && (!r.roofPresetId || !hasRoof(r.roofPresetId)))
          patch.roofPresetId = roofDefault;
        if (Object.keys(patch).length === 0) return r;
        return { ...r, ...patch };
      });
      return next.some((r, i) => r !== prev[i]) ? next : prev;
    });
  }, [ceilingPresets, floorPresets, roofPresets, setObjectMeta, setRooms]);

  useEffect(() => {
    const targetCount = objectMeta.roomsCount;
    const d = newRoomTemplateRef.current;
    setRooms((prev) => {
      if (prev.length === targetCount) return prev;
      if (prev.length > targetCount) return prev.slice(0, targetCount);

      const next = [...prev];
      for (let i = prev.length + 1; i <= targetCount; i += 1) {
        const defaultWindowPresetId = d.windowFirst;
        next.push({
          id: `r${i}`,
          name: `Комната ${i}`,
          type: 'помещение',
          floor: 1,
          topBoundaryType: 'heated',
          bottomBoundaryType: 'heated',
          areaM2: '',
          heightM: 2.7,
          floorPresetId: d.floor,
          ceilingPresetId: d.ceiling,
          roofPresetId: d.roof,
          externalWall1: createDefaultExternalWall(),
          externalWall2: createDefaultExternalWall(),
          roomExteriorLayout: defaultLayoutForRoomType('помещение'),
          ceilingAreaM2: '',
          roofAreaM2: '',
          windows: defaultWindowPresetId
            ? [createDefaultWindowFormValue(`r${i}`, 1, defaultWindowPresetId)]
            : [],
        });
      }
      return next;
    });
  }, [objectMeta.roomsCount, setRooms]);

  useEffect(() => {
    const firstWallPreset = wallPresets[0];
    if (!objectMeta.externalWalls.presetId && firstWallPreset) {
      setObjectMeta((prev) => ({
        ...prev,
        externalWalls: { ...prev.externalWalls, presetId: firstWallPreset.id },
      }));
    }
  }, [objectMeta.externalWalls.presetId, setObjectMeta, wallPresets]);

  const lastWallPresetIdRef = useRef<string | null>(null);

  useEffect(() => {
    const presetId = objectMeta.externalWalls.presetId;
    if (!presetId) return;
    const preset = wallPresets.find((p) => p.id === presetId) ?? null;
    const options = preset?.thicknessOptionsMm ?? null;
    const current = objectMeta.externalWalls.thicknessMm;

    const presetChanged = lastWallPresetIdRef.current !== presetId;
    lastWallPresetIdRef.current = presetId;

    if (!presetChanged && current != null) return;

    let next: number | undefined;
    if (options && options.length > 0) {
      next = options[0];
    } else if (preset?.material) {
      const m = preset.material.match(/(\d{2,4})\s*мм/i);
      if (m?.[1]) next = Number(m[1]);
    }

    if (next == null) return;
    if (next === current) return;

    setObjectMeta((prev) => ({
      ...prev,
      externalWalls: { ...prev.externalWalls, thicknessMm: next },
    }));
  }, [
    objectMeta.externalWalls.presetId,
    objectMeta.externalWalls.thicknessMm,
    setObjectMeta,
    wallPresets,
  ]);

  /** Квартира в МКД: границы и пресеты пола/потолка по положению в стояке. */
  useEffect(() => {
    if (objectMeta.objectType !== 'apartment') return;
    const stack = normalizeApartmentStackPosition(objectMeta.apartmentStackPosition);
    const maxF = objectMeta.floors;
    const hasFloor = (id: string) => floorPresets.some((p) => p.id === id);
    const hasCeiling = (id: string) => ceilingPresets.some((p) => p.id === id);

    setRooms((prev) => {
      const next = prev.map((r) => {
        const bounds = resolveApartmentRoomBoundaries(stack, r.floor, maxF);
        const presets = recommendedApartmentEnvelopePresets(
          bounds.bottomBoundary,
          bounds.topBoundary,
        );
        const floorPresetId = hasFloor(presets.floorPresetId)
          ? presets.floorPresetId
          : r.floorPresetId;
        const ceilingPresetId = hasCeiling(presets.ceilingPresetId)
          ? presets.ceilingPresetId
          : r.ceilingPresetId;
        const topBoundaryType =
          r.topBoundaryType === 'roof' ? r.topBoundaryType : bounds.topBoundary;
        if (
          r.bottomBoundaryType === bounds.bottomBoundary
          && topBoundaryType === bounds.topBoundary
          && r.floorPresetId === floorPresetId
          && r.ceilingPresetId === ceilingPresetId
        ) {
          return r;
        }
        return {
          ...r,
          bottomBoundaryType: bounds.bottomBoundary,
          topBoundaryType,
          floorPresetId,
          ceilingPresetId,
        };
      });
      return next.some((r, i) => r !== prev[i]) ? next : prev;
    });
  }, [
    objectMeta.objectType,
    objectMeta.apartmentStackPosition,
    objectMeta.floors,
    floorPresets,
    ceilingPresets,
    setRooms,
  ]);

  /** Дом: нижняя граница по этажу комнаты, если не задана. */
  useEffect(() => {
    if (objectMeta.objectType === 'apartment') return;
    setRooms((prev) => {
      const next = prev.map((r) => {
        const bb = defaultHouseBottomBoundary(r.floor);
        if (r.bottomBoundaryType === bb) return r;
        return { ...r, bottomBoundaryType: bb };
      });
      return next.some((r, i) => r !== prev[i]) ? next : prev;
    });
  }, [objectMeta.objectType, setRooms]);
}

/**
 * Назначение: Bootstrap приложения — resolving / start / survey.
 */

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';

import {
  clearSurveyDraftStorage,
  loadSurveyDraftFromStorage,
} from '../services/surveyDraftStorage';
import {
  clearSurveyHashFromUrl,
  resolveAppBootstrap,
} from '../surveySession/resolveAppBootstrap';
import { surveyDraftToSessionSnapshot } from '../surveySession/surveyDraftBridge';
import type { AppBootstrapMode, SurveyMutation } from '../surveySession/types';
import type { SurveyDraft } from '../types/surveyDraft';

const RESOLVING_TIMEOUT_MS = 3000;

type SurveyBootstrapResolved = Extract<
  ReturnType<typeof resolveAppBootstrap>,
  { mode: 'survey' }
>;

type InitialBootstrapSnapshot = {
  mode: AppBootstrapMode;
  surveyResolved: SurveyBootstrapResolved | null;
};

/**
 * Синхронный cold-open resolve — без фазы resolving/skeleton (LCP/CLS).
 *
 * @returns {InitialBootstrapSnapshot}
 */
function resolveInitialBootstrapSnapshot(): InitialBootstrapSnapshot {
  try {
    const storageDraft = loadSurveyDraftFromStorage();
    const resolved = resolveAppBootstrap(window.location.hash, storageDraft);
    if (resolved.mode === 'survey') {
      return { mode: 'survey', surveyResolved: resolved };
    }
    return { mode: 'start', surveyResolved: null };
  } catch {
    return { mode: 'error', surveyResolved: null };
  }
}

export type UseSurveyBootstrapParams = {
  dispatch: (mutation: SurveyMutation) => void;
  onDraftMetaLoaded: (draft: SurveyDraft) => void;
};

export type UseSurveyBootstrapResult = {
  bootstrapMode: AppBootstrapMode;
  beginSurvey: () => void;
  resetToStart: () => void;
  enterSurveyMode: () => void;
  retryBootstrap: () => void;
};

/**
 * @param params
 * @returns {UseSurveyBootstrapResult}
 */
export function useSurveyBootstrap({
  dispatch,
  onDraftMetaLoaded,
}: UseSurveyBootstrapParams): UseSurveyBootstrapResult {
  const [initialBootstrap] = useState(() => resolveInitialBootstrapSnapshot());
  const [bootstrapMode, setBootstrapMode] = useState<AppBootstrapMode>(initialBootstrap.mode);
  const onDraftMetaLoadedRef = useRef(onDraftMetaLoaded);
  const bootstrapDispatchAppliedRef = useRef(false);

  useEffect(() => {
    onDraftMetaLoadedRef.current = onDraftMetaLoaded;
  }, [onDraftMetaLoaded]);

  useLayoutEffect(() => {
    if (bootstrapDispatchAppliedRef.current) return;
    bootstrapDispatchAppliedRef.current = true;

    if (initialBootstrap.mode === 'survey' && initialBootstrap.surveyResolved) {
      dispatch({
        type: 'DRAFT_LOADED',
        draft: surveyDraftToSessionSnapshot(initialBootstrap.surveyResolved.draft),
        lastCalcReport: initialBootstrap.surveyResolved.draft.lastCalcReport ?? null,
      });
      onDraftMetaLoadedRef.current(initialBootstrap.surveyResolved.draft);
      if (initialBootstrap.surveyResolved.source === 'hash') {
        clearSurveyHashFromUrl();
      }
      return;
    }

    if (initialBootstrap.mode === 'start') {
      dispatch({ type: 'SESSION_RESET' });
    }
  }, [dispatch, initialBootstrap]);

  const resolveOnce = useCallback(() => {
    let finished = false;
    const timeoutId = window.setTimeout(() => {
      if (finished) return;
      finished = true;
      setBootstrapMode('error');
    }, RESOLVING_TIMEOUT_MS);

    /**
     * @param mode — целевой режим приложения
     */
    const finish = (mode: AppBootstrapMode) => {
      setBootstrapMode(mode);
    };

    try {
      const storageDraft = loadSurveyDraftFromStorage();
      const resolved = resolveAppBootstrap(window.location.hash, storageDraft);

      if (resolved.mode === 'survey') {
        dispatch({
          type: 'DRAFT_LOADED',
          draft: surveyDraftToSessionSnapshot(resolved.draft),
          lastCalcReport: resolved.draft.lastCalcReport ?? null,
        });
        onDraftMetaLoadedRef.current(resolved.draft);
        if (resolved.source === 'hash') {
          clearSurveyHashFromUrl();
        }
        finished = true;
        window.clearTimeout(timeoutId);
        finish('survey');
        return;
      }

      dispatch({ type: 'SESSION_RESET' });
      finished = true;
      window.clearTimeout(timeoutId);
      finish('start');
    } catch {
      finished = true;
      window.clearTimeout(timeoutId);
      setBootstrapMode('error');
    }
  }, [dispatch]);

  const beginSurvey = useCallback(() => {
    dispatch({ type: 'SURVEY_STARTED' });
    setBootstrapMode('survey');
  }, [dispatch]);

  const resetToStart = useCallback(() => {
    dispatch({ type: 'SESSION_RESET' });
    clearSurveyDraftStorage();
    setBootstrapMode('start');
  }, [dispatch]);

  const enterSurveyMode = useCallback(() => {
    setBootstrapMode('survey');
  }, []);

  const retryBootstrap = useCallback(() => {
    setBootstrapMode('resolving');
    resolveOnce();
  }, [resolveOnce]);

  return {
    bootstrapMode,
    beginSurvey,
    resetToStart,
    enterSurveyMode,
    retryBootstrap,
  };
}

/**
 * Назначение: Хук управления проектами анкеты.
 * Описание: Клиент — публичная ссылка и PDF; Dev — JSON/сервер/hash.
 */

import { useCallback, useState } from 'react';

import { useProjectBundleTransfer } from './useProjectBundleTransfer';
import { useProjectMutations } from '../query/mutations/useProjectMutations';
import { useProjectCalculationsQuery } from '../query/queries/useProjectCalculationsQuery';
import { useProjectsListQuery } from '../query/queries/useProjectsListQuery';
import {
  publishProjectShare,
  revokeProjectShare,
  downloadProjectPdf,
} from '../services/projectsApi';
import { saveSurveyDraftToStorage } from '../services/surveyDraftStorage';
import type { AppBootstrapMode } from '../surveySession/types';
import type { CalcReportJson } from '../types/calcApi';
import type { SurveyDraft } from '../types/surveyDraft';
import { downloadJsonFile, downloadTextFile } from '../utils/fileDownload';
import { parseCommercialBomFromReport } from '../utils/parsers/parseCommercialBomFromReport';
import { buildPublicShareUrlFromToken } from '../utils/parsers/parseSharePath';
import { buildSurveyDraft } from '../utils/buildSurveyDraft';
import {
  buildSurveyTextSummary,
  copyTextToClipboard,
  encodeSurveyDraftToUrl,
} from '../utils/surveyShare';

export type UseSurveyProjectParams = {
  bootstrapMode: AppBootstrapMode;
  clientName: string;
  setClientName: (value: string) => void;
  projectId: string | null;
  setProjectId: (value: string | null) => void;
  /** Поля анкеты без clientName/projectId (их хранит хук). */
  getDraftParams: () => Omit<
    Parameters<typeof buildSurveyDraft>[0],
    'savedAt' | 'schemaVersion' | 'clientName' | 'projectId'
  >;
  applyDraft: (draft: SurveyDraft) => void;
  enterSurveyMode: () => void;
  resetToStart: () => void;
  needsResetConfirm: () => boolean;
  buildCalcPayload: () => unknown;
  canRunCalc: boolean;
  setCalcReport: (report: CalcReportJson | null) => void;
  runManualCalc: () => void;
};

/**
 * @param params
 */
export function useSurveyProject({
  bootstrapMode,
  clientName,
  setClientName,
  projectId,
  setProjectId,
  getDraftParams,
  applyDraft,
  enterSurveyMode,
  resetToStart,
  needsResetConfirm,
  buildCalcPayload,
  canRunCalc,
  setCalcReport,
  runManualCalc,
}: UseSurveyProjectParams) {
  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const [statusError, setStatusError] = useState<string | null>(null);
  const [projectsOpen, setProjectsOpen] = useState(false);
  const [publicPath, setPublicPath] = useState<string | null>(null);
  const [shareBusy, setShareBusy] = useState(false);
  const [shareToastOpen, setShareToastOpen] = useState(false);

  const {
    saveProjectMutation,
    loadProjectMutation,
    loadCalculationMutation,
  } = useProjectMutations();

  const saveProjectBusy = saveProjectMutation.isPending;

  const {
    projectList,
    projectsLoading,
    refetch: refetchProjects,
  } = useProjectsListQuery({ enabled: projectsOpen });

  const { calculations, refetch: refetchCalculations } = useProjectCalculationsQuery({
    projectId,
    enabled: projectsOpen && projectId != null,
  });

  const buildDraft = useCallback((): SurveyDraft => {
    const p = getDraftParams();
    return buildSurveyDraft({
      ...p,
      clientName,
      projectId,
    });
  }, [getDraftParams, clientName, projectId]);

  const showOk = useCallback((msg: string) => {
    setStatusError(null);
    setStatusMessage(msg);
    window.setTimeout(() => {
      setStatusMessage(null);
    }, 4000);
  }, []);

  const showErr = useCallback((msg: string) => {
    setStatusMessage(null);
    setStatusError(msg);
  }, []);

  const applyDraftAndMeta = useCallback(
    (draft: SurveyDraft) => {
      applyDraft(draft);
      setClientName(draft.clientName);
      setProjectId(draft.projectId ?? null);
      saveSurveyDraftToStorage(draft);
      enterSurveyMode();
    },
    [applyDraft, enterSurveyMode, setClientName, setProjectId],
  );

  const {
    fileInputRef,
    handleFileInputChange,
    requestImport: openImportFilePicker,
    requestOpenLocal: openFilePicker,
    sendProjectBundle,
    importBusy,
    exportBusy,
  } = useProjectBundleTransfer({
    confirmBeforeImport: () => {
      if (!needsResetConfirm()) return true;
      return window.confirm(
        'Поточна анкета буде замінена імпортованим проєктом. Продовжити?',
      );
    },
    onImportSuccess: (result) => {
      applyDraft(result.draft);
      setClientName(result.draft.clientName);
      setProjectId(result.project.id);
      saveSurveyDraftToStorage(result.draft);
      enterSurveyMode();
      if (result.latestReport) {
        setCalcReport(result.latestReport);
      }
      setPublicPath(null);
      setShareToastOpen(false);
    },
    onOpenLocalSuccess: (draft) => {
      applyDraftAndMeta(draft);
    },
    onStatus: (message, error) => {
      if (error) showErr(error);
      else if (message) showOk(message);
    },
  });

  const saveToFile = useCallback(() => {
    if (bootstrapMode !== 'survey') return;
    try {
      const draft = buildDraft();
      const safe = draft.clientName
        .replace(/[^\p{L}\p{N}\-_]+/gu, '_')
        .slice(0, 40);
      const date = draft.savedAt.slice(0, 10);
      downloadJsonFile(`heatcalc-${safe}-${date}.json`, draft);
      showOk('Файл JSON збережено (Dev)');
    } catch (e) {
      showErr(e instanceof Error ? e.message : 'Не вдалося зберегти файл');
    }
  }, [bootstrapMode, buildDraft, showOk, showErr]);

  const exportProjectBundleToFile = useCallback(async () => {
    if (bootstrapMode !== 'survey') return;

    const localDraft = buildDraft();
    let localLastCalcInput: unknown;
    if (canRunCalc) {
      try {
        localLastCalcInput = buildCalcPayload();
      } catch {
        /* calcInput опционален для экспорта */
      }
    }

    await sendProjectBundle({
      projectId,
      clientName: localDraft.clientName,
      localDraft,
      localLastCalcInput,
    });
  }, [
    bootstrapMode,
    buildDraft,
    buildCalcPayload,
    canRunCalc,
    projectId,
    sendProjectBundle,
  ]);

  const saveToServer = useCallback(
    async (withCalc: boolean) => {
      if (bootstrapMode !== 'survey') return;
      try {
        const draft = buildDraft();
        const result = await saveProjectMutation.mutateAsync({
          projectId,
          clientName,
          draft,
          withCalc,
          canRunCalc,
          buildCalcPayload,
        });
        setProjectId(result.projectId);
        if (result.report) {
          setCalcReport(result.report);
        }
        if (withCalc && result.report) {
          showOk('Проєкт і розрахунок збережено на сервері');
        } else if (withCalc && !canRunCalc) {
          showOk('Проєкт збережено (розрахунок пропущено — неповна анкета)');
        } else {
          showOk('Проєкт збережено на сервері');
        }
      } catch (e) {
        const msg = e instanceof Error ? e.message : 'Помилка збереження';
        if (msg.includes('MONGODB_UNAVAILABLE') || msg.includes('503')) {
          showErr('MongoDB недоступна — збережіть JSON-файл (Dev)');
        } else {
          showErr(msg);
        }
      }
    },
    [
      bootstrapMode,
      buildDraft,
      buildCalcPayload,
      canRunCalc,
      clientName,
      projectId,
      saveProjectMutation,
      setCalcReport,
      setProjectId,
      showOk,
      showErr,
    ],
  );

  const exportTextFile = useCallback(() => {
    if (bootstrapMode !== 'survey') return;
    try {
      const draft = buildDraft();
      const report = getDraftParams().lastCalcReport ?? null;
      const text = buildSurveyTextSummary(draft, report);
      const safe = draft.clientName
        .replace(/[^\p{L}\p{N}\-_]+/gu, '_')
        .slice(0, 40);
      downloadTextFile(`heatcalc-${safe}-summary.txt`, text);
      showOk('Текстову зведенку завантажено (Dev)');
    } catch (e) {
      showErr(e instanceof Error ? e.message : 'Помилка експорту');
    }
  }, [bootstrapMode, buildDraft, getDraftParams, showOk, showErr]);

  const exportHashLink = useCallback(async () => {
    if (bootstrapMode !== 'survey') return;
    try {
      const draft = buildDraft();
      const url = encodeSurveyDraftToUrl(draft);
      await copyTextToClipboard(url);
      showOk('Hash-посилання чернетки скопійовано (Dev, без звіту)');
    } catch (e) {
      showErr(e instanceof Error ? e.message : 'Не вдалося створити посилання');
    }
  }, [bootstrapMode, buildDraft, showOk, showErr]);

  const ensureProjectSaved = useCallback(async (): Promise<string> => {
    const draft = buildDraft();
    const result = await saveProjectMutation.mutateAsync({
      projectId,
      clientName,
      draft,
      withCalc: canRunCalc,
      canRunCalc,
      buildCalcPayload,
    });
    setProjectId(result.projectId);
    if (result.report) {
      setCalcReport(result.report);
    }
    if (canRunCalc && !result.report) {
      throw new Error('Не вдалося зберегти розрахунок на сервер');
    }
    return result.projectId;
  }, [
    buildDraft,
    buildCalcPayload,
    canRunCalc,
    clientName,
    projectId,
    saveProjectMutation,
    setCalcReport,
    setProjectId,
  ]);

  const dismissShareToast = useCallback(() => {
    setShareToastOpen(false);
  }, []);

  const copyPublicLink = useCallback(async () => {
    if (bootstrapMode !== 'survey') return;
    setShareBusy(true);
    setShareToastOpen(false);
    try {
      if (!clientName.trim()) {
        throw new Error('Вкажіть ім\'я клієнта перед публікацією посилання');
      }
      const report = getDraftParams().lastCalcReport;
      if (!report || !parseCommercialBomFromReport(report)) {
        throw new Error('Немає фінансового підсумку — дочекайтеся розрахунку');
      }

      const id = await ensureProjectSaved();
      const published = await publishProjectShare(id);
      setPublicPath(published.publicPath);
      const shareUrl = buildPublicShareUrlFromToken(published.shareToken);
      await copyTextToClipboard(shareUrl);
      setShareToastOpen(true);
    } catch (e) {
      const msg = e instanceof Error ? e.message : 'Не вдалося опублікувати посилання';
      if (msg.includes('MONGODB_UNAVAILABLE') || msg.includes('503')) {
        showErr('MongoDB недоступна — публікація посилання неможлива');
      } else if (msg.includes('Буфер обміну')) {
        showErr('Буфер обміну недоступний — скопіюйте посилання вручну з Dev');
      } else {
        showErr(msg);
      }
    } finally {
      setShareBusy(false);
    }
  }, [
    bootstrapMode,
    clientName,
    ensureProjectSaved,
    getDraftParams,
    showErr,
  ]);

  const revokeShare = useCallback(async () => {
    if (!projectId) {
      showErr('Немає projectId');
      return;
    }
    try {
      await revokeProjectShare(projectId);
      setPublicPath(null);
      showOk('Публічне посилання відкликано (Dev)');
    } catch (e) {
      showErr(e instanceof Error ? e.message : 'Не вдалося відкликати посилання');
    }
  }, [projectId, showOk, showErr]);

  const printPdf = useCallback(
    (includeTechnical: boolean) => {
      if (bootstrapMode !== 'survey') return;
      void (async () => {
        try {
          const report = getDraftParams().lastCalcReport;
          if (!report || !parseCommercialBomFromReport(report)) {
            throw new Error('Немає фінансового підсумку — дочекайтеся розрахунку');
          }
          if (!canRunCalc) {
            throw new Error('Анкета неповна — розрахунок на сервер не зберегти');
          }
          const id = await ensureProjectSaved();
          await downloadProjectPdf(id, { includeTechnical });
          showOk('PDF завантажено');
        } catch (e) {
          showErr(e instanceof Error ? e.message : 'Не вдалося завантажити PDF');
        }
      })();
    },
    [
      bootstrapMode,
      canRunCalc,
      ensureProjectSaved,
      getDraftParams,
      showOk,
      showErr,
    ],
  );

  const refreshProjectList = useCallback(async () => {
    try {
      await refetchProjects();
    } catch (e) {
      showErr(e instanceof Error ? e.message : 'Не вдалося завантажити проєкти');
    }
  }, [refetchProjects, showErr]);

  const openProjectsPanel = useCallback(() => {
    setProjectsOpen(true);
    void refreshProjectList();
  }, [refreshProjectList]);

  const loadProjectById = useCallback(
    async (id: string) => {
      try {
        const result = await loadProjectMutation.mutateAsync({ projectId: id });
        if (result.draft) {
          applyDraftAndMeta(result.draft);
        } else {
          setClientName(result.clientName);
          setProjectId(result.projectId);
          enterSurveyMode();
        }
        if (result.report) {
          setCalcReport(result.report);
        }
        setPublicPath(null);
        setShareToastOpen(false);
        setProjectsOpen(false);
        showOk(`Завантажено проєкт: ${result.clientName}`);
        void refetchCalculations();
      } catch (e) {
        showErr(e instanceof Error ? e.message : 'Не вдалося відкрити проєкт');
      }
    },
    [
      applyDraftAndMeta,
      enterSurveyMode,
      loadProjectMutation,
      refetchCalculations,
      setCalcReport,
      setClientName,
      setProjectId,
      showOk,
      showErr,
    ],
  );

  const loadCalculationById = useCallback(
    async (calcId: string) => {
      if (!projectId) return;
      try {
        const report = await loadCalculationMutation.mutateAsync({
          projectId,
          calculationId: calcId,
        });
        setCalcReport(report);
        showOk('Завантажено збережений розрахунок');
      } catch (e) {
        showErr(e instanceof Error ? e.message : 'Не вдалося завантажити розрахунок');
      }
    },
    [projectId, loadCalculationMutation, setCalcReport, showOk, showErr],
  );

  const exitToStart = useCallback(() => {
    resetToStart();
    setStatusMessage(null);
    setStatusError(null);
    setClientName('');
    setProjectId(null);
    setPublicPath(null);
    setShareToastOpen(false);
    setProjectsOpen(false);
  }, [resetToStart, setClientName, setProjectId]);

  /** Выход на Start Screen: без confirm, если проект уже на сервере. */
  const exitProject = useCallback(() => {
    if (!projectId && needsResetConfirm()) {
      const ok = window.confirm(
        'Вийти з проєкту? Незбережені дані поточної анкети будуть скинуті.',
      );
      if (!ok) return;
    }
    exitToStart();
  }, [exitToStart, needsResetConfirm, projectId]);

  const startNewProject = useCallback(() => {
    if (needsResetConfirm()) {
      const ok = window.confirm(
        'Почати новий проєкт? Незбережені дані поточної анкети будуть скинуті.',
      );
      if (!ok) return;
    }
    exitToStart();
  }, [needsResetConfirm, exitToStart]);

  const report = getDraftParams().lastCalcReport ?? null;
  const hasFinancialReport = parseCommercialBomFromReport(report) != null;
  const canPrintPdf = hasFinancialReport && canRunCalc;
  const canPublishShare = Boolean(clientName.trim()) && canPrintPdf;
  const canSaveProject = Boolean(clientName.trim());

  const saveProjectDraft = useCallback(() => {
    void saveToServer(canRunCalc);
  }, [saveToServer, canRunCalc]);

  return {
    statusMessage,
    statusError,
    fileInputRef,
    handleFileInputChange,
    projectsOpen,
    setProjectsOpen,
    projectsLoading,
    projectList,
    calculations,
    publicPath,
    shareBusy,
    shareToastOpen,
    dismissShareToast,
    canPrintPdf,
    canPublishShare,
    canSaveProject,
    saveProjectBusy,
    exportBusy,
    importBusy,
    saveToFile,
    exportProjectBundleToFile,
    saveToServer,
    saveProjectDraft,
    openFilePicker,
    openImportFilePicker,
    exportTextFile,
    exportHashLink,
    copyPublicLink,
    revokeShare,
    printPdf,
    exitProject,
    openProjectsPanel,
    loadProjectById,
    loadCalculationById,
    startNewProject,
    refreshProjectList,
    buildDraft,
    runManualCalc,
  };
}

/**
 * Назначение: standalone admin dashboard обращений пользователей.
 */

import { useState } from 'react';
import { Link } from 'react-router';

import { AccountBar } from '../../components/AccountBar/AccountBar';
import { Footer } from '../../components/Footer/Footer';
import { useAdminFeedbackStream } from '../../hooks/useAdminFeedbackStream';
import { adminFeedbackUk as t } from '../../i18n/uk/adminFeedback';
import { useAdminFeedbackStatusMutation } from '../../query/mutations/useAdminFeedbackStatusMutation';
import { useAdminFeedbackQuery } from '../../query/queries/useAdminFeedbackQuery';
import { paths } from '../../routing/paths';
import {
  isAdminFeedbackStatus,
  isAdminFeedbackType,
} from '../../services/parseAdminFeedback';
import type {
  AdminFeedbackItem,
  AdminFeedbackStatus,
  AdminFeedbackType,
} from '../../types/adminFeedback';
import type { AdminFeedbackStreamState } from '../../hooks/useAdminFeedbackStream';
import styles from './AdminFeedbackPage.module.css';

const STATUS_LABELS: Record<AdminFeedbackStatus, string> = {
  new: t.statusNew,
  read: t.statusRead,
  resolved: t.statusResolved,
};

const TYPE_LABELS: Record<AdminFeedbackType, string> = {
  bug: t.typeBug,
  contact: t.typeContact,
};

const STREAM_LABELS: Record<AdminFeedbackStreamState, string> = {
  connecting: t.liveConnecting,
  connected: t.liveConnected,
  reconnecting: t.liveReconnecting,
  unavailable: t.liveUnavailable,
};

/**
 * @param value
 */
function formatDate(value: string): string {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toLocaleString('uk-UA');
}

/**
 * Разрешает только безопасные HTTP(S)-ссылки.
 *
 * @param value
 */
function safePageUrl(value: string | undefined): string | null {
  if (!value) return null;
  try {
    const url = new URL(value);
    return url.protocol === 'http:' || url.protocol === 'https:' ? url.href : null;
  } catch {
    return null;
  }
}

/**
 * Карточка одного обращения.
 *
 * @param props
 */
function FeedbackCard({
  item,
  pending,
  onStatusChange,
}: {
  item: AdminFeedbackItem;
  pending: boolean;
  onStatusChange: (status: AdminFeedbackStatus) => void;
}) {
  const pageUrl = safePageUrl(item.pageUrl);

  return (
    <article className={styles.card}>
      <div className={styles.cardHeader}>
        <div className={styles.badges}>
          <span className={`${styles.badge} ${styles[item.type]}`}>{TYPE_LABELS[item.type]}</span>
          <span className={`${styles.badge} ${styles[item.status]}`}>
            {STATUS_LABELS[item.status]}
          </span>
        </div>
        <time dateTime={item.createdAt}>{formatDate(item.createdAt)}</time>
      </div>

      <p className={styles.message}>{item.message}</p>

      <dl className={styles.meta}>
        {item.name ? (
          <>
            <dt>{t.owner}</dt>
            <dd>{item.name}</dd>
          </>
        ) : null}
        {item.email ? (
          <>
            <dt>Email</dt>
            <dd>{item.email}</dd>
          </>
        ) : null}
        {item.ownerSub ? (
          <>
            <dt>{t.ownerSub}</dt>
            <dd className={styles.mono}>{item.ownerSub}</dd>
          </>
        ) : null}
        {item.pageUrl ? (
          <>
            <dt>{t.page}</dt>
            <dd>
              {pageUrl ? (
                <a href={pageUrl} target="_blank" rel="noreferrer">
                  {item.pageUrl}
                </a>
              ) : (
                item.pageUrl
              )}
            </dd>
          </>
        ) : null}
