import {
  queuePendingNewProject,
  queuePendingProjectLoad,
} from '../../utils/pendingProjectNavigation';
import styles from './ProjectsPage.module.css';

/** Действия toolbar / списка — одна dispatch-функция. */
type ProjectsPageAction =
  | { type: 'refresh' }
  | { type: 'newProject' }
  | { type: 'openSurvey' }
  | { type: 'openTransferDialog' }
  | { type: 'closeTransferDialog' }
  | { type: 'openProject'; projectId: string };

/**
 * Список проектов клиентов с переходом в анкету.
 */
export function ProjectsPage() {
  const navigate = useNavigate();
  const { user: meUser } = useMeQuery();
  const isAdmin = meUser?.role === 'admin';
  const showExportInTransfer = isDevToolsBuildEnabled();
  const { projectList, projectsLoading, refetch } = useProjectsListQuery({ enabled: true });
  const [transferOpen, setTransferOpen] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const [statusError, setStatusError] = useState<string | null>(null);

  const notifyStatus = useCallback((message: string | null, error: string | null) => {
    setStatusMessage(message);
    setStatusError(error);
    if (message) {
      window.setTimeout(() => {
        setStatusMessage(null);
      }, 5000);
    }
  }, []);

  const {
    fileInputRef,
    handleFileInputChange,
    requestImport,
    sendProjectBundle,
    importBusy,
    exportBusy,
  } = useProjectBundleTransfer({
    onImportSuccess: async () => {
      await refetch();
      setTransferOpen(false);
    },
    onStatus: notifyStatus,
  });

  const handlePageAction = useCallback(
    (action: ProjectsPageAction) => {
      switch (action.type) {
        case 'refresh':
          void refetch();
          break;
        case 'newProject':
          queuePendingNewProject();
          void navigate(paths.home);
          break;
        case 'openSurvey':
          void navigate(paths.home);
          break;
        case 'openTransferDialog':
          setTransferOpen(true);
          break;
        case 'closeTransferDialog':
          setTransferOpen(false);
          break;
        case 'openProject':
          queuePendingProjectLoad(action.projectId);
          void navigate(paths.home);
          break;
        default: {
          const _exhaustive: never = action;
          void _exhaustive;
        }
      }
    },
    [navigate, refetch],
  );

  const handleImportFromDialog = useCallback(() => {
    requestImport();
  }, [requestImport]);

  const handleExportFromDialog = useCallback(
    (projectId: string, clientName: string) => {
      void sendProjectBundle({ projectId, clientName });
    },
    [sendProjectBundle],
  );

  return (
    <div className={styles.page}>
      <main className={styles.main}>
        <div className={styles.backRow}>
          <Link to={paths.home} className={styles.backLink}>
            ← {projectsUk.backHome}
          </Link>
        </div>
        <h1 className={styles.title}>{projectsUk.title}</h1>
        <AccountBar className={styles.accountBar} />
        {isAdmin ? (
          <p className={styles.adminHint}>{projectsUk.adminAllProjectsHint}</p>
        ) : null}
        {statusMessage ? <p className={styles.statusOk}>{statusMessage}</p> : null}
        {statusError ? <p className={styles.statusErr}>{statusError}</p> : null}
        <div className={styles.toolbar}>
          <button
            type="button"
            className={styles.button}
            onClick={() => {
              handlePageAction({ type: 'refresh' });
            }}
          >
            {projectsUk.refresh}
          </button>
          <button
            type="button"
            className={styles.primary}
            onClick={() => {
              handlePageAction({ type: 'newProject' });
            }}
          >
            {projectsUk.newProject}
          </button>
          <button
            type="button"
            className={styles.button}
            onClick={() => {
              handlePageAction({ type: 'openSurvey' });
            }}
          >
            {projectsUk.openSurvey}
          </button>
          {isAdmin ? (
            <button
              type="button"
              className={styles.button}
              onClick={() => {
                handlePageAction({ type: 'openTransferDialog' });
              }}
            >
              {projectsUk.transferProject}
            </button>
          ) : null}
        </div>

        <input
          ref={fileInputRef}
          type="file"
          accept="application/json,.json"
          className={styles.hiddenFileInput}
          onChange={handleFileInputChange}
        />

        <ProjectTransferDialog
          open={transferOpen}
          loading={projectsLoading}
          projects={projectList}
          showExportSection={showExportInTransfer}
          showOwnerInExportList={isAdmin}
          importBusy={importBusy}
          exportBusy={exportBusy}
          onClose={() => {
            handlePageAction({ type: 'closeTransferDialog' });
          }}
          onImportClick={handleImportFromDialog}
          onExportProject={handleExportFromDialog}
        />

        {projectsLoading ? (
          <p className={styles.muted}>{projectsUk.loading}</p>
        ) : projectList.length === 0 ? (
          <p className={styles.muted}>{projectsUk.empty}</p>
        ) : (
          <ul className={styles.list}>
            {projectList.map((p) => (
              <li key={p.id}>
                <button
                  type="button"
                  className={styles.itemButton}
                  onClick={() => {
                    handlePageAction({ type: 'openProject', projectId: p.id });
                  }}
                >
                  {p.clientName}
                  {isAdmin && p.ownerEmail ? (
                    <span className={styles.itemOwner}>
                      {projectsUk.owner}: {p.ownerEmail}
                    </span>
                  ) : null}
                  <span className={styles.itemMeta}>
                    {p.calculationsCount ?? 0} {projectsUk.calculations} · {projectsUk.updated}{' '}
                    {new Date(p.updatedAt).toLocaleString('uk-UA')}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        )}
      </main>
      <Footer variant="app" />
    </div>
  );
}

/**
 * Назначение: React Query mutations для операций с проектами.
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useCallback } from 'react';

import {
  createProject,
  getProject,
  getProjectCalculation,
  listProjectCalculations,
  postProjectCalc,
  updateProject,
} from '../../services/projectsApi';
import type { CalcReportJson } from '../../types/calcApi';
import type { SurveyDraft } from '../../types/surveyDraft';
import { parseSurveyDraft } from '../../utils/parsers/parseSurveyDraft';
import { queryKeys } from '../queryKeys';

export type SaveProjectParams = {
  projectId: string | null;
  clientName: string;
  draft: SurveyDraft;
  withCalc: boolean;
  canRunCalc: boolean;
  buildCalcPayload: () => unknown;
};

export type SaveProjectResult = {
  projectId: string;
  report: CalcReportJson | null;
};

export type LoadProjectParams = {
  projectId: string;
};

export type LoadProjectResult = {
  draft: SurveyDraft | null;
  clientName: string;
  projectId: string;
  report: CalcReportJson | null;
};

export type LoadCalculationParams = {
  projectId: string;
  calculationId: string;
};

/**
 * @returns mutations и invalidate-хелперы для проектов
 */
export function useProjectMutations() {
  const queryClient = useQueryClient();

  const invalidateProjects = useCallback(async () => {
    await queryClient.invalidateQueries({ queryKey: ['projects'] });
  }, [queryClient]);

  const saveProjectMutation = useMutation({
    mutationFn: async (params: SaveProjectParams): Promise<SaveProjectResult> => {
      const name = params.clientName.trim();
      if (!name) {
        throw new Error('Вкажіть ім\'я клієнта перед збереженням на сервер');
      }

      let id = params.projectId;
      if (!id) {
        const created = await createProject({
          clientName: name,
          survey: params.draft,
        });
        id = created.project.id;
      } else {
        await updateProject(id, { clientName: name, survey: params.draft });
      }

      let report: CalcReportJson | null = null;
      if (params.withCalc && params.canRunCalc && id) {
        const calcRes = await postProjectCalc(id, {
          calcInput: params.buildCalcPayload(),
          survey: params.draft,
        });
        report = calcRes.report;
      }

      return { projectId: id, report };
    },
    onSuccess: async () => {
      await invalidateProjects();
    },
  });

  const loadProjectMutation = useMutation({
    mutationFn: async (params: LoadProjectParams): Promise<LoadProjectResult> => {
      const res = await getProject(params.projectId, { includeLastCalculation: true });
      let draft: SurveyDraft | null = null;
      const surveyRaw = res.project.survey;
      if (surveyRaw && typeof surveyRaw === 'object') {
        draft = parseSurveyDraft(surveyRaw);
        draft.projectId = res.project.id;
        draft.clientName = res.project.clientName;
      }

      let report: CalcReportJson | null = null;
      const calcList = await listProjectCalculations(params.projectId, { limit: 10 });
      const latest = calcList.calculations[0];
      if (latest) {
        try {
          const full = await getProjectCalculation(params.projectId, latest.id);
          report = full.calculation.report;
        } catch {
          /* отчёт опционален */
        }
      }

      return {
        draft,
        clientName: res.project.clientName,
        projectId: res.project.id,
        report,
      };
    },
    onSuccess: async (_data, variables) => {
      await queryClient.invalidateQueries({
        queryKey: queryKeys.projectCalculations(variables.projectId),
      });
    },
  });

  const loadCalculationMutation = useMutation({
    mutationFn: async (params: LoadCalculationParams) => {
      const res = await getProjectCalculation(params.projectId, params.calculationId);
      return res.calculation.report;
    },
  });

  return {
    saveProjectMutation,
    loadProjectMutation,
    loadCalculationMutation,
    invalidateProjects,
  };
}

/**
 * Назначение: оркестрация POST /api/v1/calc через React Query.
 * Описание: автопересчёт (useQuery + debounce) и ручной расчёт (useMutation).
 */

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useCallback, useEffect, useRef, useState } from 'react';

import { postCalc } from '../services/calc';
import type { CalcReportJson } from '../types/calcApi';
import { queryKeys } from './queryKeys';
import { useDebouncedValue } from './useDebouncedValue';

/** Задержка debounce автопересчёта, мс. */
export const SURVEY_CALC_DEBOUNCE_MS = 700;

const CALC_SKIP_DEDUP = '__CALC_SKIP_DEDUP__';

export type UseSurveyCalcParams = {
  buildCalcPayload: () => unknown;
  canAutoCalc: boolean;
  calcInputKey: string;
  onCalcSuccess?: (report: CalcReportJson) => void;
  onCalcError?: (message: string) => void;
  /** Payload совпал с последним успешным — снять uiPhase=recalculating. */
  onCalcSkippedDedup?: () => void;
  draftInitializing?: boolean;
};

/**
 * HTTP-исполнитель расчёта для SurveySession.
 */
export function useSurveyCalc({
  buildCalcPayload,
  canAutoCalc,
  calcInputKey,
  onCalcSuccess,
  onCalcError,
  onCalcSkippedDedup,
  draftInitializing = false,
}: UseSurveyCalcParams) {
  const queryClient = useQueryClient();
  const buildCalcPayloadRef = useRef(buildCalcPayload);
  const onCalcSuccessRef = useRef(onCalcSuccess);
  const onCalcErrorRef = useRef(onCalcError);
  const onCalcSkippedDedupRef = useRef(onCalcSkippedDedup);
  const lastSuccessPayloadKeyRef = useRef<string | null>(null);
  const [freshCalcToken, setFreshCalcToken] = useState(0);

  useEffect(() => {
    buildCalcPayloadRef.current = buildCalcPayload;
    onCalcSuccessRef.current = onCalcSuccess;
    onCalcErrorRef.current = onCalcError;
    onCalcSkippedDedupRef.current = onCalcSkippedDedup;
  }, [buildCalcPayload, onCalcSuccess, onCalcError, onCalcSkippedDedup]);

  const debouncedKey = useDebouncedValue(calcInputKey, SURVEY_CALC_DEBOUNCE_MS);

  const autoEnabled =
    canAutoCalc &&
    !draftInitializing &&
    debouncedKey === calcInputKey &&
    calcInputKey.length > 0;

  const autoQuery = useQuery({
    queryKey: [...queryKeys.calc(debouncedKey), freshCalcToken],
    queryFn: async () => {
      const payload = buildCalcPayloadRef.current();
      const payloadKey = JSON.stringify(payload);
      if (payloadKey === lastSuccessPayloadKeyRef.current) {
        throw new Error(CALC_SKIP_DEDUP);
      }
      const data = await postCalc(payload);
      lastSuccessPayloadKeyRef.current = payloadKey;
      return data.report;
    },
    enabled: autoEnabled,
    staleTime: 0,
    gcTime: 0,
    retry: false,
  });

  useEffect(() => {
    if (!autoQuery.data || autoQuery.isFetching) return;
    onCalcSuccessRef.current?.(autoQuery.data);
  }, [autoQuery.data, autoQuery.dataUpdatedAt, autoQuery.isFetching]);

  useEffect(() => {
    if (!autoQuery.error || autoQuery.isFetching) return;
    if (autoQuery.error instanceof Error && autoQuery.error.message === CALC_SKIP_DEDUP) {
      onCalcSkippedDedupRef.current?.();
      return;
    }
    const message =
      autoQuery.error instanceof Error ? autoQuery.error.message : 'Помилка розрахунку';
    onCalcErrorRef.current?.(message);
  }, [autoQuery.error, autoQuery.errorUpdatedAt, autoQuery.isFetching]);

  const manualMutation = useMutation({
    mutationFn: async () => {
      const payload = buildCalcPayloadRef.current();
      const data = await postCalc(payload);
      lastSuccessPayloadKeyRef.current = JSON.stringify(payload);
      return data.report;
    },
    onSuccess: (report) => {
      onCalcSuccessRef.current?.(report);
    },
    onError: (error: unknown) => {
      const message = error instanceof Error ? error.message : 'Помилка розрахунку';
      onCalcErrorRef.current?.(message);
    },
  });

  const { mutateAsync: mutateCalcManual, reset: resetManualCalc, isPending: manualCalcPending } =
    manualMutation;

  const clearDebounceAndCancel = useCallback(() => {
    void queryClient.cancelQueries({ queryKey: queryKeys.calcRoot });
    resetManualCalc();
  }, [queryClient, resetManualCalc]);

  const abortInFlightCalc = useCallback(() => {
    clearDebounceAndCancel();
  }, [clearDebounceAndCancel]);

  const scheduleFreshCalc = useCallback(() => {
    lastSuccessPayloadKeyRef.current = null;
    setFreshCalcToken((token) => token + 1);
  }, []);

  const runApiCalc = useCallback(async () => {
    clearDebounceAndCancel();
    lastSuccessPayloadKeyRef.current = null;
    await mutateCalcManual();
  }, [clearDebounceAndCancel, mutateCalcManual]);

  useEffect(() => {
    if (!canAutoCalc) {
      abortInFlightCalc();
    }
  }, [canAutoCalc, abortInFlightCalc]);

  const autoError =
    autoQuery.error instanceof Error && autoQuery.error.message !== CALC_SKIP_DEDUP
      ? autoQuery.error.message
      : null;
  const manualError =
    manualMutation.error instanceof Error ? manualMutation.error.message : null;

  return {
    calcLoading: autoQuery.isFetching || manualCalcPending,
    calcError: manualError ?? autoError,
    scheduleFreshCalc,
    runApiCalc,
    abortInFlightCalc,
  };
}

/**
 * Назначение: оболочка SurveyApp с session provider для home и projects.
 */

import { useCallback, useMemo, useState } from 'react';
import { useLocation } from 'react-router';

import { AppErrorBoundary } from '../components/AppErrorBoundary/AppErrorBoundary';
import { AppRoot } from '../AppRoot';
import { usePresetLists } from '../hooks/usePresetLists';
