  const location = useLocation();
  const isHome = location.pathname === paths.home;
  const [calcEnabled, setCalcEnabled] = useState(false);

  const onBootstrapModeChange = useCallback((mode: AppBootstrapMode) => {
    setCalcEnabled(mode === 'survey');
  }, []);

  const {
    envelopePresets,
    presetsLoading,
    presetsError,
    underfloorHeatingBases,
    flooringFinishes,
    underfloorPresetsLoading,
    ufhModePresets,
    ufhModePresetsLoading,
    ufhModePresetsError,
  } = useReferenceData({ enabled: calcEnabled });

  const {
    wallPresets,
    windowPresets,
    floorPresets,
    ceilingPresets,
    roofPresets,
    sftkInsulationPresets,
    ventilatedInsulationPresets,
    insulationPresets,
  } = usePresetLists(envelopePresets);

  const initialSessionState = useMemo(() => createEmptySurveySessionState(), []);

  return (
    <AppErrorBoundary>
      <SurveySessionProvider
        initialState={initialSessionState}
        windowPresets={windowPresets}
        calcEnabled={calcEnabled}
      >
        {children ?? (
          isHome ? (
            <AppRoot
              onBootstrapModeChange={onBootstrapModeChange}
              wallPresets={wallPresets}
              windowPresetsList={windowPresets}
              floorPresets={floorPresets}
              ceilingPresets={ceilingPresets}
              roofPresets={roofPresets}
              sftkInsulationPresets={sftkInsulationPresets}
              ventilatedInsulationPresets={ventilatedInsulationPresets}
              insulationPresets={insulationPresets}
              presetsLoading={presetsLoading}
              presetsError={presetsError}
              underfloorHeatingBases={underfloorHeatingBases}
              flooringFinishes={flooringFinishes}
              underfloorPresetsLoading={underfloorPresetsLoading}
              ufhModePresets={ufhModePresets}
              ufhModePresetsLoading={ufhModePresetsLoading}
              ufhModePresetsError={ufhModePresetsError}
            />
          ) : null
        )}
      </SurveySessionProvider>
    </AppErrorBoundary>
  );
}

/**
 * Назначение: fetch-подписка на SSE admin feedback с Bearer-заголовком.
 */

import type { AdminFeedbackItem } from '../types/adminFeedback';
import { apiUrl } from '../utils/apiUrl';
import { getProjectsAuthHeaders } from './projectsAuthHeaders';
import { AdminFeedbackApiError } from './adminFeedbackApi';
import { parseAdminFeedbackItem } from './parseAdminFeedback';

export type AdminFeedbackStreamOptions = {
  signal: AbortSignal;
  onOpen: () => void;
  onCreated: (item: AdminFeedbackItem) => void;
};

/**
 * Разбирает завершённый SSE-блок. Комментарии heartbeat и неизвестные события игнорируются.
 *
 * @param block
 * @param onCreated
 */
function processSseBlock(block: string, onCreated: (item: AdminFeedbackItem) => void): void {
  let eventName = '';
  const dataLines: string[] = [];

  for (const line of block.split('\n')) {
    if (!line || line.startsWith(':')) continue;
    const separator = line.indexOf(':');
    const field = separator < 0 ? line : line.slice(0, separator);
    const rawValue = separator < 0 ? '' : line.slice(separator + 1);
    const value = rawValue.startsWith(' ') ? rawValue.slice(1) : rawValue;
    if (field === 'event') eventName = value;
    if (field === 'data') dataLines.push(value);
  }

  if (eventName !== 'feedback.created' || dataLines.length === 0) return;
  const data: unknown = JSON.parse(dataLines.join('\n'));
  onCreated(parseAdminFeedbackItem(data));
}

/**
 * Открывает одну SSE-сессию и завершается при disconnect или abort.
 *
 * @param options
 */
export async function streamAdminFeedback(options: AdminFeedbackStreamOptions): Promise<void> {
  const response = await fetch(apiUrl('/api/v1/admin/feedback/stream'), {
    headers: {
      Accept: 'text/event-stream',
      'Cache-Control': 'no-cache',
      ...(await getProjectsAuthHeaders()),
    },
    signal: options.signal,
  });

  if (!response.ok) {
    throw new AdminFeedbackApiError(
      response.status,
      `Не вдалося підключити live-оновлення: HTTP ${response.status}`,
    );
  }
  if (!response.body) {
    throw new Error('Браузер не надав потік live-оновлень');
  }

  options.onOpen();
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';

  while (!options.signal.aborted) {
    const chunk = await reader.read();
    if (chunk.done) break;
    buffer += decoder.decode(chunk.value, { stream: true });
    buffer = buffer.replaceAll('\r\n', '\n');

    let boundary = buffer.indexOf('\n\n');
    while (boundary >= 0) {
      const block = buffer.slice(0, boundary);
      buffer = buffer.slice(boundary + 2);
      processSseBlock(block, options.onCreated);
      boundary = buffer.indexOf('\n\n');
    }
  }

  options.signal.throwIfAborted();
}

/**
 * Назначение: Сборка тела запроса расчёта.
 * Описание: Преобразование состояния анкеты в JSON по контракту CalcInput для API.
 */

import { DEFAULT_WINDOW_PRESET_ID } from '../data/fallbackEnvelopePresets';
import type { EnvelopePreset, ObjectMetaValue } from '../types/envelope';
import type { UfhModePresetId } from '../types/ufhModePreset';
import type { HeatingThermalRegimePreset } from '../types/heatingThermalRegime';
import {
  DEFAULT_RADIATOR_CONNECTION,
  type RadiatorConnection,
} from '../types/radiatorConnection';
import {
  DEFAULT_RADIATOR_EMITTER_PREFERENCE,
  type RadiatorEmitterPreference,
} from '../types/radiatorEmitterPreference';
import type { UfhDistributionPreset } from '../types/ufhDistribution';
import type { HotWaterFormValue } from '../types/hotWater';
import type { WaterHeaterFormValue } from '../types/waterHeater';
import type { RoomFormValue } from '../types/rooms';
import type { HydraulicsFormValue } from '../types/hydraulics';
import type { WiringLayoutV3 } from '../surveySession/wiringLayoutV3';
import { objectMetaForCalcPayload } from '../utils/objectMetaForCalcPayload';
import { normalizeHotWaterForm } from '../utils/normalizeHotWaterForm';
import { inferRoomExteriorLayout, wallEnvelopeEntriesForRoom } from '../utils/roomExteriorLayout';

/**
 * Сборка тела POST /api/v1/calc из состояния анкеты (логика перенесена из App без изменений).
 */
export function buildCalcRequestPayload(params: {
  rooms: RoomFormValue[];
  temps: { insideC: number; outsideC: number; bathroomAirTempC?: number };
  objectMeta: ObjectMetaValue;
  hotWaterForm: HotWaterFormValue;
  waterHeaterForm: WaterHeaterFormValue;
  windowPresets: EnvelopePreset[];
  waterUnderfloorHeating?: boolean;
  underfloorDistributionPreset?: UfhDistributionPreset;
  thermalRegimePreset: HeatingThermalRegimePreset;
  radiatorConnection?: RadiatorConnection;
  radiatorEmitterPreference?: RadiatorEmitterPreference;
  ufhPresetId?: UfhModePresetId | null;
  hydraulicsForm?: HydraulicsFormValue;
  wiringLayoutV3?: WiringLayoutV3;
}) {
  const {
    rooms,
    temps,
    objectMeta,
    hotWaterForm: hotWaterFormRaw,
    waterHeaterForm,
    windowPresets,
    waterUnderfloorHeating = false,
    underfloorDistributionPreset = 'auto',
    thermalRegimePreset,
    radiatorConnection = DEFAULT_RADIATOR_CONNECTION,
    radiatorEmitterPreference = DEFAULT_RADIATOR_EMITTER_PREFERENCE,
    ufhPresetId = null,
    hydraulicsForm,
    wiringLayoutV3,
  } = params;

  const hotWaterForm = normalizeHotWaterForm(hotWaterFormRaw);

  const buildingRooms = rooms.map((r) => {
    const room: Record<string, unknown> = {
      id: r.id,
      name: r.name,
      type: r.type,
      floor: r.floor,
      topBoundary: r.topBoundaryType,
      bottomBoundary: r.bottomBoundaryType,
      areaM2: Number(r.areaM2),
      heightM: Number(r.heightM),
      roomExteriorLayout: inferRoomExteriorLayout(r),
    };
    if (waterUnderfloorHeating && r.underfloorHeating?.enabled) {
      const basePresetId = r.underfloorHeating.basePresetId.trim();
      const finishMaterialId = r.underfloorHeating.finishMaterialId.trim();
      if (basePresetId && finishMaterialId) {
        const spacing = r.underfloorHeating.pipeSpacingMm;
        const pipeSpacingMm =
          spacing === 100 || spacing === 150 || spacing === 200 ? spacing : 150;
        const furnitureRaw = r.underfloorHeating.furnitureOccupiedAreaM2;
        const furnitureOccupiedAreaM2 =
          typeof furnitureRaw === 'number' && furnitureRaw > 0 ? furnitureRaw : undefined;
        const terminal = r.underfloorHeating.ufhTerminalControl;
        const ufhTerminalControl =
          terminal === 'unibox' && Number(r.areaM2) > 0 && Number(r.areaM2) <= 20
            ? ('unibox' as const)
            : undefined;
        room.underfloorHeating = {
          enabled: true,
          basePresetId,
          finishMaterialId,
          pipeSpacingMm,
          ...(furnitureOccupiedAreaM2 != null ? { furnitureOccupiedAreaM2 } : {}),
          ...(ufhTerminalControl ? { ufhTerminalControl } : {}),
        };
      }
    }
    return room;
  });

  const envelopeElements = rooms.flatMap((r) => {
    const els: Array<Record<string, unknown>> = [];

    const externalWalls = wallEnvelopeEntriesForRoom(r);
    for (const { wall, label, construction } of externalWalls) {
      const area = typeof wall.areaM2 === 'number' ? wall.areaM2 : 0;
      if (area <= 0) continue;
      els.push({
        kind: 'wall',
        roomId: r.id,
        name: label,
        construction,
        presetId: objectMeta.externalWalls.presetId,
        areaM2: area,
        orientation: wall.orientation,
      });
    }

    const floorArea = typeof r.areaM2 === 'number' ? r.areaM2 : 0;
    if (floorArea > 0 && r.floorPresetId) {
      els.push({
        kind: 'floor',
        roomId: r.id,
        construction: 'пол',
        presetId: r.floorPresetId,
        areaM2: floorArea,
        name: 'Пол',
      });
    }

    if (r.topBoundaryType === 'roof') {
      const roofArea = typeof r.roofAreaM2 === 'number' ? r.roofAreaM2 : 0;
      if (roofArea > 0) {
        els.push({
          kind: 'roof',
          roomId: r.id,
          construction: 'кровля',
          presetId: r.roofPresetId || objectMeta.roofPresetId,
          areaM2: roofArea,
          name: 'Скаты кровли',
        });
      }
    } else if (r.topBoundaryType === 'unheated') {
      const ceilingArea = typeof r.ceilingAreaM2 === 'number' ? r.ceilingAreaM2 : 0;
      if (ceilingArea > 0) {
        els.push({
          kind: 'ceiling',
          roomId: r.id,
          construction: 'потолок',
          presetId: r.ceilingPresetId,
          areaM2: ceilingArea,
          name: 'Потолок',
        });
      }
    }

    for (const w of r.windows) {
      const wMm = typeof w.openingWidthMm === 'number' ? w.openingWidthMm : null;
      const hMm = typeof w.openingHeightMm === 'number' ? w.openingHeightMm : null;
      if (!wMm || !hMm) continue;
      const areaM2 = (wMm * hMm) / 1_000_000;
      const count = typeof w.count === 'number' && w.count > 0 ? w.count : 1;
      const winPresetOk =
        typeof w.presetId === 'string' &&
        w.presetId.trim() !== '' &&
        windowPresets.some((p) => p.id === w.presetId);
      const presetIdResolved = winPresetOk
        ? w.presetId
        : (windowPresets[0]?.id ?? DEFAULT_WINDOW_PRESET_ID);
      els.push({
        kind: 'window',
        roomId: r.id,
        construction: 'окно',
        presetId: presetIdResolved,
        areaM2,
        count,
        orientation: w.orientation,
        openingWidthMm: wMm,
        openingHeightMm: hMm,
        name: `Окно ${w.id}`,
      });
    }
    return els;
  });

  const objectMetaResolved = objectMetaForCalcPayload(objectMeta, waterHeaterForm);

  const buildingTemps: {
    insideC: number;
    outsideC: number;
    bathroomAirTempC?: number;
  } = {
    insideC: temps.insideC,
    outsideC: temps.outsideC,
  };
  if (
    typeof temps.bathroomAirTempC === 'number' &&
    Number.isFinite(temps.bathroomAirTempC) &&
    temps.bathroomAirTempC >= 24
  ) {
    buildingTemps.bathroomAirTempC = temps.bathroomAirTempC;
  }

  return {
    building: {
      temps: buildingTemps,
      objectMeta: objectMetaResolved,
      rooms: buildingRooms,
      envelopeElements,
    },
    heatingSystem: {
      hotWaterBoilerPowerMatchingScheme:
        waterHeaterForm.hotWaterBoilerPowerMatchingScheme,
      thermalRegimePreset,
      radiatorConnection,
      radiatorEmitterPreference,
      ...(ufhPresetId || waterUnderfloorHeating
        ? {
            waterUnderfloorHeating: true,
            underfloorDistributionPreset,
            ...(ufhPresetId
              ? {
                  ufhPresetId,
                  heatingEmittersMode:
                    ufhPresetId === 'ufh_only'
                      ? ('ufh_only' as const)
                      : ('mixed' as const),
                }
              : waterUnderfloorHeating
                ? { heatingEmittersMode: 'mixed' as const }
                : {}),
          }
        : {}),
    },
    hotWater: {
      residents: hotWaterForm.residents,
      coldWaterDesignSeason: hotWaterForm.coldWaterDesignSeason,
      hotWaterC: hotWaterForm.hotWaterC,
      tropicalShower: hotWaterForm.tropicalShower,
      fixtures: { ...hotWaterForm.fixtures },
    },
    ...(hydraulicsForm
      ? {
          hydraulics: {
            mainLineLengthM: hydraulicsForm.mainLineLengthM,
            deltaTSystemK: hydraulicsForm.deltaTSystemK,
            radiatorWiringSystemType: wiringLayoutV3?.systemType ?? 'auto',
            ...(hydraulicsForm.pipeMaterialPreference
              ? { pipeMaterialPreference: hydraulicsForm.pipeMaterialPreference }
              : {}),
            ...(wiringLayoutV3 != null && wiringLayoutV3.branches.length > 0
              ? {
                  radiatorBranchOverrides: wiringLayoutV3.branches
                    .filter((b) => rooms.some((r) => r.id === b.roomId))
                    .map((b) => ({
                      roomId: b.roomId,
                      pipeLengthToEquipmentM: b.pipeLengthToEquipmentM,
                    })),
                }
              : {}),
          },
        }
      : {}),
  };
}

/**
 * Назначение: HTTP-клиент расчёта.
 * Описание: POST /api/v1/calc с разбором успешного ответа и обработкой сетевых ошибок.
 */

import type { CalcOkPayload } from '../types/calcApi';
import { apiUrl } from '../utils/apiUrl';
import { isRecord } from '../utils/jsonGuards';

/** Типичная подсказка при недоступном backend в dev (см. frontend/vite.config.ts). */
export const CALC_BACKEND_HINT =
  'Запустіть API: `cd backend && npm run start` (або з кореня: `npm run dev:full` — API + UI). У dev Vite проксіює /api на http://localhost:3001; без backend браузер отримує HTTP 502.';

/** Сообщение при сетевой ошибке fetch (бэкенд не слушает порт или прокси оборвал соединение). */
function networkCalcErrorMessage(cause: unknown): string {
  const hint = CALC_BACKEND_HINT;
  if (cause instanceof TypeError) {
    const m = cause.message.toLowerCase();
    if (
      m.includes('failed to fetch') ||
      m.includes('networkerror') ||
      m.includes('load failed')
    ) {
      return `Сервер розрахунку недоступний (${cause.message}). ${hint}`;
    }
  }
  return cause instanceof Error ? cause.message : 'Помилка розрахунку';
}

function parseCalcOkPayload(data: unknown): CalcOkPayload {
  if (!isRecord(data) || data.ok !== true) {
    throw new Error('Некоректна відповідь API при розрахунку');
  }
  const reportRaw = data.report;
  if (!isRecord(reportRaw)) {
    throw new Error('Некоректна відповідь API при розрахунку: немає об\'єкта report');
  }
  return { ok: true, report: reportRaw };
}

export async function postCalc(payload: unknown): Promise<CalcOkPayload> {
  let res: Response;
  try {
    res = await fetch(apiUrl('/api/v1/calc'), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify(payload),
    });
  } catch (err: unknown) {
    throw new Error(networkCalcErrorMessage(err), {
      cause: err,
    });
  }
  const data: unknown = await res.json().catch(() => null);
  if (!res.ok) {
    if (res.status === 502 || res.status === 503 || res.status === 504) {
      throw new Error(
        `Сервер розрахунку недоступний (HTTP ${res.status}). ${CALC_BACKEND_HINT}`,
      );
    }
    let msg = `Помилка API: HTTP ${res.status}`;
    if (isRecord(data)) {
      const errNode = data.error;
      if (isRecord(errNode)) {
        const m = errNode.message;
        msg =
          typeof m === 'string'
            ? m
            : typeof m === 'number' || typeof m === 'boolean'
              ? String(m)
              : msg;
      }
    }
    throw new Error(msg);
  }
  return parseCalcOkPayload(data);
}

/**
 * Назначение: Сервис каталога оборудования.
 * Описание: Загрузка снимка каталога с GET /api/v1/catalog для справочника в UI и будущего подбора в смете.
 */

import { parseCatalogBoilers } from './parseCatalogBoilers';
import {
  parseCatalogBoilerManifolds,
  parseCatalogManifolds,
} from './parseCatalogManifolds';
import { parseCatalogIndirectWaterHeaters } from './parseCatalogIndirectWaterHeaters';
import { parseCatalogUniboxes } from './parseCatalogUniboxes';
import { parseCatalogWaterHeaters } from './parseCatalogWaterHeaters';
import { apiUrl } from '../utils/apiUrl';
import type {
  CatalogBoilerItem,
  CatalogBoilerManifoldItem,
  CatalogIndirectWaterHeaterItem,
  CatalogManifoldItem,
  CatalogUniboxItem,
  CatalogWaterHeaterItem,
} from './catalogTypes';

export type {
  CatalogBoilerCircuitPool,
  CatalogBoilerItem,
  CatalogBoilerManifoldItem,
  CatalogIndirectWaterHeaterItem,
  CatalogIndirectWaterHeaterType,
  CatalogManifoldDimensions,
  CatalogManifoldItem,
  CatalogUniboxItem,
  CatalogWaterHeaterItem,
  CatalogWaterHeaterVariant,
  ManifoldApplication,
  UniboxType,
} from './catalogTypes';

/** Типичная подсказка при недоступном upstream в dev (см. frontend/vite.config.ts). */
const CATALOG_BACKEND_HINT =
  'Запустіть API-сервер з каталогу backend (npm run start). У режимі розробки Vite проксіює запити /api на http://localhost:3001 — поки backend не слухає цей порт, браузер може отримати помилку шлюзу (502).';

export type CatalogEquipmentSnapshot = {
  catalogSource: 'file' | 'mongo';
  /** Всего котлов в обоих списках (двухконтурные + одноконтурные). */
  boilersTotal: number;
  /** Котлы (doubleCircuit + singleCircuit). */
  boilers: CatalogBoilerItem[];
  radiators: Record<string, unknown>[];
  /** Электронакопители (ЭВН). */
  waterHeaters: CatalogWaterHeaterItem[];
  /** Бойлеры косвенного нагрева (БКН). */
  indirectWaterHeaters: CatalogIndirectWaterHeaterItem[];
  pipes: Record<string, unknown>[];
  /** Коллекторы ТП / радиаторов — номенклатура для подбора и сметы. */
  manifolds: CatalogManifoldItem[];
  /** Котельные распределительные коллекторы. */
  boilerManifolds: CatalogBoilerManifoldItem[];
  /** Унибоксы — локальные регуляторы петли ТП. */
  uniboxes: CatalogUniboxItem[];
};

function catalogFailureMessage(status: number, raw: unknown): string {
  if (
    raw
    && typeof raw === 'object'
    && 'error' in raw
    && typeof (raw as { error?: { message?: unknown } }).error?.message === 'string'
  ) {
    const m = (raw as { error: { message: string } }).error.message.trim();
    if (m) return m;
  }
  if (status === 502 || status === 503 || status === 504) {
    return `Шлюз отримав недопустиму відповідь при запиті каталогу (HTTP ${status}). ${CATALOG_BACKEND_HINT}`;
  }
  return `Не вдалося завантажити каталог (HTTP ${status}). ${CATALOG_BACKEND_HINT}`;
}

/**
 * Загружает GET /api/v1/catalog и возвращает сводку для отображения.
 */
export function fetchCatalogEquipment(): Promise<CatalogEquipmentSnapshot> {
  return loadCatalogEquipmentFromApi();
}

/**
 * @returns {Promise<CatalogEquipmentSnapshot>}
 */
async function loadCatalogEquipmentFromApi(): Promise<CatalogEquipmentSnapshot> {
  let res: Response;
  try {
    res = await fetch(apiUrl('/api/v1/catalog'), {
      headers: { Accept: 'application/json' },
    });
  } catch {
    throw new Error(
      `Запит каталогу не дійшов до сервера (мережа або CORS). ${CATALOG_BACKEND_HINT}`,
    );
  }
  const raw: unknown = await res.json().catch(() => null);
  if (!res.ok) {
    throw new Error(catalogFailureMessage(res.status, raw));
  }
  if (!raw || typeof raw !== 'object' || (raw as { ok?: unknown }).ok !== true) {
    throw new Error('Некоректна відповідь API каталогу');
  }
  const data = raw as {
    catalog?: unknown;
    catalogSource?: unknown;
  };
  const cat = data.catalog && typeof data.catalog === 'object' ? (data.catalog as Record<string, unknown>) : {};
  const boilers = parseCatalogBoilers(cat.boilers);
  const src = data.catalogSource;
  const catalogSource: 'file' | 'mongo' = src === 'mongo' ? 'mongo' : 'file';

  return {
    catalogSource,
    boilersTotal: boilers.length,
    boilers,
    radiators: Array.isArray(cat.radiators) ? (cat.radiators as Record<string, unknown>[]) : [],
    waterHeaters: parseCatalogWaterHeaters(cat.waterHeaters),
    indirectWaterHeaters: parseCatalogIndirectWaterHeaters(cat.indirectWaterHeaters),
    pipes: Array.isArray(cat.pipes) ? (cat.pipes as Record<string, unknown>[]) : [],
    manifolds: parseCatalogManifolds(cat.manifolds),
    boilerManifolds: parseCatalogBoilerManifolds(cat.boilerManifolds),
    uniboxes: parseCatalogUniboxes(cat.uniboxes),
  };
}

/**
 * Назначение: HTTP-клиент feedback API (prod SaaS).
 */

import { getProjectsAuthHeaders } from './projectsAuthHeaders';
import { apiUrl } from '../utils/apiUrl';

export type FeedbackType = 'bug' | 'contact';

export type FeedbackPayload = {
  type: FeedbackType;
  message: string;
  email?: string;
  name?: string;
  pageUrl?: string;
  appVersion?: string;
  buildId?: string;
};

export type FeedbackOkResponse = {
  ok: true;
  id: string;
};

/**
 * @param payload
 * @returns {Promise<FeedbackOkResponse>}
 */
export async function submitFeedback(payload: FeedbackPayload): Promise<FeedbackOkResponse> {
  const res = await fetch(apiUrl('/api/v1/feedback'), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      ...(await getProjectsAuthHeaders()),
    },
    body: JSON.stringify(payload),
  });

  const data: unknown = await res.json();
  if (!res.ok) {
    const msg =
      data &&
      typeof data === 'object' &&
      'error' in data &&
      data.error &&
      typeof data.error === 'object' &&
      'message' in data.error &&
      typeof data.error.message === 'string'
        ? data.error.message
        : 'Не вдалося надіслати повідомлення';
    throw new Error(msg);
  }

  if (
    !data ||
    typeof data !== 'object' ||
    !('ok' in data) ||
    data.ok !== true ||
    !('id' in data) ||
    typeof data.id !== 'string'
  ) {
    throw new Error('Некоректна відповідь сервера');
  }

  return { ok: true, id: data.id };
}

/**
 * Назначение: runtime-проверка ответов admin feedback API и SSE без any.
 */

import type {
  AdminFeedbackItem,
  AdminFeedbackListResponse,
  AdminFeedbackStatus,
  AdminFeedbackType,
  AdminFeedbackUpdateResponse,
} from '../types/adminFeedback';
import { isRecord } from '../utils/jsonGuards';

const FEEDBACK_TYPES: readonly AdminFeedbackType[] = ['bug', 'contact'];
const FEEDBACK_STATUSES: readonly AdminFeedbackStatus[] = ['new', 'read', 'resolved'];
const OPTIONAL_STRING_FIELDS = [
  'email',
  'name',
  'pageUrl',
  'appVersion',
  'buildId',
  'ownerSub',
  'readAt',
  'resolvedAt',
] as const;

/**
 * @param value
 */
export function isAdminFeedbackType(value: unknown): value is AdminFeedbackType {
  return typeof value === 'string' && (FEEDBACK_TYPES as readonly string[]).includes(value);
}

/**
 * @param value
 */
export function isAdminFeedbackStatus(value: unknown): value is AdminFeedbackStatus {
  return typeof value === 'string' && (FEEDBACK_STATUSES as readonly string[]).includes(value);
}

/**
 * @param value
 * @param field
 */
function requireString(value: unknown, field: string): string {
  if (typeof value !== 'string' || !value.trim()) {
    throw new Error(`Некоректна відповідь feedback API: ${field}`);
  }
  return value.trim();
}

/**
 * @param data
 */
export function parseAdminFeedbackItem(data: unknown): AdminFeedbackItem {
  if (!isRecord(data)) {
    throw new Error('Некоректна відповідь feedback API: item');
  }
  if (!isAdminFeedbackType(data.type)) {
    throw new Error('Некоректна відповідь feedback API: type');
  }
  if (!isAdminFeedbackStatus(data.status)) {
    throw new Error('Некоректна відповідь feedback API: status');
  }

  const item: AdminFeedbackItem = {
    id: requireString(data.id, 'id'),
    type: data.type,
    status: data.status,
    message: requireString(data.message, 'message'),
    createdAt: requireString(data.createdAt, 'createdAt'),
    updatedAt: requireString(data.updatedAt, 'updatedAt'),
  };

  for (const field of OPTIONAL_STRING_FIELDS) {
    const value = data[field];
    if (value === undefined || value === null) continue;
    if (typeof value !== 'string') {
      throw new Error(`Некоректна відповідь feedback API: ${field}`);
    }
    const normalized = value.trim();
    if (normalized) item[field] = normalized;
  }

  return item;
}

/**
 * @param data
 */
export function parseAdminFeedbackListResponse(data: unknown): AdminFeedbackListResponse {
  if (!isRecord(data) || data.ok !== true || !Array.isArray(data.items)) {
    throw new Error('Некоректна відповідь списку звернень');
  }
  if (!Number.isInteger(data.limit) || typeof data.limit !== 'number' || data.limit < 1) {
    throw new Error('Некоректна відповідь списку звернень: limit');
  }
  if (
    data.nextCursor !== null &&
    (typeof data.nextCursor !== 'string' || !data.nextCursor.trim())
  ) {
    throw new Error('Некоректна відповідь списку звернень: nextCursor');
  }

  return {
    ok: true,
    items: data.items.map(parseAdminFeedbackItem),
    nextCursor: data.nextCursor?.trim() ?? null,
    limit: data.limit,
  };
}

/**
 * @param data
 */
export function parseAdminFeedbackUpdateResponse(data: unknown): AdminFeedbackUpdateResponse {
  if (!isRecord(data) || data.ok !== true || !('feedback' in data)) {
    throw new Error('Некоректна відповідь оновлення звернення');
  }
  return {
    ok: true,
    feedback: parseAdminFeedbackItem(data.feedback),
  };
}

/**
 * Назначение: Парсинг котлов из ответа GET /api/v1/catalog.
 * Описание: Нормализация doubleCircuit / singleCircuit для справочника UI.
 */

import type {
  CatalogBoilerCircuitPool,
  CatalogBoilerItem,
} from './catalogTypes';

/**
 * @param value
 */
function readTrimmedString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

/**
 * @param value
 */
function parseMountingType(value: unknown): 'wall' | 'floor' | null {
  if (value === 'wall' || value === 'floor') return value;
  return null;
}

/**
 * @param row
 * @param circuitPool
 */
function parseCatalogBoilerItem(
  row: unknown,
  circuitPool: CatalogBoilerCircuitPool,
): CatalogBoilerItem | null {
  if (!row || typeof row !== 'object') return null;
  const r = row as Record<string, unknown>;
  const model = readTrimmedString(r.model);
  if (!model) return null;

  const powerRaw = r.powerKw;
  const power =
    powerRaw && typeof powerRaw === 'object'
      ? (powerRaw as Record<string, unknown>)
      : {};
  const powerKwMin = Number(power.min);
  const powerKwMax = Number(power.max);
  const price = Number(r.price);
  if (
    !Number.isFinite(powerKwMin)
    || !Number.isFinite(powerKwMax)
    || !Number.isFinite(price)
    || price < 1
  ) {
    return null;
  }

  return {
    model,
    brand: readTrimmedString(r.brand),
    circuitPool,
    type: readTrimmedString(r.type) || '—',
    powerKwMin,
    powerKwMax,
    price,
    mountingType: parseMountingType(r.mountingType),
    article: readTrimmedString(r.article),
  };
}

/**
 * @param raw catalog.boilers
 */
export function parseCatalogBoilers(raw: unknown): CatalogBoilerItem[] {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return [];
  const boilers = raw as Record<string, unknown>;
  const out: CatalogBoilerItem[] = [];

  for (const pool of ['doubleCircuit', 'singleCircuit'] as const) {
    const list = boilers[pool];
    if (!Array.isArray(list)) continue;
    for (const row of list) {
      const item = parseCatalogBoilerItem(row, pool);
      if (item != null) out.push(item);
    }
  }

  return out;
}

/**
 * Назначение: Парсинг БКН из ответа GET /api/v1/catalog.
 * Описание: Нормализация indirectWaterHeaters для справочника UI.
 */

import type {
  CatalogIndirectWaterHeaterItem,
  CatalogIndirectWaterHeaterType,
} from './catalogTypes';

const INDIRECT_TYPES = new Set<CatalogIndirectWaterHeaterType>([
  'indirect_wall',
  'indirect_floor',
  'storage_indirect',
]);

/**
 * @param value
 */
function readTrimmedString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

/**
 * @param value
 */
function parseIndirectType(value: unknown): CatalogIndirectWaterHeaterType | null {
  if (typeof value !== 'string') return null;
  const normalized = value.trim().replace(/[\s-]+/g, '_') as CatalogIndirectWaterHeaterType;
  return INDIRECT_TYPES.has(normalized) ? normalized : null;
}

/**
 * @param row
 */
function parseCatalogIndirectWaterHeaterItem(
  row: unknown,
): CatalogIndirectWaterHeaterItem | null {
  if (!row || typeof row !== 'object') return null;
  const r = row as Record<string, unknown>;
  const model = readTrimmedString(r.model);
  const type = parseIndirectType(r.type);
  const price = Number(r.price);
  const specs =
    r.specs && typeof r.specs === 'object'
      ? (r.specs as Record<string, unknown>)
      : {};
  const volumeLiters = Number(specs.volumeLiters);
  if (
    !model
    || type == null
    || !Number.isFinite(price)
    || price < 1
    || !Number.isFinite(volumeLiters)
    || volumeLiters < 1
  ) {
    return null;
  }

  const coilPowerKw = Number(specs.powerKw);
  const minSourcePowerKw = Number(specs.minSourcePowerKw);

  return {
    model,
    brand: readTrimmedString(r.brand),
    article: readTrimmedString(r.article),
    type,
    price,
    volumeLiters,
    coilPowerKw:
      Number.isFinite(coilPowerKw) && coilPowerKw >= 0 ? coilPowerKw : null,
    minSourcePowerKw:
      Number.isFinite(minSourcePowerKw) && minSourcePowerKw >= 0.1
        ? minSourcePowerKw
        : null,
  };
}

/**
 * @param raw catalog.indirectWaterHeaters
 */
export function parseCatalogIndirectWaterHeaters(
  raw: unknown,
): CatalogIndirectWaterHeaterItem[] {
  if (!Array.isArray(raw)) return [];
  const out: CatalogIndirectWaterHeaterItem[] = [];
  for (const row of raw) {
    const item = parseCatalogIndirectWaterHeaterItem(row);
    if (item != null) out.push(item);
  }
  return out;
}

/**
 * Назначение: Парсинг коллекторов из ответа GET /api/v1/catalog.
 * Описание: Нормализация для справочника UI и будущего алгоритма подбора в смете.
 */

import type {
  CatalogBoilerManifoldItem,
  CatalogManifoldDimensions,
  CatalogManifoldItem,
  ManifoldApplication,
} from './catalogTypes';

/**
 * @param {unknown} raw
 * @returns {CatalogManifoldDimensions | null}
 */
function parseDimensions(raw: unknown): CatalogManifoldDimensions | null {
  if (!raw || typeof raw !== 'object') return null;
  const d = raw as Record<string, unknown>;
  const width = Number(d.width);
  const height = Number(d.height);
  const depth = Number(d.depth);
  if (![width, height, depth].every((n) => Number.isFinite(n))) return null;
  return { width, height, depth };
}

/**
 * @param {unknown} value
 * @returns {ManifoldApplication | null}
 */
function parseManifoldApplication(value: unknown): ManifoldApplication | null {
  if (value === 'radiator' || value === 'underfloor') return value;
  return null;
}

/**
 * @param {unknown} row
 * @returns {CatalogManifoldItem | null}
 */
export function parseCatalogManifoldItem(row: unknown): CatalogManifoldItem | null {
  if (!row || typeof row !== 'object') return null;
  const r = row as Record<string, unknown>;
  const model = typeof r.model === 'string' ? r.model.trim() : '';
  const brand = typeof r.brand === 'string' ? r.brand.trim() : '';
  const article = typeof r.article === 'string' ? r.article.trim() : '';
  const manifoldApplication = parseManifoldApplication(r.manifoldApplication);
  const dimensions = parseDimensions(r.dimensions);
  const price = Number(r.price);
  const outletsCount = Number(r.outletsCount);

  if (
    !model
    || !brand
    || !article
    || !manifoldApplication
    || !dimensions
    || !Number.isFinite(price)
    || price < 1
    || !Number.isInteger(outletsCount)
    || outletsCount < 2
    || typeof r.hasFlowMeters !== 'boolean'
  ) {
    return null;
  }

  const connectionMainInch =
    typeof r.connectionMainInch === 'string' ? r.connectionMainInch.trim() : '';
  const connectionOutletsInch =
    typeof r.connectionOutletsInch === 'string' ? r.connectionOutletsInch.trim() : '';
  const material = typeof r.material === 'string' ? r.material.trim() : '';
  const maxPressureBar = Number(r.maxPressureBar);
  const maxTemperatureC = Number(r.maxTemperatureC);

  if (
    !connectionMainInch
    || !connectionOutletsInch
    || !material
    || !Number.isFinite(maxPressureBar)
    || !Number.isFinite(maxTemperatureC)
  ) {
    return null;
  }

  return {
    model,
    brand,
    article,
    price,
    outletsCount,
    manifoldApplication,
    hasFlowMeters: r.hasFlowMeters,
    material,
    maxPressureBar,
    maxTemperatureC,
    connectionMainInch,
    connectionOutletsInch,
    dimensions,
  };
}

/**
 * @param {unknown} row
 * @returns {CatalogBoilerManifoldItem | null}
 */
export function parseCatalogBoilerManifoldItem(row: unknown): CatalogBoilerManifoldItem | null {
  if (!row || typeof row !== 'object') return null;
  const r = row as Record<string, unknown>;
  const model = typeof r.model === 'string' ? r.model.trim() : '';
  const brand = typeof r.brand === 'string' ? r.brand.trim() : '';
  const article = typeof r.article === 'string' ? r.article.trim() : '';
  const dimensions = parseDimensions(r.dimensions);
  const price = Number(r.price);
  const circuitsCount = Number(r.circuitsCount);
  const maxPowerKw = Number(r.maxPowerKw);
  const interaxleDistanceMm = Number(r.interaxleDistanceMm);
  const maxPressureBar = Number(r.maxPressureBar);
  const maxTemperatureC = Number(r.maxTemperatureC);

  if (
    !model
    || !brand
    || !article
    || !dimensions
    || !Number.isFinite(price)
    || price < 1
    || !Number.isInteger(circuitsCount)
    || circuitsCount < 1
    || !Number.isFinite(maxPowerKw)
    || typeof r.hasInsulation !== 'boolean'
    || !Number.isFinite(interaxleDistanceMm)
    || !Number.isFinite(maxPressureBar)
    || !Number.isFinite(maxTemperatureC)
  ) {
    return null;
  }

  const connectionBoilerInch =
    typeof r.connectionBoilerInch === 'string' ? r.connectionBoilerInch.trim() : '';
  const connectionCircuitsInch =
    typeof r.connectionCircuitsInch === 'string' ? r.connectionCircuitsInch.trim() : '';
  const material = typeof r.material === 'string' ? r.material.trim() : '';

  if (!connectionBoilerInch || !connectionCircuitsInch || !material) {
    return null;
  }

  return {
    model,
    brand,
    article,
    price,
    circuitsCount,
    maxPowerKw,
    hasInsulation: r.hasInsulation,
    interaxleDistanceMm,
    connectionBoilerInch,
    connectionCircuitsInch,
    maxPressureBar,
    maxTemperatureC,
    material,
    dimensions,
  };
}

/**
 * @param {unknown} rows
 * @returns {CatalogManifoldItem[]}
 */
export function parseCatalogManifolds(rows: unknown): CatalogManifoldItem[] {
  if (!Array.isArray(rows)) return [];
  const out: CatalogManifoldItem[] = [];
  for (const row of rows) {
    const item = parseCatalogManifoldItem(row);
    if (item) out.push(item);
  }
  return out;
}

/**
 * @param {unknown} rows
 * @returns {CatalogBoilerManifoldItem[]}
 */
export function parseCatalogBoilerManifolds(rows: unknown): CatalogBoilerManifoldItem[] {
  if (!Array.isArray(rows)) return [];
  const out: CatalogBoilerManifoldItem[] = [];
  for (const row of rows) {
