}

/**
 * Назначение: Парсинг унибоксов из ответа GET /api/v1/catalog.
 * Описание: Нормализация для справочника UI и подбора в смете.
 */

import type {
  CatalogManifoldDimensions,
  CatalogUniboxItem,
  UniboxType,
} from './catalogTypes';

const UNIBOX_TYPES = new Set<UniboxType>([
  'rtl_air',
  'rtl',
  'rtl_afc',
  'balancing_valve',
  'air_only',
]);

/**
 * @param {unknown} raw
 * @returns {CatalogManifoldDimensions | undefined}
 */
function parseDimensions(raw: unknown): CatalogManifoldDimensions | undefined {
  if (!raw || typeof raw !== 'object') return undefined;
  const d = raw as Record<string, unknown>;
  const width = Number(d.width);
  const height = Number(d.height);
  const depth = Number(d.depth);
  if (![width, height, depth].every((n) => Number.isFinite(n))) return undefined;
  return { width, height, depth };
}

/**
 * @param {unknown} value
 * @returns {UniboxType | null}
 */
function parseUniboxType(value: unknown): UniboxType | null {
  if (typeof value !== 'string') return null;
  const t = value.trim() as UniboxType;
  return UNIBOX_TYPES.has(t) ? t : null;
}

/**
 * @param {unknown} row
 * @returns {CatalogUniboxItem | null}
 */
export function parseCatalogUniboxItem(row: unknown): CatalogUniboxItem | null {
  if (!row || typeof row !== 'object') return null;
  const r = row as Record<string, unknown>;
  const id = typeof r.id === 'string' ? r.id.trim() : '';
  const brand = typeof r.brand === 'string' ? r.brand.trim() : '';
  const model = typeof r.model === 'string' ? r.model.trim() : '';
  const type = parseUniboxType(r.type);
  const material = typeof r.material === 'string' ? r.material.trim() : '';
  const price = Number(r.price);
  const loopsCount = Number(r.loopsCount);
  const maxAreaSqM = Number(r.maxAreaSqM);
  const maxLoopLengthM = Number(r.maxLoopLengthM);
  const maxTemperatureC = Number(r.maxTemperatureC);
  const maxPressureBar = Number(r.maxPressureBar);
  const kvM3h = Number(r.kvM3h);

  if (
    !id
    || !brand
    || !model
    || !type
    || !material
    || !Number.isFinite(price)
    || price < 1
    || !Number.isInteger(loopsCount)
    || loopsCount < 1
    || !Number.isFinite(maxAreaSqM)
    || !Number.isFinite(maxLoopLengthM)
    || !Number.isFinite(maxTemperatureC)
    || !Number.isFinite(maxPressureBar)
    || !Number.isFinite(kvM3h)
  ) {
    return null;
  }

  if (!r.connection || typeof r.connection !== 'object') return null;
  const c = r.connection as Record<string, unknown>;
  const threadRaw = typeof c.thread === 'string' ? c.thread.trim() : '';
  const fitRaw = typeof c.fit === 'string' ? c.fit.trim() : '';
  if (threadRaw !== 'G1/2' && threadRaw !== 'G3/4') return null;
  if (fitRaw !== 'eurocone' && fitRaw !== 'internal_thread') return null;
  const thread = threadRaw;
  const fit = fitRaw;

  /** @type {CatalogUniboxItem} */
  const item: CatalogUniboxItem = {
    id,
    brand,
    model,
    type,
    loopsCount,
    maxAreaSqM,
    maxLoopLengthM,
    maxTemperatureC,
    maxPressureBar,
    kvM3h,
    connection: { thread, fit },
    material,
    price,
  };

  const optKeys = [
    'minAirTempC',
    'maxAirTempC',
    'minCoolantTempC',
    'maxCoolantTempC',
    'minFlowLph',
    'maxFlowLph',
    'maxSupplyTempC',
  ] as const;
  for (const key of optKeys) {
    if (r[key] === undefined) continue;
    const n = Number(r[key]);
    if (!Number.isFinite(n)) return null;
    item[key] = n;
  }

  const dimensions = parseDimensions(r.dimensions);
  if (dimensions) item.dimensions = dimensions;
  if (typeof r.description === 'string' && r.description.trim()) {
    item.description = r.description.trim();
  }

  return item;
}

/**
 * @param {unknown} raw
 * @returns {CatalogUniboxItem[]}
 */
export function parseCatalogUniboxes(raw: unknown): CatalogUniboxItem[] {
  if (!Array.isArray(raw)) return [];
  /** @type {CatalogUniboxItem[]} */
  const out: CatalogUniboxItem[] = [];
  for (const row of raw) {
    const item = parseCatalogUniboxItem(row);
    if (item) out.push(item);
  }
  return out;
}

/**
 * Назначение: Парсинг электронакопителей из ответа GET /api/v1/catalog.
 * Описание: Нормализация waterHeaters + variants для справочника UI.
 */

import type {
  CatalogWaterHeaterItem,
  CatalogWaterHeaterVariant,
} from './catalogTypes';

/**
 * @param value
 */
function readTrimmedString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

/**
 * @param row
 */
function parseVariant(row: unknown): CatalogWaterHeaterVariant | null {
  if (!row || typeof row !== 'object') return null;
  const r = row as Record<string, unknown>;
  const volumeLiters = Number(r.volumeLiters);
  const price = Number(r.price);
  if (
    !Number.isFinite(volumeLiters)
    || volumeLiters < 1
    || !Number.isFinite(price)
    || price < 1
  ) {
    return null;
  }
  const powerKw = Number(r.powerKw);
  const heatingTimeMinutes = Number(r.heatingTimeMinutes);
  return {
    volumeLiters,
    price,
    powerKw: Number.isFinite(powerKw) && powerKw > 0 ? powerKw : null,
    heatingTimeMinutes:
      Number.isFinite(heatingTimeMinutes) && heatingTimeMinutes >= 1
        ? heatingTimeMinutes
        : null,
  };
}

/**
 * @param row
 */
function parseCatalogWaterHeaterItem(row: unknown): CatalogWaterHeaterItem | null {
  if (!row || typeof row !== 'object') return null;
  const r = row as Record<string, unknown>;
  const model = readTrimmedString(r.model);
  if (!model) return null;
  const variantsRaw = Array.isArray(r.variants) ? r.variants : [];
  const variants = variantsRaw
    .map(parseVariant)
    .filter((v): v is CatalogWaterHeaterVariant => v != null);
  if (variants.length === 0) return null;

  return {
    model,
    brand: readTrimmedString(r.brand),
    type: readTrimmedString(r.type) || 'electric_storage',
    variants,
  };
}

/**
 * @param raw catalog.waterHeaters
 */
export function parseCatalogWaterHeaters(raw: unknown): CatalogWaterHeaterItem[] {
  if (!Array.isArray(raw)) return [];
  const out: CatalogWaterHeaterItem[] = [];
  for (const row of raw) {
    const item = parseCatalogWaterHeaterItem(row);
    if (item != null) out.push(item);
  }
  return out;
}

/**
 * Назначение: strict-парсинг ответа GET /api/v1/me без any.
 */

import type {
  MeAuthProvider,
  MeOkResponse,
  MeUser,
  SubscriptionTier,
  UserRole,
} from '../types/meApi';
import { isRecord } from '../utils/jsonGuards';

const USER_ROLES: readonly UserRole[] = ['user', 'admin'];
const SUBSCRIPTION_TIERS: readonly SubscriptionTier[] = ['free', 'pro', 'marketplace'];
const AUTH_PROVIDERS: readonly MeAuthProvider[] = ['clerk', 'auth0'];

/**
 * @param value
 * @returns {value is UserRole}
 */
function isUserRole(value: unknown): value is UserRole {
  return typeof value === 'string' && (USER_ROLES as readonly string[]).includes(value);
}

/**
 * @param value
 * @returns {value is SubscriptionTier}
 */
function isSubscriptionTier(value: unknown): value is SubscriptionTier {
  return typeof value === 'string' && (SUBSCRIPTION_TIERS as readonly string[]).includes(value);
}

/**
 * @param value
 * @returns {value is MeAuthProvider}
 */
function isMeAuthProvider(value: unknown): value is MeAuthProvider {
  return typeof value === 'string' && (AUTH_PROVIDERS as readonly string[]).includes(value);
}

/**
 * @param node
 * @returns {MeUser}
 */
function parseMeUser(node: unknown): MeUser {
  if (!isRecord(node)) {
    throw new Error('Некоректна відповідь профілю: user');
  }

  const { id, email, emailVerified, role, subscription } = node;

  if (typeof id !== 'string' || !id.trim()) {
    throw new Error('Некоректна відповідь профілю: id');
  }
  if (typeof email !== 'string' || !email.trim()) {
    throw new Error('Некоректна відповідь профілю: email');
  }
  if (typeof emailVerified !== 'boolean') {
    throw new Error('Некоректна відповідь профілю: emailVerified');
  }
  if (!isUserRole(role)) {
    throw new Error('Некоректна відповідь профілю: role');
  }
  if (!isSubscriptionTier(subscription)) {
    throw new Error('Некоректна відповідь профілю: subscription');
  }

  const user: MeUser = {
    id: id.trim(),
    email: email.trim(),
    emailVerified,
    role,
    subscription,
  };

  if ('authProvider' in node && node.authProvider !== undefined) {
    if (!isMeAuthProvider(node.authProvider)) {
      throw new Error('Некоректна відповідь профілю: authProvider');
    }
    user.authProvider = node.authProvider;
  }

  if ('name' in node && node.name !== undefined) {
    if (typeof node.name !== 'string' || !node.name.trim()) {
      throw new Error('Некоректна відповідь профілю: name');
    }
    user.name = node.name.trim();
  }

  if ('devMode' in node && node.devMode !== undefined) {
    if (typeof node.devMode !== 'boolean') {
      throw new Error('Некоректна відповідь профілю: devMode');
    }
    user.devMode = node.devMode;
  }

  return user;
}

/**
 * @param data
 * @returns {MeOkResponse}
 */
export function parseMeOkResponse(data: unknown): MeOkResponse {
  if (!isRecord(data) || data.ok !== true || !('user' in data)) {
    throw new Error('Некоректна відповідь GET /api/v1/me');
  }

  return {
    ok: true,
    user: parseMeUser(data.user),
  };
}

/**
 * Назначение: strict-парсинг PublicSharePayload (в т.ч. publisherPresentation).
 */

import type { PublicSharePayload, SharePublisherPresentation } from '../types/projectsApi';
import { isRecord } from '../utils/jsonGuards';

/**
 * @param value
 * @returns {SharePublisherPresentation | undefined}
 */
export function parseSharePublisherPresentation(
  value: unknown,
): SharePublisherPresentation | undefined {
  if (!isRecord(value)) return undefined;

  const tier = value.tier;
  if (tier !== 'pro' && tier !== 'marketplace') return undefined;

  const contactEmail = value.contactEmail;
  if (typeof contactEmail !== 'string' || !contactEmail.trim()) return undefined;

  const presentation: SharePublisherPresentation = {
    tier,
    contactEmail: contactEmail.trim(),
  };

  if (typeof value.contactName === 'string' && value.contactName.trim()) {
    presentation.contactName = value.contactName.trim();
  }

  return presentation;
}

/**
 * @param node
 * @returns {PublicSharePayload}
 */
export function parsePublicSharePayload(node: unknown): PublicSharePayload {
  if (!isRecord(node)) {
    throw new Error('Некоректна відповідь публічного посилання');
  }

  const shareToken = node.shareToken;
  const clientName = node.clientName;
  const publishedAt = node.publishedAt;

  if (typeof shareToken !== 'string' || !shareToken.trim()) {
    throw new Error('Некоректний shareToken');
  }
  if (typeof clientName !== 'string' || !clientName.trim()) {
    throw new Error('Некоректний clientName');
  }
  if (typeof publishedAt !== 'string' || !publishedAt.trim()) {
    throw new Error('Некоректний publishedAt');
  }
  if (node.schemaVersion !== 1) {
    throw new Error('Непідтримувана schemaVersion');
  }
  if (!('commercial' in node)) {
    throw new Error('Немає commercial у публічному посиланні');
  }

  const matching = isRecord(node.matching) ? node.matching : {};
  const calculations = isRecord(node.calculations) ? node.calculations : {};

  /** @type {PublicSharePayload} */
  const payload: PublicSharePayload = {
    shareToken: shareToken.trim(),
    schemaVersion: 1,
    clientName: clientName.trim(),
    publishedAt: publishedAt.trim(),
    commercial: node.commercial,
    matching,
    calculations,
  };

  if (typeof node.label === 'string' && node.label.trim()) {
    payload.label = node.label.trim();
  }
  if (node.objectType === 'house' || node.objectType === 'apartment') {
    payload.objectType = node.objectType;
  }
  if (typeof node.reportGeneratedAt === 'string' && node.reportGeneratedAt.trim()) {
    payload.reportGeneratedAt = node.reportGeneratedAt.trim();
  }
  if (node.catalogSource === 'file' || node.catalogSource === 'mongo') {
    payload.catalogSource = node.catalogSource;
  }
  if (node.temps !== undefined) {
    payload.temps = node.temps;
  }
  if (Array.isArray(node.warnings)) {
    payload.warnings = node.warnings.filter((w): w is string => typeof w === 'string');
  }

  const publisherPresentation = parseSharePublisherPresentation(node.publisherPresentation);
  if (publisherPresentation) {
    payload.publisherPresentation = publisherPresentation;
  }

  return payload;
}

/**
 * @param data
 * @returns {{ ok: true; share: PublicSharePayload }}
 */
export function parsePublicShareResponse(data: unknown): { ok: true; share: PublicSharePayload } {
  if (!isRecord(data) || data.ok !== true || !('share' in data)) {
    throw new Error('Некоректна відповідь публічного посилання');
  }

  return {
    ok: true,
    share: parsePublicSharePayload(data.share),
  };
}

