/**
 * Назначение: React-контекст единой сессии анкеты.
 * Описание: dispatch → pipeline → calc executor; uiPhase для всех секций отчёта.
 */

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';

import type { EnvelopePreset } from '../types/envelope';
import { useSurveyCalc } from '../query/useSurveyCalc';
import type { CalcReportJson } from '../types/calcApi';
import { buildCalcPayloadFromDraft, canAutoCalcFromDraft } from './buildCalcInputSnapshot';
import {
  applyCalcResponseFail,
  applyCalcResponseOk,
  applyCalcSkippedDedup,
  endDraftInitializationPhase,
  runSurveyMutationPipeline,
} from './runSurveyMutationPipeline';
import {
  SurveySessionContext,
  type SurveySessionContextValue,
} from './surveySessionContext';
import type {
  SurveyCalcAction,
  SurveyMutation,
  SurveySessionState,
} from './types';

export type { SurveySessionContextValue } from './surveySessionContext';

export type SurveySessionProviderProps = {
  initialState: SurveySessionState;
  windowPresets: EnvelopePreset[];
  /** Calc только в режиме survey (Start/resolving — false). */
  calcEnabled?: boolean;
  children: ReactNode;
};

/**
 * @param props
 */
export function SurveySessionProvider({
  initialState,
  windowPresets,
  calcEnabled = true,
  children,
}: SurveySessionProviderProps) {
  const [session, setSession] = useState<SurveySessionState>(initialState);
  const windowPresetsRef = useRef(windowPresets);
  const sessionRef = useRef(session);

  useEffect(() => {
    windowPresetsRef.current = windowPresets;
  }, [windowPresets]);

  useEffect(() => {
    sessionRef.current = session;
  }, [session]);

  const onCalcSuccess = useCallback((report: CalcReportJson) => {
    setSession((prev) => applyCalcResponseOk(prev, report));
  }, []);

  const onCalcError = useCallback((message: string) => {
    setSession((prev) => applyCalcResponseFail(prev, message));
  }, []);

  const onCalcSkippedDedup = useCallback(() => {
    setSession((prev) => applyCalcSkippedDedup(prev));
  }, []);

  const buildCalcPayload = useCallback(
    () => buildCalcPayloadFromDraft(sessionRef.current.draft, windowPresetsRef.current),
    [],
  );

  const canAutoCalc = calcEnabled && canAutoCalcFromDraft(session.draft);

  const {
    calcLoading,
    calcError: runnerError,
    scheduleFreshCalc,
    runApiCalc,
    abortInFlightCalc,
  } = useSurveyCalc({
    buildCalcPayload,
    canAutoCalc,
    calcInputKey: session.calcInputKey,
    onCalcSuccess,
    onCalcError,
    onCalcSkippedDedup,
    draftInitializing: session.draftInitializing,
  });

  const handleCalcAction = useCallback(
    (action: SurveyCalcAction) => {
      if (action === 'abort_only') {
        abortInFlightCalc();
        return;
      }
      if (action === 'schedule') {
        scheduleFreshCalc();
        return;
      }
      if (action === 'schedule_immediate') {
        void runApiCalc();
      }
    },
    [abortInFlightCalc, runApiCalc, scheduleFreshCalc],
  );

  const dispatch = useCallback(
    (mutation: SurveyMutation) => {
      setSession((prev) => {
        const result = runSurveyMutationPipeline(prev, mutation);
        queueMicrotask(() => { handleCalcAction(result.calcAction); });
        return result.state;
      });

      if (mutation.type === 'DRAFT_LOADED') {
        queueMicrotask(() => {
          setSession((prev) => endDraftInitializationPhase(prev));
          scheduleFreshCalc();
        });
      }

      if (mutation.type === 'SESSION_RESET' || mutation.type === 'SURVEY_STARTED') {
        queueMicrotask(() => {
          abortInFlightCalc();
        });
      }
    },
    [handleCalcAction, scheduleFreshCalc, abortInFlightCalc],
  );

  const setReportFromProject = useCallback((report: CalcReportJson | null) => {
    setSession((prev) => ({
      ...prev,
      report,
      reportEpoch: prev.reportEpoch + 1,
      uiPhase: report != null ? 'stable' : 'idle',
      calcError: null,
    }));
  }, []);

  const mergedError = session.calcError ?? runnerError;

  const value = useMemo(
    (): SurveySessionContextValue => ({
      state: session,
      dispatch,
      draft: session.draft,
      report: session.report,
      uiPhase: session.uiPhase,
      calcLoading,
      calcError: mergedError,
      canAutoCalc: canAutoCalcFromDraft(session.draft),
      runApiCalc,
      setReportFromProject,
    }),
    [dispatch, calcLoading, mergedError, runApiCalc, setReportFromProject, session],
  );

  return (
    <SurveySessionContext.Provider value={value}>
      {children}
    </SurveySessionContext.Provider>
  );
}

/**
 * Назначение: решение о запуске calc после мутации.
 */

import type { SurveyCalcAction, SurveyMutation, SurveySessionState } from './types';
import { canAutoCalcFromDraft } from './buildCalcInputSnapshot';

/**
 * @param prev
 * @param next
 * @param mutation
 * @returns {SurveyCalcAction}
 */
export function decideCalcAction(
  prev: SurveySessionState,
  next: SurveySessionState,
  mutation: SurveyMutation,
): SurveyCalcAction {
  if (next.draftInitializing) {
    return 'none';
  }

  if (mutation.type === 'RUN_CALC_MANUAL') {
    return canAutoCalcFromDraft(next.draft) ? 'schedule_immediate' : 'none';
  }

  if (mutation.type === 'DRAFT_LOADED') {
    return canAutoCalcFromDraft(next.draft) ? 'schedule' : 'none';
  }

  if (mutation.type === 'SESSION_RESET') {
    return 'abort_only';
  }

  if (mutation.type === 'SURVEY_STARTED') {
    return 'none';
  }

  const keyChanged = prev.calcInputKey !== next.calcInputKey;
  const canAuto = canAutoCalcFromDraft(next.draft);
  const wasCanAuto = canAutoCalcFromDraft(prev.draft);

  if (!keyChanged && !(canAuto && !wasCanAuto)) {
    return 'none';
  }

  if (!canAuto) {
    return 'abort_only';
  }

  return 'schedule';
}

/**
 * Назначение: синхронизация производного состояния черновика после мутации.
 * Описание: ТП, wiringLayoutV3 — живая pipeline-логика (НЕ compat-миграция черновиков).
 */

import type { RoomFormValue } from '../types/rooms';
import type { SurveyDraftSnapshot, SurveyMutation } from './types';
import { DEFAULT_RADIATOR_CONNECTION } from '../types/radiatorConnection';
import { DEFAULT_RADIATOR_EMITTER_PREFERENCE } from '../types/radiatorEmitterPreference';
import type { WiringLayoutV3 } from './wiringLayoutV3';
import {
  adaptFlatRoomsToWiringLayout,
  createDefaultWiringLayout,
  migrateWiringLayoutOnSystemTypeChange,
} from './wiringLayoutV3';

/**
 * Снять ТП в комнатах при глобальном отключении.
 *
 * @param rooms
 */
function clearRoomUnderfloorHeating(rooms: RoomFormValue[]): RoomFormValue[] {
  return rooms.map((r) => {
    if (!r.underfloorHeating?.enabled) return r;
    return {
      ...r,
      underfloorHeating: { ...r.underfloorHeating, enabled: false },
    };
  });
}

/**
 * Заполнить ветки layout, если комнаты есть, а branches пусты.
 *
 * @param draft
 */
function ensureWiringBranches(draft: SurveyDraftSnapshot): SurveyDraftSnapshot {
  if (draft.rooms.length === 0 || draft.wiringLayoutV3.branches.length > 0) {
    return draft;
  }
  return {
    ...draft,
    wiringLayoutV3: adaptFlatRoomsToWiringLayout(
      draft.rooms,
      draft.wiringLayoutV3.systemType,
    ),
  };
}

/**
 * Пересборка layout v3 из комнат и флагов ТП.
 *
 * @param draft
 */
function rebuildWiringLayout(draft: SurveyDraftSnapshot): WiringLayoutV3 {
  const defaultLen =
    draft.hydraulicsForm.mainLineLengthM > 0
      ? Math.min(draft.hydraulicsForm.mainLineLengthM, 8)
      : 4;
  const systemType = draft.wiringLayoutV3.systemType;
  return adaptFlatRoomsToWiringLayout(draft.rooms, systemType, defaultLen);
}

/**
 * @param draft — черновик после reduce
 * @param mutation — последняя мутация
 * @returns {SurveyDraftSnapshot}
 */
export function migrateDerivedState(
  draft: SurveyDraftSnapshot,
  mutation: SurveyMutation,
): SurveyDraftSnapshot {
  if (mutation.type === 'HEATING_EMITTERS_MODE_SET') {
    if (mutation.presetId == null) {
      const rooms = clearRoomUnderfloorHeating(draft.rooms);
      return {
        ...draft,
        ufhPresetId: mutation.presetId,
        waterUnderfloorHeating: false,
        rooms,
        wiringLayoutV3: adaptFlatRoomsToWiringLayout(
          rooms,
          draft.wiringLayoutV3.systemType,
        ),
      };
    }
    const next: SurveyDraftSnapshot = {
      ...draft,
      ufhPresetId: mutation.presetId,
      waterUnderfloorHeating: true,
      // Узгодження з normalizeHeatingUfhPreset: не лишати 75/65 у чернетці при ufh_only.
      ...(mutation.presetId === 'ufh_only'
        ? { thermalRegimePreset: 'condensing_dt30_55_45' as const }
        : {}),
    };
    return {
      ...next,
      wiringLayoutV3: rebuildWiringLayout(next),
    };
  }

  if (mutation.type === 'WATER_UFH_FLAG_SET') {
    const next: SurveyDraftSnapshot = {
      ...draft,
      waterUnderfloorHeating: mutation.enabled,
      ufhPresetId: mutation.enabled ? draft.ufhPresetId : null,
      rooms: mutation.enabled
        ? draft.rooms
        : clearRoomUnderfloorHeating(draft.rooms),
    };
    return {
      ...next,
      wiringLayoutV3: rebuildWiringLayout(next),
    };
  }

  if (mutation.type === 'WIRING_SCHEME_SET') {
    return {
      ...draft,
      wiringLayoutV3: migrateWiringLayoutOnSystemTypeChange(
        draft.wiringLayoutV3,
        draft.rooms,
        mutation.systemType,
      ),
    };
  }

  if (mutation.type === 'SET_ROOMS') {
    return {
      ...draft,
      wiringLayoutV3: migrateWiringLayoutOnSystemTypeChange(
        draft.wiringLayoutV3,
        draft.rooms,
        draft.wiringLayoutV3.systemType,
      ),
    };
  }

  if (mutation.type === 'DRAFT_LOADED') {
    return ensureWiringBranches(draft);
  }

  if (mutation.type === 'SET_CURRENT_STEP' && mutation.step === 'hydraulics') {
    return ensureWiringBranches(draft);
  }

  return ensureWiringBranches(draft);
}

/**
 * @returns {SurveyDraftSnapshot} Начальный черновик сессии.
 */
export function createInitialDraftSnapshot(
  partial: Partial<SurveyDraftSnapshot> &
    Pick<
      SurveyDraftSnapshot,
      | 'objectMeta'
      | 'hotWaterForm'
      | 'waterHeaterForm'
      | 'thermalRegimePreset'
      | 'hydraulicsForm'
    >,
): SurveyDraftSnapshot {
  return {
    currentStep: partial.currentStep ?? 'object',
    objectMeta: partial.objectMeta,
    rooms: partial.rooms ?? [],
    temps: partial.temps ?? { insideC: 20, outsideC: -5 },
    hotWaterForm: partial.hotWaterForm,
    waterHeaterForm: partial.waterHeaterForm,
    waterUnderfloorHeating: partial.waterUnderfloorHeating ?? false,
    underfloorDistributionPreset:
      partial.underfloorDistributionPreset ?? 'auto',
    thermalRegimePreset: partial.thermalRegimePreset,
    radiatorConnection: partial.radiatorConnection ?? DEFAULT_RADIATOR_CONNECTION,
    radiatorEmitterPreference:
      partial.radiatorEmitterPreference ?? DEFAULT_RADIATOR_EMITTER_PREFERENCE,
    ufhPresetId: partial.ufhPresetId ?? null,
    hydraulicsForm: partial.hydraulicsForm,
    wiringLayoutV3: partial.wiringLayoutV3 ?? createDefaultWiringLayout(),
  };
}

/**
 * Назначение: reduce шага 1 pipeline — применение мутации к черновику.
 */

import type { SurveyDraftSnapshot, SurveyMutation } from './types';
import { createDefaultSurveyDraftSnapshot } from './createDefaultSurveyDraft';
import { createEmptySurveyDraftSnapshot } from './createEmptySurveySessionState';
import { normalizeHotWaterForm } from '../utils/normalizeHotWaterForm';
import { normalizeWaterHeaterForm } from '../utils/normalizeWaterHeaterForm';

/**
 * @param draft
 * @param mutation
 * @returns {SurveyDraftSnapshot}
 */
export function reduceSurveyMutation(
  draft: SurveyDraftSnapshot,
  mutation: SurveyMutation,
): SurveyDraftSnapshot {
  switch (mutation.type) {
    case 'SET_CURRENT_STEP':
      return { ...draft, currentStep: mutation.step };
    case 'SET_OBJECT_META':
      return { ...draft, objectMeta: mutation.objectMeta };
    case 'SET_ROOMS':
      return { ...draft, rooms: mutation.rooms };
    case 'SET_TEMPS':
      return { ...draft, temps: mutation.temps };
    case 'SET_HOT_WATER_FORM':
      return {
        ...draft,
        hotWaterForm: normalizeHotWaterForm(mutation.hotWaterForm),
      };
    case 'SET_WATER_HEATER_FORM':
      return {
        ...draft,
        waterHeaterForm: normalizeWaterHeaterForm(mutation.waterHeaterForm),
      };
    case 'HEATING_EMITTERS_MODE_SET':
      return { ...draft, ufhPresetId: mutation.presetId };
    case 'WATER_UFH_FLAG_SET':
      return { ...draft, waterUnderfloorHeating: mutation.enabled };
    case 'UFH_DISTRIBUTION_PRESET_SET':
      return { ...draft, underfloorDistributionPreset: mutation.preset };
    case 'WIRING_SCHEME_SET':
      return {
        ...draft,
        wiringLayoutV3: {
          ...draft.wiringLayoutV3,
          systemType: mutation.systemType,
        },
      };
    case 'SET_WIRING_BRANCHES':
      return {
        ...draft,
        wiringLayoutV3: {
          ...draft.wiringLayoutV3,
          branches: structuredClone(mutation.branches),
          metadata: {
            ...draft.wiringLayoutV3.metadata,
            migratedFrom: 'native-v3',
            updatedAt: new Date().toISOString(),
          },
        },
      };
    case 'WIRING_BRANCH_LENGTH_SET':
      return {
        ...draft,
        wiringLayoutV3: {
          ...draft.wiringLayoutV3,
          branches: draft.wiringLayoutV3.branches.map((b) =>
            b.roomId === mutation.roomId
              ? { ...b, pipeLengthToEquipmentM: mutation.pipeLengthToEquipmentM }
              : b,
          ),
          metadata: {
            ...draft.wiringLayoutV3.metadata,
            migratedFrom: 'native-v3',
            updatedAt: new Date().toISOString(),
          },
        },
      };
    case 'WIRING_BRANCH_REORDER': {
      const branches = [...draft.wiringLayoutV3.branches];
      const idx = branches.findIndex((b) => b.roomId === mutation.roomId);
      if (idx < 0) return draft;
      const swapIdx = mutation.direction === 'up' ? idx - 1 : idx + 1;
      if (swapIdx < 0 || swapIdx >= branches.length) return draft;
      const tmp = branches[idx];
      const swapBranch = branches[swapIdx];
      if (tmp === undefined || swapBranch === undefined) return draft;
      branches[idx] = swapBranch;
      branches[swapIdx] = tmp;
      return {
        ...draft,
        wiringLayoutV3: {
          ...draft.wiringLayoutV3,
          branches,
          metadata: {
            ...draft.wiringLayoutV3.metadata,
            migratedFrom: 'native-v3',
            updatedAt: new Date().toISOString(),
          },
        },
      };
    }
    case 'SET_THERMAL_REGIME_PRESET':
      return { ...draft, thermalRegimePreset: mutation.preset };
    case 'SET_RADIATOR_CONNECTION':
      return { ...draft, radiatorConnection: mutation.connection };
    case 'SET_RADIATOR_EMITTER_PREFERENCE':
      return { ...draft, radiatorEmitterPreference: mutation.preference };
    case 'SET_HYDRAULICS_FORM':
      return { ...draft, hydraulicsForm: mutation.hydraulicsForm };
    case 'DRAFT_LOADED':
      return structuredClone(mutation.draft);
    case 'SESSION_RESET':
      return createEmptySurveyDraftSnapshot();
    case 'SURVEY_STARTED':
      return createDefaultSurveyDraftSnapshot();
    case 'RUN_CALC_MANUAL':
      return draft;
    default: {
      const _exhaustive: never = mutation;
      return _exhaustive;
    }
  }
}

/**
 * Назначение: единый pipeline мутации анкеты (шаги 1–4).
 */

import { buildCalcInputKeyFromDraft } from './buildCalcInputSnapshot';
import { decideCalcAction } from './decideCalcAction';
import { migrateDerivedState } from './migrateDerivedState';
import { reduceSurveyMutation } from './reduceSurveyMutation';
import type {
  SurveyMutation,
  SurveyPipelineResult,
  SurveySessionState,
  SurveyUiPhase,
} from './types';

/**
 * @param prev
 * @param mutation
 * @returns {SurveyPipelineResult}
 */
export function runSurveyMutationPipeline(
  prev: SurveySessionState,
  mutation: SurveyMutation,
): SurveyPipelineResult {
  let draft = reduceSurveyMutation(prev.draft, mutation);
  draft = migrateDerivedState(draft, mutation);

  let thermalRegimeTouched = prev.thermalRegimeTouched;
  if (mutation.type === 'SET_THERMAL_REGIME_PRESET' && mutation.touched) {
    thermalRegimeTouched = true;
  }
  if (mutation.type === 'DRAFT_LOADED') {
    thermalRegimeTouched = true;
  }
  if (mutation.type === 'SESSION_RESET' || mutation.type === 'SURVEY_STARTED') {
    thermalRegimeTouched = false;
  }

  let draftInitializing = prev.draftInitializing;
  if (mutation.type === 'DRAFT_LOADED') {
    draftInitializing = true;
  }

  let report = prev.report;
  let reportEpoch = prev.reportEpoch;
  let uiPhase: SurveyUiPhase = prev.uiPhase;
  let calcError = prev.calcError;

  if (mutation.type === 'DRAFT_LOADED') {
    report = mutation.lastCalcReport ?? null;
    reportEpoch += 1;
    uiPhase = report != null ? 'stable' : 'idle';
    calcError = null;
  }

  if (mutation.type === 'SESSION_RESET' || mutation.type === 'SURVEY_STARTED') {
    report = null;
    reportEpoch += 1;
    uiPhase = 'idle';
    calcError = null;
    draftInitializing = false;
  }

  const calcInputKey = buildCalcInputKeyFromDraft(draft);

  const interim: SurveySessionState = {
    draft,
    report,
    reportEpoch,
    uiPhase,
    calcError,
    draftInitializing,
    thermalRegimeTouched,
    calcInputKey,
  };

  const calcAction = decideCalcAction(prev, interim, mutation);

  if (calcAction === 'schedule' || calcAction === 'schedule_immediate') {
    uiPhase = 'recalculating';
    calcError = null;
  } else if (calcAction === 'abort_only') {
    uiPhase = report != null ? 'stable' : 'idle';
  }

  if (
    mutation.type === 'DRAFT_LOADED'
    && calcAction === 'schedule'
  ) {
    draftInitializing = true;
  }

  return {
    state: {
      ...interim,
      uiPhase,
      calcError,
      draftInitializing,
      thermalRegimeTouched,
    },
    calcAction,
  };
}

/**
 * Завершение загрузки черновика (снятие guard).
 *
 * @param state
 * @returns {SurveySessionState}
 */
export function endDraftInitializationPhase(
  state: SurveySessionState,
): SurveySessionState {
  return { ...state, draftInitializing: false };
}

/**
 * Успешный ответ calc API — полная замена отчёта.
 *
 * @param state
 * @param report
 * @returns {SurveySessionState}
 */
export function applyCalcResponseOk(
  state: SurveySessionState,
  report: import('../types/calcApi').CalcReportJson,
): SurveySessionState {
  return {
    ...state,
    report,
    reportEpoch: state.reportEpoch + 1,
    uiPhase: 'stable',
    calcError: null,
  };
}

/**
 * Ошибка calc — сохраняем предыдущий отчёт.
 *
 * @param state
 * @param message
 * @returns {SurveySessionState}
 */
export function applyCalcResponseFail(
  state: SurveySessionState,
  message: string,
): SurveySessionState {
  return {
    ...state,
    uiPhase: 'error',
    calcError: message,
  };
}

/**
 * Dedup payload: POST не нужен — снимаем recalculating, отчёт без изменений.
 *
 * @param state
 * @returns {SurveySessionState}
 */
export function applyCalcSkippedDedup(state: SurveySessionState): SurveySessionState {
  return {
    ...state,
    uiPhase: state.report != null ? 'stable' : 'idle',
    calcError: null,
  };
}

/**
 * Назначение: Разбор proposal котла из отчёта.
 * Описание: Преобразование узла matching.boiler.proposal* в данные для карточки.
 */

import type { BoilerProposalView } from '../components/BoilerProposalCard/BoilerProposalCard';
import { isRecord, readStringArray } from './jsonGuards';

/** Разбирает узел proposal из отчёта API в вид для BoilerProposalCard. */
export function parseBoilerProposalPayload(raw: unknown): BoilerProposalView | null {
  if (!isRecord(raw)) return null;
  const p = raw;
  const kind = p.kind;
  if (kind !== 'single' && kind !== 'cascade') return null;
  const headline = typeof p.headline === 'string' ? p.headline : '';
  const model = typeof p.model === 'string' ? p.model : '';
  if (!headline || !model) return null;
  const unitsCount = typeof p.unitsCount === 'number' ? p.unitsCount : NaN;
  const unitMaxPowerKw = typeof p.unitMaxPowerKw === 'number' ? p.unitMaxPowerKw : NaN;
  const totalNominalKw = typeof p.totalNominalKw === 'number' ? p.totalNominalKw : NaN;
  const requiredKw = typeof p.requiredKw === 'number' ? p.requiredKw : NaN;
  const nominalReservePercent =
    typeof p.nominalReservePercent === 'number' ? p.nominalReservePercent : NaN;

  const br = p.powerRequirementBreakdown;
  if (!isRecord(br)) return null;
  const breakdownHeating =
    typeof br.heatingLoadKw === 'number' && Number.isFinite(br.heatingLoadKw)
      ? br.heatingLoadKw
      : NaN;
  const breakdownDhw =
    typeof br.hotWaterPowerKw === 'number' && Number.isFinite(br.hotWaterPowerKw)
      ? br.hotWaterPowerKw
      : NaN;

  if (
    !Number.isFinite(unitsCount)
    || !Number.isFinite(unitMaxPowerKw)
    || !Number.isFinite(totalNominalKw)
    || !Number.isFinite(requiredKw)
    || !Number.isFinite(nominalReservePercent)
    || !Number.isFinite(breakdownHeating)
    || !Number.isFinite(breakdownDhw)
  ) {
    return null;
  }
  const advantages = readStringArray(p.advantages);
  const notes = readStringArray(p.notes);
  const mountingType = p.mountingType === 'wall' || p.mountingType === 'floor' ? p.mountingType : undefined;
  const connectionDiametersRaw = p.connectionDiameters;
  const connectionDiameters = Array.isArray(connectionDiametersRaw)
    ? readStringArray(connectionDiametersRaw)
    : undefined;
  const estimatedTotalPrice =
    typeof p.estimatedTotalPrice === 'number' && Number.isFinite(p.estimatedTotalPrice)
      ? p.estimatedTotalPrice
      : undefined;
  const equipmentBundleTotalPrice =
    typeof p.equipmentBundleTotalPrice === 'number' &&
    Number.isFinite(p.equipmentBundleTotalPrice)
      ? p.equipmentBundleTotalPrice
      : undefined;
  const brRaw = p.equipmentBundlePriceBreakdown;
  let equipmentBundlePriceBreakdown:
    | import('../components/BoilerProposalCard/BoilerProposalCard').EquipmentBundlePriceBreakdownView
    | undefined;
  if (isRecord(brRaw)) {
    const boilerPrice =
      typeof brRaw.boilerPrice === 'number' && Number.isFinite(brRaw.boilerPrice)
        ? brRaw.boilerPrice
        : undefined;
    const waterHeaterPrice =
      typeof brRaw.waterHeaterPrice === 'number' &&
      Number.isFinite(brRaw.waterHeaterPrice)
        ? brRaw.waterHeaterPrice
        : undefined;
    const indirectWaterHeaterPrice =
      typeof brRaw.indirectWaterHeaterPrice === 'number' &&
      Number.isFinite(brRaw.indirectWaterHeaterPrice)
        ? brRaw.indirectWaterHeaterPrice
        : undefined;
    if (
      boilerPrice != null ||
      waterHeaterPrice != null ||
      indirectWaterHeaterPrice != null
    ) {
      equipmentBundlePriceBreakdown = {
        ...(boilerPrice !== undefined ? { boilerPrice } : {}),
        ...(waterHeaterPrice !== undefined ? { waterHeaterPrice } : {}),
        ...(indirectWaterHeaterPrice !== undefined
          ? { indirectWaterHeaterPrice }
          : {}),
      };
    }
  }
  const tier = p.tier === 'economy' || p.tier === 'efficient' ? p.tier : undefined;

  const companionsRaw = p.equipmentBundleCompanions;
  let equipmentBundleCompanions:
    | import('../components/BoilerProposalCard/BoilerProposalCard').EquipmentBundleCompanionView[]
    | undefined;
  if (Array.isArray(companionsRaw)) {
    const parsed: import('../components/BoilerProposalCard/BoilerProposalCard').EquipmentBundleCompanionView[] =
      [];
    for (const item of companionsRaw) {
      if (!isRecord(item)) continue;
      const role = item.role;
      if (role !== 'water_heater' && role !== 'indirect_water_heater') continue;
      const model = typeof item.model === 'string' ? item.model.trim() : '';
      if (!model) continue;
      const brand =
        typeof item.brand === 'string' && item.brand.trim()
          ? item.brand.trim()
          : undefined;
      const volumeLiters =
        typeof item.volumeLiters === 'number' && Number.isFinite(item.volumeLiters)
          ? item.volumeLiters
          : undefined;
      const price =
        typeof item.price === 'number' && Number.isFinite(item.price)
          ? item.price
          : undefined;
      parsed.push({
        role,
        model,
        ...(brand !== undefined ? { brand } : {}),
        ...(volumeLiters !== undefined ? { volumeLiters } : {}),
        ...(price !== undefined ? { price } : {}),
      });
    }
    if (parsed.length) equipmentBundleCompanions = parsed;
  }

  return {
    kind,
    headline,
    model,
    unitsCount,
    unitMaxPowerKw,
    totalNominalKw,
    requiredKw,
    powerRequirementBreakdown: {
      heatingLoadKw: breakdownHeating,
      hotWaterPowerKw: breakdownDhw,
    },
    nominalReservePercent,
    ...(estimatedTotalPrice !== undefined ? { estimatedTotalPrice } : {}),
    ...(equipmentBundleTotalPrice !== undefined ? { equipmentBundleTotalPrice } : {}),
    ...(equipmentBundlePriceBreakdown !== undefined
      ? { equipmentBundlePriceBreakdown }
      : {}),
    ...(equipmentBundleCompanions !== undefined
      ? { equipmentBundleCompanions }
      : {}),
    ...(mountingType !== undefined ? { mountingType } : {}),
    ...(connectionDiameters && connectionDiameters.length > 0
      ? { connectionDiameters }
      : {}),
    advantages,
    notes,
    ...(tier !== undefined ? { tier } : {}),
  };
}

/**
 * Назначение: HTML-приложение «Технический расчёт» для печати / PDF.
 * Описание: Собирает секции как на шаге technicalResult (не stub из 2–3 KPI).
 */

import { HOT_WATER_BOILER_MATCHING_SCHEME_ENUM } from '../types/heatingMatching';
import type { HotWaterBoilerPowerMatchingScheme } from '../types/heatingMatching';
import type { CalcReportJson } from '../types/calcApi';
import type { PublicSharePayload } from '../types/projectsApi';
import { heatLossReserveKw, heatLossTotalKw, wattsToKilowatts } from './calculators/heatLoss';
import { formatKw } from './format';
import { isRecord, readRecordField } from './jsonGuards';
import { parseBoilerFromReport } from './parsers/parseBoilerFromReport';
import { parseHotWaterFromReport } from './parsers/parseHotWaterFromReport';
import {
  formatRadiatorsEmittersSummaryLabel,
  parseRadiatorsMatchingFromReport,
} from './parsers/parseRadiatorsMatchingFromReport';
import { parseIndirectWaterHeaterMatchingFromReport } from './parsers/parseIndirectWaterHeaterMatchingFromReport';
import { parseWaterHeaterMatchingFromReport } from './parsers/parseWaterHeaterMatchingFromReport';
import { parseUnderfloorHeatingFromReport } from './parsers/parseUnderfloorHeatingFromReport';
import { parseHydraulicsFromReport } from './parsers/parseHydraulicsFromReport';
import { isRadiatorsMatchingSkipped } from './radiatorsSkip';

const SCHEME_SET = new Set<string>(HOT_WATER_BOILER_MATCHING_SCHEME_ENUM);

/**
 * @param v
 */
function isCalcMatchingScheme(v: string): v is HotWaterBoilerPowerMatchingScheme {
  return SCHEME_SET.has(v);
}

/**
 * @param s
 */
function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/**
 * @param title
 * @param rows
 */
function kvTable(title: string, rows: Array<[string, string]>): string {
  if (rows.length === 0) return '';
  const body = rows
    .map(
      ([k, v]) =>
        `<tr><td>${escapeHtml(k)}</td><td>${escapeHtml(v)}</td></tr>`,
    )
    .join('');
  return `<h3>${escapeHtml(title)}</h3>
<table class="tech">
  <thead><tr><th>Показник</th><th>Значення</th></tr></thead>
  <tbody>${body}</tbody>
</table>`;
}

/**
 * @param title
 * @param headers
 * @param rows
 */
function dataTable(title: string, headers: string[], rows: string[][]): string {
  if (rows.length === 0) return '';
  const head = headers.map((h) => `<th>${escapeHtml(h)}</th>`).join('');
  const body = rows
    .map(
      (r) =>
        `<tr>${r.map((c) => `<td>${escapeHtml(c)}</td>`).join('')}</tr>`,
    )
    .join('');
  return `<h3>${escapeHtml(title)}</h3>
<table class="tech">
  <thead><tr>${head}</tr></thead>
  <tbody>${body}</tbody>
</table>`;
}

/**
 * Синтетический report из публичного share (те же parsers, что для calc).
 *
 * @param share
 */
export function reportLikeFromPublicShare(share: PublicSharePayload): CalcReportJson {
  return {
    commercial: share.commercial,
    matching: share.matching,
    calculations: share.calculations,
    ...(share.warnings ? { warnings: share.warnings } : {}),
    ...(share.temps ? { temps: share.temps } : {}),
    ...(share.catalogSource || share.reportGeneratedAt
      ? {
          meta: {
            ...(share.catalogSource ? { catalogSource: share.catalogSource } : {}),
            ...(share.reportGeneratedAt
              ? { generatedAt: share.reportGeneratedAt }
              : {}),
          },
        }
      : {}),
  };
}

/**
 * Полный HTML техрасчёта для печати (секции как на technicalResult).
 *
 * @param calcReport
 * @returns HTML или пустая строка
 */
export function buildTechnicalPrintHtml(calcReport: CalcReportJson | null | undefined): string {
  if (calcReport == null || !isRecord(calcReport)) return '';

  const parts: string[] = [];

  const calculations = readRecordField(calcReport, 'calculations');
  const heatLoss = calculations ? readRecordField(calculations, 'heatLoss') : null;
  if (heatLoss && typeof heatLoss.totalWatts === 'number') {
    const heatLossKw = wattsToKilowatts(heatLoss.totalWatts);
    const rows: Array<[string, string]> = [
      ['Потужність приміщень', `${formatKw(heatLossKw, 1)} кВт`],
      ['Запас', `${formatKw(heatLossReserveKw(heatLossKw), 1)} кВт`],
      ['Разом із запасом', `${formatKw(heatLossTotalKw(heatLossKw), 1)} кВт`],
    ];
    const byRoom = Array.isArray(heatLoss.byRoom) ? heatLoss.byRoom : [];
    const roomRows: string[][] = [];
    for (const item of byRoom) {
      if (!isRecord(item)) continue;
      const name =
        typeof item.roomName === 'string'
          ? item.roomName
          : typeof item.name === 'string'
            ? item.name
            : typeof item.roomId === 'string'
              ? item.roomId
              : '—';
      const watts =
        typeof item.totalWatts === 'number'
          ? item.totalWatts
          : typeof item.heatLossWatts === 'number'
            ? item.heatLossWatts
            : null;
      if (watts == null) continue;
      roomRows.push([name, `${formatKw(wattsToKilowatts(watts), 2)} кВт`]);
    }
    parts.push(kvTable('Тепловтрати', rows));
    if (roomRows.length > 0) {
      parts.push(dataTable('Тепловтрати за приміщеннями', ['Приміщення', 'Потужність'], roomRows));
    }
  }

  const hotWater = parseHotWaterFromReport(calcReport);
  if (hotWater) {
    const rows: Array<[string, string]> = [
      ['Пікова потужність ГВП', `${formatKw(hotWater.hotWaterPowerKw)} кВт`],
      ['Пікова витрата', `${hotWater.peakFlowLps.toLocaleString('uk-UA', { maximumFractionDigits: 3 })} л/с`],
    ];
    if (hotWater.recommendedTankLiters != null) {
      rows.push(['Рекомендований бак', `${Math.round(hotWater.recommendedTankLiters)} л`]);
    }
    if (hotWater.dhwSupplyScenario) {
      rows.push([
        'Сценарій',
        hotWater.dhwSupplyScenario === 'storage' ? 'накопичувальний' : 'проточний',
      ]);
    }
    if (hotWater.residents != null) {
      rows.push(['Мешканці', String(hotWater.residents)]);
    }
    if (hotWater.hotWaterC != null && hotWater.designColdWaterC != null) {
      rows.push([
        'Температури ГВ / ХВ',
        `${hotWater.hotWaterC} / ${hotWater.designColdWaterC} °C`,
      ]);
    }
    parts.push(kvTable('Гаряча вода', rows));
  }

  const boiler = parseBoilerFromReport(calcReport, isCalcMatchingScheme);
  if (boiler?.summary) {
    const s = boiler.summary;
    const rows: Array<[string, string]> = [
      ['Тепловтрати', `${formatKw(s.heatLossKw)} кВт`],
      [`Опалення ×${s.reserveFactor}`, `${formatKw(s.heatingLoadKw)} кВт`],
      ['Потужність ГВП', `${formatKw(s.hotWaterPowerKw)} кВт`],
      ['Потрібна потужність котла', `${formatKw(s.requiredKw)} кВт`],
    ];
    const proposal =
      boiler.tierEconomy ?? boiler.legacyProposal ?? boiler.tierEfficient;
    if (proposal) {
      rows.push(['Пропозиція', `${proposal.headline}: ${proposal.model}`]);
      rows.push(['Номінал', `${formatKw(proposal.totalNominalKw)} кВт`]);
    }
    parts.push(kvTable('Котел', rows));
    if (boiler.warnings.length > 0) {
      parts.push(
        `<h3>Попередження котла</h3><ul>${boiler.warnings
          .map((w) => `<li>${escapeHtml(w)}</li>`)
          .join('')}</ul>`,
      );
    }
  }

  const radiators = parseRadiatorsMatchingFromReport(calcReport);
  if (radiators && !isRadiatorsMatchingSkipped(radiators)) {
    const rows: Array<[string, string]> = [];
    if (radiators.chosenModel) rows.push(['Модель (основна лінія)', radiators.chosenModel]);
    const emitters = formatRadiatorsEmittersSummaryLabel(radiators.emittersSummary);
    if (emitters) rows.push(['Прилади', emitters]);
    if (radiators.totalSections != null) {
      rows.push(['Секцій (осн.)', String(radiators.totalSections)]);
    }
    const eco = formatRadiatorsEmittersSummaryLabel(radiators.lineEconomy?.emittersSummary);
    const eff = formatRadiatorsEmittersSummaryLabel(radiators.lineEfficient?.emittersSummary);
    if (eco) rows.push(['Лінія «Економ»', eco]);
    if (eff) rows.push(['Лінія «Ефективний»', eff]);
    if (radiators.inputs?.supplyC != null && radiators.inputs.returnC != null) {
      rows.push([
        'Графік',
        `${radiators.inputs.supplyC}/${radiators.inputs.returnC} °C`,
      ]);
    }
    parts.push(kvTable('Радіатори', rows));

    const byRoomRows = radiators.byRoom
      .filter((r) => r.displayKind !== 'none')
      .map((r) => {
        const qty =
          r.displayKind === 'panel'
            ? `${r.unitsCount ?? 1} шт.${r.panelLengthMm != null ? ` · ${r.panelLengthMm} мм` : ''}`
            : r.sections != null
              ? `${r.sections} сек.`
              : '—';
        return [
          r.roomName || r.roomId,
          r.radiatorModel ?? '—',
          qty,
          r.deliverableWatts != null ? `${Math.round(r.deliverableWatts)} Вт` : '—',
        ];
      });
    if (byRoomRows.length > 0) {
      parts.push(
        dataTable(
          'Радіатори за приміщеннями',
          ['Приміщення', 'Модель', 'К-сть', 'Віддача'],
          byRoomRows,
        ),
      );
    }
  } else if (radiators && isRadiatorsMatchingSkipped(radiators)) {
    parts.push(kvTable('Радіатори', [['Статус', 'не потрібні (режим лише ТП)']]));
  }

  const indirect = parseIndirectWaterHeaterMatchingFromReport(calcReport);
  if (indirect) {
    const rows: Array<[string, string]> = [];
    if (indirect.selectedModel) rows.push(['Модель БКН', indirect.selectedModel]);
    if (indirect.volumeLiters != null) {
      rows.push(['Об\'єм', `${Math.round(indirect.volumeLiters)} л`]);
    }
    if (indirect.coilPowerKw != null) {
      rows.push(['Потужність змійовика', `${formatKw(indirect.coilPowerKw)} кВт`]);
    }
    if (rows.length) parts.push(kvTable('Бойлер непрямого нагріву', rows));
  }

  const electricWh = parseWaterHeaterMatchingFromReport(calcReport);
  if (electricWh) {
    const rows: Array<[string, string]> = [];
    if (electricWh.selectedModel) rows.push(['Модель', electricWh.selectedModel]);
    if (electricWh.volumeLiters != null) {
      rows.push(['Об\'єм', `${Math.round(electricWh.volumeLiters)} л`]);
    }
    if (electricWh.powerKw != null) {
      rows.push(['Потужність', `${formatKw(electricWh.powerKw)} кВт`]);
    }
    if (rows.length) parts.push(kvTable('Електронакопичувач', rows));
  }

  const ufh = parseUnderfloorHeatingFromReport(calcReport);
  if (ufh && ufh.rooms.length > 0) {
    const rows: Array<[string, string]> = [
      ['Кімнат з ТП', String(ufh.rooms.length)],
    ];
    if (ufh.totalHeatFluxUpWatts > 0) {
      rows.push([
        'Сумарний потік вгору',
        `${formatKw(wattsToKilowatts(ufh.totalHeatFluxUpWatts))} кВт`,
      ]);
    }
    if (ufh.mixingNode) {
      rows.push([
        'Змішувальний вузол',
        `котел ${ufh.mixingNode.boilerSupplyC ?? '—'} °C → контур ${ufh.mixingNode.floorCircuitSupplyC ?? '—'} °C`,
      ]);
    }
    parts.push(kvTable('Тепла підлога', rows));

    const roomRows = ufh.rooms.map((r) => [
      r.roomName || r.roomId,
      r.heatedAreaM2 != null ? `${r.heatedAreaM2.toLocaleString('uk-UA')} м²` : '—',
      `${formatKw(wattsToKilowatts(r.heatFluxUpWatts), 2)} кВт`,
      r.loopsCount != null ? String(r.loopsCount) : '—',
    ]);
    parts.push(
      dataTable(
        'Тепла підлога за приміщеннями',
        ['Приміщення', 'Активна площа', 'Потік вгору', 'Петлі'],
        roomRows,
      ),
    );
  }

  const hydraulics = parseHydraulicsFromReport(calcReport);
  if (hydraulics?.calculations) {
    const c = hydraulics.calculations;
    const rows: Array<[string, string]> = [
      ['Витрата', `${c.flowRateM3PerHour.toLocaleString('uk-UA', { maximumFractionDigits: 3 })} м³/ч`],
      ['Потрібний напір', `${c.headRequiredM.toLocaleString('uk-UA', { maximumFractionDigits: 2 })} м`],
    ];
    if (c.recommendedPipeDiameter) {
      rows.push(['Рекомендований діаметр', c.recommendedPipeDiameter]);
    }
    if (c.deltaTSystemK != null) {
      rows.push(['ΔT системи', `${c.deltaTSystemK} K`]);
    }
    const pump = hydraulics.proposal?.pumps[0] ?? hydraulics.proposal?.pump ?? null;
    if (pump) {
      const label = [pump.brand, pump.model].filter(Boolean).join(' ');
      if (label) rows.push(['Насос', label]);
    }
    parts.push(kvTable('Гідравліка', rows));
  }

  if (Array.isArray(calcReport.warnings) && calcReport.warnings.length > 0) {
    const warns = calcReport.warnings.filter((w): w is string => typeof w === 'string');
    if (warns.length > 0) {
      parts.push(
        `<h3>Попередження</h3><ul>${warns
          .slice(0, 40)
          .map((w) => `<li>${escapeHtml(w)}</li>`)
          .join('')}</ul>`,
      );
    }
  }

  if (parts.length === 0) return '';
  return `<h2>Технічний розрахунок</h2>${parts.join('\n')}`;
}

/**
 * Назначение: Нормализация kind пресетов.
 * Описание: Приведение kind к каноническому виду и сортировка стен для отображения.
 */

import type { EnvelopePreset, EnvelopePresetKind } from '../types/envelope';

const KNOWN: ReadonlySet<string> = new Set(['wall', 'window', 'ceiling', 'floor', 'roof', 'insulation']);

/**
 * Сортировка пресетов стен для UI: по подписи материала (только несущий слой).
 */
export function sortWallPresetsForDisplay(presets: EnvelopePreset[]): EnvelopePreset[] {
  return [...presets].sort((a, b) => {
    const la = (a.material || a.construction || a.id).trim();
    const lb = (b.material || b.construction || b.id).trim();
    return la.localeCompare(lb, 'ru', { sensitivity: 'base' });
  });
}

/**
 * Нормализует kind пресета для фильтрации в UI.
 * Если поле kind отсутствует или нестандартно, пытаемся вывести его из id или construction.
 */
export function envelopePresetKindNormalized(p: Partial<EnvelopePreset> & { id?: string }): EnvelopePresetKind {
  const raw = (typeof p.kind === 'string' ? p.kind : '')
    .trim()
    .toLowerCase();
  if (KNOWN.has(raw)) return raw as EnvelopePresetKind;

  const id = (typeof p.id === 'string' ? p.id : '').toLowerCase();
  if (id.startsWith('insul_')) return 'insulation';
  if (id.startsWith('window_')) return 'window';
  if (id.startsWith('wall_')) return 'wall';
  if (id.startsWith('floor_')) return 'floor';
  if (id.startsWith('ceiling_')) return 'ceiling';
  if (id.startsWith('roof_')) return 'roof';

  const c = (typeof p.construction === 'string' ? p.construction : '').toLowerCase();
  if (c.includes('окно')) return 'window';
  if (c.includes('потолок')) return 'ceiling';
  if (c === 'пол' || c.startsWith('пол ')) return 'floor';
  if (c.includes('кровл') || c.includes('покрыт') || c.includes('мансард')) return 'roof';
  if (c.includes('стен')) return 'wall';

  if (id.includes('window')) return 'window';
  if (id.includes('floor')) return 'floor';
  if (id.includes('ceiling')) return 'ceiling';
  if (id.includes('roof')) return 'roof';
  if (id.includes('wall')) return 'wall';

  return 'wall';
}

/**
 * Назначение: Сводка наружных стен объекта.
 * Описание: Краткий текст для блока комнат из objectMeta.externalWalls.
 */

import type { EnvelopePreset, ObjectMetaValue } from '../types/envelope';
import { envelopePresetLabel } from './presetLabel';

/** Краткая подпись наружных стен объекта для блока помещений. */
export function formatExternalWallsSummary(
  objectMeta: ObjectMetaValue,
  wallPresets: EnvelopePreset[],
  insulationPresets: EnvelopePreset[],
): string {
  const ew = objectMeta.externalWalls;
  const wall =
    wallPresets.find((p) => p.id === ew.presetId) ??
    ({ id: ew.presetId, material: ew.presetId, construction: 'стіна' } as EnvelopePreset);
  const parts = [envelopePresetLabel(wall)];
  if (ew.thicknessMm != null) parts.push(`${ew.thicknessMm} мм`);

  const facade = ew.facadeSystem ?? 'none';
  if (facade === 'none') {
    parts.push('без утеплювача');
    return parts.join(', ');
  }

  const insul =
    insulationPresets.find((p) => p.id === ew.insulationPresetId) ??
    (ew.insulationPresetId
      ? ({ id: ew.insulationPresetId, material: ew.insulationPresetId, construction: 'утеплювач' } as EnvelopePreset)
      : null);
  if (facade === 'sftk') parts.push('+ СФТК');
  if (facade === 'ventilated') parts.push('+ вентфасад');
  if (insul) parts.push(envelopePresetLabel(insul));
  if (ew.insulationThicknessMm != null) parts.push(`утепл. ${ew.insulationThicknessMm} мм`);
  return parts.join(', ');
}

/**
 * Назначение: Подписи строк ЭБ/БКН в компактной таблице ГВС.
 * Описание: Участие по схеме котёл/ГВС и данным matching из отчёта.
 */

import type { HotWaterBoilerPowerMatchingScheme } from '../types/heatingMatching';
import {
  SCHEME_BOILER_COMBI_BUFFER_ELECTRIC,
  SCHEME_BOILER_ELECTRIC_SEPARATE,
  SCHEME_BOILER_MAX_COMBI,
  SCHEME_BOILER_SINGLE_BUFFER_ELECTRIC,
  SCHEME_BOILER_SINGLE_INDIRECT_SUM,
} from '../types/heatingMatching';
import type { ParsedIndirectWaterHeaterMatching } from './parsers/parseIndirectWaterHeaterMatchingFromReport';
import type { ParsedWaterHeaterMatching } from './parsers/parseWaterHeaterMatchingFromReport';
import { formatKw, formatLiters } from './format';

export type HotWaterEquipmentKind = 'electric' | 'indirect';

const NOT_PARTICIPATING = 'Не бере участі в розрахунку';
const PENDING = '— (очікується розрахунок)';

/**
 * @param scheme
 * @param kind
 */
export function isHotWaterEquipmentSchemeParticipant(
  scheme: HotWaterBoilerPowerMatchingScheme,
  kind: HotWaterEquipmentKind,
): boolean {
  if (kind === 'electric') {
    return (
      scheme === SCHEME_BOILER_ELECTRIC_SEPARATE
      || scheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC
      || scheme === SCHEME_BOILER_SINGLE_BUFFER_ELECTRIC
    );
  }
  return (
    scheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM
    || scheme === SCHEME_BOILER_MAX_COMBI
  );
}

/**
 * @param matching
 */
function formatElectricMatchingLabel(
  matching: ParsedWaterHeaterMatching,
): string {
  const parts: string[] = [];
  if (matching.requiredTankLiters > 0) {
    parts.push(`${formatLiters(matching.requiredTankLiters)} л`);
  }
  if (matching.hasCatalogSelection) {
    if (matching.selectedModel != null) parts.push(matching.selectedModel);
    if (matching.volumeLiters != null) {
      parts.push(`${formatLiters(matching.volumeLiters)} л (каталог)`);
    }
    if (matching.powerKw != null) {
      parts.push(`${formatKw(matching.powerKw)} кВт`);
    }
  }
  if (parts.length === 0 && matching.warnings.length > 0) {
    return matching.warnings[0] ?? 'Підбір без позиції каталогу';
  }
  return parts.length > 0 ? parts.join(' · ') : 'Підбір виконано';
}

/**
 * @param matching
 */
function formatIndirectMatchingLabel(
  matching: ParsedIndirectWaterHeaterMatching,
): string {
  if (matching.skippedReason != null && !matching.hasCatalogSelection) {
    return NOT_PARTICIPATING;
  }
  const parts: string[] = [];
  if (matching.requiredTankLiters > 0) {
    parts.push(`${formatLiters(matching.requiredTankLiters)} л`);
  }
  if (matching.hasCatalogSelection) {
    if (matching.selectedModel != null) parts.push(matching.selectedModel);
    if (matching.volumeLiters != null) {
      parts.push(`${formatLiters(matching.volumeLiters)} л (каталог)`);
    }
    if (matching.effectiveHeatPowerKw != null) {
      parts.push(`${formatKw(matching.effectiveHeatPowerKw)} кВт`);
    }
  }
  if (parts.length === 0 && matching.warnings.length > 0) {
    return matching.warnings[0] ?? 'Підбір без позиції каталогу';
  }
  return parts.length > 0 ? parts.join(' · ') : 'Підбір виконано';
}

/**
 * @param args
 * @param args.kind
 * @param args.scheme
 * @param args.matching
 * @param args.hasReport
 */
export function resolveHotWaterEquipmentRowLabel(args: {
  kind: HotWaterEquipmentKind;
  scheme: HotWaterBoilerPowerMatchingScheme;
  matching: ParsedWaterHeaterMatching | ParsedIndirectWaterHeaterMatching | null;
  hasReport: boolean;
}): string {
  const { kind, scheme, matching, hasReport } = args;

  if (!hasReport) {
    if (!isHotWaterEquipmentSchemeParticipant(scheme, kind)) {
      return NOT_PARTICIPATING;
    }
    return PENDING;
  }

  if (kind === 'electric') {
    const electric = matching as ParsedWaterHeaterMatching | null;
    const schemeUsesElectric = isHotWaterEquipmentSchemeParticipant(
      scheme,
      'electric',
    );
    // Поза схемами з ЕВН показуємо ЕБ лише при реальному fallback (модель або warnings).
    // «Голі» requiredTankLiters без підбору — не участь (баг дзеркала літрів при 1К+БКН).
    const hasRealElectricMatch =
      electric != null
      && (electric.hasCatalogSelection || electric.warnings.length > 0);
    if (!schemeUsesElectric && !hasRealElectricMatch) {
      return NOT_PARTICIPATING;
    }
    if (electric == null) {
      return schemeUsesElectric ? PENDING : NOT_PARTICIPATING;
    }
    return formatElectricMatchingLabel(electric);
  }

  const indirect = matching as ParsedIndirectWaterHeaterMatching | null;
  if (
    !isHotWaterEquipmentSchemeParticipant(scheme, 'indirect')
    && (indirect == null || indirect.skippedReason != null)
  ) {
    return NOT_PARTICIPATING;
  }
  if (indirect == null) {
    return isHotWaterEquipmentSchemeParticipant(scheme, 'indirect')
      ? PENDING
      : NOT_PARTICIPATING;
  }
  return formatIndirectMatchingLabel(indirect);
}

/**
 * @param electric
 * @param indirect
 */
export function hasHotWaterEquipmentWarnings(
  electric: ParsedWaterHeaterMatching | null,
  indirect: ParsedIndirectWaterHeaterMatching | null,
): boolean {
  return (electric?.warnings.length ?? 0) > 0
    || (indirect?.warnings.length ?? 0) > 0;
}

/**
 * Назначение: Нормализация поля underfloorHeating в комнатах.
 * Описание: Миграция legacy presetId → basePresetId + finishMaterialId.
 */

import { DEFAULT_UNDERFLOOR_HEATING_BASE_ID } from '../data/fallbackUnderfloorHeatingPresets';
import { DEFAULT_FLOORING_FINISH_ID } from '../data/fallbackFlooringFinishes';
import type {
  RoomFormValue,
  UfhPipeSpacingMm,
  UfhTerminalControl,
} from '../types/rooms';
import { DEFAULT_UFH_PIPE_SPACING_MM } from '../types/underfloorHeating';
import { isRecord } from './jsonGuards';
import { warnCompatMigration } from './compatTelemetry';

/** Миграция устаревших монолитных presetId → base + finish (только compat). */
const LEGACY_MONOLITHIC_UFH_PRESET_MAP: Record<
  string,
  { basePresetId: string; finishMaterialId: string }
> = {
  underfloor_heating_glued_pvc_quartz_vinyl_interstory: {
    basePresetId: DEFAULT_UNDERFLOOR_HEATING_BASE_ID,
    finishMaterialId: 'pvc_glue',
  },
  underfloor_heating_floating_quartz_vinyl_interstory: {
    basePresetId: DEFAULT_UNDERFLOOR_HEATING_BASE_ID,
    finishMaterialId: 'pvc_click',
  },
};

export function migrateRoomUnderfloorHeating(rooms: RoomFormValue[]): RoomFormValue[] {
  const next = rooms.map((room) => {
    const ufh = room.underfloorHeating;
    if (!ufh) return room;
    if (!ufh.enabled) {
      const { underfloorHeating: _removed, ...rest } = room;
      return rest;
    }

    let basePresetId =
      typeof ufh.basePresetId === 'string' ? ufh.basePresetId.trim() : '';
    let finishMaterialId =
      typeof ufh.finishMaterialId === 'string' ? ufh.finishMaterialId.trim() : '';

    // Совместимость: монолитный presetId читаем через Record, без deprecated-поля типа.
    const ufhRaw = ufh as unknown;
    const legacyPresetRaw =
      isRecord(ufhRaw) && typeof ufhRaw.presetId === 'string' ? ufhRaw.presetId.trim() : '';
    if ((!basePresetId || !finishMaterialId) && legacyPresetRaw) {
      const mapped = LEGACY_MONOLITHIC_UFH_PRESET_MAP[legacyPresetRaw];
      if (mapped) {
        basePresetId = mapped.basePresetId;
        finishMaterialId = mapped.finishMaterialId;
        warnCompatMigration(
          'RoomUfhPreset',
          `${legacyPresetRaw} → base+finish (roomId=${room.id})`,
        );
      }
    }

    if (!basePresetId) basePresetId = DEFAULT_UNDERFLOOR_HEATING_BASE_ID;
    if (!finishMaterialId) finishMaterialId = DEFAULT_FLOORING_FINISH_ID;

    const rawSpacing = ufh.pipeSpacingMm;
    const pipeSpacingMm: UfhPipeSpacingMm =
      rawSpacing === 100 || rawSpacing === 150 || rawSpacing === 200
        ? rawSpacing
        : DEFAULT_UFH_PIPE_SPACING_MM;

    const terminalRaw = ufh.ufhTerminalControl;
    const ufhTerminalControl: UfhTerminalControl | undefined =
      terminalRaw === 'unibox' ? 'unibox' : undefined;

    const furnitureOccupiedAreaM2 = ufh.furnitureOccupiedAreaM2;

    const normalized = {
      enabled: true as const,
      basePresetId,
      finishMaterialId,
      pipeSpacingMm,
      ...(furnitureOccupiedAreaM2 !== undefined
        ? { furnitureOccupiedAreaM2 }
        : {}),
      ...(ufhTerminalControl ? { ufhTerminalControl } : {}),
    };

    if (
      ufh.basePresetId === normalized.basePresetId &&
      ufh.finishMaterialId === normalized.finishMaterialId &&
      ufh.pipeSpacingMm === normalized.pipeSpacingMm &&
      ufh.ufhTerminalControl === normalized.ufhTerminalControl &&
      ufh.furnitureOccupiedAreaM2 === normalized.furnitureOccupiedAreaM2 &&
      !('presetId' in ufh)
    ) {
      return room;
    }

    return {
      ...room,
      underfloorHeating: normalized,
    };
  });
  return next.some((r, i) => r !== rooms[i]) ? next : rooms;
}

/**
 * Назначение: Нормализация snapshot черновика анкеты.
 * Описание: Единственная точка входа при загрузке из файла, MongoDB и hash-URL.
 */

import { isSurveyStep } from '../constants/surveySteps';
import type { ObjectMetaValue } from '../types/envelope';
import type { HeatingThermalRegimePreset } from '../types/heatingThermalRegime';
import { isDeprecatedHeatingThermalRegimePreset } from '../types/heatingThermalRegime';
import { normalizeRadiatorConnection } from '../types/radiatorConnection';
import { normalizeRadiatorEmitterPreference } from '../types/radiatorEmitterPreference';
import type { LegacyWiringBranch } from '../types/surveyDraftCompat';
import {
  SURVEY_DRAFT_SCHEMA_VERSION,
  type SurveyDraft,
} from '../types/surveyDraft';
import {
  isUfhDistributionPreset,
  type UfhDistributionPreset,
} from '../types/ufhDistribution';
import type { RoomFormValue } from '../types/rooms';
import {
  adaptFlatRoomsToWiringLayout,
  type WiringLayoutV3,
} from '../surveySession/wiringLayoutV3';
import { warnCompatMigration } from './compatTelemetry';
import { isRecord, readRecordField } from './jsonGuards';
import { migrateObjectMetaExternalWalls } from './migrateLegacyExternalWalls';
import { migrateLegacyRoomTypes } from './migrateLegacyRoomTypes';
import { migrateRoomUnderfloorHeating } from './migrateRoomUnderfloorHeating';
import { normalizeHotWaterForm } from './normalizeHotWaterForm';
import { normalizeWaterHeaterForm } from './normalizeWaterHeaterForm';
import { migrateRoomEnvelopeFields } from './roomEnvelopeFields';
import { isUfhModePresetId } from './ufhPresetCardsForUi';
import {
  DEFAULT_HYDRAULICS_FORM,
  type HydraulicsFormValue,
} from '../types/hydraulics';

/** Строка из неизвестного JSON-поля (объекты не stringify). */
function readJsonString(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value : fallback;
}

/**
 * Нормализует сохранённый snapshot в текущий контракт SurveyDraft.
 */
export function migrateSurveyDraft(raw: unknown): SurveyDraft {
  if (!isRecord(raw)) {
    throw new Error('Файл проєкту: очікується JSON-об\'єкт');
  }
  if (!isRecord(raw.objectMeta) || !Array.isArray(raw.rooms) || !isRecord(raw.temps)) {
    throw new Error('Файл проєкту: неповний чернетка анкети');
  }

  const storedVersion = Number(raw.schemaVersion);
  if (Number.isFinite(storedVersion) && storedVersion > SURVEY_DRAFT_SCHEMA_VERSION) {
    throw new Error(
      `Непідтримувана schemaVersion: ${storedVersion} (максимум ${SURVEY_DRAFT_SCHEMA_VERSION})`,
    );
  }

  if (Number.isFinite(storedVersion) && storedVersion < SURVEY_DRAFT_SCHEMA_VERSION) {
    warnCompatMigration(
      'SurveyDraftLoad',
      `schemaVersion ${storedVersion} → ${SURVEY_DRAFT_SCHEMA_VERSION}`,
    );
  }

  const rawMeta = raw.objectMeta;
  const { indirectDhwSpaceAvailable: indirectFromMeta, ...metaRest } = rawMeta;

  if (
    raw.hotWaterBoilerPowerMatchingScheme != null ||
    indirectFromMeta != null
  ) {
    warnCompatMigration('SurveyDraftLoad', 'корневые поля ГВС/БКН → waterHeaterForm');
  }

  const waterHeaterForm = normalizeWaterHeaterForm(
    isRecord(raw.waterHeaterForm)
      ? raw.waterHeaterForm
      : {
          hotWaterBoilerPowerMatchingScheme: raw.hotWaterBoilerPowerMatchingScheme,
          indirectDhwSpaceAvailable: indirectFromMeta,
        },
  );

  const objectMeta: ObjectMetaValue = {
    ...(metaRest as ObjectMetaValue),
    externalWalls: migrateObjectMetaExternalWalls(
      (() => {
        const ew = readRecordField(rawMeta, 'externalWalls');
        if (ew && typeof ew.presetId === 'string') {
          return ew as ObjectMetaValue['externalWalls'];
        }
        return {
          presetId: 'wall_gas_concrete_d500',
          facadeSystem: 'none' as const,
        };
      })(),
    ),
  };

  const rooms = migrateRoomUnderfloorHeating(
    migrateRoomEnvelopeFields(migrateLegacyRoomTypes(raw.rooms as RoomFormValue[])),
  );

  const clientName =
    typeof raw.clientName === 'string' && raw.clientName.trim()
      ? raw.clientName.trim()
      : 'Без імені';

  const thermalRegimePreset = (() => {
    const preset = readJsonString(raw.thermalRegimePreset) as HeatingThermalRegimePreset;
    if (isDeprecatedHeatingThermalRegimePreset(preset)) {
      warnCompatMigration('SurveyDraftLoad', `thermalRegimePreset ${preset} → traditional_dt50_75_65`);
      return 'traditional_dt50_75_65' satisfies HeatingThermalRegimePreset;
    }
    return preset;
  })();

  return {
    schemaVersion: SURVEY_DRAFT_SCHEMA_VERSION,
    savedAt: typeof raw.savedAt === 'string' ? raw.savedAt : new Date().toISOString(),
    clientName,
    ...(typeof raw.projectId === 'string' ? { projectId: raw.projectId } : {}),
    currentStep: (() => {
      // Compat: пустой шаг «Итог» (summary) → «Итог финансовый».
      if (raw.currentStep === 'summary') {
        warnCompatMigration('SurveyDraftLoad', 'currentStep summary → financialResult');
        return 'financialResult';
      }
      return isSurveyStep(raw.currentStep) ? raw.currentStep : 'object';
    })(),
    objectMeta,
    rooms,
    temps: {
      insideC: Number(raw.temps.insideC) || 20,
      outsideC: Number(raw.temps.outsideC) || -5,
      ...(typeof raw.temps.bathroomAirTempC === 'number' &&
      Number.isFinite(raw.temps.bathroomAirTempC) &&
      raw.temps.bathroomAirTempC >= 24
        ? { bathroomAirTempC: raw.temps.bathroomAirTempC }
        : {}),
    },
    hotWaterForm: normalizeHotWaterForm(raw.hotWaterForm),
    waterHeaterForm,
    waterUnderfloorHeating: Boolean(raw.waterUnderfloorHeating),
    underfloorDistributionPreset: (() => {
      const v = readJsonString(raw.underfloorDistributionPreset, 'auto');
      return isUfhDistributionPreset(v) ? v : ('auto' satisfies UfhDistributionPreset);
    })(),
    thermalRegimePreset,
    radiatorConnection: normalizeRadiatorConnection(
      raw.radiatorConnection,
    ),
    radiatorEmitterPreference: normalizeRadiatorEmitterPreference(
      raw.radiatorEmitterPreference,
    ),
    ufhPresetId: (() => {
      const id = readJsonString(raw.ufhPresetId).trim();
      if (!id) return null;
      if (id === 'ufh_direct_tile' || id === 'ufh_direct_laminate') {
        warnCompatMigration('SurveyDraftLoad', `${id} → ufh_mixed_radiators`);
        return 'ufh_mixed_radiators';
      }
      return isUfhModePresetId(id) ? id : null;
    })(),
    hydraulicsForm: (() => {
      if (!isRecord(raw.hydraulicsForm)) {
        if (raw.hydraulicsForm != null) {
          warnCompatMigration('SurveyDraftLoad', 'hydraulicsForm → DEFAULT_HYDRAULICS_FORM');
        }
        return { ...DEFAULT_HYDRAULICS_FORM };
      }
      const h = raw.hydraulicsForm;
      const prefRaw = h.pipeMaterialPreference;
      const pipeMaterialPreference: HydraulicsFormValue['pipeMaterialPreference'] =
        prefRaw === 'pex' || prefRaw === 'metal_plastic' || prefRaw === 'steel'
          ? prefRaw
          : '';
      return {
        mainLineLengthM:
          typeof h.mainLineLengthM === 'number' && h.mainLineLengthM >= 0
            ? h.mainLineLengthM
            : DEFAULT_HYDRAULICS_FORM.mainLineLengthM,
        deltaTSystemK:
          typeof h.deltaTSystemK === 'number' && h.deltaTSystemK > 0
            ? h.deltaTSystemK
            : DEFAULT_HYDRAULICS_FORM.deltaTSystemK,
        pipeMaterialPreference,
      } satisfies HydraulicsFormValue;
    })(),
    wiringLayoutV3: (() => {
      if (isRecord(raw.wiringLayoutV3) && raw.wiringLayoutV3.schemaVersion === 3) {
        const wl = raw.wiringLayoutV3 as WiringLayoutV3 & {
          branches?: LegacyWiringBranch[];
        };
        const branches: LegacyWiringBranch[] = Array.isArray(wl.branches)
          ? wl.branches
          : [];
        const hasLegacyBranchLength = branches.some(
          (b) =>
            b.estimatedLengthM != null &&
            b.pipeLengthToEquipmentM == null,
        );
        if (hasLegacyBranchLength) {
          warnCompatMigration('WiringLayoutV3', 'estimatedLengthM → pipeLengthToEquipmentM');
        }
        return {
          ...wl,
          branches: branches.map((b) => ({
            roomId: b.roomId,
            pipeLengthToEquipmentM:
              typeof b.pipeLengthToEquipmentM === 'number'
                ? b.pipeLengthToEquipmentM
                : typeof b.estimatedLengthM === 'number'
                  ? b.estimatedLengthM
                  : 4,
          })),
        } satisfies WiringLayoutV3;
      }
      if (raw.wiringLayoutV3 != null) {
        warnCompatMigration('WiringLayoutV3', 'rebuild from rooms (schemaVersion ≠ 3)');
      }
      return adaptFlatRoomsToWiringLayout(rooms, 'auto');
    })(),
    lastCalcReport: (isRecord(raw.lastCalcReport)
      ? raw.lastCalcReport
      : null),
  };
}

/**
 * Назначение: Парсинг блока котла из отчёта.
 * Описание: Разбор matching.boiler, selected и tier economy/efficient для UI.
 */

import { parseBoilerProposalPayload } from '../boilerProposalParse';
import { readRecordField, readStringArray } from '../jsonGuards';
import {
  SCHEME_BOILER_MAX_COMBI,
  type HotWaterBoilerPowerMatchingScheme,
} from '../../types/heatingMatching';

/** Проверка, является ли строка допустимой схемой котла (импортируется из App.tsx). */
type IsCalcMatchingScheme = (v: string) => v is HotWaterBoilerPowerMatchingScheme;

export type ParsedBoilerSummary = {
  heatLossKw: number;
  reserveFactor: number;
  heatingLoadKw: number;
  hotWaterPowerKw: number;
  requiredKw: number;
  hotWaterBoilerPowerMatchingScheme: HotWaterBoilerPowerMatchingScheme;
  heatingLoadKwCondensing: number | null;
  requiredKwForCondensingLine: number | null;
  condensingHeatingReserveFactor: number | null;
};

export type ParsedBoilerMatching = {
  summary: ParsedBoilerSummary | null;
  tierEconomy: ReturnType<typeof parseBoilerProposalPayload>;
  tierEfficient: ReturnType<typeof parseBoilerProposalPayload>;
  legacyProposal: ReturnType<typeof parseBoilerProposalPayload>;
  warnings: string[];
};

/**
 * Витягує блок matching.boiler з повного JSON-звіту POST /api/v1/calc.
 * Повертає null, якщо блок відсутній.
 */
export function parseBoilerFromReport(
  calcReport: unknown,
  isCalcMatchingScheme: IsCalcMatchingScheme,
): ParsedBoilerMatching | null {
  if (calcReport === null || calcReport === undefined) return null;
  const matching = readRecordField(calcReport as Record<string, unknown>, 'matching');
  if (!matching) return null;
  const b = readRecordField(matching, 'boiler');
  if (!b) return null;

  const heatLossKw =
    typeof b.heatLossKw === 'number' && Number.isFinite(b.heatLossKw) ? b.heatLossKw : null;
  const reserveFactor =
    typeof b.reserveFactor === 'number' && Number.isFinite(b.reserveFactor) ? b.reserveFactor : null;
  const hotWaterPowerKw =
    typeof b.hotWaterPowerKw === 'number' && Number.isFinite(b.hotWaterPowerKw)
      ? b.hotWaterPowerKw
      : null;
  const requiredKw =
    typeof b.requiredKw === 'number' && Number.isFinite(b.requiredKw) ? b.requiredKw : null;
  const heatingLoadKw =
    typeof b.heatingLoadKw === 'number' && Number.isFinite(b.heatingLoadKw) ? b.heatingLoadKw : null;

  const schemeRaw = b.hotWaterBoilerPowerMatchingScheme;
  const schemeParsed: HotWaterBoilerPowerMatchingScheme | null =
    typeof schemeRaw === 'string' && isCalcMatchingScheme(schemeRaw) ? schemeRaw : null;
  const schemeForSummary: HotWaterBoilerPowerMatchingScheme = schemeParsed ?? SCHEME_BOILER_MAX_COMBI;

  const heatingLoadKwCondensing =
    typeof b.heatingLoadKwCondensing === 'number' && Number.isFinite(b.heatingLoadKwCondensing)
      ? b.heatingLoadKwCondensing
      : null;
  const requiredKwForCondensingLine =
    typeof b.requiredKwForCondensingLine === 'number' && Number.isFinite(b.requiredKwForCondensingLine)
      ? b.requiredKwForCondensingLine
      : null;
  const condensingHeatingReserveFactor =
    typeof b.condensingHeatingReserveFactor === 'number' &&
    Number.isFinite(b.condensingHeatingReserveFactor)
      ? b.condensingHeatingReserveFactor
      : null;

  let summary: ParsedBoilerSummary | null = null;
  if (heatLossKw != null && reserveFactor != null && hotWaterPowerKw != null && requiredKw != null) {
    summary = {
      heatLossKw,
      reserveFactor,
      heatingLoadKw: heatingLoadKw ?? heatLossKw * reserveFactor,
      hotWaterPowerKw,
      requiredKw,
      hotWaterBoilerPowerMatchingScheme: schemeForSummary,
      heatingLoadKwCondensing,
      requiredKwForCondensingLine,
      condensingHeatingReserveFactor,
    };
  }

  return {
    summary,
    tierEconomy: parseBoilerProposalPayload(b.proposalEconomy),
    tierEfficient: parseBoilerProposalPayload(b.proposalEfficient),
    legacyProposal: parseBoilerProposalPayload(b.proposal),
    warnings: readStringArray(b.warnings),
  };
}

/**
 * Назначение: парсинг report.commercial для шага «Итог финансовый».
 */

import { isRecord, readRecordField } from '../jsonGuards';

export type FinancialBomLineKind = 'equipment' | 'labor' | 'consumable' | 'note';
export type FinancialBomQtyUnit = 'pcs' | 'm' | 'section' | 'lot';
export type FinancialBomCategoryId =
  | 'boiler_room'
  | 'radiators'
  | 'ufh'
  | 'hydraulics_heating'
  | 'works';

export type ParsedFinancialBomLine = {
  id: string;
  kind: FinancialBomLineKind;
  objectType: 'house' | 'apartment';
  equipmentTypeLabel: string;
  brand: string;
  model: string;
  qty: number;
  qtyUnit: FinancialBomQtyUnit;
  unitPriceUah: number | null;
  lineTotalUah: number | null;
  scopePath: string[];
  categoryId: FinancialBomCategoryId;
  catalogId?: string;
  source: string;
  note?: string;
};

export type ParsedCommercialBom = {
  schemaVersion: 1;
  currency: 'UAH';
  lines: ParsedFinancialBomLine[];
  totals: {
    equipmentQtyPcs: number;
    equipmentTotalUah: number;
    laborTotalUah: number;
    consumablesTotalUah: number;
    grandTotalUah: number;
  };
  rates: {
    laborPercentOfEquipment: number;
    consumablesPercentOfEquipment: number;
  };
};

const KINDS = new Set<string>(['equipment', 'labor', 'consumable', 'note']);
const QTY_UNITS = new Set<string>(['pcs', 'm', 'section', 'lot']);
const CATEGORIES = new Set<string>([
  'boiler_room',
  'radiators',
  'ufh',
  'hydraulics_heating',
  'works',
]);

/**
 * @param {unknown} v
 * @returns {number}
 */
function num(v: unknown, fallback = 0): number {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

/**
 * @param {unknown} v
 * @returns {string}
 */
function str(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

/**
 * @param {unknown} raw
 * @returns {ParsedFinancialBomLine | null}
 */
function parseLine(raw: unknown): ParsedFinancialBomLine | null {
  if (!isRecord(raw)) return null;
  const id = str(raw.id);
  const kind = str(raw.kind);
  const qtyUnit = str(raw.qtyUnit);
  const categoryId = str(raw.categoryId);
  const model = str(raw.model);
  if (!id || !KINDS.has(kind) || !QTY_UNITS.has(qtyUnit) || !CATEGORIES.has(categoryId)) {
    return null;
  }
  if (!model && kind !== 'note') return null;

  const objectType = raw.objectType === 'apartment' ? 'apartment' : 'house';
  const scopePath = Array.isArray(raw.scopePath)
    ? raw.scopePath.filter((s): s is string => typeof s === 'string' && s.trim().length > 0)
    : [];
  if (scopePath.length === 0) return null;

  const unitPriceRaw = raw.unitPriceUah;
  const lineTotalRaw = raw.lineTotalUah;
  const catalogId = str(raw.catalogId);
  const note = str(raw.note);

  return {
    id,
    kind: kind as FinancialBomLineKind,
    objectType,
    equipmentTypeLabel: str(raw.equipmentTypeLabel) || 'Позиция',
    brand: str(raw.brand),
    model: model || str(raw.note) || '—',
    qty: Math.max(0, num(raw.qty)),
    qtyUnit: qtyUnit as FinancialBomQtyUnit,
    unitPriceUah:
      typeof unitPriceRaw === 'number' && Number.isFinite(unitPriceRaw)
        ? unitPriceRaw
        : null,
    lineTotalUah:
      typeof lineTotalRaw === 'number' && Number.isFinite(lineTotalRaw)
        ? lineTotalRaw
        : null,
    scopePath,
    categoryId: categoryId as FinancialBomCategoryId,
    ...(catalogId ? { catalogId } : {}),
    source: str(raw.source) || 'commercial',
    ...(note ? { note } : {}),
  };
}

/**
 * Извлекает report.commercial из JSON-отчёта calc.
 *
 * @param calcReport
 */
export function parseCommercialBomFromReport(
  calcReport: unknown,
): ParsedCommercialBom | null {
  if (calcReport == null) return null;
  if (!isRecord(calcReport)) return null;
  const commercial = readRecordField(calcReport, 'commercial');
  if (!commercial) return null;

  const linesRaw = commercial.lines;
  if (!Array.isArray(linesRaw)) return null;

  const lines: ParsedFinancialBomLine[] = [];
  for (const item of linesRaw) {
    const parsed = parseLine(item);
    if (parsed) lines.push(parsed);
  }

  const totalsRaw = readRecordField(commercial, 'totals');
  const ratesRaw = readRecordField(commercial, 'rates');
  if (!totalsRaw || !ratesRaw) return null;

  return {
    schemaVersion: 1,
    currency: 'UAH',
    lines,
    totals: {
      equipmentQtyPcs: num(totalsRaw.equipmentQtyPcs),
      equipmentTotalUah: num(totalsRaw.equipmentTotalUah),
      laborTotalUah: num(totalsRaw.laborTotalUah),
      consumablesTotalUah: num(totalsRaw.consumablesTotalUah),
      grandTotalUah: num(totalsRaw.grandTotalUah),
    },
    rates: {
      laborPercentOfEquipment: num(ratesRaw.laborPercentOfEquipment, 40),
      consumablesPercentOfEquipment: num(
        ratesRaw.consumablesPercentOfEquipment,
        15,
      ),
    },
  };
}

/**
 * Назначение: Парсинг calculations.hotWater из отчёта POST /api/v1/calc.
 * Описание: Полный блок ГВС для карты «Горячая вода» и сайдбара.
 */

import type { ParsedHotWaterReport } from '../../types/hotWaterReport';
import { isRecord, readRecordField } from '../jsonGuards';

/**
 * @param value
 */
function readFiniteNumber(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

/**
 * @param calcReport
 * @returns {ParsedHotWaterReport | null}
 */
export function parseHotWaterFromReport(
  calcReport: unknown,
): ParsedHotWaterReport | null {
  if (!isRecord(calcReport)) return null;
  const calculations = readRecordField(calcReport, 'calculations');
  if (!calculations) return null;
  const hotWater = readRecordField(calculations, 'hotWater');
  if (!hotWater) return null;

  const peakFlowLps = readFiniteNumber(hotWater.peakFlowLps);
  const hotWaterPowerKw = readFiniteNumber(hotWater.hotWaterPowerKw);
  if (peakFlowLps == null || hotWaterPowerKw == null) return null;

  const dhwRaw = hotWater.dhwSupplyScenario;
  const dhwSupplyScenario =
    dhwRaw === 'flowThrough' || dhwRaw === 'storage' ? dhwRaw : null;

  const objectTypeRaw = hotWater.objectType;
  const objectType =
    objectTypeRaw === 'apartment' || objectTypeRaw === 'house'
      ? objectTypeRaw
      : null;

  const coldSeasonRaw = hotWater.coldWaterDesignSeason;
  const coldWaterDesignSeason =
    coldSeasonRaw === 'winter' || coldSeasonRaw === 'summer'
      ? coldSeasonRaw
      : null;

  return {
    peakFlowLps,
    hotWaterPowerKw,
    peakThermalPowerKw: readFiniteNumber(hotWater.peakThermalPowerKw),
    dhwSupplyScenario,
    recommendedTankLiters: readFiniteNumber(hotWater.recommendedTankLiters),
    simultaneityFactor: readFiniteNumber(hotWater.simultaneityFactor),
    sumFlowLpsRaw: readFiniteNumber(hotWater.sumFlowLpsRaw),
    objectType,
    residents: readFiniteNumber(hotWater.residents),
    tropicalShower:
      typeof hotWater.tropicalShower === 'boolean' ? hotWater.tropicalShower : null,
    coldWaterDesignSeason,
    designColdWaterC: readFiniteNumber(hotWater.designColdWaterC),
    hotWaterC: readFiniteNumber(hotWater.hotWaterC),
    deltaTK: readFiniteNumber(hotWater.deltaTK),
    normsSchemaVersion: readFiniteNumber(hotWater.normsSchemaVersion),
    simultaneityBaseNorm: readFiniteNumber(hotWater.simultaneityBaseNorm),
    storageTankLitersPerPersonBasis: readFiniteNumber(
      hotWater.storageTankLitersPerPersonBasis,
    ),
    storageHeatTimeMinutes: readFiniteNumber(hotWater.storageHeatTimeMinutes),
    storageIndirectHeatPowerKw: readFiniteNumber(hotWater.storageIndirectHeatPowerKw),
    sessionDemandLitersMixed: readFiniteNumber(hotWater.sessionDemandLitersMixed),
    dhwEquivalentTankLitersFromSession: readFiniteNumber(
      hotWater.dhwEquivalentTankLitersFromSession,
    ),
    dhwTankLitersCombinedRaw: readFiniteNumber(hotWater.dhwTankLitersCombinedRaw),
  };
}

/**
 * Назначение: парсинг гидравлики из полного отчёта calc API.
 * Описание: matching.hydraulics.proposal, calculations.hydraulics и контекст flowDeltaTK.
 */

import type {
  ParsedHydraulicsCalculations,
  ParsedHydraulicsFlowContext,
  ParsedHydraulicsView,
} from '../../types/hydraulics';
import { isRecord, readRecordField, readStringArray } from '../jsonGuards';
import { parseHydraulicsProposalFromReport } from './parseHydraulicsProposalFromReport';

function num(v: unknown): number | null {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function parseCalculations(raw: unknown): ParsedHydraulicsCalculations | null {
  if (!isRecord(raw)) return null;
  const flowRateM3PerHour = num(raw.flowRateM3PerHour);
  const pressure = isRecord(raw.pressure) ? raw.pressure : null;
  const headFromPressure =
    pressure && typeof pressure.headRequiredM === 'number'
      ? pressure.headRequiredM
      : null;
  const headRequiredM = headFromPressure ?? 0;
  if (flowRateM3PerHour == null && headRequiredM <= 0) return null;

  const inputs = isRecord(raw.inputs) ? raw.inputs : null;
  const notes = Array.isArray(raw.notes)
    ? raw.notes.filter((n): n is string => typeof n === 'string')
    : [];

  return {
    flowRateM3PerHour: flowRateM3PerHour ?? 0,
    headRequiredM,
    deltaTSystemK: inputs ? num(inputs.deltaTSystemK) : null,
    mainLineLengthM: inputs ? num(inputs.mainLineLengthM) : null,
    recommendedPipeDiameter:
      typeof raw.recommendedPipeDiameter === 'string' && raw.recommendedPipeDiameter
        ? raw.recommendedPipeDiameter
        : null,
    notes,
  };
}

function parseFlowContextFromRadiators(radiators: Record<string, unknown>): ParsedHydraulicsFlowContext | null {
  const inputs = isRecord(radiators.inputs) ? radiators.inputs : null;
  if (!inputs) return null;

  const supplyC = num(inputs.supplyC);
  const returnC = num(inputs.returnC);
  const flowDeltaTK = num(inputs.flowDeltaTK);
  const thermalRegimeDeltaTK =
    supplyC != null && returnC != null
      ? Math.round((supplyC - returnC) * 100) / 100
      : null;

  if (flowDeltaTK == null && thermalRegimeDeltaTK == null && supplyC == null) {
    return null;
  }

  return {
    supplyC,
    returnC,
    thermalRegimeDeltaTK,
    flowDeltaTK,
  };
}

/**
 * @param calcReport Полный JSON report POST /api/v1/calc
 */
export function parseHydraulicsFromReport(calcReport: unknown): ParsedHydraulicsView | null {
  if (!isRecord(calcReport)) return null;

  const calculationsBlock = readRecordField(calcReport, 'calculations');
  const calculationsRaw = calculationsBlock
    ? readRecordField(calculationsBlock, 'hydraulics')
    : null;
  const calculations = parseCalculations(calculationsRaw);

  const matching = readRecordField(calcReport, 'matching');
  const matchingHydraulics = matching ? readRecordField(matching, 'hydraulics') : null;
  const matchingWarnings = matchingHydraulics
    ? readStringArray(matchingHydraulics.warnings)
    : [];

  const proposal = parseHydraulicsProposalFromReport(
    matchingHydraulics,
  );

  let flowContext: ParsedHydraulicsFlowContext | null = null;
  if (matching) {
    const radiators = readRecordField(matching, 'radiators');
    if (radiators) {
      flowContext = parseFlowContextFromRadiators(radiators);
    }
  }

  const hasProposalData =
    proposal != null
    && (proposal.hasPipeSelection
      || proposal.pumps.length > 0
      || proposal.designFlowM3PerHour > 0
      || proposal.headRequiredM > 0
      || proposal.unavailableReason != null);

  const hasData =
    calculations != null
    || hasProposalData
    || matchingWarnings.length > 0
    || (proposal != null && proposal.warnings.length > 0);

  if (!hasData) return null;

  return {
    proposal: hasProposalData ? proposal : null,
    calculations,
    flowContext,
    matchingWarnings,
    hasData: true,
  };
}

/**
 * Назначение: парсинг matching.hydraulics.proposal из отчёта calc API.
 */

import type {
  ParsedHydraulicsPipeLine,
  ParsedHydraulicsPipeLineGroup,
  ParsedHydraulicsPipeSegment,
  ParsedHydraulicsProposal,
  ParsedHydraulicsPumpProposal,
} from '../../types/hydraulics';

/** Fallback-підписи контурів (SSOT API — buildHydraulicsProposal.js). */
const HYDRAULICS_HEATING_CIRCUIT_LABEL = 'Контур опалення (радіатори)';
const HYDRAULICS_UFH_CIRCUIT_LABEL = 'Контур теплої підлоги';

function num(v: unknown, fallback = 0): number {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function str(v: unknown): string {
  return typeof v === 'string' ? v : '';
}

function parsePumpRole(v: unknown): ParsedHydraulicsPumpProposal['pumpRole'] {
  if (v === 'main' || v === 'zone' || v === 'dhw') return v;
  return 'main';
}

function parsePumpSource(v: unknown): ParsedHydraulicsPumpProposal['pumpSource'] {
  if (v === 'catalog' || v === 'boiler_builtin') return v;
  return 'catalog';
}

function parseTopology(
  v: unknown,
): ParsedHydraulicsProposal['topology'] | undefined {
  if (v === 'direct' || v === 'mixing_valve' || v === 'hydraulic_separator') {
    return v;
  }
  return undefined;
}

function parsePump(raw: unknown): ParsedHydraulicsPumpProposal | null {
  if (!raw || typeof raw !== 'object') return null;
  const p = raw as Record<string, unknown>;
  const pumpSource = parsePumpSource(p.pumpSource);
  const catalogPumpId = str(p.catalogPumpId);
  if (pumpSource === 'catalog' && !catalogPumpId) return null;
  if (!str(p.modeName)) return null;

  const segment =
    p.segment === 'premium' || p.segment === 'medium' || p.segment === 'budget'
      ? p.segment
      : undefined;
  const connectionNominalMm =
    typeof p.connectionNominalMm === 'number' ? p.connectionNominalMm : undefined;
  const note = typeof p.note === 'string' ? p.note : undefined;

  return {
    zoneId: str(p.zoneId) || 'boiler_primary',
    zoneLabel: str(p.zoneLabel) || 'Циркуляционный насос',
    pumpRole: parsePumpRole(p.pumpRole),
    pumpSource,
    ...(catalogPumpId ? { catalogPumpId } : {}),
    ...(typeof p.catalogBoilerId === 'string' ? { catalogBoilerId: p.catalogBoilerId } : {}),
    brand: str(p.brand),
    model: str(p.model) || catalogPumpId || str(p.zoneLabel),
    ...(segment !== undefined ? { segment } : {}),
    price: num(p.price),
    modeName: str(p.modeName),
    headAtDesignM: num(p.headAtDesignM),
    headRequiredM: num(p.headRequiredM),
    designFlowM3PerHour: num(p.designFlowM3PerHour),
    headMarginPercent: num(p.headMarginPercent),
    ...(connectionNominalMm !== undefined ? { connectionNominalMm } : {}),
    ...(note !== undefined ? { note } : {}),
  };
}

function parsePipeLine(raw: unknown): ParsedHydraulicsPipeLine | null {
  if (!raw || typeof raw !== 'object') return null;
  const p = raw as Record<string, unknown>;
  const catalogPipeId = str(p.catalogPipeId);
  if (!catalogPipeId) return null;
  return {
    catalogPipeId,
    brand: str(p.brand),
    model: str(p.model) || catalogPipeId,
    material: str(p.material),
    outerDiameterMm: num(p.outerDiameterMm),
    wallThicknessMm: num(p.wallThicknessMm),
    internalDiameterMm: num(p.internalDiameterMm),
    totalLengthM: num(p.totalLengthM),
    edgeCount: Math.max(1, Math.round(num(p.edgeCount, 1))),
    pricePerMeter: num(p.pricePerMeter),
    linePrice: num(p.linePrice),
  };
}

function parsePipeSegment(raw: unknown): ParsedHydraulicsPipeSegment | null {
  if (!raw || typeof raw !== 'object') return null;
  const p = raw as Record<string, unknown>;
  const edgeId = str(p.edgeId);
  if (!edgeId) return null;
  const role = p.segmentRole;
  const segmentRole =
    role === 'main' || role === 'branch' || role === 'ufh_loop' || role === 'dhw'
      ? role
      : 'main';
  return {
    edgeId,
    segmentLabel: str(p.segmentLabel) || edgeId,
    segmentRole,
    lengthM: num(p.lengthM),
    catalogPipeId: str(p.catalogPipeId),
    brand: str(p.brand),
    model: str(p.model) || str(p.catalogPipeId),
    material: str(p.material),
    outerDiameterMm: num(p.outerDiameterMm),
    wallThicknessMm: num(p.wallThicknessMm),
    internalDiameterMm: num(p.internalDiameterMm),
    velocityMps: num(p.velocityMps),
    pressureDropKPa: num(p.pressureDropKPa),
    pricePerMeter: num(p.pricePerMeter),
    linePrice: num(p.linePrice),
    ...(p.velocityLimitExceeded === true ? { velocityLimitExceeded: true } : {}),
    ...(p.velocityBelowMin === true ? { velocityBelowMin: true } : {}),
    ...(p.isMainLine === true ? { isMainLine: true } : {}),
    ...(p.mainTransitGuardApplied === true ? { mainTransitGuardApplied: true } : {}),
    ...(p.catalogPoolExhausted === true ? { catalogPoolExhausted: true } : {}),
    ...(Array.isArray(p.groupedRoomIds) && p.groupedRoomIds.length
      ? { groupedRoomIds: p.groupedRoomIds.map((id) => str(id)) }
      : {}),
  };
}

/**
 * Агрегирует участки в сводные позиции каталога.
 */
function aggregatePipeLinesFromSegments(
  segments: ParsedHydraulicsPipeSegment[],
): ParsedHydraulicsPipeLine[] {
  const map = new Map<string, ParsedHydraulicsPipeLine>();

  for (const seg of segments) {
    const prev = map.get(seg.catalogPipeId);
    if (prev) {
      prev.totalLengthM = Math.round((prev.totalLengthM + seg.lengthM) * 100) / 100;
      prev.edgeCount += 1;
      prev.linePrice = Math.round((prev.linePrice + seg.linePrice) * 100) / 100;
    } else {
      map.set(seg.catalogPipeId, {
        catalogPipeId: seg.catalogPipeId,
        brand: seg.brand,
        model: seg.model,
        material: seg.material,
        outerDiameterMm: seg.outerDiameterMm,
        wallThicknessMm: seg.wallThicknessMm,
        internalDiameterMm: seg.internalDiameterMm,
        totalLengthM: seg.lengthM,
        edgeCount: 1,
        pricePerMeter: seg.pricePerMeter,
        linePrice: seg.linePrice,
      });
    }
  }

  return [...map.values()].sort((a, b) => b.totalLengthM - a.totalLengthM);
}

function buildPipeLineGroupsFromSegments(
  segments: ParsedHydraulicsPipeSegment[],
): ParsedHydraulicsPipeLineGroup[] {
  const defs: Array<{
    circuitId: ParsedHydraulicsPipeLineGroup['circuitId'];
    label: string;
    roles: ParsedHydraulicsPipeSegment['segmentRole'][];
  }> = [
    {
      circuitId: 'heating',
      label: HYDRAULICS_HEATING_CIRCUIT_LABEL,
      roles: ['main', 'branch'],
    },
    {
      circuitId: 'ufh',
      label: HYDRAULICS_UFH_CIRCUIT_LABEL,
      roles: ['ufh_loop'],
    },
  ];

  return defs
    .map((def) => {
      const filtered = segments.filter((s) => def.roles.includes(s.segmentRole));
      const pipeLines = aggregatePipeLinesFromSegments(filtered);
      if (pipeLines.length === 0) return null;
      return {
        circuitId: def.circuitId,
        label: def.label,
        pipeLines,
        estimatedPrice: Math.round(pipeLines.reduce((s, l) => s + l.linePrice, 0) * 100) / 100,
      };
    })
    .filter((g): g is ParsedHydraulicsPipeLineGroup => g != null);
}

function parsePipeLineGroup(raw: unknown): ParsedHydraulicsPipeLineGroup | null {
  if (!raw || typeof raw !== 'object') return null;
  const g = raw as Record<string, unknown>;
  const circuitId = g.circuitId;
  if (circuitId !== 'heating' && circuitId !== 'ufh') return null;
  const pipeLines = (Array.isArray(g.pipeLines) ? g.pipeLines : [])
    .map(parsePipeLine)
    .filter((x): x is ParsedHydraulicsPipeLine => x != null);
  if (pipeLines.length === 0) return null;
  return {
    circuitId,
    label: str(g.label) || (circuitId === 'ufh' ? HYDRAULICS_UFH_CIRCUIT_LABEL : HYDRAULICS_HEATING_CIRCUIT_LABEL),
    pipeLines,
    estimatedPrice: num(g.estimatedPrice),
  };
}

/**
 * @param matchingHydraulics report.matching.hydraulics
 */
export function parseHydraulicsProposalFromReport(
  matchingHydraulics: Record<string, unknown> | null | undefined,
): ParsedHydraulicsProposal | null {
  if (!matchingHydraulics || typeof matchingHydraulics !== 'object') return null;

  const proposalRaw = matchingHydraulics.proposal;
  const warningsRaw = matchingHydraulics.warnings;
  const warnings = Array.isArray(warningsRaw)
    ? warningsRaw.filter((w): w is string => typeof w === 'string')
    : [];

  if (!proposalRaw || typeof proposalRaw !== 'object') {
    return {
      designFlowM3PerHour: 0,
      headRequiredM: 0,
      pipeLines: [],
      pipeLineGroups: [],
      pipeSegments: [],
      pump: null,
      pumps: [],
      estimatedPipesPrice: 0,
      estimatedPumpPrice: 0,
      estimatedTotalPrice: 0,
      unavailableReason: 'Предложение по гидравлике не сформировано.',
      pumpUnavailableReason: null,
      warnings,
      hasCatalogSelection: false,
      hasPipeSelection: false,
    };
  }

  const proposal = proposalRaw as Record<string, unknown>;
  const pipeLines = (Array.isArray(proposal.pipeLines) ? proposal.pipeLines : [])
    .map(parsePipeLine)
    .filter((x): x is ParsedHydraulicsPipeLine => x != null);
  const pipeSegments = (Array.isArray(proposal.pipeSegments) ? proposal.pipeSegments : [])
    .map(parsePipeSegment)
    .filter((x): x is ParsedHydraulicsPipeSegment => x != null);

  const pipeLineGroupsFromApi = (Array.isArray(proposal.pipeLineGroups) ? proposal.pipeLineGroups : [])
    .map(parsePipeLineGroup)
    .filter((x): x is ParsedHydraulicsPipeLineGroup => x != null);
  const pipeLineGroups =
    pipeLineGroupsFromApi.length > 0
      ? pipeLineGroupsFromApi
      : buildPipeLineGroupsFromSegments(pipeSegments);

  const pumpsRaw = Array.isArray(proposal.pumps) ? proposal.pumps : [];
  const pumpsFromArray = pumpsRaw
    .map(parsePump)
    .filter((x): x is ParsedHydraulicsPumpProposal => x != null);
  const pump = parsePump(proposal.pump) ?? pumpsFromArray[0] ?? null;
  const pumps = pumpsFromArray.length > 0 ? pumpsFromArray : pump ? [pump] : [];

  const unavailableReason =
    typeof proposal.unavailableReason === 'string' ? proposal.unavailableReason : null;
  const pumpUnavailableReason =
    typeof proposal.pumpUnavailableReason === 'string' ? proposal.pumpUnavailableReason : null;

  const hasPipeSelection = pipeLines.length > 0 || pipeLineGroups.length > 0;

  const topology = parseTopology(proposal.topology);

  return {
    designFlowM3PerHour: num(proposal.designFlowM3PerHour),
    headRequiredM: num(proposal.headRequiredM),
    ...(topology !== undefined ? { topology } : {}),
    pipeLines,
    pipeLineGroups,
    pipeSegments,
    pump,
    pumps,
    estimatedPipesPrice: num(proposal.estimatedPipesPrice),
    estimatedPumpPrice: num(proposal.estimatedPumpPrice),
    estimatedTotalPrice: num(proposal.estimatedTotalPrice),
    unavailableReason,
    pumpUnavailableReason,
    warnings,
    hasCatalogSelection: hasPipeSelection || pumps.length > 0,
    hasPipeSelection,
  };
}

/**
 * Назначение: Парсинг БКН из отчёта.
 * Описание: Разбор matching.indirectWaterHeater для WaterHeaterProposalCard / WaterHeaterMatchingPreview.
 */

import {
  isRecord,
  readRecordField,
  readStringArray,
} from '../jsonGuards';

/** Данные подбора БКН из report.matching.indirectWaterHeater */

export type ParsedIndirectWaterHeaterMatching = {
  selectedModel: string | null;
  volumeLiters: number | null;
  coilPowerKw: number | null;
  brand: string | null;
  price: number | null;
  requiredTankLiters: number;
  heatTimeMinutesFullTank: number | null;
  effectiveHeatPowerKw: number | null;
  warnings: string[];
  skippedReason: string | null;
  /** Выбрана позиция из каталога (selected не null). */
  hasCatalogSelection: boolean;
};

/**
 * Извлекает подбор бойлера косвенного нагрева из полного JSON отчёта POST /api/v1/calc.
 */
export function parseIndirectWaterHeaterMatchingFromReport(
  calcReport: unknown,
): ParsedIndirectWaterHeaterMatching | null {
  if (!isRecord(calcReport)) return null;
  const matching = readRecordField(calcReport, 'matching');
  if (!matching) return null;
  const raw = matching.indirectWaterHeater;
  if (!isRecord(raw)) return null;

  const selectedRaw = raw.selected;
  let selectedModel: string | null = null;
  let volumeLiters: number | null = null;
  let coilPowerKwParsed: number | null =
    typeof raw.coilPowerKw === 'number' && Number.isFinite(raw.coilPowerKw)
      ? raw.coilPowerKw
      : null;
  let brand: string | null = null;
  let price: number | null = null;

  const hasCatalogSelection = isRecord(selectedRaw);

  if (hasCatalogSelection) {
    const s = selectedRaw;
    selectedModel = typeof s.model === 'string' ? s.model : null;
    brand = typeof s.brand === 'string' ? s.brand : null;
    price =
      typeof s.price === 'number' && Number.isFinite(s.price) ? s.price : null;
    const specs = s.specs;
    if (isRecord(specs)) {
      const vol = specs.volumeLiters;
      volumeLiters =
        typeof vol === 'number' && Number.isFinite(vol) ? vol : null;
      const pk = specs.powerKw;
      if (
        typeof pk === 'number' &&
        Number.isFinite(pk) &&
        coilPowerKwParsed == null
      ) {
        coilPowerKwParsed = pk;
      }
    }
  }

  const requiredTankLiters =
    typeof raw.requiredTankLiters === 'number' &&
    Number.isFinite(raw.requiredTankLiters)
      ? raw.requiredTankLiters
      : 0;

  const heatTimeMinutesFullTank =
    typeof raw.heatTimeMinutesFullTank === 'number' &&
    Number.isFinite(raw.heatTimeMinutesFullTank)
      ? raw.heatTimeMinutesFullTank
      : null;

  const effectiveHeatPowerKw =
    typeof raw.effectiveHeatPowerKw === 'number' &&
    Number.isFinite(raw.effectiveHeatPowerKw)
      ? raw.effectiveHeatPowerKw
      : null;

  const warnings = readStringArray(raw.warnings);

  const skippedReason =
    typeof raw.skippedReason === 'string' && raw.skippedReason.trim() !== ''
      ? raw.skippedReason
      : null;

  return {
    selectedModel,
    volumeLiters,
    coilPowerKw: coilPowerKwParsed,
    brand,
    price,
    requiredTankLiters,
    heatTimeMinutesFullTank,
    effectiveHeatPowerKw,
    warnings,
    skippedReason,
    hasCatalogSelection,
  };
}

/**
 * Назначение: парсинг JSON-файла для Dev-импорта проекта.
 * Описание: ProjectExportBundle v1 или legacy SurveyDraft → тело POST /projects/import.
 */

import type { CalcReportJson } from '../../types/calcApi';
import type { ProjectDetail } from '../../types/projectsApi';
import { PROJECT_EXPORT_SCHEMA_VERSION } from '../../types/projectExport';
import type { SurveyDraft } from '../../types/surveyDraft';
import { isRecord } from '../jsonGuards';
import { parseSurveyDraft } from './parseSurveyDraft';

export type ParsedProjectImportFile = {
  importBody: Record<string, unknown>;
  latestReport: CalcReportJson | null;
};

/**
 * @param calculations
 */
function pickLatestReportFromCalculations(calculations: unknown[]): CalcReportJson | null {
  /** @type {Array<{ sourceCreatedAt?: string; report?: CalcReportJson }>} */
  const items = calculations
    .filter(isRecord)
    .map((item) => ({
      sourceCreatedAt:
        typeof item.sourceCreatedAt === 'string' ? item.sourceCreatedAt : undefined,
      report:
        item.report && typeof item.report === 'object' && !Array.isArray(item.report)
          ? (item.report as CalcReportJson)
          : undefined,
    }))
    .filter((item) => item.report !== undefined);

  if (items.length === 0) return null;

  items.sort((left, right) => {
    const leftTs = left.sourceCreatedAt ? Date.parse(left.sourceCreatedAt) : Number.NaN;
    const rightTs = right.sourceCreatedAt ? Date.parse(right.sourceCreatedAt) : Number.NaN;
    const leftKey = Number.isFinite(leftTs) ? leftTs : Number.MIN_SAFE_INTEGER;
    const rightKey = Number.isFinite(rightTs) ? rightTs : Number.MIN_SAFE_INTEGER;
    return rightKey - leftKey;
  });

  return items[0]?.report ?? null;
}

/**
 * @param raw
 */
export function parseProjectImportFile(raw: unknown): ParsedProjectImportFile {
  if (!isRecord(raw)) {
    throw new Error('JSON має бути обʼєктом');
  }

  if (raw.exportSchemaVersion === PROJECT_EXPORT_SCHEMA_VERSION) {
    if (!isRecord(raw.project)) {
      throw new Error('Некоректний ProjectExportBundle: немає project');
    }
    if (typeof raw.project.clientName !== 'string' || !raw.project.clientName.trim()) {
      throw new Error('Некоректний ProjectExportBundle: clientName');
    }
    if (!Array.isArray(raw.calculations)) {
      throw new Error('Некоректний ProjectExportBundle: calculations');
    }
    return {
      importBody: raw,
      latestReport: pickLatestReportFromCalculations(raw.calculations),
    };
  }

  parseSurveyDraft(raw);

  let latestReport: CalcReportJson | null = null;
  const lastCalcReport = raw.lastCalcReport;
  if (lastCalcReport && typeof lastCalcReport === 'object' && !Array.isArray(lastCalcReport)) {
    latestReport = lastCalcReport as CalcReportJson;
  } else if (Array.isArray(raw.calculations)) {
    latestReport = pickLatestReportFromCalculations(raw.calculations);
  }

  return { importBody: raw, latestReport };
}

/**
 * SurveyDraft для UI после успешного POST /projects/import.
 *
 * @param project
 * @param importBody
 * @param latestReport
 */
export function buildSurveyDraftAfterImport(
  project: ProjectDetail,
  importBody: Record<string, unknown>,
  latestReport: CalcReportJson | null,
): SurveyDraft {
  const surveyCandidate =
    project.survey
    ?? (isRecord(importBody.project) ? importBody.project.survey : undefined)
    ?? importBody;

  const draft = parseSurveyDraft(surveyCandidate);
  draft.projectId = project.id;
  draft.clientName = project.clientName;
  if (latestReport) {
    draft.lastCalcReport = latestReport;
  }
  return draft;
}

/**
 * Назначение: Парсинг подбора радиаторов.
 * Описание: Извлечение matching.radiators, lineEconomy/lineEfficient, emittersSummary.
 */

import {
  isRecord,
  readRecordField,
  readStringArray,
} from '../jsonGuards';

export type RadiatorDisplayKind = 'sectional' | 'panel' | 'none';

export type RadiatorsEmittersSummaryView = {
  panelUnits: number;
  sectionalUnits: number;
  sectionalSections: number;
  totalDeliverableWatts: number;
  roomsWithEmitter: number;
  roomsSkipped: number;
};

/** Рядок підбору радіатора по приміщенню. */
export type RadiatorsByRoomRow = {
  roomId: string;
  roomName: string;
  sections: number | null;
  priceBasis: 'section' | 'panel' | null;
  panelLengthMm: number | null;
  radiatorModel: string | null;
  deliverableWatts: number | null;
  displayKind: RadiatorDisplayKind;
  unitsCount: number | null;
  /** true — тип приладу відрізняється від economy (лише для efficient-таблиці). */
  equipmentKindChangedVsEconomy: boolean;
};

export type RadiatorsProposalLineView = {
  tier: 'economy' | 'efficient';
  byRoom: RadiatorsByRoomRow[];
  totalSections: number | null;
  emittersSummary: RadiatorsEmittersSummaryView | null;
  unavailableReason: string | null;
  supplyC: number | null;
  returnC: number | null;
};

export type ParsedRadiatorsMatching = {
  chosenModel: string | null;
  byRoom: RadiatorsByRoomRow[];
  /** Сума секцій (без панелей). */
  totalSections: number | null;
  emittersSummary: RadiatorsEmittersSummaryView | null;
  /** Підбір не виконувався (режим тільки ТП). */
  skippedReason: 'ufh_only' | null;
  roomEmitterDiffs: Array<{
    roomId: string;
    equipmentKindChanged: boolean;
  }>;
  warnings: string[];
  lineEconomy: RadiatorsProposalLineView | null;
  lineEfficient: RadiatorsProposalLineView | null;
  inputs: {
    supplyC: number | null;
    returnC: number | null;
    flowDeltaTK: number | null;
    /** EN442 mean ΔT = (Ts+Tr)/2 − Ti з matching.radiators.inputs.targetDeltaT. */
    targetDeltaT: number | null;
    radiatorConnection: 'side' | 'bottom' | null;
    radiatorEmitterPreference: 'auto' | 'sectional' | 'panel' | null;
  } | null;
  resolvedEmitterKind: 'sectional' | 'panel' | null;
};

/**
 * Формат шапки emitters для UI.
 */
export function formatRadiatorsEmittersSummaryLabel(
  summary: RadiatorsEmittersSummaryView | null | undefined,
): string | null {
  if (summary == null) return null;
  const parts: string[] = [];
  if (summary.panelUnits > 0) {
    parts.push(`панельні: ${summary.panelUnits} шт.`);
  }
  if (summary.sectionalUnits > 0) {
    parts.push(
      `секційні: ${summary.sectionalSections} сек. (${summary.sectionalUnits} прил.)`,
    );
  }
  if (summary.totalDeliverableWatts > 0) {
    parts.push(`Σ ≈ ${Math.round(summary.totalDeliverableWatts)} Вт`);
  }
  if (parts.length === 0) {
    return summary.roomsSkipped > 0 ? 'прилади не потрібні' : null;
  }
  return parts.join(' · ');
}

/**
 * Підпис кількості в таблиці (секції або панель).
 */
export function formatRadiatorRoomQuantityLabel(row: RadiatorsByRoomRow): string {
  if (row.displayKind === 'none' || !row.radiatorModel || row.radiatorModel === '—') {
    return '—';
  }
  if (row.displayKind === 'panel' || row.priceBasis === 'panel') {
    const len =
      row.panelLengthMm != null && Number.isFinite(row.panelLengthMm)
        ? ` ${Math.round(row.panelLengthMm)} мм`
        : '';
    const n =
      row.unitsCount != null && row.unitsCount > 1 ? row.unitsCount : 1;
    return n > 1
      ? `${n} шт. (панель${len})`
      : `1 шт. (панель${len})`;
  }
  if (row.sections != null) {
    const n =
      row.unitsCount != null && row.unitsCount > 1 ? row.unitsCount : 1;
    return n > 1
      ? `${n}×${row.sections} сек.`
      : `${row.sections} сек.`;
  }
  return '—';
}

function parseEmittersSummary(raw: unknown): RadiatorsEmittersSummaryView | null {
  if (!isRecord(raw)) return null;
  const num = (k: string): number => {
    const v = raw[k];
    return typeof v === 'number' && Number.isFinite(v) ? v : 0;
  };
  return {
    panelUnits: Math.trunc(num('panelUnits')),
    sectionalUnits: Math.trunc(num('sectionalUnits')),
    sectionalSections: Math.trunc(num('sectionalSections')),
    totalDeliverableWatts: num('totalDeliverableWatts'),
    roomsWithEmitter: Math.trunc(num('roomsWithEmitter')),
    roomsSkipped: Math.trunc(num('roomsSkipped')),
  };
}

function parseDisplayKind(raw: unknown): RadiatorDisplayKind {
  if (raw === 'sectional' || raw === 'panel' || raw === 'none') return raw;
  return 'none';
}

function parseByRoomRows(
  byRoomRaw: unknown,
  kindChangedByRoomId?: ReadonlySet<string>,
): RadiatorsByRoomRow[] {
  const byRoom: RadiatorsByRoomRow[] = [];
  if (!Array.isArray(byRoomRaw)) return byRoom;
  for (const item of byRoomRaw) {
    if (!isRecord(item)) continue;
    const roomId = typeof item.roomId === 'string' ? item.roomId : '';
    const roomNameRaw = item.roomName;
    const roomName =
      typeof roomNameRaw === 'string' && roomNameRaw.trim() !== ''
        ? roomNameRaw
        : roomId || '—';
    const sections =
      typeof item.sections === 'number' && Number.isFinite(item.sections)
        ? Math.trunc(item.sections)
        : null;
    const priceBasis =
      item.priceBasis === 'section' || item.priceBasis === 'panel'
        ? item.priceBasis
        : null;
    const panelLengthMm =
      typeof item.panelLengthMm === 'number' && Number.isFinite(item.panelLengthMm)
        ? item.panelLengthMm
        : null;
    const radiatorModel =
      typeof item.radiatorModel === 'string' ? item.radiatorModel : null;
    const deliverableWatts =
      typeof item.deliverableWatts === 'number' && Number.isFinite(item.deliverableWatts)
        ? item.deliverableWatts
        : null;
    const unitsCount =
      typeof item.unitsCount === 'number' && Number.isFinite(item.unitsCount)
        ? Math.trunc(item.unitsCount)
        : null;
    let displayKind = parseDisplayKind(item.displayKind);
    if (displayKind === 'none') {
      if (priceBasis === 'panel') displayKind = 'panel';
      else if (priceBasis === 'section' || sections != null) displayKind = 'sectional';
      else if (radiatorModel && radiatorModel !== '—') displayKind = 'sectional';
    }
    byRoom.push({
      roomId,
      roomName,
      sections,
      priceBasis,
      panelLengthMm,
      radiatorModel,
      deliverableWatts,
      displayKind,
      unitsCount,
      equipmentKindChangedVsEconomy: Boolean(
        roomId && kindChangedByRoomId?.has(roomId),
      ),
    });
  }
  return byRoom;
}

function parseProposalLine(
  raw: unknown,
  tier: 'economy' | 'efficient',
  kindChangedByRoomId?: ReadonlySet<string>,
): RadiatorsProposalLineView | null {
  if (!isRecord(raw)) return null;
  const tierRaw = raw.tier;
  if (tierRaw !== tier) return null;
  const byRoom = parseByRoomRows(
    raw.byRoom,
    tier === 'efficient' ? kindChangedByRoomId : undefined,
  );
  const inputs = isRecord(raw.inputs) ? raw.inputs : null;
  const supplyC =
    inputs && typeof inputs.supplyC === 'number' ? inputs.supplyC : null;
  const returnC =
    inputs && typeof inputs.returnC === 'number' ? inputs.returnC : null;
  const emittersSummary = parseEmittersSummary(raw.emittersSummary);
  const totalSectionsRaw = raw.totalSections;
  const totalSections =
    typeof totalSectionsRaw === 'number' && Number.isFinite(totalSectionsRaw)
      ? Math.trunc(totalSectionsRaw)
      : emittersSummary != null
        ? emittersSummary.sectionalSections
        : null;
  const unavailableReason =
    typeof raw.unavailableReason === 'string' ? raw.unavailableReason : null;
  return {
    tier,
    byRoom,
    totalSections,
    emittersSummary,
    unavailableReason,
    supplyC,
    returnC,
  };
}

/**
 * Витягує підбір радіаторів з повного JSON звіту POST /api/v1/calc.
 */
export function parseRadiatorsMatchingFromReport(
  calcReport: unknown,
): ParsedRadiatorsMatching | null {
  if (!isRecord(calcReport)) return null;
  const matching = readRecordField(calcReport, 'matching');
  if (!matching) return null;
  const radiators = readRecordField(matching, 'radiators');
  if (!radiators) return null;

  const chosenRaw = radiators.chosen;
  let chosenModel: string | null = null;
  if (isRecord(chosenRaw)) {
    const m = chosenRaw.model;
    chosenModel = typeof m === 'string' ? m : null;
  }

  const kindChangedByRoomId = new Set<string>();
  const diffsRaw = radiators.roomEmitterDiffs;
  if (Array.isArray(diffsRaw)) {
    for (const d of diffsRaw) {
      if (!isRecord(d)) continue;
      if (d.equipmentKindChanged === true && typeof d.roomId === 'string') {
        kindChangedByRoomId.add(d.roomId);
      }
    }
  }

  const byRoom = parseByRoomRows(radiators.byRoom);
  const emittersSummary = parseEmittersSummary(radiators.emittersSummary);
  const totalSectionsRaw = radiators.totalSections;
  const totalSections =
    typeof totalSectionsRaw === 'number' && Number.isFinite(totalSectionsRaw)
      ? Math.trunc(totalSectionsRaw)
      : emittersSummary != null
        ? emittersSummary.sectionalSections
        : null;
  const warnings = readStringArray(radiators.warnings);

  const inputsRaw = isRecord(radiators.inputs) ? radiators.inputs : null;
  let inputs: ParsedRadiatorsMatching['inputs'] = null;
  if (inputsRaw) {
    const supplyC =
      typeof inputsRaw.supplyC === 'number' && Number.isFinite(inputsRaw.supplyC)
        ? inputsRaw.supplyC
        : null;
    const returnC =
      typeof inputsRaw.returnC === 'number' && Number.isFinite(inputsRaw.returnC)
        ? inputsRaw.returnC
        : null;
    const flowDeltaTK =
      typeof inputsRaw.flowDeltaTK === 'number' && Number.isFinite(inputsRaw.flowDeltaTK)
        ? inputsRaw.flowDeltaTK
        : null;
    const targetDeltaT =
      typeof inputsRaw.targetDeltaT === 'number' && Number.isFinite(inputsRaw.targetDeltaT)
        ? inputsRaw.targetDeltaT
        : null;
    const radiatorConnection =
      inputsRaw.radiatorConnection === 'side' || inputsRaw.radiatorConnection === 'bottom'
        ? inputsRaw.radiatorConnection
        : null;
    const radiatorEmitterPreference =
      inputsRaw.radiatorEmitterPreference === 'auto'
      || inputsRaw.radiatorEmitterPreference === 'sectional'
      || inputsRaw.radiatorEmitterPreference === 'panel'
        ? inputsRaw.radiatorEmitterPreference
        : null;
    inputs = {
      supplyC,
      returnC,
      flowDeltaTK,
      targetDeltaT,
      radiatorConnection,
      radiatorEmitterPreference,
    };
  }

  const resolvedEmitterKind =
    radiators.resolvedEmitterKind === 'sectional'
    || radiators.resolvedEmitterKind === 'panel'
      ? radiators.resolvedEmitterKind
      : null;

  const roomEmitterDiffs: ParsedRadiatorsMatching['roomEmitterDiffs'] = [];
  if (Array.isArray(diffsRaw)) {
    for (const d of diffsRaw) {
      if (!isRecord(d) || typeof d.roomId !== 'string') continue;
      roomEmitterDiffs.push({
        roomId: d.roomId,
        equipmentKindChanged: d.equipmentKindChanged === true,
      });
    }
  }

  return {
    chosenModel,
    byRoom,
    totalSections,
    emittersSummary,
    skippedReason: radiators.skippedReason === 'ufh_only' ? 'ufh_only' : null,
    roomEmitterDiffs,
    warnings,
    lineEconomy: parseProposalLine(radiators.lineEconomy, 'economy'),
    lineEfficient: parseProposalLine(
      radiators.lineEfficient,
      'efficient',
      kindChangedByRoomId,
    ),
    inputs,
    resolvedEmitterKind,
  };
}

/**
 * Назначение: Парсинг расчёта тёплого пола из отчёта API.
 */

import type { CalcReportJson } from '../../types/calcApi';
import type {
  ParsedUnderfloorHeating,
  ParsedUnderfloorHeatingRoom,
  ParsedUnderfloorHydraulics,
  ParsedUfhLoopHydraulics,
  ParsedUfhMixingNodeSpec,
  ParsedUfhResolvedRecommendation,
} from '../../types/underfloorHeating';
import type { UfhDistributionPreset } from '../../types/ufhDistribution';
import { isUfhDistributionPreset } from '../../types/ufhDistribution';
import { isRecord, readRecordField, readStringArray } from '../jsonGuards';

function readFiniteNumber(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function parseMixingNode(block: Record<string, unknown>): ParsedUfhMixingNodeSpec | null {
  const raw = block.mixingNode;
  if (!isRecord(raw)) return null;

  const presetRaw = raw.distributionPreset;
  const distributionPreset =
    typeof presetRaw === 'string'
    && isUfhDistributionPreset(presetRaw)
    && presetRaw !== 'auto'
      ? presetRaw
      : null;

  return {
    boilerSupplyC: readFiniteNumber(raw.boilerSupplyC),
    floorCircuitSupplyC: readFiniteNumber(raw.floorCircuitSupplyC),
    deltaTK: readFiniteNumber(raw.deltaTK),
    flowRateM3PerHour: readFiniteNumber(raw.flowRateM3PerHour),
    headMetersMin: readFiniteNumber(raw.headMetersMin),
    valveKvsMin: readFiniteNumber(raw.valveKvsMin),
    distributionPreset,
    notes: readStringArray(raw.notes),
  };
}

function parseResolvedRecommendations(
  block: Record<string, unknown>,
): ParsedUfhResolvedRecommendation[] {
  const raw = block.resolvedRecommendations;
  if (!Array.isArray(raw)) return [];
  const out: ParsedUfhResolvedRecommendation[] = [];
  for (const item of raw) {
    if (!isRecord(item)) continue;
    const code = typeof item.code === 'string' ? item.code.trim() : '';
    const title = typeof item.title === 'string' ? item.title.trim() : '';
    const text = typeof item.text === 'string' ? item.text.trim() : '';
    const equipmentType =
      typeof item.equipmentType === 'string' ? item.equipmentType.trim() : '';
    const category = item.category;
    if (!code || !title || !text) continue;
    if (category !== 'warnings' && category !== 'automationHints') continue;
    const stepsRaw = item.resolutionSteps;
    const resolutionSteps = Array.isArray(stepsRaw)
      ? stepsRaw
          .map((s) => {
            if (!isRecord(s)) return null;
            const stepTitle = typeof s.title === 'string' ? s.title.trim() : '';
            const stepDetail = typeof s.detail === 'string' ? s.detail.trim() : '';
            if (!stepTitle || !stepDetail) return null;
            return { title: stepTitle, detail: stepDetail };
          })
          .filter((s): s is { title: string; detail: string } => s != null)
      : undefined;
    out.push({
      code,
      category,
      equipmentType: equipmentType || 'underfloor_heating',
      title,
      text,
      ...(resolutionSteps && resolutionSteps.length > 0
        ? { resolutionSteps }
        : {}),
    });
  }
  return out;
}

function parseUnderfloorHydraulics(
  block: Record<string, unknown>,
): ParsedUnderfloorHydraulics | null {
  const raw = block.underfloorHydraulics;
  if (!isRecord(raw)) return null;
  const deltaTK = readFiniteNumber(raw.deltaTK);
  const massFlowKgPerSec = readFiniteNumber(raw.massFlowKgPerSec);
  const flowRateM3PerHour = readFiniteNumber(raw.flowRateM3PerHour);
  if (deltaTK == null || massFlowKgPerSec == null || flowRateM3PerHour == null) return null;
  return { deltaTK, massFlowKgPerSec, flowRateM3PerHour };
}

function parseDistributionPreset(
  value: unknown,
): Exclude<UfhDistributionPreset, 'auto'> | null {
  if (typeof value !== 'string' || !isUfhDistributionPreset(value) || value === 'auto') {
    return null;
  }
  return value;
}

function parseLoopResolutionStatus(
  value: unknown,
): ParsedUnderfloorHeatingRoom['loopHydraulicsResolutionStatus'] | null {
  if (
    value === 'resolved_auto'
    || value === 'unresolved_velocity'
    || value === 'unresolved_pressure'
    || value === 'unresolved_conflict'
  ) {
    return value;
  }
  return null;
}

function parseLoopAppliedFix(
  value: unknown,
): ParsedUnderfloorHeatingRoom['loopHydraulicsAppliedFix'] | null {
  if (
    value === 'none'
    || value === 'loops_reduced'
    || value === 'loops_increased'
    || value === 'pipe_downsized'
    || value === 'pipe_upsized'
  ) {
    return value;
  }
  return null;
}

function parseUfhLoopHydraulics(item: unknown): ParsedUfhLoopHydraulics | null {
  if (!isRecord(item)) return null;

  const hydRaw = item.hydraulics;
  const src = isRecord(hydRaw) ? hydRaw : item;

  const loopId = typeof src.loopId === 'string' ? src.loopId : '';
  if (!loopId) return null;

  const loopLengthM =
    readFiniteNumber(src.loopLengthM)
    ?? readFiniteNumber(item.loopLengthM);
  const flowRateM3PerHour =
    readFiniteNumber(src.flowRateM3PerHour) ?? readFiniteNumber(item.flowRateM3PerHour);
  if (loopLengthM == null || flowRateM3PerHour == null) return null;

  const actionRaw = src.pipeResizeAction;
  const pipeResizeAction =
    actionRaw === 'upsized'
    || actionRaw === 'downsized'
    || actionRaw === 'loops_adjusted'
    || actionRaw === 'unchanged'
      ? actionRaw
      : 'unchanged';

  const reasonRaw = src.pipeResizeReason;
  const pipeResizeReason =
    typeof reasonRaw === 'string' && reasonRaw.trim() !== '' ? reasonRaw : null;

  return {
    loopId,
    loopLengthM,
    flowRateM3PerHour,
    internalDiameterMm: readFiniteNumber(src.internalDiameterMm),
    velocityMps: readFiniteNumber(src.velocityMps),
    pressureDropKPa: readFiniteNumber(src.pressureDropKPa),
    catalogPipeId: typeof src.catalogPipeId === 'string' ? src.catalogPipeId : null,
    initialCatalogPipeId:
      typeof src.initialCatalogPipeId === 'string' ? src.initialCatalogPipeId : null,
    pipeResizeAction,
    pipeResizeReason,
    warnings: readStringArray(src.warnings),
  };
}

function parseRoomRow(item: unknown): ParsedUnderfloorHeatingRoom | null {
  if (!isRecord(item)) return null;
  const roomId = typeof item.roomId === 'string' ? item.roomId : '';
  const roomName =
    typeof item.roomName === 'string' && item.roomName.trim() !== ''
      ? item.roomName
      : roomId || '—';
  const finishMaterialName =
    typeof item.finishMaterialName === 'string' && item.finishMaterialName.trim() !== ''
      ? item.finishMaterialName
      : typeof item.finishMaterialId === 'string'
        ? item.finishMaterialId
        : '—';
  const basePresetName =
    typeof item.basePresetName === 'string' && item.basePresetName.trim() !== ''
      ? item.basePresetName
      : typeof item.basePresetId === 'string'
        ? item.basePresetId
        : '—';

  const requiredNums = [
    item.heatFluxUpWm2,
    item.heatFluxDownWm2,
    item.heatFluxUpWatts,
    item.heatFluxDownWatts,
    item.surfaceTempC,
    item.maxSurfaceTemperatureCelsius,
    item.coveringResistanceM2KW,
  ];
  if (!requiredNums.every((n) => typeof n === 'number' && Number.isFinite(n))) return null;

  const maxAllowableRaw = item.maxAllowableHeatFluxUpWm2;
  const maxAllowableHeatFluxUpWm2 =
    typeof maxAllowableRaw === 'number' && Number.isFinite(maxAllowableRaw)
      ? maxAllowableRaw
      : 0;

  const pipeSpacingRaw = item.pipeSpacingMm;
  const pipeSpacingMm =
    pipeSpacingRaw === 100 || pipeSpacingRaw === 150 || pipeSpacingRaw === 200
      ? pipeSpacingRaw
      : 150;

  const pipeEmbedRaw = item.pipeEmbedmentResistanceM2KW;
  const pipeEmbedmentResistanceM2KW =
    typeof pipeEmbedRaw === 'number' && Number.isFinite(pipeEmbedRaw) ? pipeEmbedRaw : 0;

  const finishCoveringRaw = item.finishCoveringResistanceM2KW;
  const finishCoveringResistanceM2KW =
    typeof finishCoveringRaw === 'number' && Number.isFinite(finishCoveringRaw)
      ? finishCoveringRaw
      : (item.coveringResistanceM2KW as number);

  const comfortRaw = item.comfortMaxSurfaceTemperatureCelsius;
  const comfortMaxSurfaceTemperatureCelsius =
    typeof comfortRaw === 'number' && Number.isFinite(comfortRaw) ? comfortRaw : null;

  const finishMaxRaw = item.finishMaxSurfaceTemperatureCelsius;
  const finishMaxSurfaceTemperatureCelsius =
    typeof finishMaxRaw === 'number' && Number.isFinite(finishMaxRaw)
      ? finishMaxRaw
      : undefined;

  const presetMaxRaw = item.presetMaxSurfaceTemperatureCelsius;
  const presetMaxSurfaceTemperatureCelsius =
    typeof presetMaxRaw === 'number' && Number.isFinite(presetMaxRaw)
      ? presetMaxRaw
      : undefined;

  const loopsCountRaw = item.loopsCount;
  const loopsCount =
    typeof loopsCountRaw === 'number' && Number.isFinite(loopsCountRaw)
      ? loopsCountRaw
      : undefined;

  const loops: ParsedUfhLoopHydraulics[] = [];
  if (Array.isArray(item.loops)) {
    for (const loopRow of item.loops) {
      const parsedLoop = parseUfhLoopHydraulics(loopRow);
      if (parsedLoop) loops.push(parsedLoop);
    }
  }

  const loopHydraulicsResolutionStatus = parseLoopResolutionStatus(
    item.loopHydraulicsResolutionStatus,
  );
  const loopHydraulicsAppliedFix = parseLoopAppliedFix(item.loopHydraulicsAppliedFix);

  const readOptionalNumber = (key: string): number | undefined => {
    const raw = item[key];
    return typeof raw === 'number' && Number.isFinite(raw) ? raw : undefined;
  };

  const pipeSpacingResolutionRaw = item.pipeSpacingResolution;
  const pipeSpacingResolution =
    pipeSpacingResolutionRaw === 'matched_requested'
    || pipeSpacingResolutionRaw === 'tightened'
    || pipeSpacingResolutionRaw === 'none_sufficient'
      ? pipeSpacingResolutionRaw
      : undefined;

  const roomAreaM2 = readOptionalNumber('roomAreaM2');
  const furnitureOccupiedAreaM2 = readOptionalNumber('furnitureOccupiedAreaM2');
  const heatedAreaM2 = readOptionalNumber('heatedAreaM2');
  const requiredHeatFluxUpWm2 = readOptionalNumber('requiredHeatFluxUpWm2');
  const requestedPipeSpacingMm = readOptionalNumber('requestedPipeSpacingMm');
  const resolvedPipeSpacingMm = readOptionalNumber('resolvedPipeSpacingMm');

  return {
    roomId,
    roomName,
    basePresetName,
    finishMaterialName,
    ...(roomAreaM2 !== undefined ? { roomAreaM2 } : {}),
    ...(furnitureOccupiedAreaM2 !== undefined ? { furnitureOccupiedAreaM2 } : {}),
    ...(heatedAreaM2 !== undefined ? { heatedAreaM2 } : {}),
    ...(requiredHeatFluxUpWm2 !== undefined ? { requiredHeatFluxUpWm2 } : {}),
    ...(requestedPipeSpacingMm !== undefined ? { requestedPipeSpacingMm } : {}),
    ...(resolvedPipeSpacingMm !== undefined ? { resolvedPipeSpacingMm } : {}),
    ...(pipeSpacingResolution ? { pipeSpacingResolution } : {}),
    heatFluxUpWm2: item.heatFluxUpWm2 as number,
    heatFluxDownWm2: item.heatFluxDownWm2 as number,
    maxAllowableHeatFluxUpWm2,
    heatFluxUpWatts: item.heatFluxUpWatts as number,
    heatFluxDownWatts: item.heatFluxDownWatts as number,
    surfaceTempC: item.surfaceTempC as number,
    maxSurfaceTemperatureCelsius: item.maxSurfaceTemperatureCelsius as number,
    comfortMaxSurfaceTemperatureCelsius,
    ...(finishMaxSurfaceTemperatureCelsius !== undefined
      ? { finishMaxSurfaceTemperatureCelsius }
      : {}),
    ...(presetMaxSurfaceTemperatureCelsius !== undefined
      ? { presetMaxSurfaceTemperatureCelsius }
      : {}),
    pipeSpacingMm,
    pipeEmbedmentResistanceM2KW,
    finishCoveringResistanceM2KW,
    coveringResistanceM2KW: item.coveringResistanceM2KW as number,
    ...(loopsCount != null ? { loopsCount } : {}),
    ...(item.pipeResizeApplied === true ? { pipeResizeApplied: true } : {}),
    ...(loopHydraulicsResolutionStatus
      ? { loopHydraulicsResolutionStatus }
      : {}),
    ...(loopHydraulicsAppliedFix ? { loopHydraulicsAppliedFix } : {}),
    ...(loops.length > 0 ? { loops } : {}),
    warnings: readStringArray(item.warnings),
  };
}

export function parseUnderfloorHeatingFromReport(
  calcReport: CalcReportJson | null,
): ParsedUnderfloorHeating | null {
  if (calcReport === null) return null;
  const calculations = readRecordField(calcReport, 'calculations');
  if (!calculations) return null;
  const block = readRecordField(calculations, 'underfloorHeating');
  if (!block) return null;

  const supply = block.circuitSupplyC;
  const ret = block.circuitReturnC;
  const mean = block.circuitMeanC;
  if (typeof supply !== 'number' || typeof ret !== 'number' || typeof mean !== 'number') {
    return null;
  }

  const source = block.circuitSource;
  const circuitSource =
    source === 'heatingSystem'
    || source === 'mixed_default'
    || source === 'finish_preset'
    || source === 'ufh_mode_preset'
      ? source
      : 'mixed_default';

  const rooms: ParsedUnderfloorHeatingRoom[] = [];
  if (Array.isArray(block.rooms)) {
    for (const row of block.rooms) {
      const parsed = parseRoomRow(row);
      if (parsed) rooms.push(parsed);
    }
  }

  const totalUp = block.totalHeatFluxUpWatts;
  const totalDown = block.totalHeatFluxDownWatts;
  if (typeof totalUp !== 'number' || typeof totalDown !== 'number') return null;

  return {
    circuitSupplyC: supply,
    circuitReturnC: ret,
    circuitMeanC: mean,
    circuitSource,
    isMixingNodeRequired: block.isMixingNodeRequired === true,
    distributionPreset: parseDistributionPreset(block.distributionPreset),
    mixingNode: parseMixingNode(block),
    underfloorHydraulics: parseUnderfloorHydraulics(block),
    rooms,
    totalHeatFluxUpWatts: totalUp,
    totalHeatFluxDownWatts: totalDown,
    warnings: readStringArray(block.warnings),
    resolvedRecommendations: parseResolvedRecommendations(block),
  };
}

/**
 * Назначение: Парсинг report.matching.uniboxes для UI сметы.
 * Описание: Строки byLoop с selected / warnings и параметрами demand.
 */

import { isRecord, readRecordField } from '../jsonGuards';

export type ParsedUniboxConnection = {
  thread: string;
  fit: string;
};

export type ParsedUniboxSelected = {
  id: string;
  brand: string;
  model: string;
  type: string;
  price: number;
  maxAreaSqM: number;
  maxLoopLengthM: number;
  kvM3h: number;
  connection: ParsedUniboxConnection;
};

export type ParsedUniboxLoopDemand = {
  areaSqM: number;
  loopLengthM: number;
  circuitSupplyC: number;
  circuitReturnC: number;
  flowLph: number;
  roomAirTempC: number;
  systemPressureBar: number;
  minKvM3h: number;
  requiredFit: string;
};

export type ParsedUniboxLoopRow = {
  roomId: string;
  loopId: string;
  required: ParsedUniboxLoopDemand;
  selected: ParsedUniboxSelected | null;
  warnings: string[];
};

export type ParsedUniboxesMatching = {
  byLoop: ParsedUniboxLoopRow[];
  warnings: string[];
};

/**
 * @param {unknown} raw
 * @returns {ParsedUniboxSelected | null}
 */
function parseSelected(raw: unknown): ParsedUniboxSelected | null {
  if (!isRecord(raw)) return null;
  const id = typeof raw.id === 'string' ? raw.id.trim() : '';
  const brand = typeof raw.brand === 'string' ? raw.brand.trim() : '';
  const model = typeof raw.model === 'string' ? raw.model.trim() : '';
  const type = typeof raw.type === 'string' ? raw.type.trim() : '';
  const price = Number(raw.price);
  const maxAreaSqM = Number(raw.maxAreaSqM);
  const maxLoopLengthM = Number(raw.maxLoopLengthM);
  const kvM3h = Number(raw.kvM3h);
  if (!id || !brand || !model || !type || !Number.isFinite(price)) return null;
  const conn = isRecord(raw.connection) ? raw.connection : null;
  const thread = conn && typeof conn.thread === 'string' ? conn.thread : '';
  const fit = conn && typeof conn.fit === 'string' ? conn.fit : '';
  if (!thread || !fit) return null;
  return {
    id,
    brand,
    model,
    type,
    price,
    maxAreaSqM: Number.isFinite(maxAreaSqM) ? maxAreaSqM : 0,
    maxLoopLengthM: Number.isFinite(maxLoopLengthM) ? maxLoopLengthM : 0,
    kvM3h: Number.isFinite(kvM3h) ? kvM3h : 0,
    connection: { thread, fit },
  };
}

/**
 * @param {unknown} raw
 * @returns {ParsedUniboxLoopDemand | null}
 */
function parseDemand(raw: unknown): ParsedUniboxLoopDemand | null {
  if (!isRecord(raw)) return null;
  const areaSqM = Number(raw.areaSqM);
  const loopLengthM = Number(raw.loopLengthM);
  const circuitSupplyC = Number(raw.circuitSupplyC);
  const circuitReturnC = Number(raw.circuitReturnC);
  const flowLph = Number(raw.flowLph);
  const roomAirTempC = Number(raw.roomAirTempC);
  const systemPressureBar = Number(raw.systemPressureBar);
  const minKvM3h = Number(raw.minKvM3h);
  const requiredFit = typeof raw.requiredFit === 'string' ? raw.requiredFit : '';
  if (
    ![areaSqM, loopLengthM, circuitSupplyC, circuitReturnC, flowLph, roomAirTempC, systemPressureBar, minKvM3h].every(
      (n) => Number.isFinite(n),
    )
    || !requiredFit
  ) {
    return null;
  }
  return {
    areaSqM,
    loopLengthM,
    circuitSupplyC,
    circuitReturnC,
    flowLph,
    roomAirTempC,
    systemPressureBar,
    minKvM3h,
    requiredFit,
  };
}

/**
 * @param {unknown} calcReport
 * @returns {ParsedUniboxesMatching | null}
 */
export function parseUniboxesMatchingFromReport(calcReport: unknown): ParsedUniboxesMatching | null {
  if (!isRecord(calcReport)) return null;
  const matching = readRecordField(calcReport, 'matching');
  if (!matching) return null;
  const block = readRecordField(matching, 'uniboxes');
  if (!block) return null;

  const warningsRaw = Array.isArray(block.warnings) ? block.warnings : [];
  const warnings = warningsRaw.filter((w): w is string => typeof w === 'string' && w.trim().length > 0);

  const byLoopRaw = Array.isArray(block.byLoop) ? block.byLoop : [];
  /** @type {ParsedUniboxLoopRow[]} */
  const byLoop: ParsedUniboxLoopRow[] = [];
  for (const row of byLoopRaw) {
    if (!isRecord(row)) continue;
    const roomId = typeof row.roomId === 'string' ? row.roomId : '';
    const loopId = typeof row.loopId === 'string' ? row.loopId : '';
    const required = parseDemand(row.required);
    if (!roomId || !loopId || !required) continue;
    const rowWarnings = Array.isArray(row.warnings)
      ? row.warnings.filter((w): w is string => typeof w === 'string' && w.trim().length > 0)
      : [];
    byLoop.push({
      roomId,
      loopId,
      required,
      selected: parseSelected(row.selected),
      warnings: rowWarnings,
    });
  }

  if (byLoop.length === 0 && warnings.length === 0) return null;
  return { byLoop, warnings };
}

/**
 * Назначение: Парсинг электробойлера из отчёта.
 * Описание: Разбор matching.waterHeater для WaterHeaterProposalCard / WaterHeaterMatchingPreview.
 */

import {
  isRecord,
  readRecordField,
  readStringArray,
} from '../jsonGuards';

/** Данные подбора электрического накопительного водонагревателя из report.matching.waterHeater */

export type ParsedWaterHeaterMatching = {
  selectedModel: string | null;
  brand: string | null;
  volumeLiters: number | null;
  price: number | null;
  powerKw: number | null;
  requiredTankLiters: number;
  warnings: string[];
  /** Выбрана позиция из каталога (selected и chosenVariant). */
  hasCatalogSelection: boolean;
};

/**
 * Извлекает подбор электробойлера из полного JSON отчёта POST /api/v1/calc.
 * Возвращает null, если блок отсутствует или это пустая заглушка без подбора
 * (в т.ч. «только литры» без модели/warnings — не оживлять UI).
 */
export function parseWaterHeaterMatchingFromReport(
  calcReport: unknown,
): ParsedWaterHeaterMatching | null {
  if (!isRecord(calcReport)) return null;
  const matching = readRecordField(calcReport, 'matching');
  if (!matching) return null;
  const raw = matching.waterHeater;
  if (!isRecord(raw)) return null;

  const selectedRaw = raw.selected;
  const variantRaw = raw.chosenVariant;
  const hasCatalogSelection =
    isRecord(selectedRaw) && isRecord(variantRaw);
  const warnings = readStringArray(raw.warnings);

  if (!hasCatalogSelection && warnings.length === 0) {
    return null;
  }

  let selectedModel: string | null = null;
  let brand: string | null = null;
  let volumeLiters: number | null = null;
  let price: number | null = null;
  let powerKw: number | null = null;

  if (hasCatalogSelection) {
    const s = selectedRaw;
    selectedModel = typeof s.model === 'string' ? s.model : null;
    brand = typeof s.brand === 'string' ? s.brand : null;
    const v = variantRaw;
    volumeLiters =
      typeof v.volumeLiters === 'number' && Number.isFinite(v.volumeLiters)
        ? v.volumeLiters
        : null;
    price =
      typeof v.price === 'number' && Number.isFinite(v.price) ? v.price : null;
    powerKw =
      typeof v.powerKw === 'number' && Number.isFinite(v.powerKw)
        ? v.powerKw
        : null;
  }

  const requiredTankLiters =
    typeof raw.requiredTankLiters === 'number' &&
    Number.isFinite(raw.requiredTankLiters)
      ? raw.requiredTankLiters
      : 0;

  return {
    selectedModel,
    brand,
    volumeLiters,
    price,
    powerKw,
    requiredTankLiters,
    warnings,
    hasCatalogSelection,
  };
}

/**
 * Назначение: Ключ входа для автопересчёта.
 * Описание: Стабильная сериализация анкеты для сравнения при debounce-расчёте.
 */

import type { ObjectMetaValue } from '../types/envelope';
import type { HeatingThermalRegimePreset } from '../types/heatingThermalRegime';
import {
  DEFAULT_RADIATOR_CONNECTION,
  type RadiatorConnection,
} from '../types/radiatorConnection';
import {
  DEFAULT_RADIATOR_EMITTER_PREFERENCE,
  type RadiatorEmitterPreference,
} from '../types/radiatorEmitterPreference';
import type { UfhModePresetId } from '../types/ufhModePreset';
import type { UfhDistributionPreset } from '../types/ufhDistribution';
import type { HotWaterFormValue } from '../types/hotWater';
import type { WaterHeaterFormValue } from '../types/waterHeater';
import type { RoomFormValue } from '../types/rooms';
import { objectMetaForCalcPayload } from './objectMetaForCalcPayload';

/**
 * Стабильный ключ входа для автопересчёта (как прежде в App: JSON.stringify ключевого объекта).
 */
export function buildSurveyCalcInputKey(params: {
  temps: { insideC: number; outsideC: number; bathroomAirTempC?: number };
  objectMeta: ObjectMetaValue;
  waterHeaterForm: WaterHeaterFormValue;
  hotWaterForm: HotWaterFormValue;
  rooms: RoomFormValue[];
  waterUnderfloorHeating: boolean;
  underfloorDistributionPreset: UfhDistributionPreset;
  thermalRegimePreset: HeatingThermalRegimePreset;
  radiatorConnection?: RadiatorConnection;
  radiatorEmitterPreference?: RadiatorEmitterPreference;
  ufhPresetId?: UfhModePresetId | null;
  hydraulicsForm?: import('../types/hydraulics').HydraulicsFormValue;
}) {
  const {
    temps,
    objectMeta,
    waterHeaterForm,
    hotWaterForm,
    rooms,
    waterUnderfloorHeating,
    underfloorDistributionPreset,
    thermalRegimePreset,
    radiatorConnection = DEFAULT_RADIATOR_CONNECTION,
    radiatorEmitterPreference = DEFAULT_RADIATOR_EMITTER_PREFERENCE,
    ufhPresetId = null,
    hydraulicsForm,
  } = params;

  const objectMetaForKey = objectMetaForCalcPayload(objectMeta, waterHeaterForm);

  const key = {
    temps,
    objectMeta: {
      ...objectMetaForKey,
      apartmentStackPosition:
        objectMetaForKey.objectType === 'apartment'
          ? (objectMetaForKey.apartmentStackPosition ?? 'middle_floor')
          : undefined,
    },
    hotWaterBoilerPowerMatchingScheme:
      waterHeaterForm.hotWaterBoilerPowerMatchingScheme,
    waterUnderfloorHeating,
    underfloorDistributionPreset,
    thermalRegimePreset,
    radiatorConnection,
    radiatorEmitterPreference,
    ufhPresetId,
    hotWater: hotWaterForm,
    hydraulics: hydraulicsForm,
    rooms: rooms.map((r) => ({
      id: r.id,
      name: r.name,
      type: r.type,
      floor: r.floor,
      topBoundaryType: r.topBoundaryType,
      bottomBoundaryType: r.bottomBoundaryType,
      areaM2: r.areaM2,
      heightM: r.heightM,
      floorPresetId: r.floorPresetId,
      ceilingPresetId: r.ceilingPresetId,
      roofPresetId: r.roofPresetId,
      externalWall1: r.externalWall1,
      externalWall2: r.externalWall2,
      roomExteriorLayout: r.roomExteriorLayout,
      ceilingAreaM2: r.ceilingAreaM2,
      roofAreaM2: r.roofAreaM2,
      windows: r.windows.map((w) => ({
        id: w.id,
        presetId: w.presetId,
        openingWidthMm: w.openingWidthMm,
        openingHeightMm: w.openingHeightMm,
        orientation: w.orientation,
        count: w.count,
      })),
      underfloorHeating: r.underfloorHeating?.enabled
        ? {
            enabled: true,
            basePresetId: r.underfloorHeating.basePresetId,
            finishMaterialId: r.underfloorHeating.finishMaterialId,
            pipeSpacingMm:
              r.underfloorHeating.pipeSpacingMm === 100
              || r.underfloorHeating.pipeSpacingMm === 150
              || r.underfloorHeating.pipeSpacingMm === 200
                ? r.underfloorHeating.pipeSpacingMm
                : 150,
            furnitureOccupiedAreaM2: r.underfloorHeating.furnitureOccupiedAreaM2,
            ufhTerminalControl: r.underfloorHeating.ufhTerminalControl,
          }
        : undefined,
    })),
  };
  return JSON.stringify(key);
}

/**
 * Назначение: Экспорт и шаринг анкеты.
 * Описание: Текстовая сводка, Web Share API и кодирование черновика в URL-hash.
 */

import type { CalcReportJson } from '../types/calcApi';
import type { SurveyDraft } from '../types/surveyDraft';
import { wattsToKilowatts } from './calculators/heatLoss';
import { formatKw } from './format';
import { isRecord } from './jsonGuards';
import { parseSurveyDraft } from './parsers/parseSurveyDraft';

const URL_HASH_PREFIX = '#survey=';
/** Макс. размер JSON в hash (~50 KB). */
const MAX_HASH_JSON_BYTES = 51_200;

/** Краткая текстовая сводка для экспорта / Share API. */
export function buildSurveyTextSummary(
  draft: SurveyDraft,
  report?: CalcReportJson | null,
): string {
  const lines: string[] = [
    `Клієнт: ${draft.clientName}`,
    `Об'єкт: ${draft.objectMeta.objectType}, поверхів ${draft.objectMeta.floors}, приміщень ${draft.rooms.length}`,
    `Температури: всередині ${draft.temps.insideC} °C, зовні ${draft.temps.outsideC} °C` +
      (typeof draft.temps.bathroomAirTempC === 'number'
        ? `, повітря санвузла ${draft.temps.bathroomAirTempC} °C`
        : ''),
    `Збережено: ${draft.savedAt}`,
  ];
  const calculations = report && isRecord(report.calculations) ? report.calculations : null;
  const heatLoss =
    calculations && isRecord(calculations.heatLoss) ? calculations.heatLoss : null;
  if (heatLoss && typeof heatLoss.totalWatts === 'number') {
    lines.push(
      `Тепловтрати: ${formatKw(wattsToKilowatts(heatLoss.totalWatts))} кВт`,
    );
  }
  const matching = report && isRecord(report.matching) ? report.matching : null;
  const boiler = matching && isRecord(matching.boiler) ? matching.boiler : null;
  if (boiler && typeof boiler.requiredKw === 'number') {
    lines.push(`Котел: потрібно ${formatKw(boiler.requiredKw)} кВт`);
  }
  const selected = boiler && isRecord(boiler.selected) ? boiler.selected : null;
  const proposal = boiler && isRecord(boiler.proposal) ? boiler.proposal : null;
  const model =
    (selected && typeof selected.model === 'string' ? selected.model : null) ??
    (proposal && typeof proposal.model === 'string' ? proposal.model : null);
  if (model) lines.push(`Модель: ${model}`);
  if (report && Array.isArray(report.warnings) && report.warnings.length > 0) {
    lines.push(`Попереджень: ${report.warnings.length}`);
  }
  return lines.join('\n');
}

/** Черновик без отчёта для URL (лимит длины адресной строки). */
export function surveyDraftForUrlShare(draft: SurveyDraft): SurveyDraft {
  const { lastCalcReport: _drop, ...rest } = draft;
  void _drop;
  return rest;
}

/**
 * @param draft
 * @returns {string}
 */
export function encodeSurveyDraftToUrl(draft: SurveyDraft): string {
  const compact = surveyDraftForUrlShare(draft);
  const json = JSON.stringify(compact);
  const b64 = btoa(
    encodeURIComponent(json).replace(/%([0-9A-F]{2})/g, (_match: string, hex: string) =>
      String.fromCharCode(Number.parseInt(hex, 16)),
    ),
  );
  const base = `${window.location.origin}${window.location.pathname}`;
  return `${base}${URL_HASH_PREFIX}${b64}`;
}

/**
 * @param hash
 * @returns {SurveyDraft | null}
 */
export function decodeSurveyDraftFromHash(hash: string): SurveyDraft | null {
  if (!hash.startsWith(URL_HASH_PREFIX)) return null;
  try {
    const b64 = hash.slice(URL_HASH_PREFIX.length);
    const json = decodeURIComponent(
      Array.from(atob(b64), (c) => '%' + c.charCodeAt(0).toString(16).padStart(2, '0')).join(
        '',
      ),
    );
    if (json.length > MAX_HASH_JSON_BYTES) return null;
    return parseSurveyDraft(JSON.parse(json));
  } catch {
    return null;
  }
}

/**
 * @param text
 */
export async function copyTextToClipboard(text: string): Promise<void> {
  const clip: Clipboard | undefined = (navigator as { clipboard?: Clipboard })
    .clipboard;
  if (typeof clip?.writeText === 'function') {
    await clip.writeText(text);
    return;
  }
  throw new Error('Буфер обміну недоступний у цьому браузері');
}
